INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "优点", "is_correct": true, "explanation": "反义：“弱点”指人不太好的地方，“优点”指人的好处，二者相对。"}, {"text": "习惯", "is_correct": false, "explanation": "无反义关系：“习惯”指长期形成的行为，与“弱点”不相对。"}, {"text": "方法", "is_correct": false, "explanation": "无反义关系：“方法”指做事的途径，与“弱点”没有反义关系。"}, {"text": "道路", "is_correct": false, "explanation": "无反义关系：“道路”指行走的路线，与“弱点”不相对。"}], "correct_answer": "优点", "explanations": {"优点": "反义：“弱点”指人不太好的地方，“优点”指人的好处，二者相对。", "习惯": "无反义关系：“习惯”指长期形成的行为，与“弱点”不相对。", "方法": "无反义关系：“方法”指做事的途径，与“弱点”没有反义关系。", "道路": "无反义关系：“道路”指行走的路线，与“弱点”不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "兴趣", "is_correct": false, "explanation": "无反义关系：“兴趣”指对某事的喜爱，与“弱点”不相对。"}, {"text": "工具", "is_correct": false, "explanation": "无反义关系：“工具”指用来做事的器具，与“弱点”不相对。"}, {"text": "门路", "is_correct": false, "explanation": "无反义关系：“门路”指办事的途径，与“弱点”没有反义关系。"}, {"text": "优点", "is_correct": true, "explanation": "反义：“弱点”指人身上不太好的地方，“优点”指人的好处，二者相对。"}], "correct_answer": "优点", "explanations": {"兴趣": "无反义关系：“兴趣”指对某事的喜爱，与“弱点”不相对。", "工具": "无反义关系：“工具”指用来做事的器具，与“弱点”不相对。", "门路": "无反义关系：“门路”指办事的途径，与“弱点”没有反义关系。", "优点": "反义：“弱点”指人身上不太好的地方，“优点”指人的好处，二者相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "弱点是一个人不太好、不太行的地方。", "primary_collocate": null, "pronunciation": "ruò diǎn", "ipa": "ʐwɔ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的弱点是太容易紧张。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她唱歌很好，但英语是弱点。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的弱点是做事不够认真。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对自己的弱点，他从不逃避。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说，我的弱点就是不爱说话。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要总是盯着别人的弱点。", "target_word": "弱点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得自己最大的弱点是什么？", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他努力克服自己的弱点。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好朋友会直接指出我的弱点。", "target_word": "弱点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的弱点写在了本子上。", "target_word": "弱点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "弱點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人不太好、不太行的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "优点", "is_correct": false, "explanation": "语义：“优点”是好的地方，与“太容易紧张”矛盾。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：“爱好”指喜欢做的事，不能用来说明“太容易紧张”。"}, {"text": "弱点", "is_correct": true, "explanation": "“弱点”指一个人不太好的地方，与“太容易紧张”相符。"}, {"text": "风格", "is_correct": false, "explanation": "搭配：“风格”不说“是太容易紧张”，搭配不当。"}], "explanations": {"优点": "语义：“优点”是好的地方，与“太容易紧张”矛盾。", "爱好": "语义：“爱好”指喜欢做的事，不能用来说明“太容易紧张”。", "弱点": "“弱点”指一个人不太好的地方，与“太容易紧张”相符。", "风格": "搭配：“风格”不说“是太容易紧张”，搭配不当。"}, "sentence_index": 0, "correct_answer": "弱点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一张弱点，就是太依赖别人。", "explanation": "这里量词用错。“弱点”用量词〈个〉，不用〈张〉；〈张〉用于纸、桌子等平面的东西。"}, {"text": "她的弱点是记性很好，从不忘事。", "explanation": "这里应该用〈长处〉。“弱点”指人身上不太好的地方，记性好、从不忘事是优点，应用〈长处〉。"}, {"text": "老板说，我的弱点是责任心强，能按时完成任务。", "explanation": "这里应该用〈优点〉。“弱点”指人身上不太好的地方，责任心强是优点，应用〈优点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是天生的体格特征，不是能说成“最大的……是什么”的不足。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指收入，不是人身上不太好的地方。"}, {"text": "弱点", "is_correct": true, "explanation": "“弱点”指人身上不太好的地方，与“最大的……是什么”的问法相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不是性格或能力上的不足。"}], "explanations": {"身高": "体貌：“身高”是天生的体格特征，不是能说成“最大的……是什么”的不足。", "工资": "语义：“工资”指收入，不是人身上不太好的地方。", "弱点": "“弱点”指人身上不太好的地方，与“最大的……是什么”的问法相符。", "年龄": "语义：“年龄”指岁数，不是性格或能力上的不足。"}, "sentence_index": 6, "correct_answer": "弱点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把一颗弱点写在了本子上。", "explanation": "这里量词用错。“弱点”应用〈个〉，〈颗〉用于粒状的小东西，不用于“弱点”。"}, {"text": "他的弱点是非常聪明，考试次次都是第一。", "explanation": "这里应该用〈优势〉。“弱点”指人身上不太好的地方，聪明、考试成绩好是有利的条件，应用〈优势〉。"}, {"text": "他的弱点是跑步很快，每次比赛都拿第一。", "explanation": "这里应该用〈特长〉。“弱点”指人身上不太好、不太行的地方，跑步快、每次比赛都拿第一是突出的本领，应用〈特长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最担心的是自己弱点。", "corrected_sentence": "我最担心的是自己的弱点。", "error_description": "错误：「自己弱点」，“自己”修饰“弱点”时要加结构助词“的”。正确：「自己的弱点」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只明显的弱点，就是太固执。", "corrected_sentence": "他有一个明显的弱点，就是太固执。", "error_description": "错误：「一只弱点」，“弱点”的量词应用〈个〉，〈只〉多用于动物或成对的东西。正确：「一个弱点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
