INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不够强的地方；缺点。", "primary_collocate": null, "pronunciation": "ruò diǎn", "ipa": "ʐwɔ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这支球队的弱点是防守太差。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的弱点是不会拒绝别人。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学是我最大的弱点。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师帮我找出了学习上的弱点。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对手很快发现了我们的弱点。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有自己的弱点。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台手机的弱点是电池用不久。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他知道自己的弱点，所以每天练习。", "target_word": "弱点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别让别人看出你的弱点。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种材料的弱点是怕水。", "target_word": "弱点", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "弱點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物或人不够强的地方，缺点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64d38e22-74eb-4da9-84a8-607619094d33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "优势", "is_correct": false, "explanation": "语义：“优势”指有利的条件，与“防守太差”矛盾。"}, {"text": "弱点", "is_correct": true, "explanation": "“弱点”指不够强的地方，与“防守太差”相符。"}, {"text": "长处", "is_correct": false, "explanation": "语义：“长处”指好的地方，与“防守太差”矛盾。"}, {"text": "教练", "is_correct": false, "explanation": "配价：“教练”指人，不能说“教练是防守太差”。"}], "explanations": {"优势": "语义：“优势”指有利的条件，与“防守太差”矛盾。", "弱点": "“弱点”指不够强的地方，与“防守太差”相符。", "长处": "语义：“长处”指好的地方，与“防守太差”矛盾。", "教练": "配价：“教练”指人，不能说“教练是防守太差”。"}, "sentence_index": 0, "correct_answer": "弱点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师帮我找出了学习上的一张弱点。", "explanation": "这里量词用错。“弱点”用量词〈个〉，不用〈张〉；〈张〉用于纸等平面的东西。"}, {"text": "他的弱点是做事细心，同事都愿意和他合作。", "explanation": "这里应该用〈长处〉。“弱点”指不够强的地方，做事细心、同事愿意合作是优点，应用〈长处〉。"}, {"text": "这支球队的弱点是进攻很强。", "explanation": "这里应该用〈优势〉。“弱点”指不够强的地方，进攻很强是有利的条件，应用〈优势〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能说“颜色是电池用不久”，与句意不符。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“工作”不能说“工作是电池用不久”，搭配不当。"}, {"text": "弱点", "is_correct": true, "explanation": "“弱点”指不够强的地方，与“电池用不久”相符。"}, {"text": "外观", "is_correct": false, "explanation": "语义：“外观”指样子，与“电池用不久”没有关系。"}], "explanations": {"颜色": "语义：“颜色”指色彩，不能说“颜色是电池用不久”，与句意不符。", "工作": "搭配：“工作”不能说“工作是电池用不久”，搭配不当。", "弱点": "“弱点”指不够强的地方，与“电池用不久”相符。", "外观": "语义：“外观”指样子，与“电池用不久”没有关系。"}, "sentence_index": 6, "correct_answer": "弱点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车有一颗弱点，就是油耗高。", "explanation": "这里量词用错。“弱点”应用〈个〉，〈颗〉用于粒状的小东西，不用于“弱点”。"}, {"text": "这种材料的弱点是耐高温，很少变形。", "explanation": "这里应该用〈优点〉。“弱点”指不够强的地方，耐高温、很少变形是优点，应用〈优点〉。"}, {"text": "这部电影的弱点是特效精彩，观众很喜欢。", "explanation": "这里应该用〈亮点〉。“弱点”指不够强的地方，特效精彩是突出的优点，应用〈亮点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很大的弱点，就是不擅长表达。", "corrected_sentence": "他有一个很大的弱点，就是不擅长表达。", "error_description": "错误：「一只弱点」，“弱点”的量词应用〈个〉，〈只〉多用于动物。正确：「一个弱点」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最大弱点是粗心。", "corrected_sentence": "他最大的弱点是粗心。", "error_description": "错误：「最大弱点」，“最大”修饰“弱点”时漏掉结构助词“的”。正确：「最大的弱点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d4b5677-8c12-4f9e-ad43-babf7da1c397') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
