INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98811, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从没是从来都没有做过。", "primary_collocate": null, "pronunciation": "cóng méi", "ipa": "tsʰʊŋ˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "我从没去过北京。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没迟到过。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从没坐过飞机。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没见过这么大的雪。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟从没吃过辣的菜。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从没骗过我。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王从没学过画画。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从没吵过架。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸从没对我发过脾气。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没说过自己的难处。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "从来没有", "label": "全称"}], "register": "口语", "sense_fingerprint": "到现在为止一次也没有做过某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从没", "is_correct": true, "explanation": "正确：“从没”表示截至目前从未有过某种经历，与“去过”相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与表示经历的“去过”冲突，句子说不通。"}, {"text": "绝不", "is_correct": false, "explanation": "语义：“绝不”表示决心不做，说的是将来的态度，不能表示已有的经历。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示反复发生，与“去过北京”这样的单次经历不符。"}], "explanations": {"从没": "正确：“从没”表示截至目前从未有过某种经历，与“去过”相符。", "正在": "体貌：“正在”表示进行中，与表示经历的“去过”冲突，句子说不通。", "绝不": "语义：“绝不”表示决心不做，说的是将来的态度，不能表示已有的经历。", "常常": "语义：“常常”表示反复发生，与“去过北京”这样的单次经历不符。"}, "sentence_index": 0, "correct_answer": "从没"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上从没吃早饭。", "explanation": "这里应该用〈从不〉。从没指截至目前从未有过的经历，每天重复的习惯要用从不。"}, {"text": "我明天从没去过北京。", "explanation": "这里应该用〈不〉。从没只表示截至目前从未有过的经历，谈将来的打算要用“不”，不能用从没。"}, {"text": "我每天晚上从没看电视。", "explanation": "这里应该用〈从不〉。从没表示经历，每晚的习惯要说从不。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从没", "is_correct": true, "explanation": "正确：“从没”表示从未有过某种经历，与“学过”相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与表示经历的“学过”冲突，句子说不通。"}, {"text": "决不", "is_correct": false, "explanation": "语义：“决不”表示决心不做，说的是将来，不能表示已有的经历。"}, {"text": "时常", "is_correct": false, "explanation": "语义：“时常”表示经常发生，与“学过画画”这样的经历不符。"}], "explanations": {"从没": "正确：“从没”表示从未有过某种经历，与“学过”相符。", "正在": "体貌：“正在”表示进行中，与表示经历的“学过”冲突，句子说不通。", "决不": "语义：“决不”表示决心不做，说的是将来，不能表示已有的经历。", "时常": "语义：“时常”表示经常发生，与“学过画画”这样的经历不符。"}, "sentence_index": 6, "correct_answer": "从没"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每周末从没去图书馆。", "explanation": "这里应该用〈从不〉。从没指从未有过的经历，每周重复的习惯要用从不。"}, {"text": "他下个月从没去过英国。", "explanation": "这里应该用〈不〉。从没只表示截至目前从未有过的经历，谈将来的打算要用“不”，不能用从没。"}, {"text": "小王每天晚上从没练琴。", "explanation": "这里应该用〈从不〉。从没表示经历，每天的习惯要说从不。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从没在国外住一年。", "corrected_sentence": "我从没在国外住过一年。", "error_description": "错误：“从没”后的动词“住”漏掉了“过”。正确：“从没住过一年”。“从没”表示从未有过的经历，动词后要带“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在这家公司从没请假过。", "corrected_sentence": "我在这家公司从没请过假。", "error_description": "错误：“请假过”，“过”放在了离合词“请假”的后面。正确：“请过假”，离合词“请假”的“过”要放在“请”和“假”之间，“从没”表示从未有过的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
