INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从来没有。", "primary_collocate": null, "pronunciation": "cóng méi", "ipa": "tsʰʊŋ˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "这件事我从没想过。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市从没下过这么大的雨。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没来过我们家。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没听说过这个人。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从没生过气。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹从没一个人出过远门。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜，我从没觉得难吃。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没提起以前的事。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没喝过咖啡，不知道是什么味道。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们从没在课上玩过手机。", "target_word": "从没", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "从来没有", "label": "全称"}], "register": "口语", "sense_fingerprint": "从来没有，表示一直都不曾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158031be-7c16-4e76-bc41-c9e0a5326719') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从没", "is_correct": true, "explanation": "正确：“从没”表示一直都不曾想过，与“想过”相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“想过”所表示的已有经历冲突。"}, {"text": "决不", "is_correct": false, "explanation": "语义：“决不”表示决心不做，不能表示过去是否想过。"}, {"text": "将要", "is_correct": false, "explanation": "时间：“将要”表示将来，与表示已有经历的“想过”冲突。"}], "explanations": {"从没": "正确：“从没”表示一直都不曾想过，与“想过”相符。", "正在": "体貌：“正在”表示进行中，与“想过”所表示的已有经历冲突。", "决不": "语义：“决不”表示决心不做，不能表示过去是否想过。", "将要": "时间：“将要”表示将来，与表示已有经历的“想过”冲突。"}, "sentence_index": 0, "correct_answer": "从没"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚饭后从没散步。", "explanation": "这里应该用〈从不〉。从没指到目前为止从未有过的经历，每天重复的习惯要用从不。"}, {"text": "我下个月从没去过上海。", "explanation": "这里应该用〈不〉。从没只表示截至目前从未有过的经历，谈将来的打算要用“不”，不能用从没。"}, {"text": "我每天都从没喝茶。", "explanation": "这里应该用〈从不〉。从没表示经历，每天的习惯要说从不。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从没", "is_correct": true, "explanation": "正确：“从没”表示一直都不曾觉得，与句意中的“从未有过的感受”相符。"}, {"text": "互相", "is_correct": false, "explanation": "语义：“互相”要求两方以上彼此做某事，主语只有“我”一个人，不能说“我互相觉得”。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”指做一件事时附带做另一件事，“觉得难吃”不是能顺便做的动作。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”用于劝告、叮嘱，如“千万别…”，不能用来陈述自己的感受。"}], "explanations": {"从没": "正确：“从没”表示一直都不曾觉得，与句意中的“从未有过的感受”相符。", "互相": "语义：“互相”要求两方以上彼此做某事，主语只有“我”一个人，不能说“我互相觉得”。", "顺便": "语义：“顺便”指做一件事时附带做另一件事，“觉得难吃”不是能顺便做的动作。", "千万": "语法：“千万”用于劝告、叮嘱，如“千万别…”，不能用来陈述自己的感受。"}, "sentence_index": 6, "correct_answer": "从没"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周五从没一起去图书馆。", "explanation": "这里应该用〈从不〉。从没表示经历，每周重复的习惯要说从不。"}, {"text": "他明年从没去过英国。", "explanation": "这里应该用〈不〉。从没只表示截至目前从未有过的经历，谈将来的打算要用“不”，不能用从没。"}, {"text": "老师每天从没迟到。", "explanation": "这里应该用〈从不〉。从没表示经历，每天的习惯要说从不。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从没做了这么难的题。", "corrected_sentence": "我从没做过这么难的题。", "error_description": "错误：“做了”用“了”表示动作已完成，与“从没”表示从未有过的经历相矛盾。正确：“做过”，“过”表示曾经有过的经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里的同学从没在早自习上迟到着。", "corrected_sentence": "班里的同学从没在早自习上迟到过。", "error_description": "错误：“迟到着”，用了“着”表示持续状态。正确：“迟到过”，“从没”表示从未有过的经历，动词后要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fad33c3-bd75-4bbc-be29-393182ed23fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "必定是一定会这样，没有别的可能。", "primary_collocate": null, "pronunciation": "bì dìng", "ipa": "pi˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "天这么黑，又起风了，必定要下大雨。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的车还在楼下，人必定在家。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯亮着，他必定还没睡。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重要的会，经理必定会参加。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天练习六小时，比赛时必定能拿好成绩。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得这么有信心，这件事必定没问题。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他笑得那么开心，必定是考了好成绩。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵得很厉害，他们必定会迟到。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子这么安静，必定在偷偷玩手机。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店人这么多，菜必定很好吃。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话人根据已有的情况，肯定地推断某事一定会发生或一定是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必定", "is_correct": true, "explanation": "正确。“必定”表示根据眼前的天气情况推断一定会下大雨，符合语境。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，这里没有否定，“根本要下大雨”不通。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯的情况，不能用来推断眼前的将来大雨，“从来要下大雨”也不通。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于“千万不要／千万别”等祈使句，不能说“千万要下大雨”。"}], "explanations": {"必定": "正确。“必定”表示根据眼前的天气情况推断一定会下大雨，符合语境。", "根本": "搭配：“根本”多与否定词连用，这里没有否定，“根本要下大雨”不通。", "从来": "语义：“从来”表示一贯的情况，不能用来推断眼前的将来大雨，“从来要下大雨”也不通。", "千万": "搭配：“千万”多用于“千万不要／千万别”等祈使句，不能说“千万要下大雨”。"}, "sentence_index": 0, "correct_answer": "必定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你们必定按时交作业吗？", "explanation": "这里应该用〈一定〉。“必定”是肯定性副词，用于疑问句语气不合，问句中应说“一定”。"}, {"text": "我不确定他会不会来，他必定会来。", "explanation": "这里应该用〈或许〉。前句表示说话人没有把握，“必定”表示十分肯定，与语境矛盾。"}, {"text": "没想到他必定考上了大学。", "explanation": "这里应该用〈竟然〉。“竟然”表示出乎意料，“必定”表示事先已有把握，与“没想到”的意外语气相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必定", "is_correct": true, "explanation": "正确。“必定”表示根据“笑得很开心”推断一定考了好成绩，符合语境。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”表示本人动手，不能用来推断结果，“亲自是考了好成绩”不通。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示专门为某事而做，不能用来推断结果，“特意是考了好成绩”不通。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与由笑容推断出的结果不符。"}], "explanations": {"必定": "正确。“必定”表示根据“笑得很开心”推断一定考了好成绩，符合语境。", "亲自": "语义：“亲自”表示本人动手，不能用来推断结果，“亲自是考了好成绩”不通。", "特意": "语义：“特意”表示专门为某事而做，不能用来推断结果，“特意是考了好成绩”不通。", "仍然": "语义：“仍然”表示状态延续，与由笑容推断出的结果不符。"}, "sentence_index": 6, "correct_answer": "必定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从没去过那家店，也没听人说过，它的菜必定很好吃。", "explanation": "这里应该用〈也许〉。说话人既没去过也没听说过，没有任何根据，“必定”表示有根据的十分肯定的推断，与语境不合。"}, {"text": "那家店的菜必定好吃，我不确定。", "explanation": "这里应该用〈不一定〉。“不一定”表示不能确定，说话人只是猜测，“必定”表示确定，语义相反。"}, {"text": "他偶尔来这家店吃饭，必定每次都来。", "explanation": "这里应该用〈不一定〉。“偶尔”与“每次都来”矛盾，“必定”表示确定，应改为“不一定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天很必定会来。", "corrected_sentence": "他明天必定会来。", "error_description": "程度副词用错：“必定”是副词，不能被“很”修饰，应去掉“很”，说“必定会来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的会议，他必定会不缺席。", "corrected_sentence": "明天的会议，他必定不会缺席。", "error_description": "语序错误：否定词“不”应放在助动词“会”之前，说“不会缺席”，不能说“会不缺席”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一定；必然。", "primary_collocate": null, "pronunciation": "bì dìng", "ipa": "pi˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "只要努力，成功必定属于你。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不好好学习，考试必定不及格。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天一到，花必定会开。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谎话说多了，别人必定会发现。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有水，植物必定会死。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事不认真，必定会出错。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法太危险，必定不会成功。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天天锻炼，身体必定会越来越好。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天过去，春天必定会来。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这样骄傲下去，必定会输。", "target_word": "必定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按事理或规律，某种结果必然出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0979d30-f37e-4aca-8dc4-51c8b00cb872') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必定", "is_correct": true, "explanation": "正确。“必定”表示按道理努力的人一定会成功，符合语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“只要努力”的假设和将来含义矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚刚发生，不能和“只要努力”的假设搭配。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与否定词连用，这里没有否定，句子不通。"}], "explanations": {"必定": "正确。“必定”表示按道理努力的人一定会成功，符合语境。", "已经": "语义：“已经”表示已经发生，与“只要努力”的假设和将来含义矛盾。", "刚刚": "语义：“刚刚”表示刚刚发生，不能和“只要努力”的假设搭配。", "根本": "搭配：“根本”多与否定词连用，这里没有否定，句子不通。"}, "sentence_index": 0, "correct_answer": "必定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生必定遵守校规吗？", "explanation": "这里应该用〈一定〉。“必定”是肯定性副词，用于疑问句语气不合，问句中应说“一定”。"}, {"text": "我们必定遇见了老师。", "explanation": "这里应该用〈碰巧〉。“碰巧”表示偶然，“必定”表示按规律一定会发生，不能用于偶然的事情。"}, {"text": "没想到他必定考上了大学。", "explanation": "这里应该用〈竟然〉。“竟然”表示出乎意料，“必定”表示事先已有把握，语气不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必定", "is_correct": true, "explanation": "正确。“必定不会成功”表示按情况推断结果一定不成功，符合语境。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“太危险”所推出的必然结果不合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，不能用来推断这种将来的结果。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，不能用来推断将来的结果。"}], "explanations": {"必定": "正确。“必定不会成功”表示按情况推断结果一定不成功，符合语境。", "偶尔": "语义：“偶尔”表示不常发生，与“太危险”所推出的必然结果不合。", "刚刚": "语义：“刚刚”指刚发生的事，不能用来推断这种将来的结果。", "曾经": "语义：“曾经”指过去的经历，不能用来推断将来的结果。"}, "sentence_index": 6, "correct_answer": "必定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在超市必定碰到了老同学。", "explanation": "这里应该用〈偶然〉。在超市碰到老同学是偶然的事，“必定”表示按事理一定会发生，不能用于偶然事件。"}, {"text": "他这样骄傲下去，必定会输，但也有可能赢。", "explanation": "这里应该用〈大概〉。“必定”表示一定会发生，后句说有可能赢，表示未必，前后语义矛盾。"}, {"text": "他偶尔骄傲，有时也会赢，但必定会输。", "explanation": "这里应该用〈不一定〉。“必定”表示一定会发生，与句中有时会赢的情况不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样做，结果很必定会失败。", "corrected_sentence": "这样做，结果必定会失败。", "error_description": "程度副词用错：“必定”是副词，不能被“很”修饰，应去掉“很”，说“必定会失败”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这样努力下去，你也不必定会成功。", "corrected_sentence": "这样努力下去，你也不一定会成功。", "error_description": "否定用错：“必定”一般不受“不”否定，不说“不必定”；表示“未必”应说“不一定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2a2120-9236-4d00-bdd4-7a67e1a835fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
