INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性教育是教小朋友和大人怎么了解自己的身体、怎么保护自己。", "primary_collocate": null, "pronunciation": "xìng jiào yù", "ipa": "ɕiŋ˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 3, "sentences": [{"text": "妈妈给五岁的女儿上了第一堂性教育课。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性教育教我们怎么保护自己。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园里也可以开展性教育。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一本讲性教育的小书。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问起身体的事，就是性教育的好机会。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师说，性教育很重要。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性教育让孩子知道别人不能乱碰自己。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人也需要学一点性教育。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给孩子讲性教育时一点也不害羞。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好性教育，孩子才会更安全。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "教人了解自己的身体、学会保护自己的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性教育", "is_correct": true, "explanation": "正确。“第一堂……课”后接课程名，且适合五岁孩子的启蒙内容。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是金融产品，不适合作为五岁孩子的“第一堂课”内容。"}, {"text": "微积分", "is_correct": false, "explanation": "语义：微积分是高等数学，五岁孩子学不了，不会是她的“第一堂课”。"}, {"text": "驾照", "is_correct": false, "explanation": "语义：驾照需满十八岁才能考取，与五岁孩子的“第一堂课”不合。"}], "explanations": {"性教育": "正确。“第一堂……课”后接课程名，且适合五岁孩子的启蒙内容。", "股票": "语义：股票是金融产品，不适合作为五岁孩子的“第一堂课”内容。", "微积分": "语义：微积分是高等数学，五岁孩子学不了，不会是她的“第一堂课”。", "驾照": "语义：驾照需满十八岁才能考取，与五岁孩子的“第一堂课”不合。"}, "sentence_index": 0, "correct_answer": "性教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子每天要吃三顿性教育。", "explanation": "这里应该用〈饭〉。“性教育”是抽象的教育内容，不能吃，也不能说“吃三顿”。"}, {"text": "我家的院子里种了三棵性教育。", "explanation": "这里应该用〈树〉。“性教育”是教育内容，不是植物，不能用“棵”计量。"}, {"text": "他用性教育给房子刷了一遍油漆。", "explanation": "这里应该用〈刷子〉。“性教育”是教育活动，不是工具，不能用来刷油漆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性教育", "is_correct": true, "explanation": "正确。主语是能让孩子获得知识的教育活动。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不能让孩子了解身体隐私方面的知识。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来提醒时间，无法让孩子了解这件事。"}, {"text": "外貌", "is_correct": false, "explanation": "搭配：“让孩子知道”的主语应是能传递知识的人或事，“外貌”无法完成这一动作。"}], "explanations": {"性教育": "正确。主语是能让孩子获得知识的教育活动。", "足球": "语义：足球不能让孩子了解身体隐私方面的知识。", "闹钟": "语义：闹钟只用来提醒时间，无法让孩子了解这件事。", "外貌": "搭配：“让孩子知道”的主语应是能传递知识的人或事，“外貌”无法完成这一动作。"}, "sentence_index": 6, "correct_answer": "性教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一件性教育。", "explanation": "这里应该用〈衣服〉。“性教育”是抽象的教育活动，不能购买，也不能用“件”计量。"}, {"text": "我们在河边钓性教育。", "explanation": "这里应该用〈鱼〉。“性教育”不能钓，只能用于教育。"}, {"text": "我们在体育课上踢性教育。", "explanation": "这里应该用〈足球〉。“性教育”是教育内容，不能用脚踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每周都给女儿吃性教育。", "corrected_sentence": "妈妈每周都给女儿讲性教育。", "error_description": "“性教育”与动词“吃”搭配不当，应说“讲性教育”（“讲”表示传授内容）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的一本性教育课很受欢迎。", "corrected_sentence": "学校的一门性教育课很受欢迎。", "error_description": "“性教育课”是课程，量词应用“门”，不用“本”（“本”用于书籍）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
