INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有关人体生理、性知识和性道德的教育。", "primary_collocate": null, "pronunciation": "xìng jiào yù", "ipa": "ɕiŋ˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 3, "sentences": [{"text": "学校从初中开始开设性教育课。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性教育应该包括生理知识和道德。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家都重视青少年的性教育。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，性教育越早越好。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是给中学生看的性教育读物。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生到学校讲了一节性教育课。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性教育能帮助青少年了解自己的身体。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在性教育课上讲了不少知识。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会对性教育的看法慢慢变了。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长也要参加学校的性教育活动。", "target_word": "性教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "关于人体生理、性知识和性道德的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性教育", "is_correct": true, "explanation": "正确。“开设……课”后接课程名，“性教育”本身可以作为一门课程的名称。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是课程，不能“开设”。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：“开设”的对象是课程，“游泳池”是场所，不能说“开设游泳池课”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是学科，无法作为课程名称。"}], "explanations": {"性教育": "正确。“开设……课”后接课程名，“性教育”本身可以作为一门课程的名称。", "感冒": "语义：“感冒”是疾病，不是课程，不能“开设”。", "游泳池": "搭配：“开设”的对象是课程，“游泳池”是场所，不能说“开设游泳池课”。", "石头": "语义：“石头”不是学科，无法作为课程名称。"}, "sentence_index": 0, "correct_answer": "性教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里炒了一盘性教育。", "explanation": "这里应该用〈菜〉。“性教育”是教育内容，不能炒，也不能用“盘”计量。"}, {"text": "学校新开了一座性教育。", "explanation": "这里应该用〈楼〉。“性教育”是教育内容，不是建筑，不能用“座”计量。"}, {"text": "他是我们班的性教育。", "explanation": "这里应该用〈老师〉。“性教育”指教育内容或活动，不指人，不能把它当作人来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性教育", "is_correct": true, "explanation": "正确。主语是能传授知识的教育活动，能帮助青少年了解身体。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子与了解身体无关，不能帮助青少年认识自己的身体。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：红绿灯是交通信号，与了解身体无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“了解自己的身体”的主语应是人或教育活动，“冰箱”不能与“帮助……了解”搭配。"}], "explanations": {"性教育": "正确。主语是能传授知识的教育活动，能帮助青少年了解身体。", "鞋子": "语义：鞋子与了解身体无关，不能帮助青少年认识自己的身体。", "红绿灯": "语义：红绿灯是交通信号，与了解身体无关。", "冰箱": "搭配：“了解自己的身体”的主语应是人或教育活动，“冰箱”不能与“帮助……了解”搭配。"}, "sentence_index": 6, "correct_answer": "性教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一双性教育。", "explanation": "这里应该用〈鞋〉。“性教育”是抽象的教育活动，不能购买，也不能用“双”计量。"}, {"text": "我每天早上喝一杯性教育。", "explanation": "这里应该用〈牛奶〉。“性教育”不能饮用，“喝”的对象应是饮品。"}, {"text": "医生用尺子量了一下性教育的长度。", "explanation": "这里应该用〈身高〉。“性教育”是抽象的教育活动，没有长度，不能用尺子量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校每周都上一本性教育课。", "corrected_sentence": "我们学校每周都上一堂性教育课。", "error_description": "“性教育课”是课程，量词应用“堂”或“门”，不用“本”（“本”用于书籍）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师每周都在学校吃性教育课。", "corrected_sentence": "老师每周都在学校讲性教育课。", "error_description": "“性教育课”是课程，与动词“吃”搭配不当，应说“讲性教育课”（“讲”表示传授内容）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
