INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98825, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "成性是一件事做多了，变成改不掉的习惯。", "primary_collocate": null, "pronunciation": "chéng xìng", "ipa": "tʂʰɤŋ˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他撒谎成性，没有人再相信他。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟懒惰成性，每天都不想做事。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赌博成性，把家里的钱都输光了。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人吹牛成性，大家都不太信他。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抱怨成性，遇到小事也要说半天。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李迟到成性，老师说了很多次也没用。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝酒成性，身体越来越差。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子偷东西成性，爸爸很担心。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拖延成性，作业总是最后一天才写。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他懒散成性，连周末也不出门。", "target_word": "成性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "坏习惯做多了变成改不掉的毛病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e7f192b-be0b-4077-9581-3be7d265068c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成性", "is_correct": true, "explanation": "正确。成性（chéng xìng）指一件事做多了，变成改不掉的习惯。"}, {"text": "成型", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，成型指形成一定的形状。"}, {"text": "成形", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，成形指事物形成某种形状。"}, {"text": "成像", "is_correct": false, "explanation": "xiàng 与 xìng 韵母不同（ang 与 ing），成像指形成影像。"}, {"text": "诚信", "is_correct": false, "explanation": "xìn 没有 ng 韵尾，与 xìng 韵母不同（in 与 ing），诚信指诚实守信。"}], "explanations": {"成性": "正确。成性（chéng xìng）指一件事做多了，变成改不掉的习惯。", "成型": "xíng（第二声）与 xìng（第四声）声调不同，成型指形成一定的形状。", "成形": "xíng（第二声）与 xìng（第四声）声调不同，成形指事物形成某种形状。", "成像": "xiàng 与 xìng 韵母不同（ang 与 ing），成像指形成影像。", "诚信": "xìn 没有 ng 韵尾，与 xìng 韵母不同（in 与 ing），诚信指诚实守信。"}, "sentence_index": null, "correct_answer": "成性"}, "level_3": {"options": [{"text": "成性", "is_correct": true, "explanation": "正确。“撒谎成性”指撒谎已成习惯、改不掉，与后文“没有人再相信他”相符。"}, {"text": "戒掉", "is_correct": false, "explanation": "配价：“戒掉”要带宾语（戒掉撒谎），“撒谎戒掉”结构不成立。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指到某处看一看，与“撒谎”无关，句子说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“撒谎”和“游泳”不能连用，“撒谎游泳”没有意义。"}], "explanations": {"成性": "正确。“撒谎成性”指撒谎已成习惯、改不掉，与后文“没有人再相信他”相符。", "戒掉": "配价：“戒掉”要带宾语（戒掉撒谎），“撒谎戒掉”结构不成立。", "参观": "语义：“参观”指到某处看一看，与“撒谎”无关，句子说不通。", "游泳": "搭配：“撒谎”和“游泳”不能连用，“撒谎游泳”没有意义。"}, "sentence_index": 0, "correct_answer": "成性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天刚撒了一次谎，就撒谎成性了。", "explanation": "用法错误：这里把〈成性〉误用成了“做过一次就算定型”的意思。成性指长期重复后形成、改不掉的习惯，只撒过一次谎谈不上成性。"}, {"text": "他终于成性了，成了一名著名作家。", "explanation": "意思错误：成性指习惯形成后改不掉，没有“成功”的意思，这里不能这样用。"}, {"text": "天气一天比一天暖和，暖和成性了。", "explanation": "主语错误：成性多用于人的习惯或毛病，不能用来描写天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成性", "is_correct": true, "explanation": "正确。“喝酒成性”指喝酒已成习惯，因此身体越来越差。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，与“喝酒”没有关系，句子说不通。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”指印刷发行作品，不能说“喝酒出版”。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带宾语（修理什么），“喝酒修理”句子不完整。"}], "explanations": {"成性": "正确。“喝酒成性”指喝酒已成习惯，因此身体越来越差。", "种植": "语义：“种植”指栽种植物，与“喝酒”没有关系，句子说不通。", "出版": "搭配：“出版”指印刷发行作品，不能说“喝酒出版”。", "修理": "配价：“修理”需要带宾语（修理什么），“喝酒修理”句子不完整。"}, "sentence_index": 6, "correct_answer": "成性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒以后咳嗽成性了，过几天就好了。", "explanation": "搭配错误：〈成性〉指长期重复形成、改不掉的习惯，感冒引起的咳嗽是暂时症状，不能用成性来说。"}, {"text": "他这次考试作弊成性了，只作弊了一次。", "explanation": "用法错误：〈成性〉指长期重复后形成、改不掉的习惯，只发生过一次，谈不上成性。"}, {"text": "他越来越成性了，做事也稳重了。", "explanation": "混淆：这里应用〈成熟〉。成性指不良习惯形成，不表示人变得成熟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他健忘的成性，常常忘带钥匙。", "corrected_sentence": "他健忘成性，常常忘带钥匙。", "error_description": "错误在“健忘”和“成性”之间多了“的”。“健忘成性”中“成性”不能用“的”隔开，正确形式为“健忘成性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她马虎成性过，做作业总是出错。", "corrected_sentence": "她马虎成性，做作业总是出错。", "error_description": "错误在“成性”后多了“过”。“成性”表示习惯已经形成的持续状态，不能用“过”表示经历；正确形式为“马虎成性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130b44fd-43a5-4eae-8ae9-c3e17634b06e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
