INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "房屋的价格。", "primary_collocate": null, "pronunciation": "fáng jià", "ipa": "faŋ˧˥ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "学校附近的房价不便宜。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的房价比小城市高。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的地段房价也高。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说房价又涨了。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价和房子大小有关系。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房以前，先了解一下房价。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，北京的房价变化很大。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家想让房价稳下来。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁旁边的房价更高。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行工作，常看房价。", "target_word": "房价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "房价：房屋的价格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房价", "is_correct": true, "explanation": "正确：“房价”指房屋的价格，与“学校附近的……不便宜”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以用“便宜”来描述的东西。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“不便宜”不能用来描述“寿命”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是商品，不能说便宜或不便宜。"}], "explanations": {"房价": "正确：“房价”指房屋的价格，与“学校附近的……不便宜”相合。", "天气": "语义：天气不是可以用“便宜”来描述的东西。", "寿命": "搭配：“不便宜”不能用来描述“寿命”。", "心情": "语义：心情不是商品，不能说便宜或不便宜。"}, "sentence_index": 0, "correct_answer": "房价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套公寓的房价每月两千元。", "explanation": "这里应该用〈房租〉。按月付的钱要说〈房租〉，房价指买房子的价格。"}, {"text": "这件衣服的房价很合理。", "explanation": "这里应该用〈售价〉。房价只用于房屋，衣服的价格要说〈售价〉。"}, {"text": "他的房价很聪明。", "explanation": "语义：这里把房价当成了可以用来形容人的性质，但房价只指房屋的价钱，不能形容人聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房价", "is_correct": true, "explanation": "正确：“房价”是北京每年变化的对象，与“这几年，北京的……变化很大”相合。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐是调味品，不会说“北京的盐”在这几年变化很大。"}, {"text": "酒量", "is_correct": false, "explanation": "语义：酒量是个人能喝多少酒的能力，不能说“北京的酒量”，与“北京的……变化很大”不相合。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是人的生理活动，不能用来描述一个城市的变化。"}], "explanations": {"房价": "正确：“房价”是北京每年变化的对象，与“这几年，北京的……变化很大”相合。", "盐": "语义：盐是调味品，不会说“北京的盐”在这几年变化很大。", "酒量": "语义：酒量是个人能喝多少酒的能力，不能说“北京的酒量”，与“北京的……变化很大”不相合。", "呼吸": "语义：呼吸是人的生理活动，不能用来描述一个城市的变化。"}, "sentence_index": 6, "correct_answer": "房价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一共买了三处房价。", "explanation": "这里应该用〈房屋〉。买的是房子，房价只指价格。"}, {"text": "我把房价贴在了冰箱上。", "explanation": "语义：这里把房价当成了可以贴上去的具体纸张或标签，但房价只是价格，不能贴在冰箱上。"}, {"text": "这个房价有三个月大。", "explanation": "语义：这里把房价当成了有年龄的具体事物，但房价是价格，不能说有多大年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年房价一直涨了。", "corrected_sentence": "这几年房价一直在涨。", "error_description": "“一直”表示动作持续，要用“在”，不能用“了”，应说“房价一直在涨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "北京的房价比上海多。", "corrected_sentence": "北京的房价比上海高。", "error_description": "形容词错误：比较房价高低要用“高”，“多”表示数量，不能用于比较价格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
