INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手册是一本小小的书，告诉你怎么做一件事。", "primary_collocate": null, "pronunciation": "shǒu cè", "ipa": "ʂoʊ˨˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "洗衣机的手册告诉我怎么用它。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我照着手册一步一步装好了柜子。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手册教你怎么种花。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电视时，盒子里有一本手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会用相机，就去看手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手册上有很多图，一看就懂。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份手册说明了怎么做蛋糕。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不会装电脑？打开手册看看。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手册只有十页，很容易读完。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看着手册，学做纸飞机。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "使用手册", "label": "复合"}], "register": "中性", "sense_fingerprint": "教人一步一步做某件事的小书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手册", "is_correct": true, "explanation": "手册（shǒu cè）：教人一步一步做事的小书。"}, {"text": "首次", "is_correct": false, "explanation": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是第一次。"}, {"text": "守则", "is_correct": false, "explanation": "zé（第二声）与 cè（第四声）声母不同（z 与 c），意思是规章制度。"}, {"text": "受测", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受测试。"}], "explanations": {"手册": "手册（shǒu cè）：教人一步一步做事的小书。", "首次": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是第一次。", "守则": "zé（第二声）与 cè（第四声）声母不同（z 与 c），意思是规章制度。", "受测": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受测试。"}, "sentence_index": null, "correct_answer": "手册"}, "level_3": {"options": [{"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱讲做菜的方法，不讲洗衣机怎么用。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图标示路线和位置，不能告诉我怎么用洗衣机。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“洗衣机的”后面一般接部件或说明类名词，不接“老师”。"}, {"text": "手册", "is_correct": true, "explanation": "手册：讲解操作步骤的小书，能告诉人怎么用洗衣机。"}], "explanations": {"菜谱": "语义：菜谱讲做菜的方法，不讲洗衣机怎么用。", "地图": "语义：地图标示路线和位置，不能告诉我怎么用洗衣机。", "老师": "搭配：“洗衣机的”后面一般接部件或说明类名词，不接“老师”。", "手册": "手册：讲解操作步骤的小书，能告诉人怎么用洗衣机。"}, "sentence_index": 0, "correct_answer": "手册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在手册里写下了今天的心情。", "explanation": "这里应该用〈日记〉。手册是讲解操作步骤的小书，写心情要用〈日记〉。"}, {"text": "周末我把旅行照片贴进手册里。", "explanation": "这里应该用〈相册〉。手册是讲解操作的书，贴照片要用〈相册〉。"}, {"text": "诗人把新写的诗收进了手册。", "explanation": "这里应该用〈诗集〉。手册讲解操作步骤，收录诗歌要用〈诗集〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜单", "is_correct": false, "explanation": "语义：菜单列出可点的菜品，不讲做法，不能说明怎么做蛋糕。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单记录金额，与做蛋糕无关。"}, {"text": "合同", "is_correct": false, "explanation": "语义：合同写的是双方约定的条款，不会说明怎么做蛋糕。"}, {"text": "手册", "is_correct": true, "explanation": "手册：讲解操作的小书，能说明做蛋糕的步骤。"}], "explanations": {"菜单": "语义：菜单列出可点的菜品，不讲做法，不能说明怎么做蛋糕。", "账单": "语义：账单记录金额，与做蛋糕无关。", "合同": "语义：合同写的是双方约定的条款，不会说明怎么做蛋糕。", "手册": "手册：讲解操作的小书，能说明做蛋糕的步骤。"}, "sentence_index": 6, "correct_answer": "手册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我买了一块手册。", "explanation": "量词用错：手册是装订成册的书，应用〈本〉，〈块〉用于块状的东西。"}, {"text": "客厅的墙上挂着一幅手册。", "explanation": "量词用错：〈幅〉用于字画、图画，手册应用〈本〉。"}, {"text": "书架上摆着一张手册。", "explanation": "量词用错：〈张〉多用于平面的东西，手册是书，应用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈这本手册收进了抽屉。", "corrected_sentence": "妈妈把这本手册收进了抽屉。", "error_description": "错误：“妈妈这本手册收进了抽屉”，应为“妈妈把这本手册收进了抽屉”。“这本手册”是“收进”的受事，要用“把”提到动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一本能教人组装地手册。", "corrected_sentence": "他买了一本能教人组装的手册。", "error_description": "错误：“组装地手册”，应为“组装的手册”。“地”修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
