INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供随时查阅的小册子。", "primary_collocate": null, "pronunciation": "shǒu cè", "ipa": "ʂoʊ˨˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这本手册很薄，可以放在口袋里。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，先看看使用手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发给每个新同事一本员工手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我随身带着一本旅行手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手册里有电话号码，你查一下。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他翻开手册，找到了那一页。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手册的封面是蓝色的。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手册的字很小，奶奶看不清。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的学生手册上写着上课时间。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，老师给我们发了一份手册。", "target_word": "手册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "使用手册", "label": "复合"}], "register": "中性", "sense_fingerprint": "可随身携带、随时翻查的小册子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手册", "is_correct": true, "explanation": "手册（shǒu cè）：供随时查阅的小册子。"}, {"text": "首次", "is_correct": false, "explanation": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是第一次。"}, {"text": "守则", "is_correct": false, "explanation": "zé（第二声）与 cè（第四声）声母不同（z 与 c），意思是规章制度。"}, {"text": "受测", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受测试。"}], "explanations": {"手册": "手册（shǒu cè）：供随时查阅的小册子。", "首次": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是第一次。", "守则": "zé（第二声）与 cè（第四声）声母不同（z 与 c），意思是规章制度。", "受测": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受测试。"}, "sentence_index": null, "correct_answer": "手册"}, "level_3": {"options": [{"text": "百科全书", "is_correct": false, "explanation": "体貌：百科全书篇幅很大，通常很厚，不能说“很薄”，也放不进口袋。"}, {"text": "法典", "is_correct": false, "explanation": "语义：法典是大部头的法律文本，放不进口袋。"}, {"text": "手册", "is_correct": true, "explanation": "手册：供随时查阅的小册子，很薄，可以放进口袋。"}, {"text": "年鉴", "is_correct": false, "explanation": "语义：年鉴是逐年汇编的大部头资料，与“很薄”“放在口袋里”相矛盾。"}], "explanations": {"百科全书": "体貌：百科全书篇幅很大，通常很厚，不能说“很薄”，也放不进口袋。", "法典": "语义：法典是大部头的法律文本，放不进口袋。", "手册": "手册：供随时查阅的小册子，很薄，可以放进口袋。", "年鉴": "语义：年鉴是逐年汇编的大部头资料，与“很薄”“放在口袋里”相矛盾。"}, "sentence_index": 0, "correct_answer": "手册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在手册里写下心事。", "explanation": "这里应该用〈日记〉。手册是供随时查阅的小册子，写心事要用〈日记〉。"}, {"text": "我们把毕业照贴在手册里。", "explanation": "这里应该用〈相册〉。手册是供查阅的小册子，贴照片要用〈相册〉。"}, {"text": "这本手册讲的是一个少年的冒险故事，我看了三个晚上才看完。", "explanation": "这里应该用〈小说〉。手册是供随时查阅的小册子，讲完整的故事要用〈小说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流没有封面，“封面是蓝色的”说不通。"}, {"text": "馒头", "is_correct": false, "explanation": "语义：馒头是食物，不会有封面。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“封面”多用于书本、杂志等印刷品，不用于冰箱。"}, {"text": "手册", "is_correct": true, "explanation": "手册：装订成册的小书，有封面，“封面是蓝色的”成立。"}], "explanations": {"河流": "语义：河流没有封面，“封面是蓝色的”说不通。", "馒头": "语义：馒头是食物，不会有封面。", "冰箱": "搭配：“封面”多用于书本、杂志等印刷品，不用于冰箱。", "手册": "手册：装订成册的小书，有封面，“封面是蓝色的”成立。"}, "sentence_index": 6, "correct_answer": "手册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一张手册，放进书包里。", "explanation": "量词用错：手册是装订成册的书，应用〈本〉，不用〈张〉。"}, {"text": "我买了一片手册，放进书包里。", "explanation": "量词用错：〈片〉用于薄片状的东西，手册应用〈本〉。"}, {"text": "我买了一只手册，放进书包里。", "explanation": "量词用错：〈只〉多用于动物或成对物品中的一个，手册应用〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸给我一本随身携带地手册。", "corrected_sentence": "爸爸给我一本随身携带的手册。", "error_description": "错误：“携带地手册”，应为“携带的手册”。修饰名词要用“的”，“地”用来修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手册放回了书架上。", "corrected_sentence": "我把手册放回了书架上。", "error_description": "错误：“我手册放回了书架上”，应为“我把手册放回了书架上”。“手册”是“放回”的受事，要用“把”提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
