INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98845, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按摩是用手在身体上推一推、按一按，让人舒服。", "primary_collocate": null, "pronunciation": "àn mó", "ipa": "an⁵¹ mwo³⁵", "syllable_count": 2, "sentences": [{"text": "我肩膀很酸，请你帮我按摩一下。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天晚上给爸爸按摩背。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太累，周末去店里按摩。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生教我怎么按摩小腿。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶腿疼，我常常给她按摩。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的师傅按摩得很舒服。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭的时候，妈妈轻轻按摩他的肚子。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脖子不舒服，我来按摩一下吧。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友按摩了十分钟，手都酸了。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她按摩过很多客人，手法很好。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "按摩了", "label": "体标"}, {"form": "按摩过", "label": "体标"}, {"form": "按摩按摩", "label": "重叠"}, {"form": "按摩椅", "label": "复合"}, {"form": "按摩师", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手推按身体，让人舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洁，不能缓解肩膀的酸痛。"}, {"text": "按摩", "is_correct": true, "explanation": "正确：“按摩”是用手推按身体，符合肩膀酸、请人帮忙的语境。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理物品，不能用于人的身体。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”是自己做的运动，不说“帮我锻炼”。"}], "explanations": {"洗": "语义：“洗”是清洁，不能缓解肩膀的酸痛。", "按摩": "正确：“按摩”是用手推按身体，符合肩膀酸、请人帮忙的语境。", "修": "语义：“修”指修理物品，不能用于人的身体。", "锻炼": "搭配：“锻炼”是自己做的运动，不说“帮我锻炼”。"}, "sentence_index": 0, "correct_answer": "按摩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我按摩了一下门铃。", "explanation": "这里应该用〈按〉。按摩只用于人的身体，按门铃要用“按”。"}, {"text": "妈妈在按摩面团。", "explanation": "这里应该用〈揉〉。按摩的对象是人体，揉面团要用“揉”。"}, {"text": "他用抹布按摩桌子。", "explanation": "这里应该用〈擦〉。按摩的对象是人体，擦桌子要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按摩", "is_correct": true, "explanation": "正确：“按摩”用手轻轻推按身体，符合孩子哭、妈妈安抚的语境。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人送食物，与按摩肚子的动作不符。"}, {"text": "哄", "is_correct": false, "explanation": "配价：“哄”的对象是人，不能直接带“肚子”作宾语。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理物品，不能用于人的身体。"}], "explanations": {"按摩": "正确：“按摩”用手轻轻推按身体，符合孩子哭、妈妈安抚的语境。", "喂": "语义：“喂”是给人送食物，与按摩肚子的动作不符。", "哄": "配价：“哄”的对象是人，不能直接带“肚子”作宾语。", "修": "语义：“修”指修理物品，不能用于人的身体。"}, "sentence_index": 6, "correct_answer": "按摩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在按摩橡皮泥。", "explanation": "这里应该用〈捏〉。按摩的对象是人体，捏橡皮泥要用“捏”。"}, {"text": "他用力按摩了一下盖子。", "explanation": "这里应该用〈压〉。按摩用于人体，压盖子要用“压”。"}, {"text": "我在按摩咖啡。", "explanation": "这里应该用〈冲〉。按摩用于人体，冲咖啡要用“冲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天给爸爸按摩得肩膀。", "corrected_sentence": "妈妈昨天给爸爸按摩了肩膀。", "error_description": "“了”表示动作已完成，应紧跟动词，写作“按摩了肩膀”；“得”引出补语，不能直接接名词宾语，“按摩得肩膀”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给奶奶按摩地很轻。", "corrected_sentence": "她给奶奶按摩得很轻。", "error_description": "“得”应紧跟动词，引出补语，写作“按摩得很轻”；“地”用于状语，不能放在动词后引出补语，应说“按摩得很轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
