INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手在人体上推、按、捏等，以舒缓疲劳。", "primary_collocate": null, "pronunciation": "àn mó", "ipa": "an⁵¹ mwo³⁵", "syllable_count": 2, "sentences": [{"text": "长时间坐着以后，适当按摩可以缓解疲劳。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动后按摩肌肉，能让身体恢复得更快。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士每天为病人按摩手臂和双腿。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常去店里按摩，放松紧张的肩膀。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前按摩脚底，有助于睡得更好。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师傅按摩了三十年，经验很多。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议她每天按摩腰部十分钟。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室的人累了，就互相按摩一下。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按摩头部能让人感到轻松。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她洗完澡后，再按摩一下小腿。", "target_word": "按摩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "按摩了", "label": "体标"}, {"form": "按摩过", "label": "体标"}, {"form": "按摩按摩", "label": "重叠"}, {"form": "按摩椅", "label": "复合"}, {"form": "按摩师", "label": "复合"}], "register": "中性", "sense_fingerprint": "推按捏人体以缓解疲劳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0951d8-de99-4fb1-907c-73c4f740a35d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜会加重疲劳，与“缓解疲劳”的意思相反。"}, {"text": "按摩", "is_correct": true, "explanation": "正确：“按摩”能舒缓疲劳，符合“适当……可以缓解疲劳”的语境。"}, {"text": "加班", "is_correct": false, "explanation": "语义：加班会加重疲劳，与“缓解疲劳”矛盾。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠会加重疲劳，与“缓解疲劳”的意思相反。"}], "explanations": {"熬夜": "语义：熬夜会加重疲劳，与“缓解疲劳”的意思相反。", "按摩": "正确：“按摩”能舒缓疲劳，符合“适当……可以缓解疲劳”的语境。", "加班": "语义：加班会加重疲劳，与“缓解疲劳”矛盾。", "失眠": "语义：失眠会加重疲劳，与“缓解疲劳”的意思相反。"}, "sentence_index": 0, "correct_answer": "按摩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天按摩地板。", "explanation": "这里应该用〈擦〉。按摩的对象是人体，擦地板要用“擦”。"}, {"text": "孩子在按摩泥人。", "explanation": "这里应该用〈捏〉。按摩用于人体，捏泥人要用“捏”。"}, {"text": "医生给他按摩药。", "explanation": "这里应该用〈抹〉。按摩的对象是人体，抹药要用“抹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "语义：“喂”是给人送食物，不能用于按摩腰部。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”搭配衣物，不说“穿腰部”。"}, {"text": "按摩", "is_correct": true, "explanation": "正确：“按摩”是用手推按身体，符合医生建议每天按摩腰部的语境。"}, {"text": "讲", "is_correct": false, "explanation": "配价：“讲”的宾语是话语，不能带“腰部”作宾语。"}], "explanations": {"喂": "语义：“喂”是给人送食物，不能用于按摩腰部。", "穿": "搭配：“穿”搭配衣物，不说“穿腰部”。", "按摩": "正确：“按摩”是用手推按身体，符合医生建议每天按摩腰部的语境。", "讲": "配价：“讲”的宾语是话语，不能带“腰部”作宾语。"}, "sentence_index": 6, "correct_answer": "按摩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个面团要按摩很久才会软。", "explanation": "这里应该用〈揉〉。按摩用于人体，揉面团要用“揉”。"}, {"text": "她每天都按摩茶叶。", "explanation": "这里应该用〈泡〉。按摩用于人体，泡茶叶要用“泡”。"}, {"text": "他把鞋子按摩得很干净。", "explanation": "这里应该用〈刷〉。按摩用于人体，刷鞋子要用“刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天按摩肩膀着。", "corrected_sentence": "他每天按摩肩膀。", "error_description": "体标错误：“着”是动态助词，应紧跟动词，不能放在宾语“肩膀”后面；这里说习惯性动作，不需要“着”，应说“他每天按摩肩膀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她洗完澡后，按摩地很舒服。", "corrected_sentence": "她洗完澡后，按摩得很舒服。", "error_description": "“得”应紧跟动词，引出补语，写作“按摩得很舒服”；“地”用于状语，不能放在动词后引出补语，应说“按摩得很舒服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e3bc48f-1ede-4466-88dc-1f4b95e12531') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
