INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "撤退是离开危险的地方，往后面走。", "primary_collocate": null, "pronunciation": "chè tuì", "ipa": "ʈʂʰɤ˥˩ tʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "火越来越大，大家快撤退！", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到洪水来了，村民马上撤退到山上。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察让人们从危险的地方撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，登山队决定撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家有序地撤退，没有人受伤。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到爆炸声，工人们赶紧撤退了。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山路塌了，我们只能撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发现有蛇，我们慢慢撤退到了安全的地方。", "target_word": "撤退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，营地的人都撤退到了学校里。", "target_word": "撤退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾时，人们要沿着楼梯安全撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤退了", "label": "完成体"}, {"form": "撤退过", "label": "经验体"}], "register": "中性", "sense_fingerprint": "人为避开危险而离开并后退", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撤退", "is_correct": true, "explanation": "撤退指离开危险的地方并往后走，与「火越来越大」「快」的紧急语境一致。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是悠闲的活动，与「火越来越大」的紧急情况相矛盾。"}, {"text": "品尝", "is_correct": false, "explanation": "配价：品尝是及物动词，必须带食物等宾语，这里没有宾语，语义也与火灾不合。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情动作，无法应对正在扩大的火势。"}], "explanations": {"撤退": "撤退指离开危险的地方并往后走，与「火越来越大」「快」的紧急语境一致。", "散步": "语义：散步是悠闲的活动，与「火越来越大」的紧急情况相矛盾。", "品尝": "配价：品尝是及物动词，必须带食物等宾语，这里没有宾语，语义也与火灾不合。", "微笑": "语义：微笑是表情动作，无法应对正在扩大的火势。"}, "sentence_index": 0, "correct_answer": "撤退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司撤退了这个计划。", "explanation": "这里应该用〈撤销〉。撤销指取消计划或决定；撤退只指人或部队从所在地向后离开，不能用于计划。"}, {"text": "他撤退了那句话。", "explanation": "这里应该用〈撤回〉。撤回指收回已经说出的话；撤退不能用于言语。"}, {"text": "他撤退了这次比赛。", "explanation": "这里应该用〈退出〉。退出指离开比赛或组织；撤退不能带比赛作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤退", "is_correct": true, "explanation": "山路塌了，只能离开并往后走，与语境一致。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：山路塌了，跳舞与求生的紧急语境完全不合。"}, {"text": "打球", "is_correct": false, "explanation": "语义：路塌了时打球与求生的语境完全不合。"}, {"text": "购买", "is_correct": false, "explanation": "配价：购买是及物动词，必须带购买对象，这里没有宾语。"}], "explanations": {"撤退": "山路塌了，只能离开并往后走，与语境一致。", "跳舞": "语义：山路塌了，跳舞与求生的紧急语境完全不合。", "打球": "语义：路塌了时打球与求生的语境完全不合。", "购买": "配价：购买是及物动词，必须带购买对象，这里没有宾语。"}, "sentence_index": 6, "correct_answer": "撤退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居民们已经撤退了危险区域。", "explanation": "这里应该用〈撤离〉。撤离可以带处所宾语，表示人员离开某个地方；撤退一般不直接带处所作宾语。"}, {"text": "领导撤退了小王的职务。", "explanation": "这里应该用〈撤职〉。撤职指免去职务；撤退只指人或部队向后离开，不能用于职务。"}, {"text": "服务员撤退了桌上的杯子。", "explanation": "这里应该用〈撤掉〉。撤掉指把东西拿走；撤退指人或军队向后离开，不能带杯子这类物品作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在暴雨中撤退了营地。", "corrected_sentence": "他们在暴雨中撤退到了营地。", "error_description": "“撤退”表示从某处向后离开，离开后到达的地点要用“到”引出。这里漏掉了“到”，应改为“撤退到了营地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从山上撤退上来了。", "corrected_sentence": "他们从山上撤退下来了。", "error_description": "方向补语用错。从山上往下走应该用“下来”，不能用“上来”。应改为“撤退下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻", "is_correct": true, "explanation": "进攻与撤退意思相反：撤退是从阵地向后撤离，进攻是向敌人发起攻击。"}, {"text": "侦察", "is_correct": false, "explanation": "侦察指暗中察看敌情，与撤退不构成反义关系。"}, {"text": "集结", "is_correct": false, "explanation": "集结指部队聚集到一起，与撤退不构成反义关系。"}, {"text": "演习", "is_correct": false, "explanation": "演习指模拟作战的训练，与撤退不构成反义关系。"}], "correct_answer": "进攻", "explanations": {"进攻": "进攻与撤退意思相反：撤退是从阵地向后撤离，进攻是向敌人发起攻击。", "侦察": "侦察指暗中察看敌情，与撤退不构成反义关系。", "集结": "集结指部队聚集到一起，与撤退不构成反义关系。", "演习": "演习指模拟作战的训练，与撤退不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻", "is_correct": true, "explanation": "进攻与撤退意思相反：撤退是从阵地向后撤离，进攻是向敌人发起攻击。"}, {"text": "休整", "is_correct": false, "explanation": "休整指部队休息整顿，与撤退不构成反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造工程，与撤退不构成反义关系。"}, {"text": "巡逻", "is_correct": false, "explanation": "巡逻指来回察看，与撤退不构成反义关系。"}], "correct_answer": "进攻", "explanations": {"进攻": "进攻与撤退意思相反：撤退是从阵地向后撤离，进攻是向敌人发起攻击。", "休整": "休整指部队休息整顿，与撤退不构成反义关系。", "修建": "修建指建造工程，与撤退不构成反义关系。", "巡逻": "巡逻指来回察看，与撤退不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "军队等从原地向后撤离。", "primary_collocate": null, "pronunciation": "chè tuì", "ipa": "ʈʂʰɤ˥˩ tʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "敌人太多，军队只好撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军下令部队连夜撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们守了三天，最后撤退了。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士们一边打一边撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队撤退以后，城里安静下来。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们撤退时把大炮留在了山上。", "target_word": "撤退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队从河边撤退到了城外。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌军撤退过一次，后来又回来了。", "target_word": "撤退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护伤员，连队没有马上撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指挥官看了看地图，决定全军撤退。", "target_word": "撤退", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤退了", "label": "完成体"}, {"form": "撤退过", "label": "经验体"}], "register": "中性", "sense_fingerprint": "军队从阵地向后撤离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90645a6b-93e3-4121-8054-48deb9684cb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撤退", "is_correct": true, "explanation": "敌人太多，军队被迫离开阵地向后撤，与语境一致。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美是称赞，与「敌人太多、只好」这种被迫处境相矛盾。"}, {"text": "设计", "is_correct": false, "explanation": "配价：设计是及物动词，需要设计对象，这里没有宾语，语义也不合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎是迎接，与军队被迫离开的语境相反。"}], "explanations": {"撤退": "敌人太多，军队被迫离开阵地向后撤，与语境一致。", "赞美": "语义：赞美是称赞，与「敌人太多、只好」这种被迫处境相矛盾。", "设计": "配价：设计是及物动词，需要设计对象，这里没有宾语，语义也不合。", "欢迎": "语义：欢迎是迎接，与军队被迫离开的语境相反。"}, "sentence_index": 0, "correct_answer": "撤退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他撤退了这份申请。", "explanation": "这里应该用〈撤回〉。撤回指收回已提交的申请；撤退只指军队或人向后离开，不能用于申请。"}, {"text": "他撤退了这个项目。", "explanation": "这里应该用〈撤销〉。撤销指取消项目；撤退不能用于项目。"}, {"text": "工人们撤退了路边的路障。", "explanation": "这里应该用〈撤去〉。撤去指拿走设施或障碍物；撤退是人或军队向后离开，不能用于路障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撤退", "is_correct": true, "explanation": "军队从河边向后离开到城外，与语境一致。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：军队从河边歌唱到城外，动作与移动的语境不合。"}, {"text": "种植", "is_correct": false, "explanation": "配价：种植是及物动词，需要植物等宾语，这里没有宾语，语义也不合。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：讨论是言语行为，不能表示军队从河边移动到城外。"}], "explanations": {"撤退": "军队从河边向后离开到城外，与语境一致。", "歌唱": "语义：军队从河边歌唱到城外，动作与移动的语境不合。", "种植": "配价：种植是及物动词，需要植物等宾语，这里没有宾语，语义也不合。", "讨论": "语义：讨论是言语行为，不能表示军队从河边移动到城外。"}, "sentence_index": 6, "correct_answer": "撤退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导撤退了那位经理。", "explanation": "这里应该用〈撤职〉。撤职指免去职务；撤退不能用于人作宾语来表示免职。"}, {"text": "工人们撤退了这批设备。", "explanation": "这里应该用〈撤走〉。撤走指把东西拿走；撤退是人或军队向后离开，不能带设备作宾语。"}, {"text": "居民们撤退了危险区域。", "explanation": "这里应该用〈撤离〉。撤离指人员离开某地，可以带处所宾语；撤退一般不直接带处所作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "部队在夜色中悄悄撤退了到山谷。", "corrected_sentence": "部队在夜色中悄悄撤退到了山谷。", "error_description": "补语“到”与“了”的顺序颠倒。撤退后面要先接补语“到”，再接“了”，应说“撤退到了山谷”，不能说“撤退了到山谷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部队在夜里撤退在了山口。", "corrected_sentence": "部队在夜里撤退到了山口。", "error_description": "撤退的终点要用“到”引出，不能用“在”。应改为“撤退到了山口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c5fb969-c06a-4887-a75d-c0f4459c3ded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
