INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98851, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拟定是先把计划想好，写下来。", "primary_collocate": null, "pronunciation": "nǐ dìng", "ipa": "ni˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们先拟定一个学习计划，再开始复习。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师拟定了下个月的旅行路线。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理正在拟定明年的工作安排。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出发前，他拟定好了每天的时间表。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经拟定过三个方案，都写在本子上。", "target_word": "拟定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以前，请你先拟定一份名单。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们一起拟定了班级旅行的预算。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想先拟定目标，再决定怎么做。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生为病人拟定了一份饮食计划。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以前，妈妈拟定了详细的清单。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拟定了", "label": "了体"}, {"form": "拟定过", "label": "过体"}, {"form": "擬定", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把计划、安排、目标先想好并写下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拟定", "is_correct": true, "explanation": "拟定指先把计划想好并写下来，与“先拟定学习计划，再开始复习”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能以“学习计划”为宾语，与“先……再开始复习”的意思无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”搭配“歌”，不能说“唱学习计划”。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”不能以“学习计划”为宾语，与“先想好、写下来”的意思无关。"}], "explanations": {"拟定": "拟定指先把计划想好并写下来，与“先拟定学习计划，再开始复习”相符。", "吃": "语义：“吃”不能以“学习计划”为宾语，与“先……再开始复习”的意思无关。", "唱": "搭配：“唱”搭配“歌”，不能说“唱学习计划”。", "睡": "语义：“睡”不能以“学习计划”为宾语，与“先想好、写下来”的意思无关。"}, "sentence_index": 0, "correct_answer": "拟定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议上她拟定了一个错误。", "explanation": "这里应该用〈发现〉。拟定用于计划、方案，不能拟定“错误”。"}, {"text": "他拟定了老师的建议。", "explanation": "这里应该用〈接受〉。拟定指先想好并写下计划、方案，不能拟定别人提出的建议。"}, {"text": "他拟定了昨天的纪录。", "explanation": "这里应该用〈打破〉。拟定用于计划、方案，不用于纪录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拟定", "is_correct": true, "explanation": "拟定指先把计划想好并写下来，与“同学们一起拟定班级旅行的预算”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能以“预算”为宾语，与“一起”“班级旅行”的语境无关。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”搭配“球”等，不能说“踢预算”。"}, {"text": "戴", "is_correct": false, "explanation": "语义：“戴”用于头、手等，不能以“预算”为宾语。"}], "explanations": {"拟定": "拟定指先把计划想好并写下来，与“同学们一起拟定班级旅行的预算”相符。", "喝": "语义：“喝”不能以“预算”为宾语，与“一起”“班级旅行”的语境无关。", "踢": "搭配：“踢”搭配“球”等，不能说“踢预算”。", "戴": "语义：“戴”用于头、手等，不能以“预算”为宾语。"}, "sentence_index": 6, "correct_answer": "拟定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈拟定了一件毛衣，准备送给我。", "explanation": "这里应该用〈织〉。拟定指先把计划想好并写下来，用于计划、方案，不能用于织成的衣物。"}, {"text": "我拟定了一张照片，准备送给朋友。", "explanation": "这里应该用〈拍〉。拟定用于计划、方案，不能用于拍下来的照片。"}, {"text": "孩子拟定了一只小鸟，放进了笼子。", "explanation": "这里应该用〈养〉。拟定用于计划、方案，不能用来指饲养的小鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板过拟定了下个月的工作计划。", "corrected_sentence": "老板拟定了下个月的工作计划。", "error_description": "体标错误：“过”不能放在动词“拟定”之前；此句表示已完成的动作，应说“拟定了”，去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们拟定过三只旅行路线。", "corrected_sentence": "他们拟定过三条旅行路线。", "error_description": "量词错误：“路线”应用量词“条”，“只”多用于动物，不能用于路线；正确形式为“拟定过三条旅行路线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
