INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98852, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "起草并确定。", "primary_collocate": null, "pronunciation": "nǐ dìng", "ipa": "ni˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "两国代表正在拟定新的合作协议。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司已经拟定了新的工作制度。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "委员会拟定过几份重要的文件。", "target_word": "拟定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同由律师拟定，双方都同意。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校拟定了新的考试规定，下周公布。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府拟定了一个保护河流的办法。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家讨论以后，会议拟定了三条原则。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家们拟定了新的安全标准。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方拟定好条款后，才签了名。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司拟定了员工请假的规则。", "target_word": "拟定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拟定了", "label": "了体"}, {"form": "拟定过", "label": "过体"}, {"form": "擬定", "label": "繁体"}], "register": "书面", "sense_fingerprint": "起草协议、制度、办法等文件并最后确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f855bc-f9f9-401d-a4ac-df0922d74874') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拟定", "is_correct": true, "explanation": "拟定指起草并确定，与“两国代表正在拟定新的合作协议”相符。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开、拆除，与起草合作协议的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以“协议”为宾语。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能以“协议”为宾语，与“两国代表”的语境不符。"}], "explanations": {"拟定": "拟定指起草并确定，与“两国代表正在拟定新的合作协议”相符。", "拆": "语义：“拆”是拆开、拆除，与起草合作协议的意思不符。", "唱": "搭配：“唱”不能以“协议”为宾语。", "喝": "语义：“喝”不能以“协议”为宾语，与“两国代表”的语境不符。"}, "sentence_index": 0, "correct_answer": "拟定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人拟定了那台机器。", "explanation": "这里应该用〈修理〉。拟定指起草或确定文件、方案，不能用来处理机器。"}, {"text": "他拟定了那些旧书。", "explanation": "这里应该用〈扔掉〉。拟定指起草或确定文件、方案，不能用于旧书。"}, {"text": "爱迪生拟定了电灯。", "explanation": "这里应该用〈发明〉。拟定指起草或确定文件、方案，不能用于创造实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拟定", "is_correct": true, "explanation": "拟定指起草并确定，与“会议拟定了三条原则”相符。"}, {"text": "戴", "is_correct": false, "explanation": "语义：“戴”用于头、手等，不能以“原则”为宾语。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”不能搭配“原则”。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下，与会议确定原则的意思不符。"}], "explanations": {"拟定": "拟定指起草并确定，与“会议拟定了三条原则”相符。", "戴": "语义：“戴”用于头、手等，不能以“原则”为宾语。", "踢": "搭配：“踢”不能搭配“原则”。", "吞": "语义：“吞”是咽下，与会议确定原则的意思不符。"}, "sentence_index": 6, "correct_answer": "拟定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈拟定了一个生日蛋糕，准备晚上请客。", "explanation": "这里应该用〈烤〉。拟定指起草并确定文件、制度，不能用于做好的食物。"}, {"text": "他拟定了一幅画，挂在客厅里。", "explanation": "这里应该用〈画〉。拟定指起草并确定文件、制度，不能用于绘画作品。"}, {"text": "孩子拟定了一条鱼，放进了水缸。", "explanation": "这里应该用〈钓〉。拟定指起草并确定文件、制度，不能用于钓到的鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市场部已经拟定了好新的促销方案。", "corrected_sentence": "市场部已经拟定好了新的促销方案。", "error_description": "语序错误：结果补语“好”应紧跟在“拟定”之后，说“拟定好了”，不能说“拟定了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教育局拟定过一台新的入学办法。", "corrected_sentence": "教育局拟定过一个新的入学办法。", "error_description": "量词错误：“办法”应用量词“个”，“台”多用于机器，不能用于办法；正确形式为“拟定过一个新的入学办法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27f81918-abb3-4c1b-a1f0-c68479c10967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
