INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政府官员是在政府里做事的人。", "primary_collocate": null, "pronunciation": "zhèng fǔ guān yuán", "ipa": "ʈʂɤŋ˥˩ fu˨˩˦ kwan˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "这位政府官员每天很早就去上班。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的叔叔是一位政府官员。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位政府官员在会上讲了话。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府官员常常要开会，也要见很多人。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者问了那位政府官员几个问题。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大学毕业后，成了一名政府官员。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几位政府官员坐着汽车来到了学校。", "target_word": "政府官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的政府官员都很关心环境问题。", "target_word": "政府官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是商人，而是一位在市里工作的政府官员。", "target_word": "政府官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们给来参观的政府官员送了花。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "政府官員", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政府官员：在政府里工作、做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府官员", "is_correct": true, "explanation": "正确。「政府官员」指在政府里做事的人，「每天很早就去上班」与此相合。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：「上班」说的是工作，学生应该说「上学」。"}, {"text": "皇帝", "is_correct": false, "explanation": "语域：「皇帝」是古代的君主，不能用来说现代人每天去上班。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：「这位」用于指人，小猫是动物，应该说「这只」。"}], "explanations": {"政府官员": "正确。「政府官员」指在政府里做事的人，「每天很早就去上班」与此相合。", "学生": "搭配：「上班」说的是工作，学生应该说「上学」。", "皇帝": "语域：「皇帝」是古代的君主，不能用来说现代人每天去上班。", "小猫": "语义：「这位」用于指人，小猫是动物，应该说「这只」。"}, "sentence_index": 0, "correct_answer": "政府官员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是这家公司的政府官员。", "explanation": "这里应该用〈职员〉。政府官员指在政府里做事的人，公司的员工不能这样称呼。"}, {"text": "这家超市的政府官员很热情。", "explanation": "这里应该用〈店员〉。政府官员是政府里的人，不会在超市里招呼顾客。"}, {"text": "政府官员每天在厨房里做饭，很辛苦。", "explanation": "这里应该用〈厨师〉。政府官员是在政府里做事的人，不在厨房里做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府官员", "is_correct": true, "explanation": "正确。「几位」指人，政府官员可以坐车来学校。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「几位」指人，石头不能坐汽车，也不能来学校。"}, {"text": "古人", "is_correct": false, "explanation": "语域：「古人」属于古代，不能坐汽车来到现代的学校。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：「几位」和「坐着」只能用于人，鱼不能说「几位」或「坐着汽车」。"}], "explanations": {"政府官员": "正确。「几位」指人，政府官员可以坐车来学校。", "石头": "语义：「几位」指人，石头不能坐汽车，也不能来学校。", "古人": "语域：「古人」属于古代，不能坐汽车来到现代的学校。", "鱼": "搭配：「几位」和「坐着」只能用于人，鱼不能说「几位」或「坐着汽车」。"}, "sentence_index": 6, "correct_answer": "政府官员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的政府官员每天带我们训练。", "explanation": "这里应该用〈教练〉。政府官员是在政府里做事的人，不负责带队训练。"}, {"text": "政府官员正在给病人看病。", "explanation": "这里应该用〈医生〉。政府官员不是给病人治病的人。"}, {"text": "政府官员每天在工地上搬砖。", "explanation": "这里应该用〈工人〉。政府官员是在政府里做事的人，不在工地上搬砖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识两只政府官员。", "corrected_sentence": "我认识两位政府官员。", "error_description": "量词错误：指人的「政府官员」应该用量词「位」，不能用「只」，「只」一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天见了一位政府官员们。", "corrected_sentence": "他昨天见了一位政府官员。", "error_description": "错误在“们”。“们”表示复数，不能与数量词“一位”一起用，应说“一位政府官员”，不能说“一位政府官员们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
