INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在政府机关担任公职的人员。", "primary_collocate": null, "pronunciation": "zhèng fǔ guān yuán", "ipa": "ʈʂɤŋ˥˩ fu˨˩˦ kwan˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "他在政府机关工作，是一名政府官员。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位政府官员已经工作了三十年。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府官员要为市民认真做事。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她爸爸是政府官员，每个星期都要开会。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的政府官员对大家说了几句话。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民们给政府官员写了一封信。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加会议的政府官员有二十多位。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位政府官员把工作做得又快又好。", "target_word": "政府官员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年政府官员，后来去了一家公司。", "target_word": "政府官员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那几位政府官员正在办公室里谈着一件重要的事。", "target_word": "政府官员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "政府官員", "label": "繁体"}], "register": "正式", "sense_fingerprint": "政府官员：在政府机关担任公职的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府官员", "is_correct": true, "explanation": "正确。在政府机关工作、担任公职的人就是政府官员。"}, {"text": "学生", "is_correct": false, "explanation": "语义：「学生」在学校读书，与「在政府机关工作」相矛盾。"}, {"text": "皇帝", "is_correct": false, "explanation": "语域：「皇帝」是古代的君主，与现代机关的工作不合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：「一名」用于人，小猫是动物，应该用「一只」。"}], "explanations": {"政府官员": "正确。在政府机关工作、担任公职的人就是政府官员。", "学生": "语义：「学生」在学校读书，与「在政府机关工作」相矛盾。", "皇帝": "语域：「皇帝」是古代的君主，与现代机关的工作不合。", "小猫": "语义：「一名」用于人，小猫是动物，应该用「一只」。"}, "sentence_index": 0, "correct_answer": "政府官员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的政府官员每天做很多菜。", "explanation": "这里应该用〈厨师〉。政府官员是在政府机关担任公职的人，不在饭店做菜。"}, {"text": "政府官员每天开着出租车在街上拉客人。", "explanation": "这里应该用〈出租车司机〉。政府官员是在政府机关担任公职的人员，不开出租车拉客人。"}, {"text": "政府官员每天背着书包去上学。", "explanation": "这里应该用〈小学生〉。政府官员是工作的人，不会去上学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府官员", "is_correct": true, "explanation": "正确。「参加会议的」可以是政府官员，与「有二十多位」相合。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能参加会议，与「参加会议的」语义不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能参加会议，「位」也不用来计量石头。"}, {"text": "古人", "is_correct": false, "explanation": "语域：「古人」属于古代，与现代的会议场合不合。"}], "explanations": {"政府官员": "正确。「参加会议的」可以是政府官员，与「有二十多位」相合。", "花": "语义：花不能参加会议，与「参加会议的」语义不合。", "石头": "语义：石头不能参加会议，「位」也不用来计量石头。", "古人": "语域：「古人」属于古代，与现代的会议场合不合。"}, "sentence_index": 6, "correct_answer": "政府官员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府官员在超市里收钱。", "explanation": "这里应该用〈收银员〉。政府官员在政府里做事，不在超市里收钱。"}, {"text": "政府官员每天在花园里修剪花草。", "explanation": "这里应该用〈园丁〉。政府官员不是负责修剪花草的人。"}, {"text": "政府官员给顾客剪头发。", "explanation": "这里应该用〈理发师〉。政府官员不是给顾客理发的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的哥哥是一只政府官员。", "corrected_sentence": "他的哥哥是一名政府官员。", "error_description": "量词错误：指人的「政府官员」应该用量词「名」或「位」，「只」用于动物等，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请了一本政府官员来讲课。", "corrected_sentence": "我们请了一位政府官员来讲课。", "error_description": "量词错误：指人的「政府官员」应该用量词「位」，「本」用于书籍，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
