INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "具有教育作用的性质。", "primary_collocate": null, "pronunciation": "jiào yù xìng", "ipa": "tɕjɑʊ˥˩ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这本书的教育性很强。", "target_word": "教育性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师很重视故事的教育性。", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影不能只有娱乐性，也要有教育性。", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电视剧的教育性体现在哪里？", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者想提高这篇文章的教育性。", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "选游戏时，我们要想一想它的教育性。", "target_word": "教育性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目的娱乐性很强，教育性却很弱。", "target_word": "教育性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请专家评一评课本的教育性。", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部动画片的教育性得到了家长的认可。", "target_word": "教育性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长们都很关心玩具的教育性。", "target_word": "教育性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词用法：作品、活动等具有的教育作用这一性质，常作“……的教育性”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教育性", "is_correct": true, "explanation": "“这本书的教育性很强”说书能让人学到东西，符合句意。"}, {"text": "腐蚀性", "is_correct": false, "explanation": "语义：腐蚀性指物质损坏其他物体，书不会有这种性质。"}, {"text": "导电性", "is_correct": false, "explanation": "搭配：导电性说材料能否传电，“这本书的导电性”不成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人或动物的体形，书不说身材。"}], "explanations": {"教育性": "“这本书的教育性很强”说书能让人学到东西，符合句意。", "腐蚀性": "语义：腐蚀性指物质损坏其他物体，书不会有这种性质。", "导电性": "搭配：导电性说材料能否传电，“这本书的导电性”不成立。", "身材": "体貌：身材描述人或动物的体形，书不说身材。"}, "sentence_index": 0, "correct_answer": "教育性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧的教育性有三十斤。", "explanation": "这里误用了〈重量〉的意思。教育性是抽象性质，不能用斤计量，说强弱要用“很强”。"}, {"text": "这家医院的教育性很强，病人都很满意。", "explanation": "这里应该用〈服务质量〉。教育性指作品或活动能让人学到东西的性质，医院的服务好坏要用“服务质量”。"}, {"text": "他的教育性很高，学习成绩也很好。", "explanation": "这里应该用〈学历〉。教育性指作品或活动能让人学到东西的性质，说一个人受教育的程度要用“学历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教育性", "is_correct": true, "explanation": "“教育性却很弱”与前句“娱乐性很强”形成对比，符合句意。"}, {"text": "娱乐性", "is_correct": false, "explanation": "语义：前句已经说“娱乐性很强”，这里再用“娱乐性却很弱”自相矛盾。"}, {"text": "挥发性", "is_correct": false, "explanation": "搭配：挥发性多用于液体、化学品，不说节目的挥发性。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：硬度用于材料、物体，不用于形容节目。"}], "explanations": {"教育性": "“教育性却很弱”与前句“娱乐性很强”形成对比，符合句意。", "娱乐性": "语义：前句已经说“娱乐性很强”，这里再用“娱乐性却很弱”自相矛盾。", "挥发性": "搭配：挥发性多用于液体、化学品，不说节目的挥发性。", "硬度": "搭配：硬度用于材料、物体，不用于形容节目。"}, "sentence_index": 6, "correct_answer": "教育性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的教育性很高，我每天都喝。", "explanation": "这里应该用〈口味〉。教育性指能让人学到东西的性质，咖啡的好坏要用“口味”。"}, {"text": "这座桥的教育性很强，汽车都能从上面开过去。", "explanation": "这里应该用〈承重〉。教育性指作品或活动能让人学到东西的性质，说桥的好坏要用“承重”或“结构”。"}, {"text": "这件衣服的教育性很高，我每天都穿。", "explanation": "这里应该用〈款式〉。教育性指能让人学到东西的性质，说衣服的样子要用“款式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本小说的教育性很多。", "corrected_sentence": "这本小说的教育性很强。", "error_description": "错误：“教育性很多”，“教育性”是抽象性质，不能用“多”来说。正确：“教育性很强”。说教育性的程度要用“强”或“弱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套故事书很教育性，孩子们很喜欢。", "corrected_sentence": "这套故事书很有教育性，孩子们很喜欢。", "error_description": "错误：“很教育性”，漏掉了“有”。正确：“很有教育性”。“教育性”是抽象名词，前面要用“很有”来修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
