INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "族群是住在一起、说话和习惯差不多的一大群人。", "primary_collocate": null, "pronunciation": "zú qún", "ipa": "tsu˧˥ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "这个族群的人住在山里，说同一种话。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个族群的人都喜欢唱歌跳舞。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群已经在这里住了几百年。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给孩子讲这个族群的故事。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个族群都有自己的习惯。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个族群里最老的人。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群的人过节时会穿特别的衣服。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群的孩子从小就学自己的话。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看看那个族群怎么生活。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群的人很少，但是大家都很团结。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "少数族群", "label": "复合"}], "register": "中性", "sense_fingerprint": "住在一起、语言和习惯相近的一大群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "族群", "is_correct": true, "explanation": "正确：“族群”指住在一起、说话和习惯相近的一大群人，可以说“这个族群的人住在山里”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不指人群，“这个桌子的人住在山里”说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种花的地方，不指人群，“花园的人住在山里”说不通。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”是交流的工具，不指一群人，“这个语言的人”说不通。"}], "explanations": {"族群": "正确：“族群”指住在一起、说话和习惯相近的一大群人，可以说“这个族群的人住在山里”。", "桌子": "语义：“桌子”是家具，不指人群，“这个桌子的人住在山里”说不通。", "花园": "语义：“花园”是种花的地方，不指人群，“花园的人住在山里”说不通。", "语言": "语义：“语言”是交流的工具，不指一群人，“这个语言的人”说不通。"}, "sentence_index": 0, "correct_answer": "族群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的族群今天感冒了，要请假。", "explanation": "这里应该用〈同事〉。族群指一大群人，不能用来指一个人。"}, {"text": "我们族群的赛车在比赛中拿到了冠军。", "explanation": "这里应该用〈车队〉。赛车属于车队，族群指以共同语言、文化或血缘为特征的人群，不能说“族群的赛车”。"}, {"text": "这个族群的吉他手每天都练到很晚。", "explanation": "这里应该用〈乐队〉。吉他手是乐队的成员，族群指以共同语言、文化或血缘为特征的人群，不能说“族群的吉他手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "族群", "is_correct": true, "explanation": "正确：“族群”指有共同习俗的一大群人，“这个族群的人过节时穿特别的衣服”说得通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能指一群人，“手机的人过节时穿衣服”说不通。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是卖书的地方，不指人群，“书店的人过节时穿特别的衣服”说不通。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”指体形胖的一个人，不能指一群有共同习俗的人。"}], "explanations": {"族群": "正确：“族群”指有共同习俗的一大群人，“这个族群的人过节时穿特别的衣服”说得通。", "手机": "语义：“手机”是通讯工具，不能指一群人，“手机的人过节时穿衣服”说不通。", "书店": "语义：“书店”是卖书的地方，不指人群，“书店的人过节时穿特别的衣服”说不通。", "胖子": "体貌：“胖子”指体形胖的一个人，不能指一群有共同习俗的人。"}, "sentence_index": 6, "correct_answer": "族群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个族群的股票今天涨了百分之五。", "explanation": "这里应该用〈公司〉。族群指有共同语言、文化或血缘的人群，股票属于企业，不能说“族群的股票”。"}, {"text": "这个族群的项目进度很快，老板很满意。", "explanation": "这里应该用〈团队〉。族群指有共同语言、文化或血缘的人群，因工作组成的团队不说“族群”。"}, {"text": "这个族群的球员都很热心，常常帮助别人。", "explanation": "这里应该用〈球队〉。球员属于球队，族群指有共同语言、文化或血缘的人群，不能说“族群的球员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村子里有一只族群，已经住了好几代人。", "corrected_sentence": "我们村子里有一个族群，已经住了好几代人。", "error_description": "量词错误：“族群”指一群人，量词应用“个”，不能用“只”（“只”多用于动物或成对的东西）。正确写作：一个族群。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个族群们的人都很热情好客。", "corrected_sentence": "我们这个族群的人都很热情好客。", "error_description": "词尾错误：“族群”是表示一群人的名词，后面不能再加“们”。正确写作：这个族群的人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
