INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "具有共同文化、语言或血缘特征的人群。", "primary_collocate": null, "pronunciation": "zú qún", "ipa": "tsu˧˥ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "语言和文化相同的人，常常属于同一个族群。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多不同的族群。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "族群的文化需要大家一起保护。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究这个族群的语言和历史。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同族群的人应该互相尊重。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群有自己的文字。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者认为血缘是族群的重要特征。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族群的传统节日很有名。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个族群的语言很不一样。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们比较两个族群的文化。", "target_word": "族群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "族群关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "以共同文化、语言或血缘为特征的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "族群", "is_correct": true, "explanation": "正确：“族群”指以共同语言、文化或血缘为特征的人群，“属于同一个族群”说得通。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是演奏用的器具，不是人群，“属于同一个乐器”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴等自然状况，不能指人群，“属于同一个天气”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指个人的体形，不指群体，“属于同一个身材”说不通。"}], "explanations": {"族群": "正确：“族群”指以共同语言、文化或血缘为特征的人群，“属于同一个族群”说得通。", "乐器": "语义：“乐器”是演奏用的器具，不是人群，“属于同一个乐器”说不通。", "天气": "语义：“天气”指冷热阴晴等自然状况，不能指人群，“属于同一个天气”说不通。", "身材": "体貌：“身材”指个人的体形，不指群体，“属于同一个身材”说不通。"}, "sentence_index": 0, "correct_answer": "族群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个族群的油箱快空了，需要加油。", "explanation": "这里应该用〈汽车〉。族群指有共同语言、文化或血缘的人群，油箱属于汽车，不能说“族群的油箱”。"}, {"text": "这个族群去年的营业额翻了一番，老板很高兴。", "explanation": "这里应该用〈公司〉。族群指有共同语言、文化或血缘的人群，营业额属于企业，不能说“族群的营业额”。"}, {"text": "这个族群可以帮你检查拼写错误。", "explanation": "这里应该用〈软件〉。族群指人群，不能用来指可以检查拼写的程序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "族群", "is_correct": true, "explanation": "正确：“族群”的血缘、语言等是可以作为“重要特征”的，“血缘是族群的重要特征”说得通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”是食物，不能有血缘，“血缘是水果的重要特征”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑，不能有血缘，“血缘是房子的重要特征”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是个人的身体数值，不能作为群体的重要特征，“血缘是身高的重要特征”说不通。"}], "explanations": {"族群": "正确：“族群”的血缘、语言等是可以作为“重要特征”的，“血缘是族群的重要特征”说得通。", "水果": "语义：“水果”是食物，不能有血缘，“血缘是水果的重要特征”说不通。", "房子": "语义：“房子”是建筑，不能有血缘，“血缘是房子的重要特征”说不通。", "身高": "体貌：“身高”是个人的身体数值，不能作为群体的重要特征，“血缘是身高的重要特征”说不通。"}, "sentence_index": 6, "correct_answer": "族群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个族群的价格是三十元，比别的便宜。", "explanation": "这里应该用〈商品〉。族群指人群，不能指商品或它的价格。"}, {"text": "这个族群从市中心一直通到机场。", "explanation": "这里应该用〈道路〉。族群指人群，不能用来指从市中心通到机场的道路。"}, {"text": "这个族群的屏幕很大，看起来很清楚。", "explanation": "这里应该用〈显示器〉。族群指人群，屏幕属于显示器，不能说“族群的屏幕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只族群有很长的历史和自己的语言。", "corrected_sentence": "这个族群有很长的历史和自己的语言。", "error_description": "量词错误：“族群”应用量词“个”，不能用“只”（“只”多用于动物）。正确写作：这个族群。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个族群们的人经常一起过节。", "corrected_sentence": "两个族群的人经常一起过节。", "error_description": "词尾错误：“族群”是表示一群人的名词，后面不能再加“们”。正确写作：两个族群的人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
