INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "晚会是晚上很多人一起唱歌、跳舞、玩的活动。", "primary_collocate": null, "pronunciation": "wǎn huì", "ipa": "wan˨˩˦ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "今天晚上学校有一场晚会。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在晚会上唱了一首中文歌。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会八点开始，大家都来了。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们在晚会上跳舞，玩得很开心。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着漂亮的裙子去参加晚会。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的晚会我想带一个小礼物。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上有很多好吃的东西。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个晚会很热闹，我认识了新朋友。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的晚会十点才结束。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过中国人办的晚会吗？", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场晚会", "label": "量词"}, {"form": "联欢晚会", "label": "复合"}], "register": "中性", "sense_fingerprint": "晚上大家一起唱歌跳舞玩的聚会活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚会", "is_correct": true, "explanation": "晚会是正确答案，今天晚上学校举办的唱歌、跳舞等活动。"}, {"text": "早操", "is_correct": false, "explanation": "语义：早操在清晨进行，与“今天晚上”冲突。"}, {"text": "晨会", "is_correct": false, "explanation": "语义：晨会在早上召开，与“今天晚上”冲突。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出在早晨，与“今天晚上”冲突。"}], "explanations": {"晚会": "晚会是正确答案，今天晚上学校举办的唱歌、跳舞等活动。", "早操": "语义：早操在清晨进行，与“今天晚上”冲突。", "晨会": "语义：晨会在早上召开，与“今天晚上”冲突。", "日出": "语义：日出在早晨，与“今天晚上”冲突。"}, "sentence_index": 0, "correct_answer": "晚会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场晚会讨论了明年的预算。", "explanation": "这里应该用〈会议〉。晚会指唱歌、跳舞、玩的活动，讨论预算应说会议。"}, {"text": "这次晚会有五百人参加，大家抗议学校的规定。", "explanation": "这里应该用〈集会〉。集会是为某种诉求聚集在一起，可以用来抗议；晚会以唱歌、跳舞、玩为主，不用于抗议。"}, {"text": "晚会上，医生给病人打了一针。", "explanation": "这里应该用〈医院〉。医院是医生给病人看病、打针的地方；晚会以唱歌、跳舞、玩为主，不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚会", "is_correct": true, "explanation": "晚会是正确答案，指有很多好吃的东西的联欢活动。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是考试的地方，不会有很多好吃的东西。"}, {"text": "诊所", "is_correct": false, "explanation": "语义：诊所是看病的地方，与食物无关。"}, {"text": "体检", "is_correct": false, "explanation": "搭配：“体检”不说“在…上”摆放东西，也与食物不搭。"}], "explanations": {"晚会": "晚会是正确答案，指有很多好吃的东西的联欢活动。", "考场": "语义：考场是考试的地方，不会有很多好吃的东西。", "诊所": "语义：诊所是看病的地方，与食物无关。", "体检": "搭配：“体检”不说“在…上”摆放东西，也与食物不搭。"}, "sentence_index": 6, "correct_answer": "晚会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法官在晚会上宣布了判决。", "explanation": "这里应该用〈法庭〉。法庭是法官审理案件、宣布判决的地方；晚会是唱歌、跳舞、玩的活动，不宣布判决。"}, {"text": "今天下了一场晚会，路上很滑。", "explanation": "这里应该用〈雪〉。“下”搭配雨、雪等天气现象，晚会是活动，不能“下”。"}, {"text": "我们一起吃完了晚会，就去散步了。", "explanation": "这里应该用〈晚饭〉。“吃完”搭配饭菜等食物，晚会是唱歌、跳舞、玩的活动，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们在一张晚会上唱歌跳舞。", "corrected_sentence": "同学们在一场晚会上唱歌跳舞。", "error_description": "量词错误：晚会应用“场”计量，“张”用于纸张、桌子等扁平的东西，不能说“一张晚会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班昨天办了一只晚会。", "corrected_sentence": "我们班昨天办了一场晚会。", "error_description": "错误在量词：晚会应用“场”计量，“只”用于动物或单个物品，应说“办了一场晚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
