INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在晚间举行的联欢或文艺演出。", "primary_collocate": null, "pronunciation": "wǎn huì", "ipa": "wan˨˩˦ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "电视台今晚有一场新年的晚会。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上有歌曲、舞蹈和小品。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们为晚会准备了很多节目。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年春节，我们一家人都看电视上的晚会。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会的主持人穿着红色的衣服。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在晚会上表演了一个节目。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场晚会是公司为员工办的。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会结束后，观众都站起来鼓掌。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班要办一个毕业晚会。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在晚会上唱歌，大家听得很认真。", "target_word": "晚会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场晚会", "label": "量词"}, {"form": "新年晚会", "label": "复合"}], "register": "中性", "sense_fingerprint": "晚上举行的联欢或文艺演出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晚会", "is_correct": true, "explanation": "晚会是正确答案，指电视台今晚播出的新年联欢节目。"}, {"text": "晨会", "is_correct": false, "explanation": "语义：晨会在早上召开，与“今晚”冲突。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是悼念逝者的仪式，不是电视台播出的新年节目。"}, {"text": "早操", "is_correct": false, "explanation": "语义：早操在清晨进行，与“今晚”冲突。"}], "explanations": {"晚会": "晚会是正确答案，指电视台今晚播出的新年联欢节目。", "晨会": "语义：晨会在早上召开，与“今晚”冲突。", "葬礼": "语义：葬礼是悼念逝者的仪式，不是电视台播出的新年节目。", "早操": "语义：早操在清晨进行，与“今晚”冲突。"}, "sentence_index": 0, "correct_answer": "晚会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场晚会两队踢得很激烈，观众都站起来了。", "explanation": "这里应该用〈比赛〉。比赛有对手和胜负，晚会是文艺演出或联欢，不能说两队踢球。"}, {"text": "这次晚会展出了五十件古代瓷器，观众一件件地看。", "explanation": "这里应该用〈展览〉。展览用于展出实物或作品，观众一件件地看；晚会是联欢或文艺演出，不展出瓷器。"}, {"text": "学校的晚会上，运动员在跑道上冲刺。", "explanation": "这里应该用〈运动会〉。运动会有运动员在跑道上冲刺；晚会是联欢或文艺演出，不设跑道冲刺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晚会", "is_correct": true, "explanation": "晚会是正确答案，指公司为员工办的联欢活动。"}, {"text": "事故", "is_correct": false, "explanation": "搭配：“办”不能用于事故，事故也不是公司为员工组织的。"}, {"text": "火灾", "is_correct": false, "explanation": "语义：火灾是灾害，不是公司为员工办的活动。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争与公司为员工办活动的语境相悖。"}], "explanations": {"晚会": "晚会是正确答案，指公司为员工办的联欢活动。", "事故": "搭配：“办”不能用于事故，事故也不是公司为员工组织的。", "火灾": "语义：火灾是灾害，不是公司为员工办的活动。", "战争": "语义：战争与公司为员工办活动的语境相悖。"}, "sentence_index": 6, "correct_answer": "晚会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的晚会写得很好，老师很满意。", "explanation": "这里应该用〈论文〉。“写”的对象是论文等文字作品，晚会不能“写”。"}, {"text": "这台晚会医生做得很成功。", "explanation": "这里应该用〈手术〉。“医生做得很成功”说的是手术，晚会是联欢或文艺演出，不是医生施行的医疗活动。"}, {"text": "他在会上发表了晚会。", "explanation": "这里应该用〈演讲〉。“发表”搭配演讲、文章，不能搭配晚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班以前办过一只晚会。", "corrected_sentence": "我们班以前办过一场晚会。", "error_description": "“晚会”的量词应用“场”，不能用“只”。“只”用于动物等单个个体，不能修饰晚会。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的一本晚会办得很成功。", "corrected_sentence": "学校的一场晚会办得很成功。", "error_description": "量词错误：晚会应用“场”计量，“本”用于书册，不能说“一本晚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
