INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "晕是头转来转去，站不稳，觉得要倒下。", "primary_collocate": null, "pronunciation": "yūn", "ipa": "yn˥", "syllable_count": 1, "sentences": [{"text": "我晕得站不稳，只好扶着墙。", "target_word": "晕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她突然一晕，差点倒在地上。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玩完转椅，他晕得走不了路。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太晕了，我想坐下来休息。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他晕得说不出话来。", "target_word": "晕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "屋子在转，我晕得厉害。", "target_word": "晕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "站了两个小时，她开始晕了。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走在船上，我晕得直想坐下。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我晕得连路都看不清了。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有点晕，就靠在了墙上。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "晕了", "label": "体标"}, {"form": "晕过", "label": "体标"}, {"form": "暈", "label": "繁体"}], "register": "口语", "sense_fingerprint": "头转，站不稳，觉得要倒下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕 yūn：头转来转去，站不稳，觉得要倒下。"}, {"text": "云", "is_correct": false, "explanation": "yún（第二声）与 yūn（第一声）声调不同，意思是云。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yūn（第一声）声调不同，意思是运气、运输。"}, {"text": "允", "is_correct": false, "explanation": "yǔn（第三声）与 yūn（第一声）声调不同，意思是允许。"}, {"text": "因", "is_correct": false, "explanation": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是因为。"}], "explanations": {"晕": "晕 yūn：头转来转去，站不稳，觉得要倒下。", "云": "yún（第二声）与 yūn（第一声）声调不同，意思是云。", "运": "yùn（第四声）与 yūn（第一声）声调不同，意思是运气、运输。", "允": "yǔn（第三声）与 yūn（第一声）声调不同，意思是允许。", "因": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是因为。"}, "sentence_index": null, "correct_answer": "晕"}, "level_3": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕：指头转、站不稳，与“只好扶着墙”的语境吻合。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”描述温度，不能说“我烫得站不稳”。"}, {"text": "醒", "is_correct": false, "explanation": "搭配：“醒”指从睡眠中恢复，不能与“得站不稳”搭配。"}, {"text": "闪", "is_correct": false, "explanation": "语义：“闪”指一瞬间的光亮或动作，与站立时的感觉无关。"}], "explanations": {"晕": "晕：指头转、站不稳，与“只好扶着墙”的语境吻合。", "烫": "语义：“烫”描述温度，不能说“我烫得站不稳”。", "醒": "搭配：“醒”指从睡眠中恢复，不能与“得站不稳”搭配。", "闪": "语义：“闪”指一瞬间的光亮或动作，与站立时的感觉无关。"}, "sentence_index": 0, "correct_answer": "晕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "抱了一路孩子，我的胳膊晕得抬不起来。", "explanation": "这里应该用〈酸〉。晕指头转、站不稳，不能用来描述胳膊的酸痛。"}, {"text": "我的腿晕得厉害。", "explanation": "这里应该用〈疼〉。晕指头部发昏、站不稳，不能用来描述腿的疼痛。"}, {"text": "坐了一下午，我的屁股晕得厉害。", "explanation": "这里应该用〈麻〉。晕指头转、站不稳，不能用来描述屁股的麻木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕 yūn：头转来转去，站不稳，觉得要倒下。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yūn（第一声）声调不同，意思是韵律。"}, {"text": "匀", "is_correct": false, "explanation": "yún（第二声）与 yūn（第一声）声调不同，意思是均匀。"}, {"text": "音", "is_correct": false, "explanation": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是声音。"}], "explanations": {"晕": "晕 yūn：头转来转去，站不稳，觉得要倒下。", "韵": "yùn（第四声）与 yūn（第一声）声调不同，意思是韵律。", "匀": "yún（第二声）与 yūn（第一声）声调不同，意思是均匀。", "音": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是声音。"}, "sentence_index": null, "correct_answer": "晕"}, "level_3": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕：指头转、站不稳，与“开始……了”及站立的语境吻合。"}, {"text": "融", "is_correct": false, "explanation": "语义：“融”指熔化或融合，与站立的时间和身体感觉无关。"}, {"text": "熄", "is_correct": false, "explanation": "搭配：“熄”多用于火、灯，不能用来说人“熄了”。"}, {"text": "沸", "is_correct": false, "explanation": "语义：“沸”指液体受热翻滚，不能用来形容人的身体状态。"}], "explanations": {"晕": "晕：指头转、站不稳，与“开始……了”及站立的语境吻合。", "融": "语义：“融”指熔化或融合，与站立的时间和身体感觉无关。", "熄": "搭配：“熄”多用于火、灯，不能用来说人“熄了”。", "沸": "语义：“沸”指液体受热翻滚，不能用来形容人的身体状态。"}, "sentence_index": 6, "correct_answer": "晕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐了太久，腿晕得站不起来。", "explanation": "这里应该用〈麻〉。晕指头转、站不稳，不用于腿部的麻木。"}, {"text": "她的喉咙晕得很厉害。", "explanation": "这里应该用〈痛〉。晕不用于描述喉咙的疼痛。"}, {"text": "我的脖子晕得厉害。", "explanation": "这里应该用〈酸〉。晕指头转、站不稳，不能用来描述脖子的酸痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚下船时，他晕了得站不稳。", "corrected_sentence": "刚下船时，他晕得站不稳。", "error_description": "“晕得”是程度补语结构，“了”不能插在“晕”和“得”之间。应说“晕得站不稳”，不说“晕了得站不稳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下车就晕地站不住。", "corrected_sentence": "他一下车就晕得站不住。", "error_description": "表示程度的补语应用“得”连接，不用“地”。应说“晕得站不住”，不说“晕地站不住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
