INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "头昏眼花，感到天旋地转。", "primary_collocate": null, "pronunciation": "yūn", "ipa": "yn˥", "syllable_count": 1, "sentences": [{"text": "我坐船坐久了，头有点晕。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一站起来就觉得晕。", "target_word": "晕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看着高楼下面，我晕了。", "target_word": "晕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳很大，她晕得站不住。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没吃早饭，走路时有点晕。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐飞机从来没晕过。", "target_word": "晕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我晕是因为血压太低。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "转了十圈以后，孩子们都晕了。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝多了，说话时觉得很晕。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里太闷，我越坐越晕。", "target_word": "晕", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "晕了", "label": "体标"}, {"form": "晕过", "label": "体标"}, {"form": "暈", "label": "繁体"}], "register": "口语", "sense_fingerprint": "头昏眼花，天旋地转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕 yūn：头昏眼花，感到天旋地转。"}, {"text": "云", "is_correct": false, "explanation": "yún（第二声）与 yūn（第一声）声调不同，意思是云。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yūn（第一声）声调不同，意思是运气、运输。"}, {"text": "允", "is_correct": false, "explanation": "yǔn（第三声）与 yūn（第一声）声调不同，意思是允许。"}, {"text": "因", "is_correct": false, "explanation": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是因为。"}], "explanations": {"晕": "晕 yūn：头昏眼花，感到天旋地转。", "云": "yún（第二声）与 yūn（第一声）声调不同，意思是云。", "运": "yùn（第四声）与 yūn（第一声）声调不同，意思是运气、运输。", "允": "yǔn（第三声）与 yūn（第一声）声调不同，意思是允许。", "因": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是因为。"}, "sentence_index": null, "correct_answer": "晕"}, "level_3": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕：指头昏眼花，与坐船久了的感受相符。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：“饿”指肚子空，不能说“头有点饿”。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”指吃够了，与坐船时头部的感觉无关。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描述身形，不能用来形容头部的感觉。"}], "explanations": {"晕": "晕：指头昏眼花，与坐船久了的感受相符。", "饿": "搭配：“饿”指肚子空，不能说“头有点饿”。", "饱": "语义：“饱”指吃够了，与坐船时头部的感觉无关。", "瘦": "体貌：“瘦”描述身形，不能用来形容头部的感觉。"}, "sentence_index": 0, "correct_answer": "晕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蚊子咬过的地方晕得厉害。", "explanation": "这里应该用〈痒〉。晕指头昏眼花，不能用来描述皮肤发痒。"}, {"text": "我的牙晕得厉害。", "explanation": "这里应该用〈疼〉。晕指头部发昏，不能用来描述牙齿的疼痛。"}, {"text": "坐了太久，我的膝盖晕得厉害。", "explanation": "这里应该用〈酸〉。晕指头昏眼花，不能用来描述膝盖的酸痛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕 yūn：头昏眼花，感到天旋地转。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yūn（第一声）声调不同，意思是韵律。"}, {"text": "匀", "is_correct": false, "explanation": "yún（第二声）与 yūn（第一声）声调不同，意思是均匀。"}, {"text": "音", "is_correct": false, "explanation": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是声音。"}], "explanations": {"晕": "晕 yūn：头昏眼花，感到天旋地转。", "韵": "yùn（第四声）与 yūn（第一声）声调不同，意思是韵律。", "匀": "yún（第二声）与 yūn（第一声）声调不同，意思是均匀。", "音": "yīn 与 yūn 的韵母不同（i 与 ü），声调相同，意思是声音。"}, "sentence_index": null, "correct_answer": "晕"}, "level_3": {"options": [{"text": "晕", "is_correct": true, "explanation": "晕：指头昏、站立不稳，与血压低引起的症状相符。"}, {"text": "肿", "is_correct": false, "explanation": "搭配：“肿”多指身体局部隆起，不能说“我肿是因为血压太低”。"}, {"text": "醉", "is_correct": false, "explanation": "语义：“醉”由喝酒引起，与血压太低无关。"}, {"text": "闪", "is_correct": false, "explanation": "语义：“闪”指一瞬间的动作或光亮，不能描述人的身体状况。"}], "explanations": {"晕": "晕：指头昏、站立不稳，与血压低引起的症状相符。", "肿": "搭配：“肿”多指身体局部隆起，不能说“我肿是因为血压太低”。", "醉": "语义：“醉”由喝酒引起，与血压太低无关。", "闪": "语义：“闪”指一瞬间的动作或光亮，不能描述人的身体状况。"}, "sentence_index": 6, "correct_answer": "晕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一下撞得我手臂很晕。", "explanation": "这里应该用〈麻〉。晕指头昏眼花，不能用来描述手臂的麻木。"}, {"text": "他的肚子晕得厉害。", "explanation": "这里应该用〈痛〉。晕不用于描述肚子的疼痛。"}, {"text": "他的心晕得厉害。", "explanation": "这里应该用〈慌〉。晕指头昏眼花，不表示心里的慌乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候坐船从来没晕了。", "corrected_sentence": "我小时候坐船从来没晕过。", "error_description": "“从来没”后表示未曾有过的经历时要用“过”，不能用“了”。错误形式是“没晕了”，正确形式是“没晕过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次坐大巴，他晕了得很厉害。", "corrected_sentence": "这次坐大巴，他晕得很厉害。", "error_description": "“了”不能插在“晕”和“得”之间。应说“晕得很厉害”，不说“晕了得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
