INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98877, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "更改是把原来的换成新的。", "primary_collocate": null, "pronunciation": "gēng gǎi", "ipa": "kɤŋ˥ kaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她把旧密码更改成了新的。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把表格上的姓名更改为他的名字。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司更改了原来的名字。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈更改了家里的网络密码。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他更改了房间的号码。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把上课时间更改为九点。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发时间已经更改，请看新通知。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧地址不用了，我要更改成新地址。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板更改过菜单，加了几个新菜。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上的头像可以随时更改。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更改了", "label": "完成体"}, {"form": "更改过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词：把原来的内容换成新的，常带“成／为”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更改", "is_correct": true, "explanation": "“更改”表示把原来的换成新的，与“把……成了新的”相合。"}, {"text": "扔掉", "is_correct": false, "explanation": "搭配：“扔掉”表示丢弃，不能与“成了新的”搭配。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”表示买东西，与把旧的变成新的的含义不符。"}, {"text": "叫作", "is_correct": false, "explanation": "配价：“叫作”需要“叫作＋名称”的结构，不能接“把……成”。"}], "explanations": {"更改": "“更改”表示把原来的换成新的，与“把……成了新的”相合。", "扔掉": "搭配：“扔掉”表示丢弃，不能与“成了新的”搭配。", "购买": "语义：“购买”表示买东西，与把旧的变成新的的含义不符。", "叫作": "配价：“叫作”需要“叫作＋名称”的结构，不能接“把……成”。"}, "sentence_index": 0, "correct_answer": "更改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他更改了一个刚认识的新朋友。", "explanation": "这里应该用〈结交〉。“更改”是把原有事物换成新的，用于内容、名称等，人际关系要用“结交”。"}, {"text": "天气突然更改了。", "explanation": "这里应该用〈变化〉。“更改”需要把原有事物换成新的，自然现象的变化要用“变化”。"}, {"text": "她对我更改了挥手。", "explanation": "这里应该用〈挥〉。“更改”不能与动作搭配，挥手是动作，要用“挥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更改", "is_correct": true, "explanation": "“更改”表示变更，与“请看新通知”相合。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”表示找不到，与出发时间的变动无关。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件，不能说“时间已经打印”。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：“撕毁”表示撕坏，与“请看新通知”的语境不符。"}], "explanations": {"更改": "“更改”表示变更，与“请看新通知”相合。", "丢失": "语义：“丢失”表示找不到，与出发时间的变动无关。", "打印": "搭配：“打印”的对象是文件，不能说“时间已经打印”。", "撕毁": "语义：“撕毁”表示撕坏，与“请看新通知”的语境不符。"}, "sentence_index": 6, "correct_answer": "更改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天的事故更改了。", "explanation": "这里应该用〈发生〉。事故不能换成新的东西，应说“发生”。"}, {"text": "她更改了他。", "explanation": "这里应该用〈改变〉。更改指把原有内容换成新的，不能用于人的性格，人的变化要用“改变”。"}, {"text": "他更改了一个好觉。", "explanation": "这里应该用〈睡〉。“更改”不能与“觉”搭配，睡一个好觉要用“睡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把餐厅的菜单更改了新的。", "corrected_sentence": "他把餐厅的菜单更改成了新的。", "error_description": "缺少结果介词“成”：“更改”后表示变成的结果要用“成”，应为“更改成了新的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长更改了过课表。", "corrected_sentence": "班长更改过课表。", "error_description": "“了”与“过”不能同时用于“更改”之后，表示经历过只用“过”。应删去“了”，写作“更改过课表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
