INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变更；改动。", "primary_collocate": null, "pronunciation": "gēng gǎi", "ipa": "kɤŋ˥ kaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想更改明天的会议时间。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你更改一下这个密码。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把航班日期更改了。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地址写错了，要马上更改。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字可以更改吗？", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师更改了考试的地点。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，我们更改了去公园的计划。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你更改过手机号码吗？", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "订好的机票不能随便更改。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想更改自己的决定。", "target_word": "更改", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更改了", "label": "完成体"}, {"form": "更改过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词：变更、改动已定的时间、地点、计划、内容等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更改", "is_correct": true, "explanation": "“更改”表示变更已定的时间，与“想……明天的会议时间”相合。"}, {"text": "复印", "is_correct": false, "explanation": "语义：“复印”指复制文件，不能用于会议时间这种时间安排。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是影像、表演，不能说“观看会议时间”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复损坏的东西，与会议时间无关。"}], "explanations": {"更改": "“更改”表示变更已定的时间，与“想……明天的会议时间”相合。", "复印": "语义：“复印”指复制文件，不能用于会议时间这种时间安排。", "观看": "搭配：“观看”的对象是影像、表演，不能说“观看会议时间”。", "修理": "语义：“修理”指修复损坏的东西，与会议时间无关。"}, "sentence_index": 0, "correct_answer": "更改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近的性格更改得很大。", "explanation": "这里应该用〈改变〉。更改用于计划、名称、地址等具体内容，性格或情况的变化要用“改变”。"}, {"text": "我把坏了的灯泡更改了。", "explanation": "这里应该用〈更换〉。更改指改动已有的内容，换掉坏了的物件要用“更换”。"}, {"text": "他终于更改了困境。", "explanation": "这里应该用〈摆脱〉。更改指把原有内容换成新的，不能用于困境，摆脱困境要用“摆脱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更改", "is_correct": true, "explanation": "“更改”表示变更已定的计划，与“因为下雨，我们……了去公园的计划”相合。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，不能与“计划”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“计划”作宾语。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“因为下雨”而改变计划的语义不符。"}], "explanations": {"更改": "“更改”表示变更已定的计划，与“因为下雨，我们……了去公园的计划”相合。", "吃掉": "搭配：“吃掉”的对象是食物，不能与“计划”搭配。", "唱": "搭配：“唱”不能带“计划”作宾语。", "赞美": "语义：“赞美”表示称赞，与“因为下雨”而改变计划的语义不符。"}, "sentence_index": 6, "correct_answer": "更改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议开始后，他更改了长时间的沉默。", "explanation": "这里应该用〈打破〉。“沉默”是一种状态，不能被“更改”，打破沉默要用“打破”。"}, {"text": "他更改了坏掉的收音机。", "explanation": "这里应该用〈修理〉。更改用于改动内容或计划，修好坏掉的东西要用“修理”。"}, {"text": "她认真更改了一遍地板。", "explanation": "这里应该用〈擦〉。更改指改动内容或计划，不能用于清洁地板，擦地板要用“擦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把比赛时间更改了下午。", "corrected_sentence": "他把比赛时间更改为下午。", "error_description": "“把……更改”后要用“为”（或“成”）引出改后的新时间，句中缺少“为”，应为“更改为下午”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板更改了把菜单。", "corrected_sentence": "老板更改了菜单。", "error_description": "“把”字多余。“更改了”后直接接宾语“菜单”，不需要“把”，应删去“把”，写作“老板更改了菜单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
