INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98881, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "月黑是晚上没有月亮，天很黑。", "primary_collocate": null, "pronunciation": "yuè hēi", "ipa": "ɥɛ˥˩ xeɪ˥", "syllable_count": 2, "sentences": [{"text": "今天晚上月黑，什么都看不见。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月黑的时候，山里很安静。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天月黑，我们走得很慢。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月黑天，路上没有人。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚月黑，孩子不敢出门。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月黑的晚上，星星特别多。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在月黑的夜里上山。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上月黑，天上只有星星。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚月黑，请你带一个手电。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月黑的夜，一个人走路有点怕。", "target_word": "月黑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "月黑风高", "label": "复合"}], "register": "书面", "sense_fingerprint": "形容词：晚上没有月亮，天很黑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06b273a4-be21-462a-a87c-17dfbdecb405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月黑", "is_correct": true, "explanation": "“月黑”指夜里没有月亮，天很黑，与“什么都看不见”相合。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”与“什么都看不见”相矛盾。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：“高耸”形容山峰、建筑，不用来形容夜晚。"}, {"text": "甜美", "is_correct": false, "explanation": "体貌：“甜美”形容容貌或声音，不用来形容夜晚。"}], "explanations": {"月黑": "“月黑”指夜里没有月亮，天很黑，与“什么都看不见”相合。", "明亮": "语义：“明亮”与“什么都看不见”相矛盾。", "高耸": "搭配：“高耸”形容山峰、建筑，不用来形容夜晚。", "甜美": "体貌：“甜美”形容容貌或声音，不用来形容夜晚。"}, "sentence_index": 0, "correct_answer": "月黑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里月黑一片，我找不到开关。", "explanation": "这里应该用〈漆黑〉。月黑只指夜晚没有月光，不用来形容室内。"}, {"text": "他在太阳下干活，脸晒得月黑。", "explanation": "这里应该用〈黝黑〉。月黑只形容夜色，不用来形容人的皮肤。"}, {"text": "她的头发月黑又长。", "explanation": "这里应该用〈乌黑〉。月黑只指夜里没有月光，不用来形容头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月黑", "is_correct": true, "explanation": "“月黑的夜里”指没有月光的夜晚，可以用来修饰“夜里”。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：“滚烫”形容温度，与夜里上山的情景不协调。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”形容空间、道路，不用来修饰夜晚。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容物体的重量，不能修饰夜里。"}], "explanations": {"月黑": "“月黑的夜里”指没有月光的夜晚，可以用来修饰“夜里”。", "滚烫": "语义：“滚烫”形容温度，与夜里上山的情景不协调。", "宽阔": "搭配：“宽阔”形容空间、道路，不用来修饰夜晚。", "笨重": "语义：“笨重”形容物体的重量，不能修饰夜里。"}, "sentence_index": 6, "correct_answer": "月黑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中午很热，天空月黑。", "explanation": "这里应该用〈晴朗〉。月黑指夜里没有月光，白天的天空不能说月黑。"}, {"text": "这盏灯的光月黑，照不清字。", "explanation": "这里应该用〈昏暗〉。月黑形容夜色，不用来形容灯光。"}, {"text": "这一片海水月黑。", "explanation": "这里应该用〈深蓝〉。月黑只形容夜里没有月光，不用来指水的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那天夜里很月黑，我们早早睡了。", "corrected_sentence": "那天夜里月黑，我们早早睡了。", "error_description": "程度词错误：“月黑”已经表示夜里没有月光，前面不加“很”，应说“那天夜里月黑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月黑地晚上，我们都不愿出门。", "corrected_sentence": "月黑的晚上，我们都不愿出门。", "error_description": "结构助词错误：修饰名词“晚上”要用“的”，不用“地”；“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9278bd8b-2ec1-403d-a553-b903d09ba190') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
