INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98885, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木材是树砍下来以后做成的木头，可以做桌子和房子。", "primary_collocate": null, "pronunciation": "mù cái", "ipa": "mu˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这些木材可以做桌子。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一些木材回家。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子是用木材盖的。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木材放在院子里，下雨时要盖好。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种木材很重，也很结实。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把木材搬到车上。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用木材做了一把椅子。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人常常卖木材。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木材很干，所以容易着火。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的木材不贵。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批木材", "label": "量词"}, {"form": "木材加工", "label": "复合"}], "register": "中性", "sense_fingerprint": "树砍下来做成的木头，可做桌子和房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布", "is_correct": false, "explanation": "搭配：布常用来做衣服、窗帘，“做桌子”要用木材这类硬材料。"}, {"text": "木材", "is_correct": true, "explanation": "木材是树砍下后做成的木头，可以做桌子，符合句意。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土松软，没法直接做成桌子。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能用来做桌子。"}], "explanations": {"布": "搭配：布常用来做衣服、窗帘，“做桌子”要用木材这类硬材料。", "木材": "木材是树砍下后做成的木头，可以做桌子，符合句意。", "泥土": "语义：泥土松软，没法直接做成桌子。", "水": "语义：水是液体，不能用来做桌子。"}, "sentence_index": 0, "correct_answer": "木材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我口渴了，想喝一杯木材。", "explanation": "这里应该用〈水〉。木材是做桌子、房子的材料，不能喝；口渴要喝水。"}, {"text": "这片木材很茂密。", "explanation": "这里应该用〈树木〉。木材是砍下后加工的材料，不会生长，形容“茂密”要用“树木”。"}, {"text": "这块木材很会唱歌，大家都很喜欢。", "explanation": "这里应该用〈小鸟〉。木材是无生命的材料，不会唱歌；会唱歌的是人或小鸟这类生物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是用来写字的，做不成椅子。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，无法用来做椅子。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：“用……做……”说的是制作材料，“钱”不能用来做椅子。"}, {"text": "木材", "is_correct": true, "explanation": "木材是砍下后加工的材料，可以做椅子，符合句意。"}], "explanations": {"粉笔": "语义：粉笔是用来写字的，做不成椅子。", "空气": "语义：空气是气体，无法用来做椅子。", "钱": "搭配：“用……做……”说的是制作材料，“钱”不能用来做椅子。", "木材": "木材是砍下后加工的材料，可以做椅子，符合句意。"}, "sentence_index": 6, "correct_answer": "木材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那片木材里很安静。", "explanation": "这里应该用〈树林〉。木材是材料，不能作为可以走进去的地方，“里面很安静”要用“树林”。"}, {"text": "这些木材长得很茂盛。", "explanation": "这里应该用〈树〉。木材不会生长，“长得茂盛”只能用于植物。"}, {"text": "这些木材上开满了花。", "explanation": "这里应该用〈草地〉。木材是加工后的材料，不会开花，“开满花”要说草地这类有植物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂又运来一个木材。", "corrected_sentence": "工厂又运来一批木材。", "error_description": "“木材”前的量词应用“批”。“个”只用于单个的东西，木材是大宗材料，不能说“一个木材”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把木材们搬进了仓库。", "corrected_sentence": "我们把木材搬进了仓库。", "error_description": "错误在“木材”后加了“们”。“们”表示人的复数，木材是物质名词，应说“把木材搬进了仓库”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
