INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木加工成的材料，用于建筑和制作家具。", "primary_collocate": null, "pronunciation": "mù cái", "ipa": "mu˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这家工厂专门加工木材。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建筑工地需要大量木材。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做家具要选好的木材。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口木材的价格这几年涨了。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批木材质量很好，没有坏的地方。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用优质木材制作家具。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上有很多不同的木材，有的适合做家具。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板是用木材做的。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护森林，国家限制木材出口。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年都从北方运来木材。", "target_word": "木材", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一批木材", "label": "量词"}, {"form": "木材市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "树木加工成的建筑和家具材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心", "is_correct": false, "explanation": "搭配：“加工”要搭配产品或原料，“心”不能被加工。"}, {"text": "木材", "is_correct": true, "explanation": "木材是树木加工成的材料，工厂可以加工，符合句意。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，工厂无法加工它。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，工厂不加工它。"}], "explanations": {"心": "搭配：“加工”要搭配产品或原料，“心”不能被加工。", "木材": "木材是树木加工成的材料，工厂可以加工，符合句意。", "云": "语义：云是天上的水汽，工厂无法加工它。", "空气": "语义：空气看不见摸不着，工厂不加工它。"}, "sentence_index": 0, "correct_answer": "木材"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用木材炒了一盘菜。", "explanation": "这里应该用〈青菜〉。木材是建筑和家具的材料，不能拿来炒菜吃。"}, {"text": "这片木材郁郁葱葱。", "explanation": "这里应该用〈树木〉。木材不会生长，“郁郁葱葱”只能形容树木这类植物。"}, {"text": "工人把木材剥下来了。", "explanation": "这里应该用〈树皮〉。剥下来的是长在树上的树皮，木材是加工后的材料，不能说“剥下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜", "is_correct": false, "explanation": "语义：菜是蔬菜，不能用来做家具。"}, {"text": "木材", "is_correct": true, "explanation": "木材是树木加工成的材料，有的适合做家具，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能用来做家具。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：“钱”不能用来做家具。"}], "explanations": {"菜": "语义：菜是蔬菜，不能用来做家具。", "木材": "木材是树木加工成的材料，有的适合做家具，符合句意。", "鱼": "语义：鱼不能用来做家具。", "钱": "搭配：“钱”不能用来做家具。"}, "sentence_index": 6, "correct_answer": "木材"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里种了一些木材。", "explanation": "这里应该用〈树苗〉。木材是加工后的材料，不能种，“种”只能用于树苗等植物。"}, {"text": "木材开花了。", "explanation": "这里应该用〈果树〉。木材是加工后的材料，不会开花，“开花”只能用于果树等植物。"}, {"text": "这片木材上开满了花。", "explanation": "这里应该用〈草地〉。木材不会开花，“开满花”要说草地这类长着植物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车运来了一个木材。", "corrected_sentence": "卡车运来了一车木材。", "error_description": "“木材”前的量词应用“车”。“个”只用于单个的东西，木材是大宗材料，不能说“一个木材”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们运来了一头木材。", "corrected_sentence": "他们运来了一车木材。", "error_description": "量词错误：“头”用于牲畜，木材应用“车”计量，不能说“一头木材”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
