INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "根源是一件事最开始的原因。", "primary_collocate": null, "pronunciation": "gēn yuán", "ipa": "kən˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这场争吵的根源是一句误会的话。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生想找出这种病的根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贫穷是很多问题的根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要解决问题，先要找到根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的矛盾有很深的根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有想过这件事的根源。", "target_word": "根源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要查清事故的根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "懒惰是失败的根源。", "target_word": "根源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你知道这个习惯的根源吗？", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争的根源常常很复杂。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一件事最开始的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根源", "is_correct": true, "explanation": "正确。「根源」指事情最开始的原因，这里说争吵的起因是一句误会的话。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是争吵的起因，不能等同于「一句误会的话」。"}, {"text": "时间", "is_correct": false, "explanation": "语义：「时间」指时刻，不能是「一句误会的话」。"}, {"text": "作用", "is_correct": false, "explanation": "搭配：「作用」指效果或功能，与「是一句误会的话」搭配不通。"}], "explanations": {"根源": "正确。「根源」指事情最开始的原因，这里说争吵的起因是一句误会的话。", "颜色": "语义：「颜色」不是争吵的起因，不能等同于「一句误会的话」。", "时间": "语义：「时间」指时刻，不能是「一句误会的话」。", "作用": "搭配：「作用」指效果或功能，与「是一句误会的话」搭配不通。"}, "sentence_index": 0, "correct_answer": "根源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的根源要在明天举行。", "explanation": "这里应该用〈活动〉。根源指最开始的原因，不能像活动一样在明天举行。"}, {"text": "这部电影的根源很长，我看了三个小时。", "explanation": "这里应该用〈片长〉。根源指原因，不能用来说电影有多长。"}, {"text": "他终于完成了这个根源。", "explanation": "这里应该用〈任务〉。根源是原因，不能被完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根源", "is_correct": true, "explanation": "正确。「查清事故的根源」指查明事故最开始的原因。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：「查清」的对象应是原因或事实，「口味」不能被查清。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」指身体或物体的重量，不是事故的起因。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」指身体的高度，与事故的起因无关。"}], "explanations": {"根源": "正确。「查清事故的根源」指查明事故最开始的原因。", "口味": "搭配：「查清」的对象应是原因或事实，「口味」不能被查清。", "体重": "语义：「体重」指身体或物体的重量，不是事故的起因。", "身高": "语义：「身高」指身体的高度，与事故的起因无关。"}, "sentence_index": 6, "correct_answer": "根源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次学习的根源很大。", "explanation": "这里应该用〈收获〉。根源指原因，不指收获的多少。"}, {"text": "他把根源装进了行李箱。", "explanation": "这里应该用〈东西〉。根源是抽象的原因，不能装进行李箱。"}, {"text": "这个根源很好吃，大家都抢着吃。", "explanation": "这里应该用〈食物〉。根源是抽象的原因，不能用来形容食物好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于找到了一条根源。", "corrected_sentence": "他们终于找到了一个根源。", "error_description": "量词错误：「根源」是抽象名词，应该用「个」，不能用「条」，「条」用于长而细的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
