INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物产生的根本原因或来源。", "primary_collocate": null, "pronunciation": "gēn yuán", "ipa": "kən˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "污染的根源是工厂排出的脏水。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文化的根源在历史里。", "target_word": "根源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说，快乐的根源是心态。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家正在研究疾病的根源。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次危机的根源是什么？", "target_word": "根源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坏习惯的根源往往在小时候。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "找不到根源，问题就解决不了。", "target_word": "根源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题的根源已经找到了。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些矛盾的根源在于利益不同。", "target_word": "根源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把问题的根源写在了报告里。", "target_word": "根源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "事物产生的根本原因或来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根源", "is_correct": true, "explanation": "正确。「污染的根源」指污染最开始的来源，句子说明是工厂排出的脏水。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是污染的起因，不能是「工厂排出的脏水」。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」指快慢，不能是「工厂排出的脏水」。"}, {"text": "作用", "is_correct": false, "explanation": "搭配：「作用」指功能或效果，与「是工厂排出的脏水」搭配不通。"}], "explanations": {"根源": "正确。「污染的根源」指污染最开始的来源，句子说明是工厂排出的脏水。", "颜色": "语义：「颜色」不是污染的起因，不能是「工厂排出的脏水」。", "速度": "语义：「速度」指快慢，不能是「工厂排出的脏水」。", "作用": "搭配：「作用」指功能或效果，与「是工厂排出的脏水」搭配不通。"}, "sentence_index": 0, "correct_answer": "根源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的根源是三。", "explanation": "这里应该用〈答案〉。根源指原因，不能指题目的得数。"}, {"text": "他把根源贴在了墙上。", "explanation": "这里应该用〈海报〉。根源是抽象的原因或来源，不能贴在墙上。"}, {"text": "他一口气吃了三个根源。", "explanation": "这里应该用〈苹果〉。根源是抽象的，不能用来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根源", "is_correct": true, "explanation": "正确。「找不到根源」指找不到问题最开始的原因，所以问题无法解决。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」指气候，不是可以被找到的问题原因。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：「找不到」通常搭配可以寻找的原因或线索，「长度」不能这样搭配。"}, {"text": "温度", "is_correct": false, "explanation": "语义：「温度」指冷热程度，不是问题的起因。"}], "explanations": {"根源": "正确。「找不到根源」指找不到问题最开始的原因，所以问题无法解决。", "天气": "语义：「天气」指气候，不是可以被找到的问题原因。", "长度": "搭配：「找不到」通常搭配可以寻找的原因或线索，「长度」不能这样搭配。", "温度": "语义：「温度」指冷热程度，不是问题的起因。"}, "sentence_index": 6, "correct_answer": "根源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的根源很便宜。", "explanation": "这里应该用〈价格〉。根源是原因，不能用来说东西便宜。"}, {"text": "这座房子的根源在北边。", "explanation": "这里应该用〈入口〉。根源指原因，不指方位。"}, {"text": "他的报告很长，根源是三十页。", "explanation": "这里应该用〈篇幅〉。根源是原因，不能用来说报告有几页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
