INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楷书的别称，笔画工整的字体。", "primary_collocate": null, "pronunciation": "zhèng shū", "ipa": "ʈʂɤŋ˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "正书就是楷书。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅作品是用正书写的。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们学写字，多从正书开始。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了十年正书。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有一本正书字帖。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正书的笔画很清楚。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说正书也叫楷书。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块碑上的字是正书。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢正书，不太喜欢草书。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要写好正书，先要坐正。", "target_word": "正书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "正书：楷书的别称，笔画工整的字体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98894, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正书", "is_correct": true, "explanation": "正书：楷书的别称，笔画工整的字体。"}, {"text": "正数", "is_correct": false, "explanation": "zhèng 相同，shū（第一声）与 shù（第四声）声调不同，意思是正数。"}, {"text": "赠书", "is_correct": false, "explanation": "zh 与 z 声母不同，zèng shū 意思是赠送图书。"}, {"text": "圣书", "is_correct": false, "explanation": "zh 与 sh 声母不同，shèng shū 意思是圣书（宗教经典）。"}], "explanations": {"正书": "正书：楷书的别称，笔画工整的字体。", "正数": "zhèng 相同，shū（第一声）与 shù（第四声）声调不同，意思是正数。", "赠书": "zh 与 z 声母不同，zèng shū 意思是赠送图书。", "圣书": "zh 与 sh 声母不同，shèng shū 意思是圣书（宗教经典）。"}, "sentence_index": null, "correct_answer": "正书"}, "level_3": {"options": [{"text": "正书", "is_correct": true, "explanation": "正书：楷书的别称，与“正书就是楷书”相符。"}, {"text": "草书", "is_correct": false, "explanation": "语义：草书是另一种字体，“草书就是楷书”不成立。"}, {"text": "行书", "is_correct": false, "explanation": "语义：行书与楷书不同，“行书就是楷书”说不通。"}, {"text": "字帖", "is_correct": false, "explanation": "搭配：“就是”后应接字体名称，字帖是材料，不能与楷书等同。"}], "explanations": {"正书": "正书：楷书的别称，与“正书就是楷书”相符。", "草书": "语义：草书是另一种字体，“草书就是楷书”不成立。", "行书": "语义：行书与楷书不同，“行书就是楷书”说不通。", "字帖": "搭配：“就是”后应接字体名称，字帖是材料，不能与楷书等同。"}, "sentence_index": 0, "correct_answer": "正书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他练了十年正书，字都连在一起，看不出笔画。", "explanation": "这里应该用〈草书〉。草书笔画连绵、少断笔；正书笔画独立分明，不会“字都连在一起”。"}, {"text": "他的正书字字狂放，几乎不成章法。", "explanation": "这里应该用〈狂草〉。狂草字字狂放、不成章法，正书端正平稳，不能这样描述。"}, {"text": "正书的笔画圆转弯曲，很有古意。", "explanation": "这里应该用〈篆书〉。正书笔画方正平直，不会圆转弯曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正书", "is_correct": true, "explanation": "正书：楷书的别称，与“老师说正书也叫楷书”相符。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：篆书是另一种字体，不叫楷书。"}, {"text": "隶书", "is_correct": false, "explanation": "语义：隶书与楷书是不同字体，“隶书也叫楷书”不成立。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“也叫”后应接字体名称，字迹是泛称，不能说“叫楷书”。"}], "explanations": {"正书": "正书：楷书的别称，与“老师说正书也叫楷书”相符。", "篆书": "语义：篆书是另一种字体，不叫楷书。", "隶书": "语义：隶书与楷书是不同字体，“隶书也叫楷书”不成立。", "字迹": "搭配：“也叫”后应接字体名称，字迹是泛称，不能说“叫楷书”。"}, "sentence_index": 6, "correct_answer": "正书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "正书的字行笔灵动，笔断意连。", "explanation": "这里应该用〈行书〉。行书行笔灵动、笔断意连；正书讲究端正稳重，不能这样写。"}, {"text": "正书的笔势飞动，一气呵成。", "explanation": "这里应该用〈行草〉。正书讲究端正平稳，与“飞动”“一气呵成”矛盾。"}, {"text": "正书的笔画扁平，讲究蚕头燕尾。", "explanation": "这里应该用〈隶书〉。蚕头燕尾是隶书的特征，正书没有这种写法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些正书们都很工整。", "corrected_sentence": "这些正书都很工整。", "error_description": "“正书”是事物名词，后面不能加“们”。“们”只用于人，应说“这些正书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用正书写字得很工整。", "corrected_sentence": "他用正书写字写得很工整。", "error_description": "动词带宾语时，后面接“得”要重复动词：应说“写字写得很工整”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
