INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比较分析是把几样东西放在一起看，找出哪里一样哪里不一样。", "primary_collocate": null, "pronunciation": "bǐ jiào fēn xī", "ipa": "pi˨˩˦ tɕjɑʊ˥˩ fən˥ ɕi˥", "syllable_count": 4, "sentences": [{"text": "老师让我们做一个比较分析。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份比较分析写得很清楚。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做比较分析以前，先看看数据。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较分析能让我们看到两家店的不同。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过比较分析，他发现了问题。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用比较分析选了最好的手机。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比较分析需要三天时间。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较分析告诉我们，哪种方法更好。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对两个城市做了比较分析。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想看这次的比较分析。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}], "register": "中性", "sense_fingerprint": "把几样东西放在一起看，找出相同和不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比较分析", "is_correct": true, "explanation": "正确：“比较分析”是把几样东西放在一起对照的工作，可以作为“做一个”的对象。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是自然景物，不是可以“做”出来的任务或成果，句子说不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：“阳光”是自然现象，不能被“做”成一个任务。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数的物质名词，不能和“一个”搭配，也不能说“做一个空气”。"}], "explanations": {"比较分析": "正确：“比较分析”是把几样东西放在一起对照的工作，可以作为“做一个”的对象。", "大海": "语义：“大海”是自然景物，不是可以“做”出来的任务或成果，句子说不通。", "阳光": "语义：“阳光”是自然现象，不能被“做”成一个任务。", "空气": "搭配：“空气”是不可数的物质名词，不能和“一个”搭配，也不能说“做一个空气”。"}, "sentence_index": 0, "correct_answer": "比较分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的比较分析昨晚咬了我一口。", "explanation": "这里应该用〈狗〉。“比较分析”是研究工作，不会咬人，指动物应说〈狗〉。"}, {"text": "他的比较分析饿了，要去吃饭。", "explanation": "这里应该用〈孩子〉。“比较分析”是研究方法，不会饿，指人应说〈孩子〉。"}, {"text": "这份比较分析在桌子上睡着了，叫都叫不醒。", "explanation": "这里应该用〈学生〉。“比较分析”是研究工作，不会睡觉，指人应说〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比较分析", "is_correct": true, "explanation": "正确：“这个比较分析”指一项研究工作，完成它可以“需要三天时间”。"}, {"text": "河水", "is_correct": false, "explanation": "语义：“河水”是自然物，不是需要完成的工作，不能“需要三天时间”。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "语义：“蝴蝶”是动物，不是需要三天完成的任务，句子说不通。"}, {"text": "清风", "is_correct": false, "explanation": "搭配：“清风”是自然现象，不用“这个”计量，也不说“需要三天时间”。"}], "explanations": {"比较分析": "正确：“这个比较分析”指一项研究工作，完成它可以“需要三天时间”。", "河水": "语义：“河水”是自然物，不是需要完成的工作，不能“需要三天时间”。", "蝴蝶": "语义：“蝴蝶”是动物，不是需要三天完成的任务，句子说不通。", "清风": "搭配：“清风”是自然现象，不用“这个”计量，也不说“需要三天时间”。"}, "sentence_index": 6, "correct_answer": "比较分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位明星的比较分析在舞台上唱了一首歌。", "explanation": "这里应该用〈歌手〉。“比较分析”是研究方法，不会唱歌，指人唱歌应说〈歌手〉。"}, {"text": "我的比较分析笑着跟老师打了招呼。", "explanation": "这里应该用〈同学〉。“比较分析”是研究方法，不会笑，指人打招呼应说〈同学〉。"}, {"text": "我们的比较分析在台下用力鼓掌。", "explanation": "这里应该用〈观众〉。“比较分析”是研究方法，不会鼓掌，指看演出的人应说〈观众〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的比较分析做很仔细。", "corrected_sentence": "他的比较分析做得很仔细。", "error_description": "错误在“得”的缺失。“做很仔细”漏掉了补语的结构助词“得”，应说“做得很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上个学期做了过一次比较分析。", "corrected_sentence": "我们上个学期做过一次比较分析。", "error_description": "错误在动态助词重复。“做了过”同时用了“了”和“过”，多余的“了”应去掉，应说“做过一次比较分析”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
