INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将不同对象并置对照，找出异同并加以研究的方法。", "primary_collocate": null, "pronunciation": "bǐ jiào fēn xī", "ipa": "pi˨˩˦ tɕjɑʊ˥˩ fən˥ ɕi˥", "syllable_count": 4, "sentences": [{"text": "比较分析是社会科学常用的研究方法。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者用比较分析研究两种文化。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇论文使用了比较分析。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较分析要先找到可以对照的对象。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文主要采用比较分析，对比了两国的法律。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较分析让学者看出两种制度的异同。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课教我们怎么使用比较分析。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做历史研究时，比较分析很有用。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用比较分析研究两国的教育。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较分析的结果支持了他的看法。", "target_word": "比较分析", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "比较分析法", "label": "复合"}], "register": "书面", "sense_fingerprint": "并置对照不同对象、找出异同的研究方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比较分析", "is_correct": true, "explanation": "正确：“比较分析”是社会科学中的研究方法，可以作主语，符合句子的定义语境。"}, {"text": "文具", "is_correct": false, "explanation": "语义：“文具”是学习用品，不是研究方法，不能作主语说这种定义。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是研究方法，句子说不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不能用于这种书面的定义句。"}], "explanations": {"比较分析": "正确：“比较分析”是社会科学中的研究方法，可以作主语，符合句子的定义语境。", "文具": "语义：“文具”是学习用品，不是研究方法，不能作主语说这种定义。", "天气": "语义：“天气”是自然现象，不是研究方法，句子说不通。", "玩意儿": "语域：“玩意儿”是口语说法，不能用于这种书面的定义句。"}, "sentence_index": 0, "correct_answer": "比较分析"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的比较分析在操场上跑了三圈。", "explanation": "这里应该用〈同学〉。“比较分析”是研究方法，不会跑步，指人跑步应说〈同学〉。"}, {"text": "我们的比较分析在台上跳了一支舞。", "explanation": "这里应该用〈舞者〉。“比较分析”是研究方法，不会跳舞，指人跳舞应说〈舞者〉。"}, {"text": "这次比较分析把午饭吃光了。", "explanation": "这里应该用〈大家〉。“比较分析”是研究方法，不会吃饭，指人吃饭应说〈大家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比较分析", "is_correct": true, "explanation": "正确：“使用比较分析”指运用这种研究方法，符合“怎么使用”的宾语要求。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：“海浪”是自然现象，不是可以“使用”的方法，句子说不通。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“使用”接方法或工具，不接食物，应说“吃饺子”。"}, {"text": "云层", "is_correct": false, "explanation": "语义：“云层”是天空中的气象现象，不能被“使用”。"}], "explanations": {"比较分析": "正确：“使用比较分析”指运用这种研究方法，符合“怎么使用”的宾语要求。", "海浪": "语义：“海浪”是自然现象，不是可以“使用”的方法，句子说不通。", "饺子": "搭配：“使用”接方法或工具，不接食物，应说“吃饺子”。", "云层": "语义：“云层”是天空中的气象现象，不能被“使用”。"}, "sentence_index": 6, "correct_answer": "比较分析"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的比较分析在操场上踢足球。", "explanation": "这里应该用〈同学〉。“比较分析”是研究方法，不会踢球，指人踢球应说〈同学〉。"}, {"text": "这份比较分析很甜，妈妈做得很好吃。", "explanation": "这里应该用〈蛋糕〉。“比较分析”是研究方法，不能吃，指食物应说〈蛋糕〉。"}, {"text": "我的比较分析正在厨房里做饭。", "explanation": "这里应该用〈厨师〉。“比较分析”是研究方法，不会做饭，指人做饭应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者在分析数据时用了一把比较分析。", "corrected_sentence": "研究者在分析数据时用了比较分析。", "error_description": "量词错误：“把”多用于有柄的器具，“比较分析”是方法，不能用“一把”计量。正确写作：用了比较分析。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门课上我们学了过比较分析。", "corrected_sentence": "这门课上我们学过比较分析。", "error_description": "错误在动态助词重复。“学了过”同时用了“了”和“过”，多余的“了”应去掉，应说“学过比较分析”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
