INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "民兵是平时做自己的事，有需要时才拿起枪保护大家的普通人。", "primary_collocate": null, "pronunciation": "mín bīng", "ipa": "min˧˥ piŋ˥", "syllable_count": 2, "sentences": [{"text": "民兵是普通人，不是天天打仗的军人。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时是民兵，平时在田里干活。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有坏人来村子时，民兵拿起枪保护大家。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位民兵每天先下地种菜，再去站岗。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有二十多个民兵，大家都认识他们。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是警察，只是一个村里的民兵。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时，很多农民成了民兵，拿枪保护家乡。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民兵白天做饭、种田，晚上拿枪巡逻。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我很想当民兵，因为他们有枪。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个民兵正在山路上保护过路的人。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "民兵组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "平时务农，需要时拿枪保护大家的普通人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民兵", "is_correct": true, "explanation": "正确答案：民兵，平时做自己的事、需要时拿枪保护大家的普通人，与句子相符。"}, {"text": "将军", "is_correct": false, "explanation": "语义：将军不是普通人，句子说的是普通人。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝不是普通人，与“普通人”矛盾。"}, {"text": "贵族", "is_correct": false, "explanation": "搭配：“普通人”与“贵族”相对，句中不能说贵族是普通人。"}], "explanations": {"民兵": "正确答案：民兵，平时做自己的事、需要时拿枪保护大家的普通人，与句子相符。", "将军": "语义：将军不是普通人，句子说的是普通人。", "皇帝": "语义：皇帝不是普通人，与“普通人”矛盾。", "贵族": "搭配：“普通人”与“贵族”相对，句中不能说贵族是普通人。"}, "sentence_index": 0, "correct_answer": "民兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "民兵每天在前线打仗，很少回家。", "explanation": "这里应该用〈战士〉。战士是专门打仗的军人；民兵平时做自己的事，有需要时才拿枪，不天天打仗。"}, {"text": "民兵每天在指挥部里研究作战计划，很少出门。", "explanation": "这里应该用〈将军〉。将军是指挥作战的军官；民兵是平时做自己的事的普通人，不负责指挥部的工作。"}, {"text": "民兵每天在山里训练，日夜不停。", "explanation": "这里应该用〈特种兵〉。特种兵是专门训练作战的军人；民兵平时做自己的事，不日夜训练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民兵", "is_correct": true, "explanation": "正确答案：民兵，战争时拿枪保护家乡的普通人，与句子相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作与战时拿枪保护家乡不相关，句子说的是拿枪。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不会因为战争而拿枪保护家乡。"}, {"text": "作家", "is_correct": false, "explanation": "搭配：“拿枪保护家乡”与“作家”的身份不搭配。"}], "explanations": {"民兵": "正确答案：民兵，战争时拿枪保护家乡的普通人，与句子相符。", "厨师": "语义：厨师的工作与战时拿枪保护家乡不相关，句子说的是拿枪。", "歌手": "语义：歌手不会因为战争而拿枪保护家乡。", "作家": "搭配：“拿枪保护家乡”与“作家”的身份不搭配。"}, "sentence_index": 6, "correct_answer": "民兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个民兵是我们国家的一个少数民族，有自己的语言。", "explanation": "这里应该用〈民族〉。民兵是人的身份，不是民族；少数民族才有自己的语言。"}, {"text": "民兵一年到头都在训练场，很少回家。", "explanation": "这里应该用〈运动员〉。运动员专职训练；民兵平时做自己的事，有需要才拿枪，不一年到头在训练场。"}, {"text": "民兵每天在军舰上值班，很少靠岸。", "explanation": "这里应该用〈水兵〉。水兵是常年在军舰上服役的军人；民兵平时做自己的事，不在军舰上值班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有三个民兵们，都很年轻。", "corrected_sentence": "村里有三个民兵，都很年轻。", "error_description": "数量错：“们”不能和数词一起用。说“三个民兵”，不能说“三个民兵们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只民兵每天早上都来站岗。", "corrected_sentence": "一位民兵每天早上都来站岗。", "error_description": "量词用错：指人的民兵应用“位”或“名”，“只”用于动物或成对的东西。把“一位民兵”说成“一只民兵”就错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不脱离生产、平时从事本职工作的群众性武装组织成员。", "primary_collocate": null, "pronunciation": "mín bīng", "ipa": "min˧˥ piŋ˥", "syllable_count": 2, "sentences": [{"text": "民兵平时在家种地，有任务时才集合。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是村里的一名民兵，也是一位农民。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民兵和军人不同，他们平时不离开工作岗位。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，村里的民兵马上去河边帮忙。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家组织民兵每年训练一次。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人年轻时当过民兵。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民兵的本职工作是种地，不是打仗。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民兵们在山上巡逻，保护村子的安全。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他白天在工厂上班，晚上去参加民兵的训练。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，民兵和警察一起救人。", "target_word": "民兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "民兵組織", "label": "繁体"}, {"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "不脱离生产的群众性武装组织成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民兵", "is_correct": true, "explanation": "正确答案：民兵，平时在家种地、有任务时集合的人，与句子相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不是平时在家种地、有任务时集合的人。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不种地，也不会在任务时集合。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“种地”与“厨师”的身份不搭配，厨师不说“平时在家种地”。"}], "explanations": {"民兵": "正确答案：民兵，平时在家种地、有任务时集合的人，与句子相符。", "学生": "语义：学生不是平时在家种地、有任务时集合的人。", "游客": "语义：游客不种地，也不会在任务时集合。", "厨师": "搭配：“种地”与“厨师”的身份不搭配，厨师不说“平时在家种地”。"}, "sentence_index": 0, "correct_answer": "民兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "民兵平时住在营房里，有任务时集合。", "explanation": "这里应该用〈军人〉。民兵平时在家从事本职工作，不住营房，有任务时才集合。"}, {"text": "民兵都是专职的，每天在部队里训练。", "explanation": "这里应该用〈士兵〉。士兵是专职的军人；民兵不脱离生产，平时做本职工作，不是专职的。"}, {"text": "民兵一入伍就离开了农田，每天操练。", "explanation": "这里应该用〈战士〉。战士入伍后离开生产、专门操练；民兵不脱离生产，平时照常种地做工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民兵", "is_correct": true, "explanation": "正确答案：民兵，本职工作是种地、不打仗的人，与句子相符。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人的本职工作不是种地，句子说的是农活。"}, {"text": "士兵", "is_correct": false, "explanation": "语义：士兵的本职工作是打仗，与“不是打仗”矛盾。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“本职工作是种地”的人应与农业相关，司机不种地，搭配不通。"}], "explanations": {"民兵": "正确答案：民兵，本职工作是种地、不打仗的人，与句子相符。", "工人": "语义：工人的本职工作不是种地，句子说的是农活。", "士兵": "语义：士兵的本职工作是打仗，与“不是打仗”矛盾。", "司机": "搭配：“本职工作是种地”的人应与农业相关，司机不种地，搭配不通。"}, "sentence_index": 6, "correct_answer": "民兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "民兵每天只练习，不干别的事情。", "explanation": "这里应该用〈运动员〉。民兵平时要做本职工作，不能只练习、不干别的事。"}, {"text": "民兵在部队里有很高的军衔，要带兵打仗。", "explanation": "这里应该用〈将军〉。民兵没有军衔，也不负责带兵打仗；将军才有军衔。"}, {"text": "我们国家有五十六个民兵，各自有自己的语言和风俗。", "explanation": "这里应该用〈民族〉。民兵是人的身份，不是民族；民族才有自己的语言和风俗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有一只民兵，很会修机器。", "corrected_sentence": "村里有一位民兵，很会修机器。", "error_description": "量词用错：指人的民兵应用“位”或“名”，“只”用于动物或成对的东西。把“一位民兵”说成“一只民兵”就错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时过当民兵，后来去了城里的工厂。", "corrected_sentence": "他年轻时当过民兵，后来去了城里的工厂。", "error_description": "体标位置错：“过”是动词后的体标，必须紧跟动词“当”，说“当过民兵”；把“过”放在“当”前面，说“过当民兵”就错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
