INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汽油是给汽车加的油，车子喝了它才会跑。", "primary_collocate": null, "pronunciation": "qì yóu", "ipa": "tɕʰi˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "车没有汽油了，我们去加油站吧。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给汽车加了五十块钱的汽油。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油很贵，所以我少开车。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车一百公里要用六升汽油。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油的味道很重，我不喜欢。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有汽油，车子就不能跑。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天汽油又涨价了。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油站里卖汽油，也卖水。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油很容易烧起来，加油站不能抽烟。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸忘了加汽油，车在路上停了。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升", "label": "量词"}, {"form": "汽油车", "label": "复合"}], "register": "中性", "sense_fingerprint": "给汽车加的油，车靠它才能开动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：车不用面包，“没有面包了”与去加油站无关。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：车不用牛奶，句中的“没有”与加油站对不上。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“没有……了”后面要接车的燃料，钥匙不是燃料，与“去加油站”不搭。"}, {"text": "汽油", "is_correct": true, "explanation": "汽油：车用的燃料，缺了就要去加油站补充。"}], "explanations": {"面包": "语义：车不用面包，“没有面包了”与去加油站无关。", "牛奶": "语义：车不用牛奶，句中的“没有”与加油站对不上。", "钥匙": "搭配：“没有……了”后面要接车的燃料，钥匙不是燃料，与“去加油站”不搭。", "汽油": "汽油：车用的燃料，缺了就要去加油站补充。"}, "sentence_index": 0, "correct_answer": "汽油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本汽油，放在后备箱里。", "explanation": "量词用错：汽油是液体，应用〈升〉或〈桶〉，不用〈本〉。"}, {"text": "加油站卖一只汽油，很便宜。", "explanation": "量词用错：〈只〉多用于动物或成对物品中的一个，汽油应用〈升〉或〈桶〉。"}, {"text": "爸爸买了一张汽油。", "explanation": "量词用错：〈张〉多用于平面的东西，汽油应用〈升〉或〈桶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "朋友", "is_correct": false, "explanation": "语义：人不能涨价，“朋友又涨价了”说不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是商品，不会涨价。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“涨价”多用于商品和价格，不搭配“时间”。"}, {"text": "汽油", "is_correct": true, "explanation": "汽油：是商品，可以涨价，符合“今天又涨价了”。"}], "explanations": {"朋友": "语义：人不能涨价，“朋友又涨价了”说不通。", "阳光": "语义：阳光不是商品，不会涨价。", "时间": "搭配：“涨价”多用于商品和价格，不搭配“时间”。", "汽油": "汽油：是商品，可以涨价，符合“今天又涨价了”。"}, "sentence_index": 6, "correct_answer": "汽油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的汽油快用完了，妈妈打电话叫人送汽油。", "explanation": "这里应该用〈煤气〉。汽油是汽车的燃料，做饭要用〈煤气〉。"}, {"text": "伤口有点疼，妈妈用汽油消毒。", "explanation": "这里应该用〈酒精〉。汽油有毒、易燃，消毒要用〈酒精〉。"}, {"text": "做菜时，妈妈加了一点汽油。", "explanation": "这里应该用〈酱油〉。汽油是燃料，有毒，不能用来调味，调味要用〈酱油〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的车用地汽油是九十五号的。", "corrected_sentence": "我的车用的汽油是九十五号的。", "error_description": "错误：“用地汽油”，应为“用的汽油”。修饰名词要用“的”，“地”修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸汽油倒进了油箱。", "corrected_sentence": "爸爸把汽油倒进了油箱。", "error_description": "错误：“爸爸汽油倒进了油箱”，应为“爸爸把汽油倒进了油箱”。“汽油”是“倒进”的受事，要用“把”提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
