INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从石油中提炼出的液体燃料，用于汽车等发动机。", "primary_collocate": null, "pronunciation": "qì yóu", "ipa": "tɕʰi˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "汽油是从石油里提炼出来的。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油和柴油都是燃料，用在不同的发动机里。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油是一种无色的液体。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种发动机只能用汽油，不能用柴油。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用石油生产汽油和塑料。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油容易挥发，要放在安全的地方。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电动车不用汽油，用电。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油价格跟石油价格有关系。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油燃烧时会放出热量。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽油发动机比柴油发动机安静。", "target_word": "汽油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升", "label": "量词"}, {"form": "汽油机", "label": "复合"}], "register": "中性", "sense_fingerprint": "石油提炼出的液体燃料，供发动机使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白糖", "is_correct": false, "explanation": "语义：白糖不是从石油里提炼的，是从甘蔗或甜菜里提取的。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石油提炼得到的是液体，石头是固体，形态不符。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是粮食加工品，不从石油中提炼。"}, {"text": "汽油", "is_correct": true, "explanation": "汽油：从石油里提炼出的液体燃料，符合句意。"}], "explanations": {"白糖": "语义：白糖不是从石油里提炼的，是从甘蔗或甜菜里提取的。", "石头": "体貌：石油提炼得到的是液体，石头是固体，形态不符。", "面粉": "语义：面粉是粮食加工品，不从石油中提炼。", "汽油": "汽油：从石油里提炼出的液体燃料，符合句意。"}, "sentence_index": 0, "correct_answer": "汽油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家里的灶具用的是汽油。", "explanation": "这里应该用〈天然气〉。汽油是液体燃料，不用于家用灶具，灶具要用〈天然气〉。"}, {"text": "这台老式打印机每次开机前要加一罐汽油。", "explanation": "这里应该用〈墨水〉。汽油是发动机燃料，打印机要加墨水，加汽油完全用错了。"}, {"text": "我每天早上喝一杯汽油，补充能量。", "explanation": "这里应该用〈牛奶〉。汽油是有毒的燃料，不能饮用，补充营养应当喝〈牛奶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是动力来源，“不用……用电”的对比不成立。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“用”后接能源或燃料，“玩具”不能作为动力来源。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是照明用品，不是车的动力，与“用电”的对照不成立。"}, {"text": "汽油", "is_correct": true, "explanation": "汽油：车用燃料，与“用电”形成对比，符合句意。"}], "explanations": {"饼干": "语义：饼干是食品，不是动力来源，“不用……用电”的对比不成立。", "玩具": "搭配：“用”后接能源或燃料，“玩具”不能作为动力来源。", "蜡烛": "语义：蜡烛是照明用品，不是车的动力，与“用电”的对照不成立。", "汽油": "汽油：车用燃料，与“用电”形成对比，符合句意。"}, "sentence_index": 6, "correct_answer": "汽油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "加油站里有一块汽油。", "explanation": "量词用错：汽油是液体，应用〈升〉或〈桶〉，不用〈块〉。"}, {"text": "工厂里有一条汽油。", "explanation": "量词用错：〈条〉用于细长的东西，汽油应用〈升〉或〈桶〉。"}, {"text": "他的车里有一根汽油。", "explanation": "量词用错：〈根〉用于细长的东西，汽油应用〈升〉或〈桶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种从石油里炼出地汽油很容易挥发。", "corrected_sentence": "这种从石油里炼出的汽油很容易挥发。", "error_description": "错误：“炼出地汽油”，应为“炼出的汽油”。修饰名词要用“的”，“地”修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人汽油装进了桶里。", "corrected_sentence": "工人把汽油装进了桶里。", "error_description": "错误：“工人汽油装进了桶里”，应为“工人把汽油装进了桶里”。“汽油”是“装进”的受事，要用“把”提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
