INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沿岸是河或海边上的一长条地方。", "primary_collocate": null, "pronunciation": "yán àn", "ipa": "jɛn˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "河流沿岸有很多绿色的树。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江沿岸有很多大城市。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的沿岸种着很多花。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，海南岛沿岸的游客特别多。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河沿岸的人们喜欢吃面条。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿岸的房子都很旧，但是很漂亮。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在黄海沿岸散步，看见了很多海鸟。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿岸的饭店都卖新鲜的鱼，价格也不贵。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，沿岸的渔船都回港了。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家沿岸的天气比山里暖和。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "沿着河或海的边上的一长条地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正确：“河流沿岸”指河边的一长条地方，与后面“有很多绿色的树”相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是室内房间，不能和“河流”构成一个地带，句子说不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“河流”后面要接表示方位的词，“手机”不能用在这里。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是室内场所，不能说“河流教室”，与树的位置矛盾。"}], "explanations": {"沿岸": "正确：“河流沿岸”指河边的一长条地方，与后面“有很多绿色的树”相符。", "厨房": "语义：“厨房”是室内房间，不能和“河流”构成一个地带，句子说不通。", "手机": "搭配：“河流”后面要接表示方位的词，“手机”不能用在这里。", "教室": "语义：“教室”是室内场所，不能说“河流教室”，与树的位置矛盾。"}, "sentence_index": 0, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山脚沿岸住着几户人家。", "explanation": "这里应该用〈山脚下〉。沿岸指河、湖、海边的一长条地方，山脚没有河岸，不能用沿岸。"}, {"text": "教室沿岸放着很多桌子。", "explanation": "这里应该用〈教室里〉。沿岸只指河、湖、海边的地带，教室里不能用沿岸。"}, {"text": "田沿岸种着麦子。", "explanation": "这里应该用〈田边〉。沿岸是河、湖、海边的地带，田边不能用沿岸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正确：“在黄海沿岸散步”指在海边的一长条地带散步，与后面“看见了很多海鸟”相符。"}, {"text": "会议室", "is_correct": false, "explanation": "语义：“会议室”是室内场所，不能在黄海上散步，句子说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“在……散步”要求地点，“课本”不是可以散步的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不是散步的场所，与黄海无关。"}], "explanations": {"沿岸": "正确：“在黄海沿岸散步”指在海边的一长条地带散步，与后面“看见了很多海鸟”相符。", "会议室": "语义：“会议室”是室内场所，不能在黄海上散步，句子说不通。", "课本": "搭配：“在……散步”要求地点，“课本”不是可以散步的地方。", "冰箱": "语义：“冰箱”是家用电器，不是散步的场所，与黄海无关。"}, "sentence_index": 6, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客厅沿岸摆着一张沙发。", "explanation": "这里应该用〈客厅里〉。沿岸只指河、湖、海边的地带，客厅里不能用沿岸。"}, {"text": "屋顶沿岸住着很多鸽子。", "explanation": "这里应该用〈屋顶上〉。沿岸只指河、湖、海边的地带，屋顶不能用沿岸。"}, {"text": "森林沿岸有很多鸟。", "explanation": "这里应该用〈森林里〉。沿岸只用于水边的地带，森林里没有河岸，不能用沿岸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在操场沿岸跑步。", "corrected_sentence": "我们在河流沿岸跑步。", "error_description": "错误在“操场沿岸”。沿岸只用于河、湖、海边的地带，操场没有岸，应说“河流沿岸”（或“操场上”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在黄海一个沿岸玩耍。", "corrected_sentence": "孩子们在黄海沿岸玩耍。", "error_description": "量词错误：“沿岸”是一长条地方，前面不能加数量词“一个”。正确写作：孩子们在黄海沿岸玩耍。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
