INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河、湖、海岸边的地带。", "primary_collocate": null, "pronunciation": "yán àn", "ipa": "jɛn˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "湖的沿岸有一条长长的小路。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "莱茵河沿岸有很多古老的小镇。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿岸的风景很美，我拍了很多照片。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在海河沿岸建了几个新公园。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿岸的水很浅，孩子们可以在那儿玩水。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她住在珠江沿岸，每天早上都去跑步。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖沿岸的草地上坐着很多人。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿岸的酒店晚上都亮着灯。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，运河沿岸的树叶都变黄了。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太湖沿岸有不少好吃的饭店。", "target_word": "沿岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "河、湖、海岸边的地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正确：“湖的沿岸”指湖边的一长条地带，与后面“有一条长长的小路”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”在空中，不是湖的一部分，不能说“湖的天空有一条小路”。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“湖的”后面要接表示地点的词，“书包”不是地点。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是随身物品，不是湖的一部分，句子说不通。"}], "explanations": {"沿岸": "正确：“湖的沿岸”指湖边的一长条地带，与后面“有一条长长的小路”相符。", "天空": "语义：“天空”在空中，不是湖的一部分，不能说“湖的天空有一条小路”。", "书包": "搭配：“湖的”后面要接表示地点的词，“书包”不是地点。", "手机": "语义：“手机”是随身物品，不是湖的一部分，句子说不通。"}, "sentence_index": 0, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "草原沿岸住着很多牧民。", "explanation": "这里应该用〈草原上〉。沿岸指河、湖、海边的一长条地方，草原上没有河岸，不能用沿岸。"}, {"text": "山坡沿岸种着很多茶树。", "explanation": "这里应该用〈山坡上〉。沿岸只用于水边，山坡上没有河湖海岸，不能用沿岸。"}, {"text": "床沿岸放着一杯水。", "explanation": "这里应该用〈床边〉。沿岸只指河、湖、海边的地带，床边不能用沿岸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沿岸", "is_correct": true, "explanation": "正确：“这个湖沿岸的草地”指湖边的草地，符合“坐着很多人”的语境。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是室内的商店，不是湖边的地方，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不是湖边的地带，句子说不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“这个湖”后面要接表示方位的词，“电视”不能用在这里。"}], "explanations": {"沿岸": "正确：“这个湖沿岸的草地”指湖边的草地，符合“坐着很多人”的语境。", "书店": "语义：“书店”是室内的商店，不是湖边的地方，句子说不通。", "冰箱": "语义：“冰箱”是家用电器，不是湖边的地带，句子说不通。", "电视": "搭配：“这个湖”后面要接表示方位的词，“电视”不能用在这里。"}, "sentence_index": 6, "correct_answer": "沿岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山顶沿岸有一座小庙。", "explanation": "这里应该用〈山顶上〉。沿岸指河、湖、海边的地带，山顶没有岸边，不能用沿岸。"}, {"text": "书包沿岸挂着很多钥匙。", "explanation": "这里应该用〈书包上〉。沿岸只指河、湖、海边的地带，书包上不能用沿岸。"}, {"text": "黑板沿岸写着作业。", "explanation": "这里应该用〈黑板上〉。沿岸不能用于黑板，黑板上写字应说〈黑板上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在公园沿岸散步。", "corrected_sentence": "我们在湖的沿岸散步。", "error_description": "错误在“公园沿岸”。沿岸只用于河、湖、海边的地带，公园本身没有岸，应说“湖的沿岸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔民们把湖的沿岸撒网。", "corrected_sentence": "渔民们在湖的沿岸撒网。", "error_description": "错误在介词“把”。“撒网”的地点应用介词“在”引出，说“在湖的沿岸撒网”；“把”字句要求宾语受到处置，“沿岸”是地点，不能用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
