INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98914, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用注射器将液体药物注入体内。", "primary_collocate": null, "pronunciation": "zhù shè", "ipa": "tʂu˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "护士给病人注射了药物。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生正在给小孩注射疫苗。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生将药液注射到病人体内。", "target_word": "注射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注射前，护士先用酒精擦手臂。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天要给自己注射胰岛素。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狗咬人后，要尽快注射疫苗。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士把药水慢慢注射到病人的血管里。", "target_word": "注射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注射药物以后，病人睡着了。", "target_word": "注射", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕疼，不想去医院注射。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药不能口服，只能注射。", "target_word": "注射", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "注射了", "label": "完成体"}, {"form": "注射过", "label": "经历体"}, {"form": "注射器", "label": "复合词"}, {"form": "注射液", "label": "复合词"}], "register": "书面", "sense_fingerprint": "医护人员用注射器把药液、疫苗等注入人体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6cfd6c5-0201-4335-98b8-7045c06a3902') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "注射", "is_correct": true, "explanation": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。"}, {"text": "注视", "is_correct": false, "explanation": "第二音节韵母不同：shì 为 -i，shè 为 -e；注视意思是凝视。"}, {"text": "祝贺", "is_correct": false, "explanation": "第二音节声母不同：hè 为 h，shè 为 sh；祝贺意思是庆贺。"}, {"text": "猪舍", "is_correct": false, "explanation": "第一音节声调不同：zhū 为第一声，zhù 为第四声；猪舍意思是养猪的棚屋。"}, {"text": "畜舍", "is_correct": false, "explanation": "第一音节声母不同：chù 为送气的 ch，zhù 为不送气的 zh；畜舍意思是养牲畜的房舍。"}], "explanations": {"注射": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。", "注视": "第二音节韵母不同：shì 为 -i，shè 为 -e；注视意思是凝视。", "祝贺": "第二音节声母不同：hè 为 h，shè 为 sh；祝贺意思是庆贺。", "猪舍": "第一音节声调不同：zhū 为第一声，zhù 为第四声；猪舍意思是养猪的棚屋。", "畜舍": "第一音节声母不同：chù 为送气的 ch，zhù 为不送气的 zh；畜舍意思是养牲畜的房舍。"}, "sentence_index": null, "correct_answer": "注射"}, "level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物、身体等，不能洗药物，与“给病人……了药物”的句意不合。"}, {"text": "注射", "is_correct": true, "explanation": "注射：用针管把药物打入病人体内，与“给病人……了药物”搭配。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只配衣服、鞋袜等，不能说穿药物。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”用于纸张、布料等，不能用于药物。"}], "explanations": {"洗": "语义：“洗”的对象是衣物、身体等，不能洗药物，与“给病人……了药物”的句意不合。", "注射": "注射：用针管把药物打入病人体内，与“给病人……了药物”搭配。", "穿": "搭配：“穿”只配衣服、鞋袜等，不能说穿药物。", "撕": "搭配：“撕”用于纸张、布料等，不能用于药物。"}, "sentence_index": 0, "correct_answer": "注射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大量的热水注射到了浴缸里。", "explanation": "这里应该用〈注入〉。注射专指用针把药液打进人体，往容器里灌水要用“注入”。"}, {"text": "医生给他注射了血。", "explanation": "这里应该用〈输〉。注射指把药液打入体内，输血要用“输”，血液不能说注射。"}, {"text": "老师把正确的道理注射给学生。", "explanation": "这里应该用〈灌输〉。注射只用于药液进入人体，抽象的道理要用“灌输”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98914, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "注射", "is_correct": true, "explanation": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。"}, {"text": "注释", "is_correct": false, "explanation": "第二音节韵母不同：shì 为 -i，shè 为 -e；注释意思是解释字词或文句。"}, {"text": "竹舍", "is_correct": false, "explanation": "第一音节声调不同：zhú 为第二声，zhù 为第四声；竹舍意思是竹子搭的房屋。"}, {"text": "注册", "is_correct": false, "explanation": "第二音节声母不同：cè 为 c，shè 为 sh；注册意思是登记。"}], "explanations": {"注射": "注射（zhù shè）：用针把药液打进体内，是本词的读音与意思。", "注释": "第二音节韵母不同：shì 为 -i，shè 为 -e；注释意思是解释字词或文句。", "竹舍": "第一音节声调不同：zhú 为第二声，zhù 为第四声；竹舍意思是竹子搭的房屋。", "注册": "第二音节声母不同：cè 为 c，shè 为 sh；注册意思是登记。"}, "sentence_index": null, "correct_answer": "注射"}, "level_3": {"options": [{"text": "涂", "is_correct": false, "explanation": "搭配：“涂”是把药膏等抹在表面，药水不能涂进血管里。"}, {"text": "注射", "is_correct": true, "explanation": "注射：用针把药水送入体内，与“慢慢……到病人的血管里”的句意相合。"}, {"text": "搅", "is_correct": false, "explanation": "语义：“搅”是搅拌，与把药水送入血管的动作不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷，药水不能被扔进血管里。"}], "explanations": {"涂": "搭配：“涂”是把药膏等抹在表面，药水不能涂进血管里。", "注射": "注射：用针把药水送入体内，与“慢慢……到病人的血管里”的句意相合。", "搅": "语义：“搅”是搅拌，与把药水送入血管的动作不符。", "扔": "语义：“扔”是抛掷，药水不能被扔进血管里。"}, "sentence_index": 6, "correct_answer": "注射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民给庄稼注射了农药。", "explanation": "这里应该用〈喷〉。注射是把药液打进人体或动物体内，给庄稼施农药要用“喷”。"}, {"text": "园丁给花注射了水。", "explanation": "这里应该用〈浇〉。注射只用于把药液送入体内，给花浇水要用“浇”。"}, {"text": "工人往罐子里注射了水。", "explanation": "这里应该用〈灌〉。注射只用于人或动物体内，往罐子里灌水要用“灌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候注射了过疫苗。", "corrected_sentence": "他小时候注射过疫苗。", "error_description": "错误：“注射”后同时用了完成标记“了”和经历标记“过”，两者不能共现。应去掉“了”，说“注射过”，表示曾经打过疫苗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把麻药注射他的手臂上。", "corrected_sentence": "医生把麻药注射到他的手臂上。", "error_description": "错误：“注射”后漏掉了引出去向的介词“到”，应说“注射到他的手臂上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
