INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98919, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "深受是特别地受到。", "primary_collocate": null, "pronunciation": "shēn shòu", "ipa": "ʂən˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书深受小朋友喜爱。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师深受学生欢迎。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她深受大家的尊重。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌深受年轻人喜欢。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园深受老人欢迎。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目深受观众欢迎。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李做事认真，深受老板信任。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果深受孩子们喜爱。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷人很好，深受邻居尊敬。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面条深受客人喜欢。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "特别地受到（喜爱、欢迎、信任等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98919, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深受", "is_correct": true, "explanation": "深受（shēn shòu）是本词的标准读音与词义，正确。"}, {"text": "伸手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是伸出手。"}, {"text": "身手", "is_correct": false, "explanation": "第二音节 shǒu（第三声）与 shòu（第四声）声调不同，意思是本领、技能。"}, {"text": "申述", "is_correct": false, "explanation": "第二音节韵母 u 与 ou 不同，意思是陈述、说明。"}, {"text": "神兽", "is_correct": false, "explanation": "第一音节 shén（第二声）与 shēn（第一声）声调不同，意思是神话中的野兽。"}], "explanations": {"深受": "深受（shēn shòu）是本词的标准读音与词义，正确。", "伸手": "shǒu（第三声）与 shòu（第四声）声调不同，意思是伸出手。", "身手": "第二音节 shǒu（第三声）与 shòu（第四声）声调不同，意思是本领、技能。", "申述": "第二音节韵母 u 与 ou 不同，意思是陈述、说明。", "神兽": "第一音节 shén（第二声）与 shēn（第一声）声调不同，意思是神话中的野兽。"}, "sentence_index": null, "correct_answer": "深受"}, "level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”与“喜爱”意思相反，句子说书受小朋友喜爱。"}, {"text": "深受", "is_correct": true, "explanation": "深受：特别地受到，与“喜爱”搭配，句意通顺。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”搭配声誉、权利，不说“享有喜爱”。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意、抵制，与“喜爱”的意思相矛盾。"}], "explanations": {"讨厌": "语义：“讨厌”与“喜爱”意思相反，句子说书受小朋友喜爱。", "深受": "深受：特别地受到，与“喜爱”搭配，句意通顺。", "享有": "搭配：“享有”搭配声誉、权利，不说“享有喜爱”。", "反对": "语义：“反对”表示不同意、抵制，与“喜爱”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "深受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料稍微深受学生欢迎。", "explanation": "这里应该用〈很受〉。“深受”本身表示程度很深，与“稍微”矛盾。"}, {"text": "这些孩子深受数学课本。", "explanation": "这里应该用〈深入〉。“深受”后接的是喜爱、影响等感受，不接“数学课本”这类物体。"}, {"text": "他深受抱歉。", "explanation": "这里应该用〈深感〉。“深受”后接的是所受的喜爱或影响，“抱歉”是说话人自己的心情，不能作“受”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”与“信任”相反，句子说小李做事认真，应当得到信任。"}, {"text": "深受", "is_correct": true, "explanation": "深受：特别地受到，与“信任”搭配，句意通顺。"}, {"text": "辜负", "is_correct": false, "explanation": "语义：“辜负”指没有达到别人的期望，与“做事认真”的褒扬语境相反。"}, {"text": "轻视", "is_correct": false, "explanation": "语义：“轻视”表示看不起，与“信任”的态度相反。"}], "explanations": {"怀疑": "语义：“怀疑”与“信任”相反，句子说小李做事认真，应当得到信任。", "深受": "深受：特别地受到，与“信任”搭配，句意通顺。", "辜负": "语义：“辜负”指没有达到别人的期望，与“做事认真”的褒扬语境相反。", "轻视": "语义：“轻视”表示看不起，与“信任”的态度相反。"}, "sentence_index": 6, "correct_answer": "深受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师深受人心。", "explanation": "这里应该用〈深得〉。“深受”后接的是喜爱或影响，不接“人心”；“深得人心”是另一个固定搭配。"}, {"text": "这家店的面条深受客人的付款。", "explanation": "“深受”后接的是喜爱或影响等感受，不接“付款”这类行为，此处不宜用“深受”。"}, {"text": "这个地区深受泥潭。", "explanation": "这里应该用〈深陷〉。“深陷”表示陷入某种境地，“深受”后接的是感受或影响，不接“泥潭”这类地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影很深受观众欢迎。", "corrected_sentence": "这部电影深受观众欢迎。", "error_description": "错误形式：“很深受”。正确形式：“深受”。“深受”本身已表示程度很深，前面不必再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款手机被深受年轻人青睐。", "corrected_sentence": "这款手机深受年轻人青睐。", "error_description": "错误形式：“被深受”。正确形式：“深受”。“深受”本身已含“受”的意思，前面不能再加“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
