INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "受到很深的影响或很大程度地受到。", "primary_collocate": null, "pronunciation": "shēn shòu", "ipa": "ʂən˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他的想法深受父母影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子深受爷爷的影响，爱写毛笔字。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生活习惯深受家人影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她深受这部电影的影响，也想当演员。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市深受海洋气候影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明深受哥哥影响，也喜欢踢足球。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生深受老师的影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的菜深受四川菜影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画深受中国传统文化影响。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民深受天气影响，今年很辛苦。", "target_word": "深受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "受到很深的影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98920, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深受", "is_correct": true, "explanation": "深受（shēn shòu）是本词的标准读音与词义，正确。"}, {"text": "伸手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是伸出手。"}, {"text": "身手", "is_correct": false, "explanation": "第二音节 shǒu（第三声）与 shòu（第四声）声调不同，意思是本领、技能。"}, {"text": "申述", "is_correct": false, "explanation": "第二音节韵母 u 与 ou 不同，意思是陈述、说明。"}, {"text": "神兽", "is_correct": false, "explanation": "第一音节 shén（第二声）与 shēn（第一声）声调不同，意思是神话中的野兽。"}], "explanations": {"深受": "深受（shēn shòu）是本词的标准读音与词义，正确。", "伸手": "shǒu（第三声）与 shòu（第四声）声调不同，意思是伸出手。", "身手": "第二音节 shǒu（第三声）与 shòu（第四声）声调不同，意思是本领、技能。", "申述": "第二音节韵母 u 与 ou 不同，意思是陈述、说明。", "神兽": "第一音节 shén（第二声）与 shēn（第一声）声调不同，意思是神话中的野兽。"}, "sentence_index": null, "correct_answer": "深受"}, "level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "搭配：“享受”搭配待遇、生活，不说“享受父母影响”。"}, {"text": "反抗", "is_correct": false, "explanation": "语义：“反抗”与“影响”相抵触，句子说想法受父母影响。"}, {"text": "深受", "is_correct": true, "explanation": "深受：受到很深的影响，与“父母”搭配，句意通顺。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“受影响”的意思不合。"}], "explanations": {"享受": "搭配：“享受”搭配待遇、生活，不说“享受父母影响”。", "反抗": "语义：“反抗”与“影响”相抵触，句子说想法受父母影响。", "深受": "深受：受到很深的影响，与“父母”搭配，句意通顺。", "讨厌": "语义：“讨厌”表示厌恶，与“受影响”的意思不合。"}, "sentence_index": 0, "correct_answer": "深受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她稍微深受这部电影的影响，也想当演员。", "explanation": "这里应该用〈受…影响〉。“深受”表示影响很深，与表示轻微程度的“稍微”矛盾。"}, {"text": "她深受这部电影的票价，也想当演员。", "explanation": "这里应该用〈受…影响〉。“深受”后要接“影响”一类的词，“深受这部电影的票价”缺少“影响”，句子不通。"}, {"text": "她深受这部电影的导演，也想当演员。", "explanation": "这里应该用〈受…影响〉。“深受”后接的是影响或感受，不能直接接人物“导演”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”与“受影响”的意思不合，句子说学生受老师的影响。"}, {"text": "深受", "is_correct": true, "explanation": "深受：受到很深的影响，与“老师的影响”搭配，句意通顺。"}, {"text": "轻视", "is_correct": false, "explanation": "语义：“轻视”表示看不起，与“受老师影响”的态度相反。"}, {"text": "辜负", "is_correct": false, "explanation": "搭配：“辜负”多接期望、信任，不说“辜负老师的影响”。"}], "explanations": {"怀疑": "语义：“怀疑”与“受影响”的意思不合，句子说学生受老师的影响。", "深受": "深受：受到很深的影响，与“老师的影响”搭配，句意通顺。", "轻视": "语义：“轻视”表示看不起，与“受老师影响”的态度相反。", "辜负": "搭配：“辜负”多接期望、信任，不说“辜负老师的影响”。"}, "sentence_index": 6, "correct_answer": "深受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民深受土地。", "explanation": "这里应该用〈深入〉。“深受”后接的是影响或感受，不接“土地”这类地点。"}, {"text": "农民深受天气，今年很辛苦。", "explanation": "这里应该用〈深受…影响〉。“深受”后要接“影响”一类的词，只说“深受天气”句子不完整。"}, {"text": "农民深受今年的草帽。", "explanation": "这里不能用〈深受〉。“深受”后接的是影响或感受，不接“草帽”这类物品，此处应说〈戴着〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
