INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汉堡是两片圆圆的面包中间夹着肉和菜的食物。", "primary_collocate": null, "pronunciation": "hàn bǎo", "ipa": "xan˥˩ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你看，汉堡中间夹着肉和菜。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里吃着汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汉堡的面包又圆又软。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把汉堡放进了书包里。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉堡里夹了一片奶酪。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早饭吃了汉堡和鸡蛋。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家自己做汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉堡里的菜很新鲜。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快餐店的汉堡卖得很快。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学做汉堡给朋友吃。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "汉堡包", "label": "复合词"}, {"form": "漢堡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两片圆面包中间夹着肉和菜的食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉堡", "is_correct": true, "explanation": "正确：汉堡是两片面包中间夹着肉和菜的食物，“中间夹着肉和菜”说得通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能夹肉和菜，与“中间夹着肉和菜”矛盾。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能用来夹肉和菜，句子意思不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“夹着肉和菜”要用于面包、饼类等，不能说“窗户中间夹着肉和菜”。"}], "explanations": {"汉堡": "正确：汉堡是两片面包中间夹着肉和菜的食物，“中间夹着肉和菜”说得通。", "手机": "语义：手机不能夹肉和菜，与“中间夹着肉和菜”矛盾。", "椅子": "语义：椅子不能用来夹肉和菜，句子意思不通。", "窗户": "搭配：“夹着肉和菜”要用于面包、饼类等，不能说“窗户中间夹着肉和菜”。"}, "sentence_index": 0, "correct_answer": "汉堡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汉堡要放进开水里煮。", "explanation": "这里应该用〈饺子〉。饺子才放进开水里煮；汉堡是面包夹肉饼和菜做的，不用煮。"}, {"text": "我买了一把汉堡。", "explanation": "这里应该用〈个〉。“把”多用于有柄的东西，汉堡没有柄，不能用“把”。"}, {"text": "我买了一条汉堡。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，汉堡是圆的，不能用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉堡", "is_correct": true, "explanation": "正确：妈妈在家可以自己做汉堡，句子成立。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能在家自己做出来，与“在家自己做”矛盾。"}, {"text": "高速公路", "is_correct": false, "explanation": "语义：高速公路不能在家里做，句子意思不通。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“做”后接的是可以制作的物品，天体不能说“做月亮”。"}], "explanations": {"汉堡": "正确：妈妈在家可以自己做汉堡，句子成立。", "大海": "语义：大海不能在家自己做出来，与“在家自己做”矛盾。", "高速公路": "语义：高速公路不能在家里做，句子意思不通。", "月亮": "搭配：“做”后接的是可以制作的物品，天体不能说“做月亮”。"}, "sentence_index": 6, "correct_answer": "汉堡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汉堡要剥了皮再吃。", "explanation": "这里应该用〈香蕉〉。香蕉要先剥皮再吃；汉堡是面包夹肉饼和菜做的，没有皮可剥。"}, {"text": "汉堡要倒进杯子里喝。", "explanation": "这里应该用〈果汁〉。倒进杯子里喝的是果汁、牛奶这类液体；汉堡是固体食物，不能倒进杯子里喝。"}, {"text": "他买了一支汉堡。", "explanation": "这里应该用〈个〉。“支”用于笔、棍子这类细长的东西，汉堡不能用“支”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根汉堡里夹着鸡蛋和奶酪。", "corrected_sentence": "这个汉堡里夹着鸡蛋和奶酪。", "error_description": "错误形式：“这根汉堡”；正确形式：“这个汉堡”。“根”用于细长的东西，汉堡应搭配量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我们做了一条汉堡。", "corrected_sentence": "妈妈给我们做了一个汉堡。", "error_description": "错误形式：“一条汉堡”；正确形式：“一个汉堡”。“条”用于细长的东西，汉堡应搭配量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
