INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用圆面包夹肉饼、蔬菜等做成的食品。", "primary_collocate": null, "pronunciation": "hàn bǎo", "ipa": "xan˥˩ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我中午想吃一个汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汉堡里有肉饼和菜。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都带孩子去吃汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的汉堡又大又好吃。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点了一个汉堡和一杯可乐。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉堡太烫了，你等一下再吃。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹不喜欢汉堡里的洋葱。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口气吃了两个汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一个鸡肉汉堡。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃汉堡的时候，别忘了拿纸巾。", "target_word": "汉堡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "汉堡包", "label": "复合词"}, {"form": "漢堡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "圆面包夹肉饼和蔬菜做成的快餐食品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉堡", "is_correct": true, "explanation": "正确：汉堡是食物，“一个汉堡”与“中午想吃”相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能吃，“想吃”的对象应是食物。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是电子设备，不能用来吃。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“吃”的宾语一般是食物，不能说“吃老师”。"}], "explanations": {"汉堡": "正确：汉堡是食物，“一个汉堡”与“中午想吃”相符。", "手机": "语义：手机不能吃，“想吃”的对象应是食物。", "电脑": "语义：电脑是电子设备，不能用来吃。", "老师": "搭配：“吃”的宾语一般是食物，不能说“吃老师”。"}, "sentence_index": 0, "correct_answer": "汉堡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一杯汉堡。", "explanation": "这里应该用〈个〉。“杯”用于饮料，汉堡应说“一个汉堡”。"}, {"text": "这串汉堡很甜。", "explanation": "这里应该用〈葡萄〉。“一串”用于葡萄这类连在一起的果实；汉堡是面包夹肉饼和菜做的，不论“串”。"}, {"text": "我买了一根汉堡。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，汉堡是圆的，不能用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉堡", "is_correct": true, "explanation": "正确：汉堡里夹着肉饼和菜，“妹妹不喜欢汉堡里的洋葱”成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不能装洋葱，“钢琴里的洋葱”说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板上不会有洋葱，与“洋葱”所在的地方不符。"}, {"text": "妈妈", "is_correct": false, "explanation": "搭配：“里”表示处所，人不能用来作为“里”的前面成分，不能说“妈妈里的洋葱”。"}], "explanations": {"汉堡": "正确：汉堡里夹着肉饼和菜，“妹妹不喜欢汉堡里的洋葱”成立。", "钢琴": "语义：钢琴不能装洋葱，“钢琴里的洋葱”说不通。", "黑板": "语义：黑板上不会有洋葱，与“洋葱”所在的地方不符。", "妈妈": "搭配：“里”表示处所，人不能用来作为“里”的前面成分，不能说“妈妈里的洋葱”。"}, "sentence_index": 6, "correct_answer": "汉堡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汉堡要放进开水里煮。", "explanation": "这里应该用〈饺子〉。饺子才放进开水里煮；汉堡是面包夹肉饼和菜做的，不用煮。"}, {"text": "汉堡要用勺子舀着吃。", "explanation": "这里应该用〈粥〉。舀着吃的是粥、汤这类流食；汉堡是用面包夹肉饼和菜做的固体食物，不能用勺子舀。"}, {"text": "他买了一本汉堡。", "explanation": "这里应该用〈个〉。“本”用于书、本子，汉堡应说“一个汉堡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午想买一杯汉堡。", "corrected_sentence": "我下午想买一个汉堡。", "error_description": "错误形式：“一杯汉堡”；正确形式：“一个汉堡”。“杯”用于饮料，汉堡应搭配量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他中午一口气吃了两本汉堡。", "corrected_sentence": "他中午一口气吃了两个汉堡。", "error_description": "错误形式：“两本汉堡”；正确形式：“两个汉堡”。“本”用于书、本子，汉堡应搭配量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
