INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98927, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保守", "is_correct": true, "explanation": "保守：与“激进”相对，指不愿急速变革、主张稳妥。"}, {"text": "严密", "is_correct": false, "explanation": "严密：指周到、无漏洞，与“激进”不构成反义。"}, {"text": "圆滑", "is_correct": false, "explanation": "圆滑：指处事灵活、不得罪人，与“激进”的意思无关。"}, {"text": "清淡", "is_correct": false, "explanation": "清淡：形容味道或颜色不浓，与“激进”无关。"}], "correct_answer": "保守", "explanations": {"保守": "保守：与“激进”相对，指不愿急速变革、主张稳妥。", "严密": "严密：指周到、无漏洞，与“激进”不构成反义。", "圆滑": "圆滑：指处事灵活、不得罪人，与“激进”的意思无关。", "清淡": "清淡：形容味道或颜色不浓，与“激进”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98927, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "激进是想法很大胆，想很快就改变很多东西。", "primary_collocate": null, "pronunciation": "jī jìn", "ipa": "tɕi˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他的想法很大胆，也很激进。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想一年内改变所有规定，真激进。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个计划太激进，我不敢试。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的经理做事很激进。", "target_word": "激进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想把公司全部换掉，真激进。", "target_word": "激进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的想法常常比较激进。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的建议听起来很激进。", "target_word": "激进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话直接，想法也激进。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个月就要改完，这太激进了。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以前很保守，现在变得激进了。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "激进派", "label": "复合词"}, {"form": "激进主义", "label": "复合词"}, {"form": "激進", "label": "繁体"}], "register": "书面", "sense_fingerprint": "想法大胆，想很快改变很多东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：想法大胆，想很快改变很多东西。"}, {"text": "基金", "is_correct": false, "explanation": "只有第二个音节的声调不同（jīn 与 jìn），意思是资金。"}, {"text": "挤进", "is_correct": false, "explanation": "只有第一个音节的声调不同（jǐ 与 jī），意思是挤入。"}, {"text": "西进", "is_correct": false, "explanation": "只有第一个音节的声母不同（x 与 j），意思是向西前进。"}], "explanations": {"激进": "激进：想法大胆，想很快改变很多东西。", "基金": "只有第二个音节的声调不同（jīn 与 jìn），意思是资金。", "挤进": "只有第一个音节的声调不同（jǐ 与 jī），意思是挤入。", "西进": "只有第一个音节的声母不同（x 与 j），意思是向西前进。"}, "sentence_index": null, "correct_answer": "激进"}, "level_3": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：想法大胆，想很快改变很多东西，与“也很”后面的语境吻合。"}, {"text": "清淡", "is_correct": false, "explanation": "语义：“清淡”多形容味道或颜色，不用来形容想法的程度。"}, {"text": "圆润", "is_correct": false, "explanation": "搭配：“圆润”形容声音或线条，不能修饰“想法”。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”指温度低，与“想法”无关。"}], "explanations": {"激进": "激进：想法大胆，想很快改变很多东西，与“也很”后面的语境吻合。", "清淡": "语义：“清淡”多形容味道或颜色，不用来形容想法的程度。", "圆润": "搭配：“圆润”形容声音或线条，不能修饰“想法”。", "冰凉": "语义：“冰凉”指温度低，与“想法”无关。"}, "sentence_index": 0, "correct_answer": "激进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我激进地希望他能回来。", "explanation": "这里应该用〈迫切〉。激进用于主张或做法，不能修饰“希望”的心情。"}, {"text": "街上很激进，车来车往。", "explanation": "这里应该用〈喧闹〉。激进不用来形容地方的热闹程度。"}, {"text": "他对这件事有激进的兴趣。", "explanation": "这里应该用〈强烈〉。激进用于主张或做法，不修饰“兴趣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：想法大胆，想很快改变很多东西，与“听起来很”的语境吻合。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线或颜色，不能形容“建议”。"}, {"text": "矮", "is_correct": false, "explanation": "语义：「矮」指高度低，与「建议」无关。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与“建议”无关。"}], "explanations": {"激进": "激进：想法大胆，想很快改变很多东西，与“听起来很”的语境吻合。", "亮": "语义：“亮”指光线或颜色，不能形容“建议”。", "矮": "语义：「矮」指高度低，与「建议」无关。", "咸": "语义：“咸”指味道，与“建议”无关。"}, "sentence_index": 6, "correct_answer": "激进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他激进地跑完了全程。", "explanation": "这里应该用〈快速〉。激进表示主张或做法的激烈，不描述跑步的速度。"}, {"text": "他的声音很激进。", "explanation": "这里应该用〈响亮〉。激进不用来形容声音的大小。"}, {"text": "房间很激进，光线很好。", "explanation": "这里应该用〈明亮〉。激进不用来形容房间的光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的建议太激进的，大家接受不了。", "corrected_sentence": "他的建议太激进，大家接受不了。", "error_description": "形容词作谓语时句末不加“的”。应说“太激进，大家接受不了”，不说“太激进的，大家接受不了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
