INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98928, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "主张急速、大幅度变革的。", "primary_collocate": null, "pronunciation": "jī jìn", "ipa": "tɕi˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他的改革想法很激进。", "target_word": "激进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个政党的主张太激进了。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人认为这项政策过于激进。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "激进的改革常常带来风险。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在会上提出了激进的计划。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板的做法比以前激进多了。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她主张用激进的办法改变制度。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从来没有提过这么激进的方案。", "target_word": "激进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者一直支持激进的变革。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温和的人不喜欢激进的做法。", "target_word": "激进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "激进派", "label": "复合词"}, {"form": "激进主义", "label": "复合词"}, {"form": "激進", "label": "繁体"}], "register": "书面", "sense_fingerprint": "主张急速、大幅度变革", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '371004fc-2a0b-444b-9f4a-36953370ef70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：主张急速、大幅度变革的。"}, {"text": "基金", "is_correct": false, "explanation": "只有第二个音节的声调不同（jīn 与 jìn），意思是资金。"}, {"text": "挤进", "is_correct": false, "explanation": "只有第一个音节的声调不同（jǐ 与 jī），意思是挤入。"}, {"text": "西进", "is_correct": false, "explanation": "只有第一个音节的声母不同（x 与 j），意思是向西前进。"}], "explanations": {"激进": "激进：主张急速、大幅度变革的。", "基金": "只有第二个音节的声调不同（jīn 与 jìn），意思是资金。", "挤进": "只有第一个音节的声调不同（jǐ 与 jī），意思是挤入。", "西进": "只有第一个音节的声母不同（x 与 j），意思是向西前进。"}, "sentence_index": null, "correct_answer": "激进"}, "level_3": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：主张急速、大幅度变革，与“改革想法”的语境吻合。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：“光滑”形容表面平整，不能修饰“想法”。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”描述声音，与“改革想法”无关。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或声音，不用来形容想法。"}], "explanations": {"激进": "激进：主张急速、大幅度变革，与“改革想法”的语境吻合。", "光滑": "搭配：“光滑”形容表面平整，不能修饰“想法”。", "清脆": "语义：“清脆”描述声音，与“改革想法”无关。", "安静": "语义：“安静”形容环境或声音，不用来形容想法。"}, "sentence_index": 0, "correct_answer": "激进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试前他激进得睡不着。", "explanation": "这里应该用〈紧张〉。激进指主张急速变革，不表示心里的紧张。"}, {"text": "听到喜讯，他激进得说不出话来。", "explanation": "这里应该用〈激动〉。激进指主张急速变革，不表示内心的喜悦。"}, {"text": "风刮得很激进，树枝都断了。", "explanation": "这里应该用〈猛烈〉。激进用于人的主张或做法，不能形容风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激进", "is_correct": true, "explanation": "激进：主张急速、大幅度变革，与“用……的办法改变制度”吻合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，“甜的办法”不成立。"}, {"text": "矮", "is_correct": false, "explanation": "语义：「矮」指高度低，「矮的办法」不成立。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线或颜色，不能形容“办法”。"}], "explanations": {"激进": "激进：主张急速、大幅度变革，与“用……的办法改变制度”吻合。", "甜": "语义：“甜”指味道，“甜的办法”不成立。", "矮": "语义：「矮」指高度低，「矮的办法」不成立。", "亮": "语义：“亮”指光线或颜色，不能形容“办法”。"}, "sentence_index": 6, "correct_answer": "激进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的胃疼得很激进。", "explanation": "这里应该用〈剧烈〉。激进不用来形容疼痛的程度，只用于主张或做法。"}, {"text": "老虎激进地扑了过来。", "explanation": "这里应该用〈凶猛〉。激进不用来形容动物的动作。"}, {"text": "大家激进地欢迎他的到来。", "explanation": "这里应该用〈热烈〉。激进指主张变革，不表示欢迎时的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老板做事很很激进，常常一周内就换掉一批员工。", "corrected_sentence": "这位老板做事很激进，常常一周内就换掉一批员工。", "error_description": "程度副词“很”不能重复。应说“很激进”，不说“很很激进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革的步子迈得太激进的，很多人反对。", "corrected_sentence": "这次改革的步子迈得太激进了，很多人反对。", "error_description": "“太……了”结构中句末要用“了”，不能用“的”。应说“太激进了”，不说“太激进的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '736e061d-c4e9-4198-8a71-3d4d267b9863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
