INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "浓度是水里放的东西有多少，越多就越浓。", "primary_collocate": null, "pronunciation": "nóng dù", "ipa": "nʊŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "糖水的浓度越高，喝起来越甜。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐放得越多，盐水的浓度就越大。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂蜜水的浓度太高，你再加点水吧。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用盐水洗菜，盐水的浓度不能太高。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药水的浓度不一样，颜色也不一样。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果汁的浓度不够，味道有点淡。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往糖水里加了水，浓度变低了。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓度高的盐水很咸，不能直接喝。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给宝宝冲奶粉，浓度要刚刚好。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们比较两杯糖水的浓度。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃度", "label": "繁体"}, {"form": "浓度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "水里放的东西（糖、盐等）有多少，越多越浓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浓度", "is_correct": true, "explanation": "浓度：糖水中糖分含量的多少，越高越甜，与句意相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格高低与糖水甜不甜无关，“价格越高，喝起来越甜”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：糖水没有年龄，“年龄越高”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色说“深”不说“高”，“颜色越高”不成立。"}], "explanations": {"浓度": "浓度：糖水中糖分含量的多少，越高越甜，与句意相符。", "价格": "语义：价格高低与糖水甜不甜无关，“价格越高，喝起来越甜”说不通。", "年龄": "语义：糖水没有年龄，“年龄越高”说不通。", "颜色": "搭配：颜色说“深”不说“高”，“颜色越高”不成立。"}, "sentence_index": 0, "correct_answer": "浓度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的浓度很深，味道很重。", "explanation": "这里应该用〈颜色〉。浓度说高低，不说深浅；“深”用于颜色。"}, {"text": "这块木头的浓度很大，所以很重。", "explanation": "这里应该用〈密度〉。密度指单位体积的质量，说木头的轻重要用密度；浓度只指溶液中溶质的多少。"}, {"text": "这杯水的浓度太高了，要等一会儿再喝。", "explanation": "这里应该用〈温度〉。要等一会儿才能喝，是因为温度会下降，浓度不会随时间降温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浓度", "is_correct": true, "explanation": "浓度：糖水中糖分含量的多少，加水后会变低，与句意相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：往糖水里加水不会改变人的身高，句意不通。"}, {"text": "车速", "is_correct": false, "explanation": "语义：糖水里加水与车速无关，句意不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积说“变小”，不说“变低”，“体积变低了”不搭配。"}], "explanations": {"浓度": "浓度：糖水中糖分含量的多少，加水后会变低，与句意相符。", "身高": "语义：往糖水里加水不会改变人的身高，句意不通。", "车速": "语义：糖水里加水与车速无关，句意不通。", "体积": "搭配：体积说“变小”，不说“变低”，“体积变低了”不搭配。"}, "sentence_index": 6, "correct_answer": "浓度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路的浓度是三公里。", "explanation": "这里应该用〈长度〉。公里是长度单位，浓度不能用公里计量。"}, {"text": "他的浓度是一米六。", "explanation": "这里应该用〈身高〉。一米六是身高，浓度不以长度计。"}, {"text": "这袋米的浓度是五公斤。", "explanation": "这里应该用〈重量〉。公斤是重量单位，浓度不以公斤计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯浓度的糖水很甜。", "corrected_sentence": "这种浓度的糖水很甜。", "error_description": "量词错误：“浓度”是抽象的程度，不能用“杯”计量，应说“这种浓度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种糖水的浓度们都很高。", "corrected_sentence": "这两种糖水的浓度都很高。", "error_description": "“浓度”是抽象名词，后面不能加“们”。“们”只用于人，应说“浓度都很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
