INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "溶液中所含溶质的多少。", "primary_collocate": null, "pronunciation": "nóng dù", "ipa": "nʊŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这种溶液的浓度是百分之十。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验前，老师先测了溶液的浓度。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "溶液的浓度越大，里面的溶质越多。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盐酸的浓度记在本子上。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加水以后，溶液的浓度会变小。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要算出这瓶溶液的浓度。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种溶液的浓度不同，反应也不同。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓度太高的酸，用的时候要小心。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用仪器测出了氢氧化钠溶液的浓度。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验要求溶液的浓度保持不变。", "target_word": "浓度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濃度", "label": "繁体"}, {"form": "浓度计", "label": "复合"}], "register": "书面", "sense_fingerprint": "化学上溶液里溶质含量的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4e257c-d76d-447e-870c-0909fbaadfdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浓度", "is_correct": true, "explanation": "浓度：溶液中溶质含量的多少，用百分数表示，与句意相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：溶液的温度不能用百分数表示，“温度是百分之十”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：溶液没有年龄，“年龄是百分之十”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用百分数表示，“颜色是百分之十”不成立。"}], "explanations": {"浓度": "浓度：溶液中溶质含量的多少，用百分数表示，与句意相符。", "温度": "语义：溶液的温度不能用百分数表示，“温度是百分之十”说不通。", "年龄": "语义：溶液没有年龄，“年龄是百分之十”说不通。", "颜色": "搭配：颜色不用百分数表示，“颜色是百分之十”不成立。"}, "sentence_index": 0, "correct_answer": "浓度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天平能称出样品的浓度。", "explanation": "这里应该用〈质量〉。天平称的是质量，浓度是溶质含量的比例，不能称量。"}, {"text": "这块石头的浓度很大，很难敲碎。", "explanation": "这里应该用〈硬度〉。硬度指物体抵抗压入或刮擦的能力；浓度只指溶液中溶质的多少，不能用来说石头。"}, {"text": "这个反应的浓度很快，几秒钟就完成了。", "explanation": "这里应该用〈速度〉。“快”说的是速度，浓度不表示快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浓度", "is_correct": true, "explanation": "浓度：溶液中溶质含量的多少，不同溶液浓度不同，反应也不同，与句意相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不同不会决定化学反应的快慢，句意不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：溶液没有生日，“生日不同”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：溶液一般说“保质期”，不说“寿命”，且与“反应也不同”无关。"}], "explanations": {"浓度": "浓度：溶液中溶质含量的多少，不同溶液浓度不同，反应也不同，与句意相符。", "价格": "语义：价格不同不会决定化学反应的快慢，句意不通。", "生日": "语义：溶液没有生日，“生日不同”说不通。", "寿命": "搭配：溶液一般说“保质期”，不说“寿命”，且与“反应也不同”无关。"}, "sentence_index": 6, "correct_answer": "浓度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个实验的浓度是二十分钟。", "explanation": "这里应该用〈时间〉。分钟是时间单位，浓度不以分钟计量。"}, {"text": "用尺子量出管子的浓度。", "explanation": "这里应该用〈长度〉。尺子量的是长度，浓度不能用尺量。"}, {"text": "两地的浓度是三公里。", "explanation": "这里应该用〈距离〉。公里衡量距离，浓度不以公里计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这杯浓度的盐酸很危险。", "corrected_sentence": "这种浓度的盐酸很危险。", "error_description": "量词错误：“浓度”不用“杯”计量，应说“这种浓度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两种溶液的浓度们都很高。", "corrected_sentence": "这两种溶液的浓度都很高。", "error_description": "“浓度”是抽象名词，后面不能加“们”。“们”只用于人，应说“浓度都很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67457b36-9b08-436a-8906-a17e34b2c92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为首是排在最前面，带着大家的那一个。", "primary_collocate": null, "pronunciation": "wéi shǒu", "ipa": "weɪ˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "以老师为首，我们走进了公园。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以经理为首的几个人先到了。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们以小明为首，排着队出门。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以队长为首，大家一起上了山。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，以中国队为首的几个队都来了。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以爷爷为首，全家人坐在桌子旁。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以他为首的小组今天去北京。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以导游为首，游客们慢慢往前走。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们以校长为首，去看了学生。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以哥哥为首，几个孩子跑进了房间。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "为首的", "label": "的字结构"}], "register": "书面", "sense_fingerprint": "排在最前面、带着大家的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟随", "is_correct": false, "explanation": "配价：“跟随”后要带对象，不能用“以……”引出，“以老师跟随”句子不通。"}, {"text": "坐", "is_correct": false, "explanation": "语义：“坐”不能表示带领大家走，句意不通。"}, {"text": "为首", "is_correct": true, "explanation": "为首：居于首位、带头，与“以老师……”的格式相配，符合句意。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”是排在后面，与带领大家走进公园的意思相反。"}], "explanations": {"跟随": "配价：“跟随”后要带对象，不能用“以……”引出，“以老师跟随”句子不通。", "坐": "语义：“坐”不能表示带领大家走，句意不通。", "为首": "为首：居于首位、带头，与“以老师……”的格式相配，符合句意。", "落后": "语义：“落后”是排在后面，与带领大家走进公园的意思相反。"}, "sentence_index": 0, "correct_answer": "为首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行，困难很为首，主要是天气。", "explanation": "这里应该用〈主要〉。“为首”指居于首位带头的人，是动词，不能受“很”修饰；说最主要的困难要说“主要的困难是天气”。"}, {"text": "这个计划，问题很为首，就是资金不足。", "explanation": "这里应该用〈主要〉。“为首”是动词，指带头的人，不能受“很”修饰；应说“主要问题是资金不足”。"}, {"text": "他的意见很为首，我不同意。", "explanation": "这里应该用〈重要〉。“为首”指带头的人，不能形容意见，也不能受“很”修饰；可说“他的意见很重要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "语义：“睡”不能表示带领小组，句意不通。"}, {"text": "为首", "is_correct": true, "explanation": "为首：居于首位、带头，符合“以他……的小组”的格式，符合句意。"}, {"text": "跟", "is_correct": false, "explanation": "配价：“跟”后要带宾语，“跟的小组”缺少对象。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是逃跑，不能指带领小组去北京。"}], "explanations": {"睡": "语义：“睡”不能表示带领小组，句意不通。", "为首": "为首：居于首位、带头，符合“以他……的小组”的格式，符合句意。", "跟": "配价：“跟”后要带宾语，“跟的小组”缺少对象。", "逃": "语义：“逃”是逃跑，不能指带领小组去北京。"}, "sentence_index": 6, "correct_answer": "为首"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动，任务很为首，就是打扫教室。", "explanation": "这里应该用〈主要〉。“为首”是动词，指带头的人，不能受“很”修饰；应说“主要任务是打扫教室”。"}, {"text": "原因很为首，是他忘了带钥匙。", "explanation": "这里应该用〈主要〉。“为首”是动词，不能受“很”修饰；说主要原因要用“主要”。"}, {"text": "规定很为首，是不许迟到。", "explanation": "这里应该用〈主要〉。“为首”指带头的人，不能形容规定；应说“主要的规定是不许迟到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以校长为首了，大家走进了教室。", "corrected_sentence": "以校长为首，大家走进了教室。", "error_description": "“为首”后不能加“了”。应说“以校长为首，大家走进了教室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以班长为首同学们去了操场。", "corrected_sentence": "以班长为首的同学们去了操场。", "error_description": "“以……为首”修饰名词“同学们”时，中间要加“的”，应说“以班长为首的同学们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
