INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "居于首位，带头。", "primary_collocate": null, "pronunciation": "wéi shǒu", "ipa": "weɪ˧˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "代表团以王先生为首。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为首的那个人我不认识。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以公司老板为首的人正在开会。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，以我姐姐为首的一队先出发了。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以李老师为首的老师们参加了活动。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在前面、为首的是一位老人。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以医生为首的小组去了山里。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以市长为首的人来学校参观。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为首的学生说了几句话，大家都笑了。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察以一位高个子为首，走进了大楼。", "target_word": "为首", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "为首的", "label": "的字结构"}], "register": "书面", "sense_fingerprint": "居于首位、带头的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落后", "is_correct": false, "explanation": "语义：“落后”是排在后面，“代表团以王先生落后”句意不通。"}, {"text": "跟随", "is_correct": false, "explanation": "配价：“跟随”后要带对象，不能用“以……”引出，句子不通。"}, {"text": "为首", "is_correct": true, "explanation": "为首：居于首位、带头，与“代表团以王先生……”的格式相配，符合句意。"}, {"text": "坐", "is_correct": false, "explanation": "语义：“坐”不能表示带领代表团，句意不通。"}], "explanations": {"落后": "语义：“落后”是排在后面，“代表团以王先生落后”句意不通。", "跟随": "配价：“跟随”后要带对象，不能用“以……”引出，句子不通。", "为首": "为首：居于首位、带头，与“代表团以王先生……”的格式相配，符合句意。", "坐": "语义：“坐”不能表示带领代表团，句意不通。"}, "sentence_index": 0, "correct_answer": "为首"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，难题很为首，是体力。", "explanation": "这里应该用〈主要〉。“为首”是动词，指带头的人，不能受“很”修饰；应说“主要的难题是体力”。"}, {"text": "这个方案，风险很为首，主要是成本。", "explanation": "这里应该用〈主要〉。“为首”是动词，指带头的人，不能受“很”修饰；应说“主要风险是成本”。"}, {"text": "他的想法很为首，是省钱。", "explanation": "这里应该用〈主要〉。“为首”指带头的人，不能形容想法；应说“他的主要想法是省钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩", "is_correct": false, "explanation": "语义：“玩”不能表示带头，“以医生玩的小组”句意不通。"}, {"text": "追", "is_correct": false, "explanation": "配价：“追”后要带宾语，“追的小组”缺少对象。"}, {"text": "为首", "is_correct": true, "explanation": "为首：居于首位、带头，符合“以医生……的小组”的格式，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与带领小组去山里无关，句意不通。"}], "explanations": {"玩": "语义：“玩”不能表示带头，“以医生玩的小组”句意不通。", "追": "配价：“追”后要带宾语，“追的小组”缺少对象。", "为首": "为首：居于首位、带头，符合“以医生……的小组”的格式，符合句意。", "吃": "语义：“吃”与带领小组去山里无关，句意不通。"}, "sentence_index": 6, "correct_answer": "为首"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次大会，议题很为首，是经济。", "explanation": "这里应该用〈主要〉。“为首”指带头的人，不能受“很”修饰；应说“主要议题是经济”。"}, {"text": "错误很为首，是粗心。", "explanation": "这里应该用〈主要〉。“为首”是动词，不能受“很”修饰；说主要的错误要用“主要”。"}, {"text": "他的心愿很为首，是出国留学。", "explanation": "这里应该用〈最大〉。“为首”指带头的人，不能形容心愿；应说“他最大的心愿是出国留学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很以张经理为首，代表团进了会场。", "corrected_sentence": "以张经理为首，代表团进了会场。", "error_description": "“以……为首”是固定格式，前面不能加“很”等程度副词，应说“以张经理为首，代表团进了会场。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以部长为首代表团来到了学校。", "corrected_sentence": "以部长为首的代表团来到了学校。", "error_description": "“以……为首”修饰名词“代表团”时，中间要加“的”，应说“以部长为首的代表团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
