INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98937, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "独家是只有一个人或一家有，别人没有。", "primary_collocate": null, "pronunciation": "dú jiā", "ipa": "tu˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这是我们店的独家配方。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是我们的独家报道。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他们家独家的秘方。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿到了一个独家消息。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法是我们公司独家的。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张是记者拍的独家照片。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想吃独家小菜，就来我们店。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜是奶奶独家秘制的。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆有独家的做法。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条独家新闻让大家很吃惊。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独家新闻", "label": "复合词"}, {"form": "独家报道", "label": "复合词"}, {"form": "獨家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只有某一个人或一家拥有，别人没有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独家", "is_correct": true, "explanation": "正确：“独家配方”指只有这家店有的配方，与“我们店的”相符。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：“寂寞”形容人的心情，不能用来修饰配方。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体的质地，配方不能说坚硬。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指不熟悉，与“我们店的配方”这种归属关系说不通。"}], "explanations": {"独家": "正确：“独家配方”指只有这家店有的配方，与“我们店的”相符。", "寂寞": "搭配：“寂寞”形容人的心情，不能用来修饰配方。", "坚硬": "搭配：“坚硬”形容物体的质地，配方不能说坚硬。", "陌生": "语义：“陌生”指不熟悉，与“我们店的配方”这种归属关系说不通。"}, "sentence_index": 0, "correct_answer": "独家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他独家走了很远的路。", "explanation": "这里应该用〈独自〉。“独自”表示一个人做某事；“独家”表示只有一家拥有，不能用来说一个人走路。"}, {"text": "她是家里独家的孩子。", "explanation": "这里应该用〈唯一〉。“唯一”可以形容人；“独家”多用于消息、配方、报道等，不用来形容人。"}, {"text": "我独家和老师谈话。", "explanation": "这里应该用〈单独〉。“单独”表示一个人或单个地做某事；“独家”不能用来表示和谁谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独家", "is_correct": true, "explanation": "正确：“独家小菜”指只有这家店有的菜，“想吃独家小菜，就来我们店”成立。"}, {"text": "悲伤", "is_correct": false, "explanation": "搭配：“悲伤”形容情绪，小菜不能悲伤。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，不能用来修饰小菜。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”是人的性格，不能用来修饰小菜。"}], "explanations": {"独家": "正确：“独家小菜”指只有这家店有的菜，“想吃独家小菜，就来我们店”成立。", "悲伤": "搭配：“悲伤”形容情绪，小菜不能悲伤。", "沉默": "语义：“沉默”指不说话，不能用来修饰小菜。", "懒惰": "语义：“懒惰”是人的性格，不能用来修饰小菜。"}, "sentence_index": 6, "correct_answer": "独家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都来了，独家他没来。", "explanation": "这里应该用〈唯独〉。“唯独”表示在大家都做某事时，单单排除某人；“独家”表示只有一家拥有，不能用来排除某个人。"}, {"text": "老人一个人住，常常很独家。", "explanation": "这里应该用〈孤独〉。“孤独”形容心里的感受；“独家”不能用来形容人的心情。"}, {"text": "他至今独家，没有结婚。", "explanation": "这里应该用〈单身〉。“单身”说一个人没有配偶；“独家”不能用来说人的婚姻状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家报纸刊登了一条独家了新闻。", "corrected_sentence": "这家报纸刊登了一条独家新闻。", "error_description": "错误形式：“独家了新闻”；正确形式：“独家新闻”。“独家”是形容词，修饰名词“新闻”时中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部剧在我们平台独家了上线。", "corrected_sentence": "这部剧在我们平台独家上线。", "error_description": "错误形式：“独家了上线”；正确形式：“独家上线”。“独家”是形容词，作状语修饰动词“上线”，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
