INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98938, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只有一家独有或独占的。", "primary_collocate": null, "pronunciation": "dú jiā", "ipa": "tu˧˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这家公司拿到了独家代理权。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在我们网站独家播出。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司是这种车的独家代理。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛由我们电视台独家转播。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书由这家出版社独家出版。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目只在我们这里独家播放。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他接受了我们的独家采访。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的新歌是独家首播。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店独家经营这种饮料。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们的独家合作伙伴。", "target_word": "独家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独家代理", "label": "复合词"}, {"form": "独家采访", "label": "复合词"}, {"form": "獨家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只有一家独占经营、播出或代理权的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b29c89d9-b0fa-4ab5-8d2c-338920874c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独家", "is_correct": true, "explanation": "正确：“独家代理权”指只有这家公司拥有的代理权，与“拿到了”相符。"}, {"text": "友好", "is_correct": false, "explanation": "搭配：“友好”形容人或关系的态度，不能用来修饰代理权。"}, {"text": "红色", "is_correct": false, "explanation": "语义：颜色与代理权的归属无关，句子意思不通。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，代理权不能说聪明。"}], "explanations": {"独家": "正确：“独家代理权”指只有这家公司拥有的代理权，与“拿到了”相符。", "友好": "搭配：“友好”形容人或关系的态度，不能用来修饰代理权。", "红色": "语义：颜色与代理权的归属无关，句子意思不通。", "聪明": "搭配：“聪明”形容人的智力，代理权不能说聪明。"}, "sentence_index": 0, "correct_answer": "独家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家独家穿了校服。", "explanation": "这里应该用〈统一〉。“统一”指大家一起做同样的事；“独家”表示只有一家拥有，不能用来说大家穿衣服。"}, {"text": "这部电影在所有电视台都独家播出。", "explanation": "这里应该用〈联播〉。“独家”表示只有一家播出；几家电视台同时播出同一节目要说“联播”，不能说“独家”。"}, {"text": "我们店的包和别家是独家的。", "explanation": "这里应该用〈同款〉。“同款”指样式相同；“独家”表示只有一家有，别家也有的东西就不能说独家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独家", "is_correct": true, "explanation": "正确：“独家采访”指只给这家媒体的采访，与“接受了我们的”相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容环境或物体的状态，不能用来修饰采访。"}, {"text": "嫩绿", "is_correct": false, "explanation": "语义：“嫩绿”是颜色，不能用来修饰采访。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音，采访不能说沙哑。"}], "explanations": {"独家": "正确：“独家采访”指只给这家媒体的采访，与“接受了我们的”相符。", "潮湿": "语义：“潮湿”形容环境或物体的状态，不能用来修饰采访。", "嫩绿": "语义：“嫩绿”是颜色，不能用来修饰采访。", "沙哑": "搭配：“沙哑”形容声音，采访不能说沙哑。"}, "sentence_index": 6, "correct_answer": "独家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子很独家，没有朋友。", "explanation": "这里应该用〈孤独〉。“独家”不能用来形容人的心情或状态；“孤独”才是描述没有朋友的感受。"}, {"text": "她选择独家，不结婚。", "explanation": "这里应该用〈独身〉。“独身”表示一个人不结婚；“独家”不能用来说人的婚姻选择。"}, {"text": "我们的独家合作伙伴很多。", "explanation": "这里应该用〈多家〉，即“我们有多家合作伙伴”。“独家”表示只有一家，合作伙伴有好几家时不能用“独家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司独家了代理这款手机。", "corrected_sentence": "这家公司独家代理这款手机。", "error_description": "错误形式：“独家了代理”；正确形式：“独家代理”。“独家”是形容词，作状语修饰动词“代理”，中间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店今天推出了独家了优惠。", "corrected_sentence": "这家商店今天推出了独家优惠。", "error_description": "错误形式：“独家了优惠”；正确形式：“独家优惠”。“独家”是形容词，修饰名词“优惠”时中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '630fdbe9-2454-46a4-b936-9af31ded3f3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先天性", "is_correct": true, "explanation": "先天性指出生时就有，与「后天形成」相对，是获得性的反义。"}, {"text": "慢性", "is_correct": false, "explanation": "慢性指病程长，与「获得性」不构成反义。"}, {"text": "急性", "is_correct": false, "explanation": "急性指发病快，与「获得性」不构成反义。"}, {"text": "暂时性", "is_correct": false, "explanation": "暂时性指时间短，与「获得性」不构成反义。"}], "correct_answer": "先天性", "explanations": {"先天性": "先天性指出生时就有，与「后天形成」相对，是获得性的反义。", "慢性": "慢性指病程长，与「获得性」不构成反义。", "急性": "急性指发病快，与「获得性」不构成反义。", "暂时性": "暂时性指时间短，与「获得性」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "先天性", "is_correct": true, "explanation": "先天性指生来就有，与「获得性」正相反。"}, {"text": "季节性", "is_correct": false, "explanation": "季节性指随季节出现，与「获得性」不构成反义。"}, {"text": "周期性", "is_correct": false, "explanation": "周期性指有规律地重复，与「获得性」不构成反义。"}, {"text": "永久性", "is_correct": false, "explanation": "永久性指持续不变，与「获得性」不构成反义。"}], "correct_answer": "先天性", "explanations": {"先天性": "先天性指生来就有，与「获得性」正相反。", "季节性": "季节性指随季节出现，与「获得性」不构成反义。", "周期性": "周期性指有规律地重复，与「获得性」不构成反义。", "永久性": "永久性指持续不变，与「获得性」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "获得性是说不是生下来就有，是后来才有的。", "primary_collocate": null, "pronunciation": "huò dé xìng", "ipa": "xwo˥˩ tɤ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种习惯不是天生的，是获得性的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些能力是遗传的，有些能力是获得性的。", "target_word": "获得性", "complexity_tier": "T3", "furigana": "huò dé xìng", "sentence_source": "generated"}, {"text": "说话的能力有一部分是获得性的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕水是获得性的，是小时候掉进河里以后才有的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言是获得性的，不是生下来就会的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的好习惯大多是获得性的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，音乐能力也可能是获得性的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的坏脾气是获得性的，以前不是这样。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的经验是获得性的，要靠多年工作才有。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口音是获得性的，不是爸妈给的。", "target_word": "获得性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获得性免疫", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不是天生的，是后来才有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "获得性", "is_correct": true, "explanation": "获得性指后天形成，与「不是天生的」相符。"}, {"text": "先天性", "is_correct": false, "explanation": "语义：先天性指生下来就有，与句中「不是天生的」矛盾，不能说「是先天性的」。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：慢性多用于病症，不说「慢性的习惯」。"}, {"text": "急性", "is_correct": false, "explanation": "搭配：急性形容病的发作，不用于形容习惯。"}], "explanations": {"获得性": "获得性指后天形成，与「不是天生的」相符。", "先天性": "语义：先天性指生下来就有，与句中「不是天生的」矛盾，不能说「是先天性的」。", "慢性": "搭配：慢性多用于病症，不说「慢性的习惯」。", "急性": "搭配：急性形容病的发作，不用于形容习惯。"}, "sentence_index": 0, "correct_answer": "获得性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的眼睛颜色是获得性的，出生时就定了。", "explanation": "这里用错了：获得性指后天形成，眼睛颜色出生时已定，应说「先天的」，不能用「获得性」。"}, {"text": "他的血型是获得性的，是从父母那里传下来的。", "explanation": "这里用错了：血型从父母遗传而来，属先天特征，与「后天形成」正相反，不能用「获得性」。"}, {"text": "他的鼻子形状是获得性的，一出生就这样。", "explanation": "这里用错了：一出生就有的特征是先天的，「获得性」只用于后天形成的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获得性", "is_correct": true, "explanation": "获得性指后天形成，符合「音乐能力也可能是……的」的说法。"}, {"text": "放射性", "is_correct": false, "explanation": "语义：放射性指物质放出射线，与音乐能力无关，句意不通。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：季节性指随季节出现，与音乐能力无关，句意不通。"}, {"text": "易燃性", "is_correct": false, "explanation": "搭配：易燃性多用于物质，不用来说能力。"}], "explanations": {"获得性": "获得性指后天形成，符合「音乐能力也可能是……的」的说法。", "放射性": "语义：放射性指物质放出射线，与音乐能力无关，句意不通。", "季节性": "语义：季节性指随季节出现，与音乐能力无关，句意不通。", "易燃性": "搭配：易燃性多用于物质，不用来说能力。"}, "sentence_index": 6, "correct_answer": "获得性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个奖项是获得性的，是他努力得到的。", "explanation": "这里用错了：「获得性」指特征是后天形成、非先天具有，不表示「通过努力取得、得到」的意思；这里不能用「获得性」，应说「得到的」。"}, {"text": "这种药是获得性的，大家都能在药店买到。", "explanation": "这里用错了：「获得性」指后天形成、非先天具有，不表示「能够得到、容易买到」的意思（那是「可获得性」）；这里不能用「获得性」。"}, {"text": "这套房子是获得性的，是他花钱买下的。", "explanation": "这里用错了：「获得性」只指后天形成的特征，不指物品是「买来的」；这里不应用「获得性」，应说「买下的」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种能力获得性的，需要靠练习。", "corrected_sentence": "这种能力是获得性的，需要靠练习。", "error_description": "「是」漏掉了。「获得性」作谓语时要用「是……的」，应说「这种能力是获得性的」，不能省略「是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的鼻音很获得性的，要靠纠正。", "corrected_sentence": "他的鼻音是获得性的，要靠纠正。", "error_description": "「很」不能修饰「获得性」这类表示类别的词，作谓语要用「是……的」，应说「是获得性的」，不说「很获得性的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
