INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法中表示动作发生在现在的时态形式。", "primary_collocate": null, "pronunciation": "xiàn zài shì", "ipa": "ɕjɛn˥˩ tsai˥˩ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "英语里，动词的现在式和过去式不一样。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本语法书先讲现在式，再讲过去式。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在式表示动作发生在现在。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语时，我先背动词的现在式。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写出这些动词的现在式。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动词的现在式很简单，过去式很难。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日语的动词有现在式，也有过去式。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试要求我们把过去式的动词改成现在式。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语法书说，现在式常常用来讲每天的习惯。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作文里，动词的现在式用错了好几个。", "target_word": "现在式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现在进行式", "label": "复合"}, {"form": "现在完成式", "label": "复合"}, {"form": "現在式", "label": "繁体"}], "register": "书面", "sense_fingerprint": "语法中表示动作发生在现在的时态形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在式", "is_correct": true, "explanation": "这里说的是英语动词两种时态形式的区别，应填“现在式”。"}, {"text": "过去式", "is_correct": false, "explanation": "语义：前后都是“过去式”，“和过去式不一样”无法构成对比。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“动词的”后面不能接“味道”，动词没有味道这种属性。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“动词的”后面接“颜色”没有语法意义，动词不具有颜色。"}], "explanations": {"现在式": "这里说的是英语动词两种时态形式的区别，应填“现在式”。", "过去式": "语义：前后都是“过去式”，“和过去式不一样”无法构成对比。", "味道": "搭配：“动词的”后面不能接“味道”，动词没有味道这种属性。", "颜色": "搭配：“动词的”后面接“颜色”没有语法意义，动词不具有颜色。"}, "sentence_index": 0, "correct_answer": "现在式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“我昨天吃了饭”里的动词要用现在式。", "explanation": "这里应该用〈过去式〉。“昨天吃了”说的是过去已经发生的动作，动词要用过去式。"}, {"text": "我下周要参加比赛，这里的动词要用现在式。", "explanation": "这里应该用〈将来时〉。下周的比赛还没有发生，不能用现在式。"}, {"text": "现在式表示动作已经在过去发生了。", "explanation": "这里应该用〈过去式〉。表示动作发生在过去的是过去式；现在式表示动作发生在现在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现在式", "is_correct": true, "explanation": "前后两项是动词的两种时态形式，这里应填“现在式”。"}, {"text": "名词", "is_correct": false, "explanation": "语义：名词是词类，不是动词的时态形式，“动词有名词”说不通。"}, {"text": "形容词", "is_correct": false, "explanation": "搭配：“动词有形容词”不搭配，形容词修饰名词，动词没有这种形式。"}, {"text": "主语", "is_correct": false, "explanation": "语义：主语是句子成分，不是动词的时态形式，与“过去式”并列说不通。"}], "explanations": {"现在式": "前后两项是动词的两种时态形式，这里应填“现在式”。", "名词": "语义：名词是词类，不是动词的时态形式，“动词有名词”说不通。", "形容词": "搭配：“动词有形容词”不搭配，形容词修饰名词，动词没有这种形式。", "主语": "语义：主语是句子成分，不是动词的时态形式，与“过去式”并列说不通。"}, "sentence_index": 6, "correct_answer": "现在式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个副词也有现在式和过去式。", "explanation": "错在词类：现在式和过去式是动词的时态形式，副词没有这种变化。"}, {"text": "“现在”就是现在式，我们现在出发吧。", "explanation": "这里把〈现在式〉当成了“此刻”这个词，但它是动词的语法形式，不是时间词。"}, {"text": "这款手机是现在式的。", "explanation": "这里的〈现在式〉被用成了“最新款式”的意思，语法术语只指动词的时态形式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课讲了两条现在式。", "corrected_sentence": "这门课讲了两种现在式。", "error_description": "量词错误：“现在式”是语法形式，应该用“种”，不能用“条”（“条”用于细长的东西）。正确的说法是“两种现在式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次作业里，动词地现在式很多。", "corrected_sentence": "这次作业里，动词的现在式很多。", "error_description": "结构助词错误：修饰名词“现在式”要用“的”，不能用“地”（“地”修饰动词、形容词）。应为“动词的现在式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
