INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用完是把东西都用光了，一点也不剩。", "primary_collocate": null, "pronunciation": "yòng wán", "ipa": "jʊŋ˥˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "我的零花钱已经用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把胶水都用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙膏快用完了，该买新的了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一瓶油用完了，又去买了一瓶。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没用完那张电话卡。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸用完了，请再拿一包来。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整瓶墨水都用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把所有的颜料都用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的盐用完了，我去超市买。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些电池用完了，别再用了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用完了", "label": "完成体"}, {"form": "用完过", "label": "经历体"}, {"form": "没用完", "label": "否定"}, {"form": "用不完", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "用完：把东西都用光，一点不剩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用完", "is_correct": true, "explanation": "用完表示零花钱全部用光，符合“已经……了”的语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：零花钱是钱，不会感冒，这句话说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“钱”为宾语，零花钱不能被吃掉。"}, {"text": "生病", "is_correct": false, "explanation": "语义：零花钱不会生病，这句话说不通。"}], "explanations": {"用完": "用完表示零花钱全部用光，符合“已经……了”的语境。", "感冒": "语义：零花钱是钱，不会感冒，这句话说不通。", "吃": "搭配：“吃”不能以“钱”为宾语，零花钱不能被吃掉。", "生病": "语义：零花钱不会生病，这句话说不通。"}, "sentence_index": 0, "correct_answer": "用完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月只用完一半零花钱，其余的都存起来。", "explanation": "这里应该用〈用掉〉。用完指全部用光、一点不剩，只用了一部分要说用掉。"}, {"text": "这块橡皮我用完了，还剩下一大半。", "explanation": "这里应该用〈用过〉。用完指全部用光，与“还剩下一大半”矛盾；橡皮只是用过，并没有用光，要用〈用过〉。"}, {"text": "汽车每天用完一小部分油，油箱里还剩不少。", "explanation": "这里应该用〈用掉〉。用完指全部用光，只用了一小部分要说用掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用完", "is_correct": true, "explanation": "用完表示整瓶墨水全部用光，与“都”的语境一致。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：墨水是液体，不能被撕碎，这句话说不通。"}, {"text": "写完", "is_correct": false, "explanation": "搭配：“写”的宾语应是字或作业，不能说写完墨水。"}, {"text": "修理", "is_correct": false, "explanation": "语义：墨水不能修理，这句话说不通。"}], "explanations": {"用完": "用完表示整瓶墨水全部用光，与“都”的语境一致。", "撕碎": "语义：墨水是液体，不能被撕碎，这句话说不通。", "写完": "搭配：“写”的宾语应是字或作业，不能说写完墨水。", "修理": "语义：墨水不能修理，这句话说不通。"}, "sentence_index": 6, "correct_answer": "用完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋薯片我用完了一大半，还剩下一小包。", "explanation": "这里应该用〈吃掉〉。用完指全部用光，只吃掉一大半要用〈吃掉〉，“用完了一大半”与“全部用光”矛盾。"}, {"text": "这盒饼干我用完两块，其余的都留着。", "explanation": "这里应该用〈吃了〉。饼干是吃的，说吃掉几块要说“吃了两块”；用完指东西被全部用光。"}, {"text": "这些菜我用完了一半，剩下的留着。", "explanation": "这里应该用〈吃了〉。用完指全部用光，与“一半”矛盾；只吃了一部分要说“吃了一半”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的水果还没用完了。", "corrected_sentence": "我的水果还没用完。", "error_description": "“没”否定的是尚未完成的动作，句末不能再加“了”；应说“还没用完”，不能说“没用完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一个星期就把那瓶牛奶用完了了。", "corrected_sentence": "我一个星期就把那瓶牛奶用完了。", "error_description": "“了”重复：句末“了”只用一个，应说“用完了”，不能说“用完了了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
