INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用到没有剩余。", "primary_collocate": null, "pronunciation": "yòng wán", "ipa": "jʊŋ˥˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "这个月的钱我早就用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的电快用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把今天的时间都用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的纸已经用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大米用完了，明天得去买。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个月的流量用完了吗？", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用完了所有的积分。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这罐咖啡我两周就用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔的墨水用完了，真可惜。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个月的预算都用完了。", "target_word": "用完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用完了", "label": "完成体"}, {"form": "用完过", "label": "经历体"}, {"form": "没用完", "label": "否定"}, {"form": "用不完", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "用完：使用到没有剩余", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用完", "is_correct": true, "explanation": "用完表示钱全部用光，与“早就……了”的语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：钱不会生病，这句话说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语应是字，不能说写钱。"}, {"text": "长高", "is_correct": false, "explanation": "语义：钱不会长高，这句话说不通。"}], "explanations": {"用完": "用完表示钱全部用光，与“早就……了”的语境相符。", "生病": "语义：钱不会生病，这句话说不通。", "写": "搭配：“写”的宾语应是字，不能说写钱。", "长高": "语义：钱不会长高，这句话说不通。"}, "sentence_index": 0, "correct_answer": "用完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月只用完一部分工资，剩下的存起来。", "explanation": "这里应该用〈用掉〉。用完指全部用光，只用了一部分要说用掉。"}, {"text": "这份报告我昨晚就用完了。", "explanation": "这里应该用〈写完〉。用完指东西被耗尽，报告是写出来的，写好应说写完。"}, {"text": "这张地图我每次都用完，还剩下一大半。", "explanation": "这里应该用〈用过〉。用完指每次都全部用光，与“还剩下一大半”矛盾；地图只是用过几次，并没有用光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用完", "is_correct": true, "explanation": "用完表示积分全部用光，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：积分不能被撕，这句话说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语应是字，不能说写积分。"}, {"text": "修", "is_correct": false, "explanation": "语义：积分不能被修理，这句话说不通。"}], "explanations": {"用完": "用完表示积分全部用光，符合句意。", "撕": "语义：积分不能被撕，这句话说不通。", "写": "搭配：“写”的宾语应是字，不能说写积分。", "修": "语义：积分不能被修理，这句话说不通。"}, "sentence_index": 6, "correct_answer": "用完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器每天用完一部分电，剩下的留着明天用。", "explanation": "这里应该用〈消耗〉。用完指全部用光，只耗掉一部分要说消耗。"}, {"text": "这盒巧克力我用完两块，其余的都留着。", "explanation": "这里应该用〈吃了〉。巧克力是吃的，应说“吃了两块”；用完指东西被全部用光。"}, {"text": "这碗汤我用完了一半，剩下的留着。", "explanation": "这里应该用〈喝了〉。用完指全部用光，与“一半”矛盾；汤只喝了一部分要说“喝了一半”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这罐蜂蜜我们一个月就用完了了。", "corrected_sentence": "这罐蜂蜜我们一个月就用完了。", "error_description": "“了”重复：句末“了”只用一个，应说“用完了”，不能说“用完了了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
