INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98971, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "相中是看了几个以后，选了一个自己喜欢的。", "primary_collocate": null, "pronunciation": "xiāng zhòng", "ipa": "ɕjɑŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我看了三家店，最后相中了这家。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在市场上转了一圈，相中了一条红裙子。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子时，我们看了五套，才相中这一套。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他逛了很多书店，相中了一本旧书。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看了很多小狗，相中了一只黄色的。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们看了好几个，你相中哪一个了？", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王看了几辆车，相中了最便宜的那辆。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相中的那件衣服，已经卖完了。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了很多桌子，终于相中一张木头的。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们先看了几块地，然后相中了河边那块。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相中了", "label": "体标"}, {"form": "相中过", "label": "体标"}], "register": "口语", "sense_fingerprint": "看了几个以后，选中一个自己喜欢的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相中", "is_correct": true, "explanation": "相中：看过三家店后选定这家，与“最后”的语境吻合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆除，与前面“看了三家店”的挑选语境不符。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，店铺不是挑选的对象，语境中说不通。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”接可移动的物件，“这家”是店铺，不能说搬了这家。"}], "explanations": {"相中": "相中：看过三家店后选定这家，与“最后”的语境吻合。", "拆": "语义：“拆”是拆除，与前面“看了三家店”的挑选语境不符。", "修": "语义：“修”指修理，店铺不是挑选的对象，语境中说不通。", "搬": "搭配：“搬”接可移动的物件，“这家”是店铺，不能说搬了这家。"}, "sentence_index": 0, "correct_answer": "相中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我相中了他的观点，所以完全支持。", "explanation": "这里应该用〈认同〉。相中只用于经比较后选定具体的人或物，不能用来表示赞同观点。"}, {"text": "他终于相中了一个秘密。", "explanation": "这里应该用〈发现〉。相中是挑选后选定，不能用于找到原本就存在的事物。"}, {"text": "我相中了你的话，所以照着做了。", "explanation": "这里应该用〈相信〉。相中不用于判断话语是否可信，应说“相信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相中", "is_correct": true, "explanation": "相中：看过几辆车后选定最便宜的一辆，与语境吻合。"}, {"text": "撞", "is_correct": false, "explanation": "语义：“撞”表示碰撞，与“看了几辆车”的挑选语境不符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”表示损坏，与挑选车辆的语境相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，不能用来说挑选车辆，句子说不通。"}], "explanations": {"相中": "相中：看过几辆车后选定最便宜的一辆，与语境吻合。", "撞": "语义：“撞”表示碰撞，与“看了几辆车”的挑选语境不符。", "砸": "语义：“砸”表示损坏，与挑选车辆的语境相矛盾。", "吃": "语义：“吃”指吃东西，不能用来说挑选车辆，句子说不通。"}, "sentence_index": 6, "correct_answer": "相中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很相中明天的天气，所以带了伞。", "explanation": "这里应该用〈担心〉。相中用于挑选，不能表示对天气的忧虑。"}, {"text": "我相中了他的遭遇，心里很难过。", "explanation": "这里应该用〈同情〉。相中是选定，不能表示对别人遭遇的怜悯。"}, {"text": "妈妈相中了我这次的成绩，高兴得不得了。", "explanation": "这里应该用〈满意〉。相中是经比较后选定具体的人或物，不能用来表示对成绩感到满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈逛了两家商场，最后相中着一件大衣。", "corrected_sentence": "妈妈逛了两家商场，最后相中了一件大衣。", "error_description": "“相中着”误用了持续体“着”。挑选是一次性完成的动作，应说“相中了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小刘逛了几家鞋店，最后相中了一条黑皮鞋。", "corrected_sentence": "小刘逛了几家鞋店，最后相中了一双黑皮鞋。", "error_description": "量词错误：皮鞋要用“双”计量，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
