INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经过挑选，看中。", "primary_collocate": null, "pronunciation": "xiāng zhòng", "ipa": "ɕjɑŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "导演在很多人中间相中了她。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多小伙子，王奶奶一眼就相中了小李。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们挑了很久，相中了这个地方开小店。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板挑来挑去，最后相中了那个年轻的木匠。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相中的那个人，我也认识。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从很多照片里相中了这一张。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练挑了一圈，相中了这个高个子男孩。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挑了很多年，还没有相中过哪个姑娘。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐挑了半天，相中的是一条蓝围巾。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布他早就相中了，可是太贵了。", "target_word": "相中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相中了", "label": "体标"}, {"form": "相中过", "label": "体标"}], "register": "口语", "sense_fingerprint": "经过挑选，看中某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相中", "is_correct": true, "explanation": "相中：从很多人中挑选后看中她，与语境吻合。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”表示殴打，与“在很多人中间挑选”的语境不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，与“在很多人中间挑选”的语境不符，句子说不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“在很多人中间挑选”的语境不符，句子说不通。"}], "explanations": {"相中": "相中：从很多人中挑选后看中她，与语境吻合。", "打": "语义：“打”表示殴打，与“在很多人中间挑选”的语境不符。", "洗": "语义：“洗”是清洗，与“在很多人中间挑选”的语境不符，句子说不通。", "扔": "语义：“扔”是丢弃，与“在很多人中间挑选”的语境不符，句子说不通。"}, "sentence_index": 0, "correct_answer": "相中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我相中了他的失败，心里很同情他。", "explanation": "这里应该用〈同情〉。相中是挑选看中，不能用来表示对别人失败的同情。"}, {"text": "大家相中了这场比赛的结果，纷纷鼓掌。", "explanation": "这里应该用〈认可〉。相中是挑选看中某人或某物，不能用来表示对比赛结果的认可。"}, {"text": "老师相中了他的错误，当场指了出来。", "explanation": "这里应该用〈发现〉。相中是挑选后看中，不能表示找出别人的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相中", "is_correct": true, "explanation": "相中：挑了一圈后看中这个高个子男孩，与语境吻合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚碰击，与“挑了一圈”的挑选语境不符。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示责备，与挑选人的语境不符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是吃东西，不能用来说挑选人，句子说不通。"}], "explanations": {"相中": "相中：挑了一圈后看中这个高个子男孩，与语境吻合。", "踢": "语义：“踢”是用脚碰击，与“挑了一圈”的挑选语境不符。", "骂": "语义：“骂”表示责备，与挑选人的语境不符。", "吃": "语义：“吃”是吃东西，不能用来说挑选人，句子说不通。"}, "sentence_index": 6, "correct_answer": "相中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我相中了这件事，一直不敢相信。", "explanation": "这里应该用〈怀疑〉。相中是选定，不能表示对事情真假的疑虑。"}, {"text": "我很相中你的哭声，心里很烦躁。", "explanation": "这里应该用〈烦〉。相中是挑选看中，不能表示对哭声感到厌烦。"}, {"text": "我相中了这场雨，心里很烦。", "explanation": "这里应该用〈讨厌〉。相中是挑选看中，不能表示讨厌某种天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐挑了很久，最后相中着一件毛衣。", "corrected_sentence": "姐姐挑了很久，最后相中了一件毛衣。", "error_description": "“相中着”误用了持续体“着”。挑选是一次性完成的动作，应说“相中了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈挑了很久，终于相中了一条新冰箱。", "corrected_sentence": "妈妈挑了很久，终于相中了一台新冰箱。", "error_description": "量词错误：冰箱要用“台”计量，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
