INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国共产党省级委员会的简称。", "primary_collocate": null, "pronunciation": "shěng wěi", "ipa": "ʂɤŋ˨˩ weɪ˨˩", "syllable_count": 2, "sentences": [{"text": "省委召开了一次重要会议。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委领导来我们学校参观。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是省委的工作人员。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委发出了新的通知。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天省委宣布了一个好消息。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委的院子里种着很多树。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委要求大家认真学习文件。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年进了省委工作。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委研究了这个城市的发展问题。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省委的会议室里坐满了人。", "target_word": "省委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "中国共产党省级委员会的简称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省委", "is_correct": true, "explanation": "正确答案。省委是党的省级委员会，可以召开会议。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能召开会议。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能召开会议。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：“召开”的主语应是机构或人，“会议”不能再召开会议。"}], "explanations": {"省委": "正确答案。省委是党的省级委员会，可以召开会议。", "窗户": "语义：窗户是建筑部件，不能召开会议。", "树": "语义：树不能召开会议。", "会议": "搭配：“召开”的主语应是机构或人，“会议”不能再召开会议。"}, "sentence_index": 0, "correct_answer": "省委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的省委发出了新的通知。", "explanation": "这里应该用〈党委〉。省委管一个省，学校的领导机构要用党委。"}, {"text": "我的叔叔是省委，每天很忙。", "explanation": "这里应该用〈省长〉。省委是机构，不是某个人的职位。"}, {"text": "我们学校旁边的省委卖很多西瓜。", "explanation": "这里应该用〈西瓜摊〉。省委是机构，不做买卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省委", "is_correct": true, "explanation": "正确答案。省委是党的机构，能够要求大家学习文件。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“要求”需要有权威的施事，“小狗”不能要求大家。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不会学习文件，也不能提出要求。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能提出要求，也不能让人学习文件。"}], "explanations": {"省委": "正确答案。省委是党的机构，能够要求大家学习文件。", "小狗": "搭配：“要求”需要有权威的施事，“小狗”不能要求大家。", "老鼠": "语义：老鼠不会学习文件，也不能提出要求。", "石头": "语义：石头不能提出要求，也不能让人学习文件。"}, "sentence_index": 6, "correct_answer": "省委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天把省委放进书包里。", "explanation": "这里应该用〈书〉。省委是机构，不能装进书包。"}, {"text": "省委是这个省最大的城市。", "explanation": "这里应该用〈省会〉。省会是省级行政中心城市，省委不能当城市说。"}, {"text": "我在省委买菜。", "explanation": "这里应该用〈菜市场〉。省委是机构，不是买菜的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的一座省委有很多工作人员。", "corrected_sentence": "这个省的省委有很多工作人员。", "error_description": "量词错误：“省委”是机构，不能加“一座”。去掉“一座”，直接说“这个省的省委”，或用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都从省委开会。", "corrected_sentence": "他每天都在省委开会。", "error_description": "介词错误：表示地点应用“在”，“从”表示起点，应说“他每天都在省委开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
