INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "睡着是闭上眼睛，睡进了梦里。", "primary_collocate": null, "pronunciation": "shuì zháo", "ipa": "ʂweɪ˥˩ ʈʂɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "宝宝在妈妈怀里睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一躺下就睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看书看着看着就睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，请小声说话。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太累了，坐在车上睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着雨，我很快就睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫在沙发上睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着音乐，我慢慢睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看电视时睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课堂上睡着了，老师很生气。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡着了", "label": "完成体"}, {"form": "没睡着", "label": "否定"}, {"form": "睡不着", "label": "可能补语（否定）"}, {"form": "睡得着", "label": "可能补语（肯定）"}], "register": "口语", "sense_fingerprint": "闭上眼睛，真正入睡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指忘掉某事，宝宝在妈妈怀里不会“忘记”，与场景不符。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：宝宝不会“讨论”，与睡在妈妈怀里的场景不符。"}, {"text": "睡着", "is_correct": true, "explanation": "睡着：闭上眼睛，进入睡眠，与“宝宝在妈妈怀里”的场景相符。"}, {"text": "写完", "is_correct": false, "explanation": "语义：宝宝不会“写完”东西，与睡觉的场景不合。"}], "explanations": {"忘记": "语义：“忘记”指忘掉某事，宝宝在妈妈怀里不会“忘记”，与场景不符。", "讨论": "语义：宝宝不会“讨论”，与睡在妈妈怀里的场景不符。", "睡着": "睡着：闭上眼睛，进入睡眠，与“宝宝在妈妈怀里”的场景相符。", "写完": "语义：宝宝不会“写完”东西，与睡觉的场景不合。"}, "sentence_index": 0, "correct_answer": "睡着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我睡着了，却正在看书。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，不能与正在进行的清醒动作并存。"}, {"text": "这把椅子睡着了。", "explanation": "这里不能用〈睡着〉。“睡着”只指人或动物入睡，家具不会入睡，此处可改用〈放〉。"}, {"text": "我睡着在床上。", "explanation": "这里应该用〈睡〉。“睡着”表示入睡的结果，不能带“在床上”这类地点补语，应说“睡在床上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：小猫不会“考试”，与沙发上的场景不符。"}, {"text": "睡着", "is_correct": true, "explanation": "睡着：闭上眼睛，进入睡眠，与“小猫在沙发上”的场景相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”需要说话的人，句子说的是小猫，不合。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接收者和物品作宾语，句中缺少宾语。"}], "explanations": {"考试": "语义：小猫不会“考试”，与沙发上的场景不符。", "睡着": "睡着：闭上眼睛，进入睡眠，与“小猫在沙发上”的场景相符。", "批评": "语义：“批评”需要说话的人，句子说的是小猫，不合。", "送给": "配价：“送给”需要接收者和物品作宾语，句中缺少宾语。"}, "sentence_index": 6, "correct_answer": "睡着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在课堂上睡着，却认真地听讲。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，不能与“认真地听讲”并存。"}, {"text": "他在课堂上睡着，却拿起笔记写字。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，与“拿起笔记写字”矛盾。"}, {"text": "这张桌子在课堂上睡着了。", "explanation": "这里不能用〈睡着〉。“睡着”指人入睡，桌子不会睡，此处应改用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚坐下就睡着着了。", "corrected_sentence": "他刚坐下就睡着了。", "error_description": "错误形式：“睡着着”。正确形式：“睡着了”。“着”重复，“睡着”后只需加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看书看到很晚才睡着着。", "corrected_sentence": "他看书看到很晚才睡着。", "error_description": "错误形式：“睡着着”。正确形式：“睡着”。“着”重复，应去掉多余的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
