INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入睡眠状态。", "primary_collocate": null, "pronunciation": "shuì zháo", "ipa": "ʂweɪ˥˩ ʈʂɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "昨晚太热，我一直没睡着。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝了咖啡，今天晚上我很晚才睡着。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你睡着了吗？", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，他很快睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想着明天的考试，半夜才睡着。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太吵，孩子很久才睡着。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十点才睡着。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡着的时候，手机响了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关了灯，他很快就睡着了。", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数羊能让你睡着吗？", "target_word": "睡着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "睡着了", "label": "完成体"}, {"form": "没睡着", "label": "否定"}, {"form": "睡不着", "label": "可能补语（否定）"}, {"form": "睡得着", "label": "可能补语（肯定）"}], "register": "口语", "sense_fingerprint": "进入睡眠状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪等受热变成液体，不能说人“融化”。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液体变成冰，与“我”的状态不合。"}, {"text": "睡着", "is_correct": true, "explanation": "睡着：进入睡眠状态，与“太热，一直没睡着”的语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，主语不能是“我”，“我一直没下雨”不通。"}], "explanations": {"融化": "语义：“融化”指冰雪等受热变成液体，不能说人“融化”。", "结冰": "语义：“结冰”指液体变成冰，与“我”的状态不合。", "睡着": "睡着：进入睡眠状态，与“太热，一直没睡着”的语境相符。", "下雨": "语义：“下雨”是天气现象，主语不能是“我”，“我一直没下雨”不通。"}, "sentence_index": 0, "correct_answer": "睡着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃了药，他很快睡着了，却仍在看书。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，与“仍在看书”矛盾。"}, {"text": "吃了药，他很快睡着，却起床去跑步。", "explanation": "这里应该用〈醒〉。“睡着”表示已入睡，与“起床去跑步”矛盾。"}, {"text": "吃了药，他很快睡着在床上。", "explanation": "这里应该用〈睡〉。“睡着”表示入睡的结果，不能带“在床上”这类地点补语，应说“睡在床上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪受热变成水，不能说人“十点才融化”。"}, {"text": "高考", "is_correct": false, "explanation": "语义：“高考”是考试名称，不能说“她十点才高考”。"}, {"text": "睡着", "is_correct": true, "explanation": "睡着：进入睡眠状态，与“十点才”的时间语境相符。"}, {"text": "借给", "is_correct": false, "explanation": "配价：“借给”需要借的人和物作宾语，句中缺少宾语。"}], "explanations": {"融化": "语义：“融化”指冰雪受热变成水，不能说人“十点才融化”。", "高考": "语义：“高考”是考试名称，不能说“她十点才高考”。", "睡着": "睡着：进入睡眠状态，与“十点才”的时间语境相符。", "借给": "配价：“借给”需要借的人和物作宾语，句中缺少宾语。"}, "sentence_index": 6, "correct_answer": "睡着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "数羊让你睡着了，你却仍在路上跑步。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，与“仍在路上跑步”矛盾。"}, {"text": "数羊能让你睡着在沙发上吗？", "explanation": "这里应该用〈躺〉。“睡着”表示入睡的结果，不能带“在沙发上”这类地点补语，应说“躺在沙发上”。"}, {"text": "数羊数到睡着，却一直清醒地数到天亮。", "explanation": "这里应该用〈醒着〉。“睡着”表示已入睡，与“一直清醒地数到天亮”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他半夜两点才睡着着。", "corrected_sentence": "他半夜两点才睡着。", "error_description": "错误形式：“睡着着”。正确形式：“睡着”。“着”重复，应去掉多余的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我打着哈欠，却没睡着着。", "corrected_sentence": "我打着哈欠，却没睡着。", "error_description": "错误形式：“睡着着”。正确形式：“睡着”。“着”重复，应去掉多余的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
