INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "矿是地下埋着的石头和金属，可以挖出来用。", "primary_collocate": null, "pronunciation": "kuàng", "ipa": "kʰwɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这座山下面有很多矿，可以挖出来用。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在山里找到了一种新矿。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的矿越挖越少。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用机器把矿运到山外。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里出产的矿很值钱，所以很多人来挖。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这座山的地下埋着矿。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道山里有没有可以挖的矿。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家发现这个地方有矿，就报告了政府。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种矿是金属，不是普通的石头。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从山里挖出了很多矿，装满了车。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "礦", "label": "繁体"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "地下埋着、可挖出来使用的石头和金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，地下埋着、可以挖出来用的矿物。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与矿 kuàng（第四声）声调不同，意思是竹篮。"}, {"text": "狂", "is_correct": false, "explanation": "狂 kuáng（第二声）与矿 kuàng（第四声）声调不同，意思是疯狂。"}, {"text": "逛", "is_correct": false, "explanation": "guàng 与 kuàng 声母不同（g 对 k），意思是闲逛。"}], "explanations": {"矿": "正确答案：矿，地下埋着、可以挖出来用的矿物。", "筐": "筐 kuāng（第一声）与矿 kuàng（第四声）声调不同，意思是竹篮。", "狂": "狂 kuáng（第二声）与矿 kuàng（第四声）声调不同，意思是疯狂。", "逛": "guàng 与 kuàng 声母不同（g 对 k），意思是闲逛。"}, "sentence_index": null, "correct_answer": "矿"}, "level_3": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，地下埋着、可以挖出来用的矿物，与句子相符。"}, {"text": "火", "is_correct": false, "explanation": "语义：火不是埋在地下、可以挖出来使用的东西。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是埋在地下、可以挖出来用的东西，句子说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不埋在地下，也不能挖出来用，句子说不通。"}], "explanations": {"矿": "正确答案：矿，地下埋着、可以挖出来用的矿物，与句子相符。", "火": "语义：火不是埋在地下、可以挖出来使用的东西。", "房子": "语义：房子不是埋在地下、可以挖出来用的东西，句子说不通。", "汽车": "语义：汽车不埋在地下，也不能挖出来用，句子说不通。"}, "sentence_index": 0, "correct_answer": "矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们用机器把矿抽到地面上。", "explanation": "这里应该用〈石油〉。抽用于液体、气体，矿是固体，要用“挖”或“运”。"}, {"text": "他把矿存进了银行。", "explanation": "这里应该用〈金子〉。存进银行的是金子这类加工过的贵重物品，矿是没有加工的矿物。"}, {"text": "他每天早上喝一杯矿，说是对身体好。", "explanation": "这里应该用〈水〉。矿是固体的矿物，不能当饮料喝；能喝的是矿泉水，不能只说“矿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，地下埋着、可以挖出来用的矿物。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 kuàng 声母不同（h 对 k），意思是晃动。"}, {"text": "创", "is_correct": false, "explanation": "chuàng 与 kuàng 声母不同（ch 对 k），意思是创造。"}, {"text": "抗", "is_correct": false, "explanation": "kàng 与 kuàng 少了介音 u，意思是抵抗。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 kuàng 韵母不同（ai 对 ang），意思是快。"}], "explanations": {"矿": "正确答案：矿，地下埋着、可以挖出来用的矿物。", "晃": "huàng 与 kuàng 声母不同（h 对 k），意思是晃动。", "创": "chuàng 与 kuàng 声母不同（ch 对 k），意思是创造。", "抗": "kàng 与 kuàng 少了介音 u，意思是抵抗。", "快": "kuài 与 kuàng 韵母不同（ai 对 ang），意思是快。"}, "sentence_index": null, "correct_answer": "矿"}, "level_3": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，可以挖的矿物，与句子相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是埋在山里、可以挖出来的东西。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不埋在山里，也不能挖出来用。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“挖”接的是实物，“挖歌”不成立。"}], "explanations": {"矿": "正确答案：矿，可以挖的矿物，与句子相符。", "电脑": "语义：电脑不是埋在山里、可以挖出来的东西。", "窗户": "语义：窗户不埋在山里，也不能挖出来用。", "歌": "搭配：“挖”接的是实物，“挖歌”不成立。"}, "sentence_index": 6, "correct_answer": "矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他往咖啡里加了一勺矿。", "explanation": "这里应该用〈糖〉。矿是固体的矿物，不能加进饮料里当调料；加进咖啡的是糖。"}, {"text": "他在院子里种了一些矿。", "explanation": "这里应该用〈菜〉。菜是植物，可以种；矿是埋在地下的矿物，种不出来。"}, {"text": "他把矿涂在面包上，当早饭吃了。", "explanation": "这里应该用〈蜂蜜〉。蜂蜜可以涂在面包上；矿是固体的矿物，不能这样吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在山里找到了一只矿。", "corrected_sentence": "工人在山里找到了一块矿。", "error_description": "量词用错：矿石应用“块”，“只”用于动物或成对的东西。把“一块矿”说成“一只矿”就错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人从山里挖了出三块矿。", "corrected_sentence": "工人从山里挖出了三块矿。", "error_description": "补语位置错：“挖出”是动补结构，“了”要放在补语“出”后面，说“挖出了”，不能说“挖了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
