INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开采矿物的场所，即矿山或矿井。", "primary_collocate": null, "pronunciation": "kuàng", "ipa": "kʰwɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他爸爸在矿里挖了二十年煤。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座矿因为不安全，去年不再挖煤了。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿上的工人每天早上六点下井。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子旁边新开了一座矿，很多人去挖煤。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是这座矿的工人，每天下井。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座矿很深，工人要坐车下去。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要检查每一座矿的井下安全。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司买下了两座矿，想挖煤。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿里很黑，工人头上都戴着灯。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座矿的井下发生了事故，工人都很担心。", "target_word": "矿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "礦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开采矿物的场所，矿山", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，开采矿物的场所。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与矿 kuàng（第四声）声调不同，意思是竹篮。"}, {"text": "狂", "is_correct": false, "explanation": "狂 kuáng（第二声）与矿 kuàng（第四声）声调不同，意思是疯狂。"}, {"text": "逛", "is_correct": false, "explanation": "guàng 与 kuàng 声母不同（g 对 k），意思是闲逛。"}], "explanations": {"矿": "正确答案：矿，开采矿物的场所。", "筐": "筐 kuāng（第一声）与矿 kuàng（第四声）声调不同，意思是竹篮。", "狂": "狂 kuáng（第二声）与矿 kuàng（第四声）声调不同，意思是疯狂。", "逛": "guàng 与 kuàng 声母不同（g 对 k），意思是闲逛。"}, "sentence_index": null, "correct_answer": "矿"}, "level_3": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，开采矿物的场所，与“在矿里挖煤”相符。"}, {"text": "煤", "is_correct": false, "explanation": "语义：煤是挖出来的东西，不是挖煤的场所。"}, {"text": "家", "is_correct": false, "explanation": "语义：家不是挖煤的地方，句子说的是矿井。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“挖煤”的场所是矿井、矿山，不说“在水里挖煤”。"}], "explanations": {"矿": "正确答案：矿，开采矿物的场所，与“在矿里挖煤”相符。", "煤": "语义：煤是挖出来的东西，不是挖煤的场所。", "家": "语义：家不是挖煤的地方，句子说的是矿井。", "水": "搭配：“挖煤”的场所是矿井、矿山，不说“在水里挖煤”。"}, "sentence_index": 0, "correct_answer": "矿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把那座矿放进书包，带回了家。", "explanation": "这里应该用〈书〉。书可以放进书包；矿是开采矿物的场所，很大，不能放进书包。"}, {"text": "我叔叔是一名矿，每天下井。", "explanation": "这里应该用〈工人〉。矿是地方，不能指人。"}, {"text": "她今天穿了一座新矿去上学。", "explanation": "这里应该用〈衣服〉。衣服可以穿；矿是开采矿物的场所，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98982, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，开采矿物的场所。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 kuàng 声母不同（h 对 k），意思是晃动。"}, {"text": "创", "is_correct": false, "explanation": "chuàng 与 kuàng 声母不同（ch 对 k），意思是创造。"}, {"text": "抗", "is_correct": false, "explanation": "kàng 与 kuàng 少了介音 u，意思是抵抗。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 kuàng 韵母不同（ai 对 ang），意思是快。"}], "explanations": {"矿": "正确答案：矿，开采矿物的场所。", "晃": "huàng 与 kuàng 声母不同（h 对 k），意思是晃动。", "创": "chuàng 与 kuàng 声母不同（ch 对 k），意思是创造。", "抗": "kàng 与 kuàng 少了介音 u，意思是抵抗。", "快": "kuài 与 kuàng 韵母不同（ai 对 ang），意思是快。"}, "sentence_index": null, "correct_answer": "矿"}, "level_3": {"options": [{"text": "矿", "is_correct": true, "explanation": "正确答案：矿，开采矿物的场所，与“每一座矿的井下安全”相符。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不在地下，也没有井下。"}, {"text": "河", "is_correct": false, "explanation": "语义：河没有井下，句子说的是矿井。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“井下安全”说的是矿井、隧道，不说学校的井下。"}], "explanations": {"矿": "正确答案：矿，开采矿物的场所，与“每一座矿的井下安全”相符。", "树": "语义：树不在地下，也没有井下。", "河": "语义：河没有井下，句子说的是矿井。", "学校": "搭配：“井下安全”说的是矿井、隧道，不说学校的井下。"}, "sentence_index": 6, "correct_answer": "矿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他泡了一杯矿，慢慢喝了起来。", "explanation": "这里应该用〈茶〉。茶可以泡着喝；矿指开采矿物的场所，是地方，不能泡着喝。"}, {"text": "他在院子里养了一些矿。", "explanation": "这里应该用〈花〉。花是植物，可以养；矿指开采矿物的场所，是地方，养不了。"}, {"text": "他用矿把画钉在墙上。", "explanation": "这里应该用〈钉子〉。钉子能把东西钉住；矿指开采矿物的场所，是地方，不能用来钉东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只矿已经关了两年。", "corrected_sentence": "那座矿已经关了两年。", "error_description": "量词用错：矿井应用“座”，“只”用于动物或成对的东西。把“那座矿”说成“那只矿”就错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司买了下三座矿。", "corrected_sentence": "公司买下了三座矿。", "error_description": "补语位置错：“买下”是动补结构，“了”要放在补语“下”后面，说“买下了”，不能说“买了下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
