INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98983, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "稿是写好的字，或者画好的图，还没有最后定下来。", "primary_collocate": null, "pronunciation": "gǎo", "ipa": "kaʊ˨˩", "syllable_count": 1, "sentences": [{"text": "他正在写一篇新稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这份稿再看一遍。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们明天交稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份稿还没定下来，大家可以再提意见。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的稿还没有写完。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上在家写稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份稿上有很多错字。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑把稿还给了我。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把稿发给我看看。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他改了三次稿才满意。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "稿子", "label": "复合"}, {"form": "稿件", "label": "复合"}, {"form": "初稿", "label": "复合"}], "register": "中性", "sense_fingerprint": "写好或画好但还没定下来的草稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。稿指写好或画好但还没定下来的草稿。"}, {"text": "高", "is_correct": false, "explanation": "gāo（第一声）与 gǎo（第三声）声调不同，意思是高。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是考试。"}, {"text": "改", "is_correct": false, "explanation": "gǎi 与 gǎo 韵母不同（ai 与 ao），声调相同，意思是改动。"}, {"text": "好", "is_correct": false, "explanation": "hǎo 与 gǎo 声母不同（h 与 g），声调相同，意思是好。"}], "explanations": {"稿": "正确答案。稿指写好或画好但还没定下来的草稿。", "高": "gāo（第一声）与 gǎo（第三声）声调不同，意思是高。", "考": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是考试。", "改": "gǎi 与 gǎo 韵母不同（ai 与 ao），声调相同，意思是改动。", "好": "hǎo 与 gǎo 声母不同（h 与 g），声调相同，意思是好。"}, "sentence_index": null, "correct_answer": "稿"}, "level_3": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。“写一篇新稿”指写一篇还没定稿的草稿。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被写，“写一篇新房子”说不通。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“篇”用于文章，歌曲要用“首”，不能说“一篇新歌”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被写，“写一篇新石头”说不通。"}], "explanations": {"稿": "正确答案。“写一篇新稿”指写一篇还没定稿的草稿。", "房子": "语义：房子不能被写，“写一篇新房子”说不通。", "歌": "搭配：“篇”用于文章，歌曲要用“首”，不能说“一篇新歌”。", "石头": "语义：石头不能被写，“写一篇新石头”说不通。"}, "sentence_index": 0, "correct_answer": "稿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份稿已经正式生效了。", "explanation": "这里应该用〈文件〉。稿是还没定下来的草稿，不能生效；已经正式生效的要用文件。"}, {"text": "这份稿太甜了，我不想吃。", "explanation": "这里应该用〈蛋糕〉。稿是写好或画好的内容，不能吃，也没有甜味。"}, {"text": "我写了一只稿。", "explanation": "这里应该用〈份〉或〈篇〉。“只”用于动物等，稿要用“份”或“篇”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98983, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。稿指写好或画好但还没定下来的草稿。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gǎo（第三声）声调不同，意思是告诉。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 gǎo 声母不同（b 与 g），韵母与声调相同，意思是宝贝。"}, {"text": "烤", "is_correct": false, "explanation": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是烘烤。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 gǎo 声母不同（l 与 g），韵母与声调相同，意思是年老。"}], "explanations": {"稿": "正确答案。稿指写好或画好但还没定下来的草稿。", "告": "gào（第四声）与 gǎo（第三声）声调不同，意思是告诉。", "宝": "bǎo 与 gǎo 声母不同（b 与 g），韵母与声调相同，意思是宝贝。", "烤": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是烘烤。", "老": "lǎo 与 gǎo 声母不同（l 与 g），韵母与声调相同，意思是年老。"}, "sentence_index": null, "correct_answer": "稿"}, "level_3": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。“这份稿上有很多错字”指草稿上有错字。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭上不会有错字，“这份饭上有很多错字”说不通。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜上不会有错字，这种说法不成立。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“份”不用于量人，“这份小孩”不成立，而且小孩身上不会有错字。"}], "explanations": {"稿": "正确答案。“这份稿上有很多错字”指草稿上有错字。", "饭": "语义：饭上不会有错字，“这份饭上有很多错字”说不通。", "菜": "语义：菜上不会有错字，这种说法不成立。", "小孩": "搭配：“份”不用于量人，“这份小孩”不成立，而且小孩身上不会有错字。"}, "sentence_index": 6, "correct_answer": "稿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这部稿放进了冰箱。", "explanation": "这里应该用〈食物〉。稿是写好的文字或画，不是食物，不能放进冰箱保存。"}, {"text": "我在稿上写信。", "explanation": "这里应该用〈信纸〉。稿是写好或画好的内容，不是写字用的纸。"}, {"text": "我昨天写了一座稿。", "explanation": "这里应该用〈份〉或〈篇〉。“座”用于山、楼房等大型固定的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这只稿改了三遍。", "corrected_sentence": "我把这份稿改了三遍。", "error_description": "量词错误：稿用“份”或“篇”来数，“只”用于动物等，应说“这份稿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他稿交给了老板。", "corrected_sentence": "他把稿交给了老板。", "error_description": "漏掉“把”：这里要用把字句，应说“他把稿交给了老板”，不能直接说“他稿交给了老板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
