INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文章、图画等的草底或已写成的文章。", "primary_collocate": null, "pronunciation": "gǎo", "ipa": "kaʊ˨˩", "syllable_count": 1, "sentences": [{"text": "她今天要交两篇稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇稿写得很清楚。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报社写稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一份旧稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇稿我已经写完了。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把稿看完了。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的稿已经写好了。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的稿寄给编辑。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的稿很受欢迎。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家每天写五千字的稿。", "target_word": "稿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "稿子", "label": "复合"}, {"form": "稿件", "label": "复合"}, {"form": "初稿", "label": "复合"}], "register": "中性", "sense_fingerprint": "文章图画的草底或已写成的文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。稿指文章、图画的草底或已写成的文章。"}, {"text": "高", "is_correct": false, "explanation": "gāo（第一声）与 gǎo（第三声）声调不同，意思是高。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是考试。"}, {"text": "改", "is_correct": false, "explanation": "gǎi 与 gǎo 韵母不同（ai 与 ao），声调相同，意思是改动。"}, {"text": "好", "is_correct": false, "explanation": "hǎo 与 gǎo 声母不同（h 与 g），声调相同，意思是好。"}], "explanations": {"稿": "正确答案。稿指文章、图画的草底或已写成的文章。", "高": "gāo（第一声）与 gǎo（第三声）声调不同，意思是高。", "考": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是考试。", "改": "gǎi 与 gǎo 韵母不同（ai 与 ao），声调相同，意思是改动。", "好": "hǎo 与 gǎo 声母不同（h 与 g），声调相同，意思是好。"}, "sentence_index": null, "correct_answer": "稿"}, "level_3": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。“交两篇稿”指交两篇写好的文章。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“篇”用于文章，饭不能用“篇”来数。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“篇”不能用来数钥匙，“两篇钥匙”说不通。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不是可以交的文章，“交两篇水”说不通。"}], "explanations": {"稿": "正确答案。“交两篇稿”指交两篇写好的文章。", "饭": "搭配：“篇”用于文章，饭不能用“篇”来数。", "钥匙": "搭配：“篇”不能用来数钥匙，“两篇钥匙”说不通。", "水": "语义：水是液体，不是可以交的文章，“交两篇水”说不通。"}, "sentence_index": 0, "correct_answer": "稿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把稿很锋利。", "explanation": "这里应该用〈刀〉。稿是文字或画稿，没有刀刃，不能说锋利。"}, {"text": "他用稿擦手。", "explanation": "这里应该用〈纸〉。稿是写好的文字，不是擦手的东西。"}, {"text": "这只稿很长。", "explanation": "这里应该用〈篇〉。“只”用于动物等，文章要用“篇”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98984, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。稿指文章、图画的草底或已写成的文章。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gǎo（第三声）声调不同，意思是告诉。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 gǎo 声母不同（b 与 g），韵母与声调相同，意思是宝贝。"}, {"text": "烤", "is_correct": false, "explanation": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是烘烤。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 gǎo 声母不同（l 与 g），韵母与声调相同，意思是年老。"}], "explanations": {"稿": "正确答案。稿指文章、图画的草底或已写成的文章。", "告": "gào（第四声）与 gǎo（第三声）声调不同，意思是告诉。", "宝": "bǎo 与 gǎo 声母不同（b 与 g），韵母与声调相同，意思是宝贝。", "烤": "kǎo 与 gǎo 声母不同（k 与 g），声调相同，意思是烘烤。", "老": "lǎo 与 gǎo 声母不同（l 与 g），韵母与声调相同，意思是年老。"}, "sentence_index": null, "correct_answer": "稿"}, "level_3": {"options": [{"text": "稿", "is_correct": true, "explanation": "正确答案。“这本书的稿”指书的文字稿，已经写好了。"}, {"text": "图", "is_correct": false, "explanation": "搭配：画好的东西要说“画好”，不说“写好”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能被写，“这本书的树已经写好了”说不通。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不能被写，“这本书的船已经写好了”说不通。"}], "explanations": {"稿": "正确答案。“这本书的稿”指书的文字稿，已经写好了。", "图": "搭配：画好的东西要说“画好”，不说“写好”。", "树": "语义：树不能被写，“这本书的树已经写好了”说不通。", "船": "语义：船不能被写，“这本书的船已经写好了”说不通。"}, "sentence_index": 6, "correct_answer": "稿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道稿很好吃。", "explanation": "这里应该用〈菜〉。稿是文字，不能吃。"}, {"text": "这碗稿很香。", "explanation": "这里应该用〈汤〉。稿是文字，没有香味。"}, {"text": "这首稿很好听。", "explanation": "这里应该用〈歌〉。稿是文字，不能用耳朵听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把两只稿寄给了编辑。", "corrected_sentence": "她把两篇稿寄给了编辑。", "error_description": "量词错误：稿用“篇”来数，“只”用于动物等，应说“两篇稿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "编辑已经稿退回来了。", "corrected_sentence": "编辑已经把稿退回来了。", "error_description": "漏掉“把”：把字句的宾语“稿”前要加“把”，应说“编辑已经把稿退回来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
