INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98987, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "签字是在纸上写下自己的名字。", "primary_collocate": null, "pronunciation": "qiān zì", "ipa": "tɕʰjɛn˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "请在这里签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，在纸上签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的作业，妈妈每天都要签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你签字以后，就可以走了。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在表格下面签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在桌子前签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知道应该在哪里签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她签字的时候，手有点儿抖。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天要去银行签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签字以前，请先看一看。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簽字", "label": "繁体"}, {"form": "签过字", "label": "体标"}], "register": "中性", "sense_fingerprint": "在纸上写下自己的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98987, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指记不住，不是可以在这里完成的动作，“请在这里忘记”说不通。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”指离开或躲避，不能用来请对方在这里完成的动作。"}, {"text": "签字", "is_correct": true, "explanation": "正确：“签字”是在纸上写下自己的名字，与“请在这里”搭配。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”后要接对象，如“相信某人”，句中没有对象，结构不成立。"}], "explanations": {"忘记": "语义：“忘记”指记不住，不是可以在这里完成的动作，“请在这里忘记”说不通。", "逃跑": "语义：“逃跑”指离开或躲避，不能用来请对方在这里完成的动作。", "签字": "正确：“签字”是在纸上写下自己的名字，与“请在这里”搭配。", "相信": "配价：“相信”后要接对象，如“相信某人”，句中没有对象，结构不成立。"}, "sentence_index": 0, "correct_answer": "签字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在水里签字，游得很快。", "explanation": "这里应该用〈游泳〉。签字是在纸上写名字，在水里游的动作要说“游泳”。"}, {"text": "他在汤里签字了。", "explanation": "这里应该用〈搅〉。汤里不能签字，要说“搅”。"}, {"text": "他在空中签字了。", "explanation": "这里应该用〈写〉。签字要写在纸上，空中写字要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”后要接对象，如“原谅他”，句中没有对象，结构不成立。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体的状况，不是可以选择地点去完成的动作，句子说不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧也是身体的状况，不能说“应该在哪里发烧”，句意不通。"}, {"text": "签字", "is_correct": true, "explanation": "正确：“在哪里签字”问的是签字的地点，“签字”是在纸上写下自己的名字。"}], "explanations": {"原谅": "配价：“原谅”后要接对象，如“原谅他”，句中没有对象，结构不成立。", "生病": "语义：生病是身体的状况，不是可以选择地点去完成的动作，句子说不通。", "发烧": "语义：发烧也是身体的状况，不能说“应该在哪里发烧”，句意不通。", "签字": "正确：“在哪里签字”问的是签字的地点，“签字”是在纸上写下自己的名字。"}, "sentence_index": 6, "correct_answer": "签字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上围着操场签字五圈。", "explanation": "这里应该用〈跑步〉。签字是在纸上写名字，不能“围着操场签五圈”。"}, {"text": "吃完饭，我们去公园里慢慢签字，看看花。", "explanation": "这里应该用〈散步〉。签字是在纸上写名字，在公园里慢慢走要说“散步”。"}, {"text": "他在河里签字。", "explanation": "这里应该用〈游泳〉。签字不用于水中的活动，这里要说“游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前签字过，所以知道流程。", "corrected_sentence": "我以前签过字，所以知道流程。", "error_description": "错误在“过”的位置：“签字”是离合词，“过”要放在“签”后面，应说“签过字”，不能说“签字过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你签字了以后，就可以走了。", "corrected_sentence": "你签了字以后，就可以走了。", "error_description": "错误在离合词的“了”：“签字”是离合词，“了”要放在“签”和“字”之间，应说“签了字以后”，不能说“签字了以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
