INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98988, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在文件上亲笔写下自己的名字。", "primary_collocate": null, "pronunciation": "qiān zì", "ipa": "tɕʰjɛn˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "两家公司的老板在合同上签字了。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完文件，就签字了。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先读合同再签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东要在租房合同上签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让病人的家人在文件上签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在证书上签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意的话，就在这里签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们签字以后，合同就有用了。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理还没有在文件上签字。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签字前要看清楚每一页。", "target_word": "签字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簽字", "label": "繁体"}, {"form": "签过字", "label": "体标"}], "register": "中性", "sense_fingerprint": "在文件上亲笔写名字表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”和合同没有关系，“在合同上吃了”说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不是在合同上做的动作，句子说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是在合同上做的动作，“在合同上睡觉了”说不通。"}, {"text": "签字", "is_correct": true, "explanation": "正确：“签字”是在合同上写下名字表示同意，与“合同上”搭配。"}], "explanations": {"吃": "语义：“吃”和合同没有关系，“在合同上吃了”说不通。", "唱": "语义：“唱”不是在合同上做的动作，句子说不通。", "睡觉": "语义：“睡觉”不是在合同上做的动作，“在合同上睡觉了”说不通。", "签字": "正确：“签字”是在合同上写下名字表示同意，与“合同上”搭配。"}, "sentence_index": 0, "correct_answer": "签字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在锅里签字，做了一盘菜。", "explanation": "这里应该用〈炒菜〉。签字是在文件上写名字，在锅里做菜要说“炒菜”。"}, {"text": "工人们在石碑上签字。", "explanation": "这里应该用〈刻〉。石碑上的字要“刻”，“签字”用于文件。"}, {"text": "他在天空中签字了。", "explanation": "这里应该用〈写〉。签字是在文件上亲笔写名字，天空中写字要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投降", "is_correct": false, "explanation": "语义：“投降”是认输或放弃抵抗，不是同意后在这里做的动作，句子说不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，不能用来表示同意，句子说不通。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是对人或过错的宽恕，与“你同意的话，就在这里”的语境不合，句子说不通。"}, {"text": "签字", "is_correct": true, "explanation": "正确：“你同意的话，就在这里签字”中，“签字”表示在文件上亲笔写名字表示同意。"}], "explanations": {"投降": "语义：“投降”是认输或放弃抵抗，不是同意后在这里做的动作，句子说不通。", "咳嗽": "语义：“咳嗽”是身体的反应，不能用来表示同意，句子说不通。", "原谅": "语义：“原谅”是对人或过错的宽恕，与“你同意的话，就在这里”的语境不合，句子说不通。", "签字": "正确：“你同意的话，就在这里签字”中，“签字”表示在文件上亲笔写名字表示同意。"}, "sentence_index": 6, "correct_answer": "签字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在这把钥匙上签字了。", "explanation": "这里应该用〈刻〉。签字是在文件上写名字，钥匙上的字要“刻”。"}, {"text": "游客们在沙堡上签字。", "explanation": "这里应该用〈写〉。签字用于文件，沙堡上写字要说“写”。"}, {"text": "他在河里签字。", "explanation": "这里应该用〈游泳〉。签字不用于水中的活动，这里要说“游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很签字了。", "corrected_sentence": "他已经签字了。", "error_description": "错误在副词：“很”是程度副词，不能修饰“签字”这类动作动词；应改为“已经”，说“他已经签字了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他签字了合同。", "corrected_sentence": "他签了合同。", "error_description": "错误在离合词：“签字”是离合词，不能直接带宾语，多出的“字”应删去，说“签了合同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
