INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时指带有临时宪法性质的法律。", "primary_collocate": null, "pronunciation": "yuē fǎ", "ipa": "yɛ˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "历史书里写到过那部约法。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那部约法是在一百多年前公布的。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了约法的历史。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部约法只用了几年。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时的政府公布了一部约法。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这部约法有五十多条。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在课上读了那部约法。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部约法没有留到现在。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上订立了一部约法。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那部约法后来被废除了。", "target_word": "约法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "旧时带有临时宪法性质的法律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约法", "is_correct": true, "explanation": "正确。约法指旧时带有临时宪法性质的法律，历史书里写的正是它。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“那部”用于书、电影等作品，饭店不能用“部”计量。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：历史书里写的不会是饼干，句意与“历史”不符。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：历史书里写到的不是老虎，老虎不是一部作品。"}], "explanations": {"约法": "正确。约法指旧时带有临时宪法性质的法律，历史书里写的正是它。", "饭店": "搭配：“那部”用于书、电影等作品，饭店不能用“部”计量。", "饼干": "语义：历史书里写的不会是饼干，句意与“历史”不符。", "老虎": "语义：历史书里写到的不是老虎，老虎不是一部作品。"}, "sentence_index": 0, "correct_answer": "约法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要学习现代约法。", "explanation": "这里应该用〈法律〉。约法指旧时带有临时宪法性质的法律，不指现代法律。"}, {"text": "他每天用约法刷牙。", "explanation": "这里应该用〈牙刷〉。约法指法律或约定的规则，不能用来刷牙。"}, {"text": "我们国家现行的约法规定了公民的基本权利。", "explanation": "这里应该说〈宪法〉。约法指旧时带有临时宪法性质的法律，不指现行宪法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约法", "is_correct": true, "explanation": "正确。约法指旧时的临时宪法，同学们在课上读的正是它。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“那部”用于书、电影等作品，窗户不能用“部”计量。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：课上读的是文字材料，不能读太阳。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是可以在课上阅读的东西。"}], "explanations": {"约法": "正确。约法指旧时的临时宪法，同学们在课上读的正是它。", "窗户": "搭配：“那部”用于书、电影等作品，窗户不能用“部”计量。", "太阳": "语义：课上读的是文字材料，不能读太阳。", "面包": "语义：面包是食物，不是可以在课上阅读的东西。"}, "sentence_index": 6, "correct_answer": "约法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国在会上签订了一部约法。", "explanation": "这里应该用〈条约〉。约法是旧时带有临时宪法性质的法律，两国之间的协议要用条约。"}, {"text": "老人用约法切西瓜。", "explanation": "这里应该用〈刀〉。约法是法律规矩，不能用来切东西。"}, {"text": "他每天早上吃一部约法当早饭。", "explanation": "语义：约法是法律，不是可以吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书上写着那座约法的内容。", "corrected_sentence": "书上写着那部约法的内容。", "error_description": "“那座约法”中量词错误：“座”用于山、楼等大型固定物，约法应用“部”，应改为“那部约法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座约法早就被废除了。", "corrected_sentence": "这部约法早就被废除了。", "error_description": "“这座约法”中量词错误：“座”用于山、楼等大型固定物，约法应用“部”，应改为“这部约法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
