INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98991, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "丝毫是一点点也没有。", "primary_collocate": null, "pronunciation": "sī háo", "ipa": "sɨ˥ xɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他丝毫不怕困难。", "target_word": "丝毫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我丝毫没有想到他会来。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对如此大的压力，他丝毫不慌乱。", "target_word": "丝毫", "complexity_tier": "T3", "furigana": "sī háo", "sentence_source": "generated"}, {"text": "她丝毫不在乎别人怎么说。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的话，我丝毫不生气。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对钱丝毫没有兴趣。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着大雨，他丝毫不着急。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法丝毫没有用。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师丝毫没发现我在看手机。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑了十公里，他丝毫不觉得累。", "target_word": "丝毫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词，用在否定前，表示一点点也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98991, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丝毫", "is_correct": true, "explanation": "丝毫（sī háo）意思是一点点也没有，常用于否定句，正是本题要听的词。"}, {"text": "自豪", "is_correct": false, "explanation": "自豪（zì háo）与 sī 的声母不同（z 与 s），声调也不同，意思是因成就而骄傲。"}, {"text": "四号", "is_correct": false, "explanation": "四号（sì hào）第一音节 sì（第四声）与 sī（第一声）声调不同，第二音节 hào 与 háo 声调也不同，意思是第四号。"}, {"text": "司号", "is_correct": false, "explanation": "司号（sī hào）第一音节相同，第二音节 hào（第四声）与 háo（第二声）声调不同，意思是吹号的人。"}], "explanations": {"丝毫": "丝毫（sī háo）意思是一点点也没有，常用于否定句，正是本题要听的词。", "自豪": "自豪（zì háo）与 sī 的声母不同（z 与 s），声调也不同，意思是因成就而骄傲。", "四号": "四号（sì hào）第一音节 sì（第四声）与 sī（第一声）声调不同，第二音节 hào 与 háo 声调也不同，意思是第四号。", "司号": "司号（sī hào）第一音节相同，第二音节 hào（第四声）与 háo（第二声）声调不同，意思是吹号的人。"}, "sentence_index": null, "correct_answer": "丝毫"}, "level_3": {"options": [{"text": "丝毫", "is_correct": true, "explanation": "丝毫与“不怕”连用，表示一点也没有，符合句意。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行中，不能修饰“不怕”这种稳定的心理状态。"}, {"text": "略", "is_correct": false, "explanation": "语义：“略”表示稍微，不能与“不怕”构成“一点也不”的完全否定，句意不通。"}, {"text": "稍微", "is_correct": false, "explanation": "语义：“稍微不怕困难”只是程度轻，弱化了“不怕”的态度，与“丝毫”要表达的完全否定不符。"}], "explanations": {"丝毫": "丝毫与“不怕”连用，表示一点也没有，符合句意。", "正在": "体貌：“正在”表示动作进行中，不能修饰“不怕”这种稳定的心理状态。", "略": "语义：“略”表示稍微，不能与“不怕”构成“一点也不”的完全否定，句意不通。", "稍微": "语义：“稍微不怕困难”只是程度轻，弱化了“不怕”的态度，与“丝毫”要表达的完全否定不符。"}, "sentence_index": 0, "correct_answer": "丝毫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他丝毫有点紧张。", "explanation": "这里应该用〈稍微〉。丝毫只用于否定句，表示一点也没有，不能修饰“有点紧张”这样的肯定说法。"}, {"text": "我丝毫相信他。", "explanation": "这里应该用〈完全〉。丝毫要与否定词连用，强调一点也没有；肯定地表示信任要用〈完全〉。"}, {"text": "他丝毫会来。", "explanation": "这里应该用〈一定〉。丝毫只能用于否定，不能用于“会来”这样的肯定判断；肯定地说必然要用〈一定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丝毫", "is_correct": true, "explanation": "丝毫与“不着急”连用，强调一点也不急，与“外面下着大雨”的紧迫语境形成对比。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去的状态，与句中正在进行的“下着大雨”不相符。"}, {"text": "毕竟", "is_correct": false, "explanation": "语义：“毕竟”表示总括或让步，无法引出“不着急”这一态度，句意不通。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙，与“不着急”的意思正相矛盾，句意不通。"}], "explanations": {"丝毫": "丝毫与“不着急”连用，强调一点也不急，与“外面下着大雨”的紧迫语境形成对比。", "曾经": "体貌：“曾经”指过去的状态，与句中正在进行的“下着大雨”不相符。", "毕竟": "语义：“毕竟”表示总括或让步，无法引出“不着急”这一态度，句意不通。", "赶紧": "语义：“赶紧”表示急忙，与“不着急”的意思正相矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "丝毫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩丝毫很好，老师很满意。", "explanation": "这里应该用〈十分〉。丝毫只用于否定句，表示一点儿也没有，不能修饰肯定的“很好”。"}, {"text": "这个方案丝毫有效，大家都很赞同。", "explanation": "这里应该用〈确实〉。丝毫只能与否定词连用，表示一点儿也没有；肯定地说有效要用〈确实〉。"}, {"text": "他丝毫喜欢这个城市，所以常常来。", "explanation": "这里应该用〈非常〉。丝毫只表示否定意义的“一点儿也没有”，不能用来表达肯定的喜爱程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我丝毫有怀疑他的话。", "corrected_sentence": "我丝毫没有怀疑他的话。", "error_description": "“丝毫”只用于否定句，它后面要接否定词“没有”，不能说“丝毫有”；应改为“丝毫没有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈丝毫生气，只是笑了笑。", "corrected_sentence": "妈妈丝毫不生气，只是笑了笑。", "error_description": "“丝毫”只用于否定句，后面要接否定词“不”，不能直接接“生气”；应说“丝毫不生气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
