INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总长是全部加起来一共有多长。", "primary_collocate": null, "pronunciation": "zǒng cháng", "ipa": "tsʊŋ˨˩˦ tʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条路的总长是五公里。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的总长一共三百米。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你量一量这根绳子的总长。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的总长超过一千公里。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三段布的总长是十二米。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有木板的总长算出来了。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条地铁线的总长有四十公里。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车的总长大概两百米。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城的总长你知道是多少吗？", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些线接起来，总长是八米。", "target_word": "总长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "总长度", "label": "复合"}], "register": "中性", "sense_fingerprint": "各部分加起来的全部长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总长", "is_correct": true, "explanation": "正确答案：总长（zǒng cháng），指全部加起来一共有多长。"}, {"text": "总厂", "is_correct": false, "explanation": "总厂（zǒng chǎng）：第二个字声调不同（cháng 与 chǎng），意思是一个工厂的总部。"}, {"text": "总产", "is_correct": false, "explanation": "总产（zǒng chǎn）：第二个字韵母 ang 与 an 不同，声调也不同，意思是总产量。"}, {"text": "总称", "is_correct": false, "explanation": "总称（zǒng chēng）：第二个字韵母 ang 与 eng 不同，声调也不同，意思是概括的名称。"}, {"text": "总成", "is_correct": false, "explanation": "总成（zǒng chéng）：第二个字韵母 ang 与 eng 不同，声调相同，意思是部件组合成的总体。"}], "explanations": {"总长": "正确答案：总长（zǒng cháng），指全部加起来一共有多长。", "总厂": "总厂（zǒng chǎng）：第二个字声调不同（cháng 与 chǎng），意思是一个工厂的总部。", "总产": "总产（zǒng chǎn）：第二个字韵母 ang 与 an 不同，声调也不同，意思是总产量。", "总称": "总称（zǒng chēng）：第二个字韵母 ang 与 eng 不同，声调也不同，意思是概括的名称。", "总成": "总成（zǒng chéng）：第二个字韵母 ang 与 eng 不同，声调相同，意思是部件组合成的总体。"}, "sentence_index": null, "correct_answer": "总长"}, "level_3": {"options": [{"text": "总长", "is_correct": true, "explanation": "正确：“总长”指全部加起来的长度，“这条路的总长是五公里”说得通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”通常说“每小时多少公里”，不说“速度是五公里”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是长度，“这条路的颜色是五公里”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱的数目，不是长度，“这条路的价格是五公里”说不通。"}], "explanations": {"总长": "正确：“总长”指全部加起来的长度，“这条路的总长是五公里”说得通。", "速度": "搭配：“速度”通常说“每小时多少公里”，不说“速度是五公里”。", "颜色": "语义：“颜色”不是长度，“这条路的颜色是五公里”说不通。", "价格": "语义：“价格”指钱的数目，不是长度，“这条路的价格是五公里”说不通。"}, "sentence_index": 0, "correct_answer": "总长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的总长是四十人。", "explanation": "这里应该用〈总数〉。“总长”表示长度，人数的合计要说“总数”。"}, {"text": "他的总长是六十公斤。", "explanation": "这里应该用〈体重〉。“总长”表示长度，人的轻重要说“体重”，用公斤计。"}, {"text": "这块地的总长是三百平方米。", "explanation": "这里应该用〈面积〉。“总长”表示长度，“平方米”是面积单位，两者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总长", "is_correct": true, "explanation": "正确：“总长”指全部长度，“这条地铁线的总长有四十公里”说得通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，不是长度，“这条地铁线的名字有四十公里”说不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”指座椅，不是长度，“这条地铁线的座位有四十公里”说不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人数，不是长度，“这条地铁线的人口有四十公里”说不通。"}], "explanations": {"总长": "正确：“总长”指全部长度，“这条地铁线的总长有四十公里”说得通。", "名字": "语义：“名字”是称呼，不是长度，“这条地铁线的名字有四十公里”说不通。", "座位": "语义：“座位”指座椅，不是长度，“这条地铁线的座位有四十公里”说不通。", "人口": "语义：“人口”指人数，不是长度，“这条地铁线的人口有四十公里”说不通。"}, "sentence_index": 6, "correct_answer": "总长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的总长是一米五。", "explanation": "这里应该用〈身高〉。“总长”指各部分加起来的长度，人的高矮要说“身高”。"}, {"text": "这袋米的总长是十公斤。", "explanation": "这里应该用〈重量〉。“总长”表示长度，“公斤”是重量单位，两者不能搭配。"}, {"text": "今天的总长是二十度。", "explanation": "这里应该用〈温度〉。“总长”表示长度，“度”是温度单位，两者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座大桥的一个总长是两公里。", "corrected_sentence": "这座大桥的总长是两公里。", "error_description": "量词错误：“总长”是表示长度的名词，前面不能加数量词“一个”。正确写作：这座大桥的总长是两公里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把所有绳子的一个总长量出来了。", "corrected_sentence": "我把所有绳子的总长量出来了。", "error_description": "量词错误：“总长”表示长度，不能用数量词“一个”修饰。正确写作：我把所有绳子的总长量出来了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
