INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98995, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "翘是一头向上弯起来。", "primary_collocate": null, "pronunciation": "qiào", "ipa": "tɕʰiɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "太阳把木板晒翘了。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的角都翘起来了。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板湿了以后，边上翘了。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧照片的边翘着。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸放久了，四个角都翘了。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的一条腿太短，桌面一头翘着。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的鞋头有点翘，很可爱。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发睡觉后翘了起来。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后门板翘了，关不上。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木板一湿就容易翘。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翘了", "label": "完成体"}, {"form": "翘着", "label": "持续体"}, {"form": "翘起来", "label": "复合趋向"}, {"form": "翘起", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "翘：物体一头向上弯起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘（第四声）：一头向上弯起。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiào（第四声）声调不同，意思是灵巧。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是敲打。"}, {"text": "锹", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是铁锹。"}], "explanations": {"翘": "翘（第四声）：一头向上弯起。", "巧": "qiǎo（第三声）与 qiào（第四声）声调不同，意思是灵巧。", "敲": "qiāo（第一声）与 qiào（第四声）声调不同，意思是敲打。", "锹": "qiāo（第一声）与 qiào（第四声）声调不同，意思是铁锹。"}, "sentence_index": null, "correct_answer": "翘"}, "level_3": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘表示木板一端向上弯起，符合“晒……了”的结果。"}, {"text": "醒", "is_correct": false, "explanation": "语义：木板不会被晒醒，这句话说不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：木板不会哭，这句话说不通。"}, {"text": "化", "is_correct": false, "explanation": "搭配：“化”多用于冰、糖，木板不能说晒化。"}], "explanations": {"翘": "翘表示木板一端向上弯起，符合“晒……了”的结果。", "醒": "语义：木板不会被晒醒，这句话说不通。", "哭": "语义：木板不会哭，这句话说不通。", "化": "搭配：“化”多用于冰、糖，木板不能说晒化。"}, "sentence_index": 0, "correct_answer": "翘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "柳树的枝条翘下来了。", "explanation": "这里应该用〈垂〉。翘指一端向上扬起，枝条向下垂要用〈垂〉。"}, {"text": "地面翘下去了一块。", "explanation": "这里应该用〈陷〉。翘指一端向上扬起，地面向下陷进去要用〈陷〉，“翘下去”与此相反。"}, {"text": "他翘下腰捡东西。", "explanation": "这里应该用〈弯〉。翘指一端向上扬起，弯腰是身体向前下弯，不能用翘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98995, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘（第四声）：一头向上弯起。"}, {"text": "桥", "is_correct": false, "explanation": "qiáo（第二声）与 qiào（第四声）声调不同，意思是桥。"}, {"text": "悄", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是安静。"}, {"text": "瞧", "is_correct": false, "explanation": "qiáo（第二声）与 qiào（第四声）声调不同，意思是看。"}], "explanations": {"翘": "翘（第四声）：一头向上弯起。", "桥": "qiáo（第二声）与 qiào（第四声）声调不同，意思是桥。", "悄": "qiāo（第一声）与 qiào（第四声）声调不同，意思是安静。", "瞧": "qiáo（第二声）与 qiào（第四声）声调不同，意思是看。"}, "sentence_index": null, "correct_answer": "翘"}, "level_3": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘表示鞋头一端向上弯起，符合“有点……很可爱”的描述。"}, {"text": "饿", "is_correct": false, "explanation": "语义：鞋头不会饿，这句话说不通。"}, {"text": "困", "is_correct": false, "explanation": "语义：鞋头不会困，这句话说不通。"}, {"text": "渴", "is_correct": false, "explanation": "语义：鞋头不会渴，这句话说不通。"}], "explanations": {"翘": "翘表示鞋头一端向上弯起，符合“有点……很可爱”的描述。", "饿": "语义：鞋头不会饿，这句话说不通。", "困": "语义：鞋头不会困，这句话说不通。", "渴": "语义：鞋头不会渴，这句话说不通。"}, "sentence_index": 6, "correct_answer": "翘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙面中间翘进去了一块。", "explanation": "这里应该用〈凹〉。翘指一端向上扬起，墙面中间向里陷要用〈凹〉，不能说翘进去。"}, {"text": "旗杆翘起来了，很笔直。", "explanation": "这里应该用〈竖〉。旗杆直立，不是一端向上弯起，“翘起来”与“很笔直”也矛盾。"}, {"text": "他翘直了腰。", "explanation": "这里应该用〈挺〉。翘指一端向上弯起，身体挺直要用〈挺〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风一吹，屋檐的瓦就翘下来了。", "corrected_sentence": "风一吹，屋檐的瓦就翘起来了。", "error_description": "“翘”的方向是向上，应说“翘起来”，不能说“翘下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旧地板的边缘着翘了。", "corrected_sentence": "旧地板的边缘翘着。", "error_description": "“着”须紧跟在“翘”之后，说“翘着”；“着”放在“翘”前面不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
