INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一端向上扬起。", "primary_collocate": null, "pronunciation": "qiào", "ipa": "tɕʰiɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "小狗高兴得尾巴翘着。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在沙发上翘着二郎腿。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的嘴角微微翘了一下。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生气了，嘴巴翘得很高。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟的尾巴向上翘着。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脚翘在椅子上看电视。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫翘起尾巴走过来。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑的时候，嘴角轻轻翘着。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船头高高翘着，很好看。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟翘着腿躺在床上。", "target_word": "翘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翘了", "label": "完成体"}, {"form": "翘着", "label": "持续体"}, {"form": "翘起", "label": "复合趋向"}, {"form": "翘起来", "label": "复合趋向"}], "register": "中性", "sense_fingerprint": "翘：把一端向上扬起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘（第四声）：一端向上扬起。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiào（第四声）声调不同，意思是灵巧。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是敲打。"}, {"text": "锹", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是铁锹。"}], "explanations": {"翘": "翘（第四声）：一端向上扬起。", "巧": "qiǎo（第三声）与 qiào（第四声）声调不同，意思是灵巧。", "敲": "qiāo（第一声）与 qiào（第四声）声调不同，意思是敲打。", "锹": "qiāo（第一声）与 qiào（第四声）声调不同，意思是铁锹。"}, "sentence_index": null, "correct_answer": "翘"}, "level_3": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘表示尾巴向上扬起，符合“小狗高兴”的画面。"}, {"text": "垂", "is_correct": false, "explanation": "语义：高兴时尾巴不会垂下，这与“高兴”矛盾。"}, {"text": "夹", "is_correct": false, "explanation": "语义：夹着尾巴多表示害怕，与“高兴”矛盾。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不能以“尾巴”为宾语，这句话说不通。"}], "explanations": {"翘": "翘表示尾巴向上扬起，符合“小狗高兴”的画面。", "垂": "语义：高兴时尾巴不会垂下，这与“高兴”矛盾。", "夹": "语义：夹着尾巴多表示害怕，与“高兴”矛盾。", "吹": "搭配：“吹”不能以“尾巴”为宾语，这句话说不通。"}, "sentence_index": 0, "correct_answer": "翘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的眼泪翘了下来。", "explanation": "这里应该用〈落〉。翘指一端向上扬起，眼泪向下掉要用〈落〉。"}, {"text": "他的耳朵翘下来了。", "explanation": "这里应该用〈垂〉。耳朵向下垂要用〈垂〉，翘表示向上扬起。"}, {"text": "她翘着头读书。", "explanation": "这里应该用〈低〉。翘指向上扬起，读书时低头是向下，不能用翘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98996, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘（第四声）：一端向上扬起。"}, {"text": "桥", "is_correct": false, "explanation": "qiáo（第二声）与 qiào（第四声）声调不同，意思是桥。"}, {"text": "悄", "is_correct": false, "explanation": "qiāo（第一声）与 qiào（第四声）声调不同，意思是安静。"}, {"text": "瞧", "is_correct": false, "explanation": "qiáo（第二声）与 qiào（第四声）声调不同，意思是看。"}], "explanations": {"翘": "翘（第四声）：一端向上扬起。", "桥": "qiáo（第二声）与 qiào（第四声）声调不同，意思是桥。", "悄": "qiāo（第一声）与 qiào（第四声）声调不同，意思是安静。", "瞧": "qiáo（第二声）与 qiào（第四声）声调不同，意思是看。"}, "sentence_index": null, "correct_answer": "翘"}, "level_3": {"options": [{"text": "翘", "is_correct": true, "explanation": "翘起表示尾巴向上扬起，符合句中的动作。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“起”搭配后接尾巴，这里说不通。"}, {"text": "揉", "is_correct": false, "explanation": "搭配：“揉起”一般用于手或纸，不能说揉起尾巴。"}, {"text": "熄", "is_correct": false, "explanation": "语义：熄是使火或灯灭，不能用于尾巴。"}], "explanations": {"翘": "翘起表示尾巴向上扬起，符合句中的动作。", "咬": "搭配：“咬”不能与“起”搭配后接尾巴，这里说不通。", "揉": "搭配：“揉起”一般用于手或纸，不能说揉起尾巴。", "熄": "语义：熄是使火或灯灭，不能用于尾巴。"}, "sentence_index": 6, "correct_answer": "翘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书包翘在桌上。", "explanation": "这里应该用〈摆〉。翘指一端向上扬起，把书包放在桌上要用〈摆〉，不能说翘在桌上。"}, {"text": "他把腿翘下来休息。", "explanation": "这里应该用〈放〉。翘表示一端向上扬起，腿放下要用〈放〉，不能说翘下来。"}, {"text": "水翘在地上了。", "explanation": "这里应该用〈洒〉。翘指一端向上扬起，水向地上泼落要用〈洒〉，不能说翘在地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小狗的尾巴翘下来了。", "corrected_sentence": "这只小狗的尾巴翘起来了。", "error_description": "“翘”指向上扬起，应说“翘起来”；“翘下来”表示向下，与“翘”的方向相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把脚翘下去，坐在台阶上。", "corrected_sentence": "妹妹把脚放下去，坐在台阶上。", "error_description": "“翘”指一端向上扬起，“翘下去”方向相反；把脚放下应说“放下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
