INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脉是手腕上能摸到一跳一跳的地方，是血在流。", "primary_collocate": null, "pronunciation": "mài", "ipa": "mai˥˩", "syllable_count": 1, "sentences": [{"text": "医生摸了摸病人的脉。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑完步，医生马上给他把脉。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手腕上有一个地方，能摸到脉。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的脉很慢，医生有点担心。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把手放在这里，就能感到脉在跳。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她睡着以后，医生轻轻地为她诊脉。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士一边看表，一边摸我的脉。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脉太弱了，医生说要多休息。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到自己的脉，你来帮我摸摸。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩发烧的时候，脉会跳得比平时快。", "target_word": "脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脉搏", "label": "复合"}, {"form": "动脉", "label": "复合"}, {"form": "脈", "label": "繁体"}], "register": "通用", "sense_fingerprint": "手腕上能摸到的脉搏跳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脉", "is_correct": true, "explanation": "脉（mài）指手腕上能摸到跳动的地方，即脉搏。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mài（第四声）声调不同，意思是购买。"}, {"text": "埋", "is_correct": false, "explanation": "mái（第二声）与 mài（第四声）声调不同，意思是埋藏。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mài 声调相同，韵母不同（an 与 ai），意思是速度低。"}], "explanations": {"脉": "脉（mài）指手腕上能摸到跳动的地方，即脉搏。", "买": "mǎi（第三声）与 mài（第四声）声调不同，意思是购买。", "埋": "mái（第二声）与 mài（第四声）声调不同，意思是埋藏。", "慢": "màn 与 mài 声调相同，韵母不同（an 与 ai），意思是速度低。"}, "sentence_index": null, "correct_answer": "脉"}, "level_3": {"options": [{"text": "脉", "is_correct": true, "explanation": "正确：“脉”指手腕上能摸到的脉搏，正是医生诊查时摸的部位。"}, {"text": "血", "is_correct": false, "explanation": "语义：“血”不能被诊脉式地摸，与“摸”的诊查动作不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是身体的部分，不能被医生摸。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不是医生用手摸的对象，与句意不合。"}], "explanations": {"脉": "正确：“脉”指手腕上能摸到的脉搏，正是医生诊查时摸的部位。", "血": "语义：“血”不能被诊脉式地摸，与“摸”的诊查动作不合。", "名字": "语义：“名字”不是身体的部分，不能被医生摸。", "身高": "体貌：“身高”指人的高矮，不是医生用手摸的对象，与句意不合。"}, "sentence_index": 0, "correct_answer": "脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他流了很多脉，医生很紧张。", "explanation": "这里应该用〈血〉。脉是手腕上感到的跳动，不会“流”，会流的是〈血〉。"}, {"text": "农民在地里种了很多脉。", "explanation": "这里应该用〈麦〉。麦是一种作物，与“脉”同音但意思不同；脉指脉搏。"}, {"text": "他的脉很发达，经常去健身房练举重。", "explanation": "这里应该用〈肌肉〉。脉指手腕上能摸到的跳动，不指肌肉；说身体发达、有力量要用〈肌肉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脉", "is_correct": true, "explanation": "脉（mài）指手腕上能摸到跳动的地方，即脉搏。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 mài（第四声）声调不同，意思是马匹。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mài 韵母不同（a 与 ai），声调相同，意思是责骂。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 mài 韵母不同（ei 与 ai），声调相同，意思是妹妹。"}, {"text": "冒", "is_correct": false, "explanation": "mào 与 mài 韵母不同（ao 与 ai），声调相同，意思是冒出。"}], "explanations": {"脉": "脉（mài）指手腕上能摸到跳动的地方，即脉搏。", "马": "mǎ（第三声）与 mài（第四声）声调不同，意思是马匹。", "骂": "mà 与 mài 韵母不同（a 与 ai），声调相同，意思是责骂。", "妹": "mèi 与 mài 韵母不同（ei 与 ai），声调相同，意思是妹妹。", "冒": "mào 与 mài 韵母不同（ao 与 ai），声调相同，意思是冒出。"}, "sentence_index": null, "correct_answer": "脉"}, "level_3": {"options": [{"text": "脉", "is_correct": true, "explanation": "正确：“脉”指脉搏，护士给病人诊查时摸的正是它。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“看表”看的是时间，但时间不能被摸，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“摸”不能与“心情”搭配，身体上不能摸到心情。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是抽象的数字，不能被摸，与句意不合。"}], "explanations": {"脉": "正确：“脉”指脉搏，护士给病人诊查时摸的正是它。", "时间": "语义：“看表”看的是时间，但时间不能被摸，句意不通。", "心情": "搭配：“摸”不能与“心情”搭配，身体上不能摸到心情。", "年龄": "语义：“年龄”是抽象的数字，不能被摸，与句意不合。"}, "sentence_index": 6, "correct_answer": "脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发烧了，脉很高。", "explanation": "这里应该用〈体温〉。发烧时“高”的是体温；脉是跳动的，不说“脉很高”。"}, {"text": "医生说他的脉太高了。", "explanation": "这里应该用〈血压〉。“高”通常修饰血压，脉要说“快”或“慢”。"}, {"text": "她每天早上用梳子梳一梳脉。", "explanation": "这里应该用〈头发〉。梳子梳的是头发；脉是手腕上能摸到的跳动，不能梳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给他把了一只脉，说他很健康。", "corrected_sentence": "医生给他把了一下脉，说他很健康。", "error_description": "错误形式：“一只脉”；正确形式：“一下脉”。“把脉”这个动作用动量词“下”计量，说“把一下脉”；“只”是名量词，不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子发烧的时候，跳脉得很快。", "corrected_sentence": "孩子发烧的时候，脉跳得很快。", "error_description": "错误形式：“跳脉”；正确形式：“脉跳”。“脉”是主语，要放在动词“跳”之前，颠倒后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
