INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肿瘤是身体里长出来的不该有的肉块，会让人生病。", "primary_collocate": null, "pronunciation": "zhǒng liú", "ipa": "ʈʂʊŋ˨˩ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他的肿瘤是在体检时发现的。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担心爸爸的肿瘤会越长越大。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说肿瘤要尽快切掉。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肚子里的肿瘤有拳头那么大。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗身上长了肿瘤，主人带它去看病。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他害怕自己得了肿瘤，不敢去医院。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个肿瘤是良性的，一般不会要人的命。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以后，肿瘤慢慢变小了。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有很多得了肿瘤的病人。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用刀把肿瘤拿掉，她很快就好了。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "良性肿瘤", "label": "复合"}, {"form": "恶性肿瘤", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里长出来的不该有的肉块，会让人生病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肿瘤", "is_correct": true, "explanation": "正确：肿瘤是身体里长出来的肉块，可以通过体检发现，与“在体检时发现的”搭配。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是人戴的东西，不是体检要查出来的身体问题，句子语义说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不会在体检时被发现，句子说不通。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“在体检时发现的”搭配的是身体状况，不能说“答案是在体检时发现的”。"}], "explanations": {"肿瘤": "正确：肿瘤是身体里长出来的肉块，可以通过体检发现，与“在体检时发现的”搭配。", "眼镜": "语义：眼镜是人戴的东西，不是体检要查出来的身体问题，句子语义说不通。", "地铁": "语义：地铁是交通工具，不会在体检时被发现，句子说不通。", "答案": "搭配：“在体检时发现的”搭配的是身体状况，不能说“答案是在体检时发现的”。"}, "sentence_index": 0, "correct_answer": "肿瘤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手背上长满了肿瘤，颜色深褐，据说是上了年纪才会长的。", "explanation": "这里应该用〈老年斑〉。老年斑是皮肤色素沉积形成的扁平斑块，不是增生的肉块，也不会让人生病。"}, {"text": "他脸上长了一个肿瘤，用手一挤就消了。", "explanation": "这里说的是脸上的青春痘，挤一挤就消，不是肿瘤。肿瘤是细胞异常增生形成的新生物，不会被挤掉。"}, {"text": "医生在他的胃里找到了一张肿瘤，要切掉。", "explanation": "量词错误：这里应该用〈个〉。“张”用于平面的东西，肿瘤是块状的，不能说“一张肿瘤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肿瘤", "is_correct": true, "explanation": "正确：肿瘤可以是良性的，一般不会危及生命，与“良性的”和“不会要人的命”搭配。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是病原体，没有良性和恶性之分，“病毒是良性的”说不通。"}, {"text": "骨折", "is_correct": false, "explanation": "搭配：“良性”多用于肿瘤、病变，不能用来形容骨折。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景不是疾病，不能谈良性或恶性，句子语义说不通。"}], "explanations": {"肿瘤": "正确：肿瘤可以是良性的，一般不会危及生命，与“良性的”和“不会要人的命”搭配。", "病毒": "语义：病毒是病原体，没有良性和恶性之分，“病毒是良性的”说不通。", "骨折": "搭配：“良性”多用于肿瘤、病变，不能用来形容骨折。", "风景": "语义：风景不是疾病，不能谈良性或恶性，句子语义说不通。"}, "sentence_index": 6, "correct_answer": "肿瘤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的胳膊上起了一个小肿瘤，过几天就消了。", "explanation": "这里应该用〈疙瘩〉。胳膊上起的小疙瘩几天就能消，肿瘤不会这样自行消失。"}, {"text": "夏天到了，他背上起了很多肿瘤，痒得厉害。", "explanation": "这里说的是夏天出的痱子，痒得厉害，不是肿瘤。肿瘤不会因为天热而起疹子般地痒。"}, {"text": "医生从她的胃里取出了一根肿瘤。", "explanation": "量词错误：这里应该用〈个〉。“根”用于细长的东西，肿瘤是块状的，不能说“一根肿瘤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说她肚子里有一只肿瘤，已经有拳头那么大。", "corrected_sentence": "医生说她肚子里有一个肿瘤，已经有拳头那么大。", "error_description": "量词错误：肿瘤应用量词“个”。“只”多用于动物，不能说“一只肿瘤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说，这条肿瘤是良性的，不用太担心。", "corrected_sentence": "医生说，这个肿瘤是良性的，不用太担心。", "error_description": "量词错误：肿瘤应用量词“个”。“条”用于细长的东西，不能说“这条肿瘤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
