INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机体细胞异常增生形成的新生物。", "primary_collocate": null, "pronunciation": "zhǒng liú", "ipa": "ʈʂʊŋ˨˩ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "医生说他肚子里长了一个肿瘤。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个肿瘤很小，不用马上做手术。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果出来了，那个肿瘤是良性的。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器看到了她肺里的肿瘤。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后，医生把肿瘤拿出来了。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肿瘤变大了，所以他最近总是疼。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸去医院做肿瘤检查，要等三天才有结果。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉我们，早点发现肿瘤，治疗就容易。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个肿瘤是恶性的，需要很长时间治疗。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种肿瘤长得很慢，病人不会马上觉得难受。", "target_word": "肿瘤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "良性肿瘤", "label": "复合"}, {"form": "恶性肿瘤", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体细胞异常增生形成的新生物，医学上的肿瘤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肿瘤", "is_correct": true, "explanation": "正确：“肿瘤”指细胞异常增生形成的新生物，可以长在肚子里，与“长了一个”搭配。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是金属工具，不会在人的肚子里长出来，“长了一个钥匙”说不通。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：肚子里长出的应是病变组织，西瓜是食物，不可能在人体内长出来。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不会在人的肚子里长出来，句子语义说不通。"}], "explanations": {"肿瘤": "正确：“肿瘤”指细胞异常增生形成的新生物，可以长在肚子里，与“长了一个”搭配。", "钥匙": "语义：钥匙是金属工具，不会在人的肚子里长出来，“长了一个钥匙”说不通。", "西瓜": "语义：肚子里长出的应是病变组织，西瓜是食物，不可能在人体内长出来。", "电视": "语义：电视是家用电器，不会在人的肚子里长出来，句子语义说不通。"}, "sentence_index": 0, "correct_answer": "肿瘤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从他的胃里切下了一根肿瘤。", "explanation": "量词错误：这里应该用〈个〉。“根”用于细长的东西，肿瘤是块状的，不能说“一根肿瘤”。"}, {"text": "晚上被蚊子咬了，他腿上起了好几个肿瘤，痒得睡不着。", "explanation": "这里应该用〈包〉。被蚊子咬后起的是痒痒的小包，第二天就会消，不是肿瘤。肿瘤是细胞异常增生形成的新生物。"}, {"text": "我撞到桌角，额头上起了一个肿瘤，过两天就消了。", "explanation": "这里说的是撞伤后的肿包，不是肿瘤。肿瘤是细胞异常增生形成的新生物，不会几天就消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肿瘤", "is_correct": true, "explanation": "正确：“做肿瘤检查”指针对肿瘤的医学检查，在医院进行，需要等待结果。"}, {"text": "手机", "is_correct": false, "explanation": "语义：去医院做的是身体相关的检查，手机不是医院检查的对象。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是日常用品，不会成为医院里检查的对象，句子说不通。"}, {"text": "病魔", "is_correct": false, "explanation": "语域：“病魔”是文学化的说法，不用于医院里正式的检查，与“做……检查”不搭。"}], "explanations": {"肿瘤": "正确：“做肿瘤检查”指针对肿瘤的医学检查，在医院进行，需要等待结果。", "手机": "语义：去医院做的是身体相关的检查，手机不是医院检查的对象。", "钥匙": "语义：钥匙是日常用品，不会成为医院里检查的对象，句子说不通。", "病魔": "语域：“病魔”是文学化的说法，不用于医院里正式的检查，与“做……检查”不搭。"}, "sentence_index": 6, "correct_answer": "肿瘤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚底磨出了一个肿瘤，要用针挑破。", "explanation": "这里应该用〈水泡〉。走路磨出的是水泡，肿瘤是细胞异常增生形成的，不会因为摩擦而出现。"}, {"text": "他的手臂撞青了，里面有一大块肿瘤。", "explanation": "这里应该用〈瘀血〉。撞伤后皮下淤积的是瘀血，不是肿瘤，几天后会慢慢吸收。"}, {"text": "医生从她的胃里取出了一片肿瘤。", "explanation": "量词错误：这里应该用〈个〉。“片”用于平面的东西，肿瘤是块状的，不能说“一片肿瘤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生在他的肝上发现了一条肿瘤，要尽快手术。", "corrected_sentence": "医生在他的肝上发现了一个肿瘤，要尽快手术。", "error_description": "量词错误：肿瘤应用量词“个”。“条”用于细长的东西，肿瘤是块状的，不能说“一条肿瘤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只肿瘤长得很快，要尽早治疗。", "corrected_sentence": "这个肿瘤长得很快，要尽早治疗。", "error_description": "量词错误：肿瘤应用量词“个”。“只”多用于动物，不能说“这只肿瘤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
