INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体胯上、胸下的部位。", "primary_collocate": null, "pronunciation": "yāo", "ipa": "jau̯˥", "syllable_count": 1, "sentences": [{"text": "他的腰上系着一条蓝色的带子。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时水已经到我的腰了。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她双手叉着腰站在门口。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我的腰，说没有大问题。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近胖了，腰变粗了。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在腰上挂着一把小刀。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳舞时，腰要放松，不要太硬。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水涨到了我的腰，我不敢再往前走。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转了转腰，觉得舒服多了。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的腰受过伤，不能跑得太快。", "target_word": "腰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腰带", "label": "复合"}, {"form": "腰部", "label": "复合"}], "register": "中性", "sense_fingerprint": "人体胯上、胸下的部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "腰", "is_correct": true, "explanation": "正确答案：yāo（第一声），指人体胯上、胸下的部位。"}, {"text": "要", "is_correct": false, "explanation": "yào（第四声）与 yāo（第一声）声调不同，意思是“想要、需要”。"}, {"text": "摇", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是晃动。"}, {"text": "咬", "is_correct": false, "explanation": "yǎo（第三声）与 yāo（第一声）声调不同，意思是用牙齿夹住。"}], "explanations": {"腰": "正确答案：yāo（第一声），指人体胯上、胸下的部位。", "要": "yào（第四声）与 yāo（第一声）声调不同，意思是“想要、需要”。", "摇": "yáo（第二声）与 yāo（第一声）声调不同，意思是晃动。", "咬": "yǎo（第三声）与 yāo（第一声）声调不同，意思是用牙齿夹住。"}, "sentence_index": null, "correct_answer": "腰"}, "level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "正确：“腰上系着带子”指把带子系在身体中间的部位，是常见说法。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板是铺在地上的材料，不能系东西，这句说不通。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是学习用的家具，不能系带子，这里说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指面部的气色，不能说“脸色上系着带子”。"}], "explanations": {"腰": "正确：“腰上系着带子”指把带子系在身体中间的部位，是常见说法。", "地板": "语义：地板是铺在地上的材料，不能系东西，这句说不通。", "课桌": "语义：课桌是学习用的家具，不能系带子，这里说不通。", "脸色": "体貌：“脸色”指面部的气色，不能说“脸色上系着带子”。"}, "sentence_index": 0, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用腰刷牙。", "explanation": "这里应该用〈手〉。刷牙要用手拿牙刷，“腰”不能用来刷牙。"}, {"text": "他的腰上戴着一顶帽子。", "explanation": "这里应该用〈头〉。帽子要戴在头上，“腰”是身体中间的部位，不能戴帽子。"}, {"text": "他用腰关上了门。", "explanation": "这里应该用〈手〉。关门要靠手，“腰”不能用来关门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "腰", "is_correct": true, "explanation": "正确答案：yāo（第一声），指人体胯上、胸下的部位。"}, {"text": "药", "is_correct": false, "explanation": "yào（第四声）与 yāo（第一声）声调不同，意思是药物。"}, {"text": "窑", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是烧制陶瓷或砖的建筑。"}, {"text": "舀", "is_correct": false, "explanation": "yǎo（第三声）与 yāo（第一声）声调不同，意思是用勺子取出液体。"}], "explanations": {"腰": "正确答案：yāo（第一声），指人体胯上、胸下的部位。", "药": "yào（第四声）与 yāo（第一声）声调不同，意思是药物。", "窑": "yáo（第二声）与 yāo（第一声）声调不同，意思是烧制陶瓷或砖的建筑。", "舀": "yǎo（第三声）与 yāo（第一声）声调不同，意思是用勺子取出液体。"}, "sentence_index": null, "correct_answer": "腰"}, "level_3": {"options": [{"text": "腰", "is_correct": true, "explanation": "正确：跳舞时身体中间的部位要放松，说“腰”符合语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子不是身体部位，跳舞时不能说“鞋子要放松”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不能“放松”或“太硬”，这里说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指整体体形，不说“身材要放松”，句子说不通。"}], "explanations": {"腰": "正确：跳舞时身体中间的部位要放松，说“腰”符合语境。", "鞋子": "语义：鞋子不是身体部位，跳舞时不能说“鞋子要放松”。", "音乐": "语义：音乐不能“放松”或“太硬”，这里说不通。", "身材": "体貌：“身材”指整体体形，不说“身材要放松”，句子说不通。"}, "sentence_index": 6, "correct_answer": "腰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔倒后，腰站不起来。", "explanation": "这里应该用〈腿〉。站起来要靠腿，“腰”不能站起来。"}, {"text": "他举着腰向我挥手。", "explanation": "这里应该用〈胳膊〉。挥手要举起胳膊，“腰”不能被举起来挥动。"}, {"text": "他用腰踢起了足球。", "explanation": "这里应该用〈脚〉。踢球要靠脚，“腰”不能用来踢球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她双手扶腰着，慢慢站起来。", "corrected_sentence": "她双手扶着腰，慢慢站起来。", "error_description": "错误：“扶腰着”；正确：“扶着腰”。动态助词“着”要紧跟动词“扶”，放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他弯腰下，把鞋带系好。", "corrected_sentence": "他弯下腰，把鞋带系好。", "error_description": "错误：“弯腰下”；正确：“弯下腰”。补语“下”应紧跟动词“弯”，放在“腰”前面，不能放在“腰”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
