INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "船舶是在水上走的大小各种船。", "primary_collocate": null, "pronunciation": "chuán bó", "ipa": "ʈʂʰwan˧˥ po˧˥", "syllable_count": 2, "sentences": [{"text": "河面上有各种船舶，大的小的都有。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头边停满了船舶。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些船舶一早就出海了。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边看来来往往的船舶。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，船舶都亮起了灯。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "江上的船舶慢慢往前开。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责管理船舶。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一家卖船舶零件的店。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，船舶在水上晃得很厉害。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的海面上有几艘船舶。", "target_word": "船舶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在水上行驶的大大小小各种船", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "船舶", "is_correct": true, "explanation": "正确。船舶指在水上行驶的大大小小的船，河面上的正是船。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会漂在河面上，与“河面上有各种”不符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不在河面上行驶，句子说的是水上的船。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不会漂在河面上，与“河面上有各种……”不符。"}], "explanations": {"船舶": "正确。船舶指在水上行驶的大大小小的船，河面上的正是船。", "椅子": "语义：椅子不会漂在河面上，与“河面上有各种”不符。", "汽车": "语义：汽车不在河面上行驶，句子说的是水上的船。", "礼物": "语义：礼物不会漂在河面上，与“河面上有各种……”不符。"}, "sentence_index": 0, "correct_answer": "船舶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑着船舶去上班。", "explanation": "这里应该用〈自行车〉。船舶是船只，不能骑。"}, {"text": "他在图书馆借了一本船舶。", "explanation": "这里应该用〈书〉。船舶是船只，图书馆借的应是书。"}, {"text": "他长大后想当一名船舶。", "explanation": "这里应该用〈船员〉。船舶指船只，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船舶", "is_correct": true, "explanation": "正确。船舶在这里指公司所管理的各种船只。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：公司一般不管理孩子，“管理”的对象与句意不符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是公司可以负责管理的对象。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是公司能负责管理的对象，句意不通。"}], "explanations": {"船舶": "正确。船舶在这里指公司所管理的各种船只。", "孩子": "语义：公司一般不管理孩子，“管理”的对象与句意不符。", "天空": "语义：天空不是公司可以负责管理的对象。", "月亮": "语义：月亮不是公司能负责管理的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "船舶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里切了船舶。", "explanation": "这里应该用〈菜〉。船舶是船只，不能切。"}, {"text": "他在晚会上唱了一首船舶。", "explanation": "这里应该用〈歌〉。船舶指船只，不是歌曲，唱的应是歌。"}, {"text": "这家餐厅的船舶很好吃。", "explanation": "语义：船舶是船只，不是食物，不能说好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河面上有三座船舶，大的小的都有。", "corrected_sentence": "河面上有三艘船舶，大的小的都有。", "error_description": "“三座船舶”中量词错误：“座”用于山、楼等大型固定物，船舶应用“艘”，应改为“三艘船舶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在公司负责管理两台船舶。", "corrected_sentence": "他在公司负责管理两艘船舶。", "error_description": "“两台船舶”中量词错误：“台”用于机器、电器等，船舶应用“艘”，应改为“两艘船舶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
