INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99007, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每个地方都是这样。", "primary_collocate": null, "pronunciation": "chù chù", "ipa": "ʈʂʰu˥˩ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "春天到了，处处是花。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市处处很干净。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里处处有人。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上处处是绿色的树。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里处处都很安静。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的街上处处是灯。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里处处能听到笑声。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市处处有公园。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里处处有水。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边处处是孩子。", "target_word": "处处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "處處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每个地方都是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处处", "is_correct": true, "explanation": "处处：每个地方都是这样，与“春天到了，处处是花”的意思相符，正确。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，与“春天到了”之后满眼是花的整体景象相悖。"}, {"text": "随时", "is_correct": false, "explanation": "语义：“随时”说的是时间，不是地方的范围，与句中描写的景象不符。"}, {"text": "仅", "is_correct": false, "explanation": "语域：“仅”偏书面，表示只有，与“处处”的普遍义相反，不适合这句口语化的描写。"}], "explanations": {"处处": "处处：每个地方都是这样，与“春天到了，处处是花”的意思相符，正确。", "偶尔": "语义：“偶尔”表示有时候，与“春天到了”之后满眼是花的整体景象相悖。", "随时": "语义：“随时”说的是时间，不是地方的范围，与句中描写的景象不符。", "仅": "语域：“仅”偏书面，表示只有，与“处处”的普遍义相反，不适合这句口语化的描写。"}, "sentence_index": 0, "correct_answer": "处处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我处处每周去一次图书馆。", "explanation": "这里应该用〈经常〉。处处只表示地点范围，不能和“每周一次”这样表示次数的说法连用。"}, {"text": "他处处每天晚上十点才睡。", "explanation": "这里应该用〈通常〉。处处指地点范围，不能表示每天晚上的作息习惯。"}, {"text": "她处处连续三天给我打电话。", "explanation": "这里应该用〈一直〉。处处只表示地点范围，不能表示时间上的持续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处处", "is_correct": true, "explanation": "处处：每个地方都能听到笑声，与“学校里能听到笑声”的意思相符，正确。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：「亲自」指本人动手，与「能听到笑声」这一感知结果不搭。"}, {"text": "兀自", "is_correct": false, "explanation": "语域：“兀自”是文言用法，与这句口语化的叙述不协调。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”一般与“不”“没”连用，不能直接说“从来能听到”。"}], "explanations": {"处处": "处处：每个地方都能听到笑声，与“学校里能听到笑声”的意思相符，正确。", "亲自": "语义：「亲自」指本人动手，与「能听到笑声」这一感知结果不搭。", "兀自": "语域：“兀自”是文言用法，与这句口语化的叙述不协调。", "从来": "搭配：“从来”一般与“不”“没”连用，不能直接说“从来能听到”。"}, "sentence_index": 6, "correct_answer": "处处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我处处早上七点起床。", "explanation": "这里应该用〈每天〉。处处表示每个地方，不能表示时间上的习惯。"}, {"text": "他去过很多处处。", "explanation": "这里应该用〈地方〉。处处是副词，不能当名词作宾语。"}, {"text": "下课以后处处我们去吃饭。", "explanation": "这里应该用〈然后〉。处处表示每个地方，不表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天的校园里处处的开满了花。", "corrected_sentence": "春天的校园里处处开满了花。", "error_description": "「处处」是副词，后面不能直接加「的」。应写作「处处开满了花」，把「处处」直接放在动词「开满」前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末的商场里很处处都有人。", "corrected_sentence": "周末的商场里处处都有人。", "error_description": "「处处」本身表示范围，不能再受程度副词「很」修饰。应写作「处处都有人」，去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
