INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "排成的队伍。", "primary_collocate": null, "pronunciation": "háng liè", "ipa": "xɑŋ˧˥ lje˥˩", "syllable_count": 2, "sentences": [{"text": "游行的行列走过了大街。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们的行列非常整齐。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生们排成整齐的行列，走进了礼堂。", "target_word": "行列", "complexity_tier": "T3", "furigana": "xīn shēng men pái chéng zhěng qí de háng liè zǒu jìn le lǐ táng", "sentence_source": "generated"}, {"text": "下课后同学们站成行列，依次走出教室。", "target_word": "行列", "complexity_tier": "T3", "furigana": "xià kè hòu tóng xué men zhàn chéng háng liè yī cì zǒu chū jiào shì", "sentence_source": "generated"}, {"text": "学生的行列从学校走到公园。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穿红衣服的行列在路上慢慢前进。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开幕式上，运动员们排成长长的行列走过看台。", "target_word": "行列", "complexity_tier": "T3", "furigana": "kāi mù shì shàng yùn dòng yuán men pái chéng cháng cháng de háng liè zǒu guò kàn tái", "sentence_source": "generated"}, {"text": "节日里，跳舞的行列很热闹。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保志愿者排成行列，走上街头宣传。", "target_word": "行列", "complexity_tier": "T3", "furigana": "huán bǎo zhì yuàn zhě pái chéng háng liè zǒu shàng jiē tóu xuān chuán", "sentence_source": "generated"}, {"text": "军人的行列走过广场，大家都鼓掌。", "target_word": "行列", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "排成的队伍，多指人依次排列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行列", "is_correct": true, "explanation": "“游行的”修饰排成队伍的人群，人群能“走过大街”，所以是行列。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼不能“走过大街”，也不是游行的队伍。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会游行，也不能走过大街。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“游行的”不能修饰“脚印”，脚印与“走过大街”不相搭。"}], "explanations": {"行列": "“游行的”修饰排成队伍的人群，人群能“走过大街”，所以是行列。", "大楼": "语义：大楼不能“走过大街”，也不是游行的队伍。", "河流": "语义：河流不会游行，也不能走过大街。", "脚印": "搭配：“游行的”不能修饰“脚印”，脚印与“走过大街”不相搭。"}, "sentence_index": 0, "correct_answer": "行列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的行列安排得很满，每天都很忙。", "explanation": "这里应该用〈行程〉。行列指排成的队伍，不指旅行或日程的安排。"}, {"text": "请把要买的东西写成一个行列。", "explanation": "这里应该用〈清单〉。行列指人排成的队伍，写下来的条目要说清单。"}, {"text": "街道那头走来一棵行列。", "explanation": "这里的量词应该用〈支〉。“棵”用于植物，不能用来数人排成的队伍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行列", "is_correct": true, "explanation": "“排成长长的”后面接“行列”，运动员排成队列走过看台，句意最贴切。"}, {"text": "棋子", "is_correct": false, "explanation": "语义：棋子不会排成队走过看台，句中的主语是运动员。"}, {"text": "语法", "is_correct": false, "explanation": "搭配：“排成”不能接“语法”，语法不能排成队列。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍不会走过看台，句中走的是运动员。"}], "explanations": {"行列": "“排成长长的”后面接“行列”，运动员排成队列走过看台，句意最贴切。", "棋子": "语义：棋子不会排成队走过看台，句中的主语是运动员。", "语法": "搭配：“排成”不能接“语法”，语法不能排成队列。", "书籍": "语义：书籍不会走过看台，句中走的是运动员。"}, "sentence_index": 6, "correct_answer": "行列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在医疗行列工作多年。", "explanation": "这里应该用〈行业〉。行列指排成的队伍，不指职业领域；工作领域要说行业。"}, {"text": "我在这次考试中的行列是第三名。", "explanation": "这里应该用〈名次〉。行列指排成的队伍，不指考试或比赛的排名。"}, {"text": "这支行列在比赛中表现很好。", "explanation": "这里应该用〈队伍〉。行列强调排成一排、一队的人，不指参加比赛的队伍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游行地行列很长，走了很久。", "corrected_sentence": "游行的行列很长，走了很久。", "error_description": "结构助词错误：修饰名词“行列”要用“的”，不能用“地”（“地”修饰动词、形容词）。应为“游行的行列”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛开始前，同学们排成了长长行列。", "corrected_sentence": "比赛开始前，同学们排成了长长的行列。", "error_description": "结构助词遗漏：“长长”修饰“行列”时要加“的”，应为“长长的行列”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
