INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99016, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "市场上商品的价格。", "primary_collocate": null, "pronunciation": "háng shi", "ipa": "xɑŋ˧˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "米的行市涨了一点儿。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场上的行市各不一样。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很了解布料的行市。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年房子的行市一直在涨。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按现在的行市，这辆车能卖三万块。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天水果多，行市就便宜。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人们都很关心行市。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行市这么高，我不想买。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常看行市，决定什么时候卖货。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋的行市一天一个样。", "target_word": "行市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "市场上商品的价格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行市", "is_correct": true, "explanation": "行市指市场上商品的价格，正好填入“米的___涨了一点儿”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，米不能有体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只用于人或动物，米不能有年龄，也谈不上“涨”。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人的数量，与“米”不搭配，不能说米的人口涨了。"}], "explanations": {"行市": "行市指市场上商品的价格，正好填入“米的___涨了一点儿”。", "体重": "语义：“体重”指人或动物的重量，米不能有体重。", "年龄": "语义：“年龄”只用于人或动物，米不能有年龄，也谈不上“涨”。", "人口": "搭配：“人口”指人的数量，与“米”不搭配，不能说米的人口涨了。"}, "sentence_index": 0, "correct_answer": "行市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在电脑行市工作，每天都很忙。", "explanation": "这里应该用〈行业〉。“行市”指商品的价格，表示职业领域要说“行业”。"}, {"text": "他的行市每个月都很稳定。", "explanation": "这里应该用〈薪水〉。“行市”指商品价格，个人每个月的薪水不能说成行市。"}, {"text": "我们每个星期都去行市，挑选新鲜的水果。", "explanation": "这里应该用〈菜市场〉。“行市”指商品的价格，买菜的地方要说“菜市场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行市", "is_correct": true, "explanation": "行市指商品的价格，正好填入“商人们都很关心___”。"}, {"text": "认真", "is_correct": false, "explanation": "词性：“认真”是形容词，不能作“关心”的宾语。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“关心故事”不自然，一般不说商人关心故事。"}, {"text": "干净", "is_correct": false, "explanation": "词性：“干净”是形容词，不能作“关心”的宾语。"}], "explanations": {"行市": "行市指商品的价格，正好填入“商人们都很关心___”。", "认真": "词性：“认真”是形容词，不能作“关心”的宾语。", "故事": "搭配：“关心故事”不自然，一般不说商人关心故事。", "干净": "词性：“干净”是形容词，不能作“关心”的宾语。"}, "sentence_index": 6, "correct_answer": "行市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试的行市很好，得了九十分。", "explanation": "这里应该用〈成绩〉。“行市”指商品价格，考试的分数要说“成绩”。"}, {"text": "老板每个月月底给我们发行市。", "explanation": "这里应该用〈工资〉。“行市”指商品价格，老板发给员工的钱要说“工资”。"}, {"text": "我们排在行市里，等了一个小时。", "explanation": "这里应该用〈队伍〉。“行市”指商品的价格，排队的人群要说“队伍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种米的一个行市最近涨了一点儿。", "corrected_sentence": "这种米的行市最近涨了一点儿。", "error_description": "量词错误：“行市”是抽象名词，表示商品的价格，不能用“个”计量。应去掉“一个”，说“米的行市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天鸡蛋的行市很贵。", "corrected_sentence": "这几天鸡蛋的行市很高。", "error_description": "搭配错误：“行市”本身指价格，价格只能说“高/低”，不能说“贵/便宜”。应说“行市很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
