INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99019, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "行驶是车子或船在路上、水里走。", "primary_collocate": null, "pronunciation": "xíng shǐ", "ipa": "ɕiŋ˧˥ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那辆公共汽车正在公路上行驶。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车在雨中慢慢行驶着。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很窄，车不能快速行驶。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在河里平稳地行驶。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车在夜里行驶了很长时间。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，前面的车行驶得很慢。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车行驶过这座大桥时，天还没亮。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请靠右行驶。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆新车行驶起来很安静。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾天气，车辆要慢点儿行驶。", "target_word": "行驶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行驶了", "label": "体标"}, {"form": "行驶着", "label": "体标"}, {"form": "行驶过", "label": "体标"}], "register": "中性", "sense_fingerprint": "车子或船在路上、水里走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b12da1c0-45be-4ff5-b000-71e282348403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99019, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行驶", "is_correct": true, "explanation": "正确答案：xíng shǐ，指车子或船在路上、水里行进。"}, {"text": "形式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是样子、格式。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng 与 xíng、shì 与 shǐ 的声调都不同，意思是姓。"}, {"text": "信使", "is_correct": false, "explanation": "xìn 与 xíng 的韵母不同（in 与 ing），意思是送信的人。"}], "explanations": {"行驶": "正确答案：xíng shǐ，指车子或船在路上、水里行进。", "形式": "shì（第四声）与 shǐ（第三声）声调不同，意思是样子、格式。", "姓氏": "xìng 与 xíng、shì 与 shǐ 的声调都不同，意思是姓。", "信使": "xìn 与 xíng 的韵母不同（in 与 ing），意思是送信的人。"}, "sentence_index": null, "correct_answer": "行驶"}, "level_3": {"options": [{"text": "行驶", "is_correct": true, "explanation": "正确：车子在路上行进，用“行驶”符合语境。"}, {"text": "飞", "is_correct": false, "explanation": "语义：汽车不会飞，“正在公路上飞”说不通。"}, {"text": "游", "is_correct": false, "explanation": "语义：汽车不能游泳，“正在公路上游”说不通。"}, {"text": "漂", "is_correct": false, "explanation": "搭配：“漂”多指在水面上浮动，一般不说在公路上漂。"}], "explanations": {"行驶": "正确：车子在路上行进，用“行驶”符合语境。", "飞": "语义：汽车不会飞，“正在公路上飞”说不通。", "游": "语义：汽车不能游泳，“正在公路上游”说不通。", "漂": "搭配：“漂”多指在水面上浮动，一般不说在公路上漂。"}, "sentence_index": 0, "correct_answer": "行驶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天行驶去学校，很快就到了。", "explanation": "这里应该用〈步行〉。“行驶”的主语是车、船，人走路不能说“行驶”。"}, {"text": "飞机在天上行驶，很平稳。", "explanation": "这里应该用〈飞行〉。飞机在空中飞，“行驶”只用于车、船在路上或水上行进。"}, {"text": "小狗在院子里行驶，跑得很开心。", "explanation": "这里应该用〈跑〉。小狗靠四条腿跑，不说“行驶”，“行驶”只用于车、船在路上或水上行进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99019, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行驶", "is_correct": true, "explanation": "正确答案：xíng shǐ，指车子或船在路上、水里行进。"}, {"text": "刑事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是与法律犯罪有关的。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng 与 xíng、shì 与 shǐ 的声调都不同，意思是令人高兴的事。"}, {"text": "信史", "is_correct": false, "explanation": "xìn 与 xíng 的韵母不同（in 与 ing），意思是可靠的历史记载。"}], "explanations": {"行驶": "正确答案：xíng shǐ，指车子或船在路上、水里行进。", "刑事": "shì（第四声）与 shǐ（第三声）声调不同，意思是与法律犯罪有关的。", "幸事": "xìng 与 xíng、shì 与 shǐ 的声调都不同，意思是令人高兴的事。", "信史": "xìn 与 xíng 的韵母不同（in 与 ing），意思是可靠的历史记载。"}, "sentence_index": null, "correct_answer": "行驶"}, "level_3": {"options": [{"text": "行驶", "is_correct": true, "explanation": "正确：汽车经过大桥时用“行驶”，符合语境。"}, {"text": "跳", "is_correct": false, "explanation": "语义：汽车不能跳，“汽车跳过这座大桥”说不通。"}, {"text": "扛", "is_correct": false, "explanation": "语义：汽车不能扛东西，“汽车扛过这座大桥”说不通。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”要带搬运的对象，这里没有宾语，“汽车搬过”说不通。"}], "explanations": {"行驶": "正确：汽车经过大桥时用“行驶”，符合语境。", "跳": "语义：汽车不能跳，“汽车跳过这座大桥”说不通。", "扛": "语义：汽车不能扛东西，“汽车扛过这座大桥”说不通。", "搬": "配价：“搬”要带搬运的对象，这里没有宾语，“汽车搬过”说不通。"}, "sentence_index": 6, "correct_answer": "行驶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马在草原上行驶，跑得很快。", "explanation": "这里应该用〈奔跑〉。马靠四条腿跑，不说“行驶”，“行驶”只用于车、船。"}, {"text": "鱼在水里行驶，游得很自在。", "explanation": "这里应该用〈游弋〉。鱼靠身体在水中活动，不说“行驶”，“行驶”只用于车、船。"}, {"text": "老师在教室里行驶，讲得很清楚。", "explanation": "这里应该用〈走动〉。人在室内走动，不说“行驶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大巴在雪地里慢慢行驶了着。", "corrected_sentence": "大巴在雪地里慢慢行驶着。", "error_description": "错误：“行驶了着”；正确：“行驶着”。“了”和“着”不能同时用在同一个动词后面，表示持续状态只用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小朋友们在操场上快速行驶。", "corrected_sentence": "小朋友们在操场上快速奔跑。", "error_description": "错误：“小朋友们……行驶”；正确：“小朋友们……奔跑”。“行驶”只用于车、船，人用脚跑不能说“行驶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d113333-4415-4f48-b1b4-54bffb37babd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
