INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装甲是裹在车或船外面又硬又厚的铁，子弹打不穿。", "primary_collocate": null, "pronunciation": "zhuāng jiǎ", "ipa": "ʈʂwaŋ˥ tɕja˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆车外面有一层厚厚的装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子弹打不穿这种装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军舰的装甲又硬又厚，炮弹也很难打坏。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给这艘船装上新的装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克有装甲，所以不怕子弹。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵坐在车里，车的装甲很厚，很安全。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种装甲太重了，船开得很慢。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车的装甲坏了，工人正在修。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸车外面的装甲，冰冷又硬。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让船更安全，他们在外面加了装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层装甲", "label": "量词"}, {"form": "装甲车", "label": "复合"}, {"form": "装甲兵", "label": "复合"}], "register": "中性", "sense_fingerprint": "车、船外面又硬又厚、能挡子弹的铁壳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装甲", "is_correct": true, "explanation": "正确：装甲是裹在车外面的厚金属层，这里说的正是车的外层。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不会裹在车的外面。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不是能覆盖物体的材料，不能说“一层厚厚的声音”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“一层厚厚的”只能修饰能覆盖物体的材料，不能修饰心情。"}], "explanations": {"装甲": "正确：装甲是裹在车外面的厚金属层，这里说的正是车的外层。", "蛋糕": "语义：蛋糕是食物，不会裹在车的外面。", "声音": "搭配：声音不是能覆盖物体的材料，不能说“一层厚厚的声音”。", "心情": "搭配：“一层厚厚的”只能修饰能覆盖物体的材料，不能修饰心情。"}, "sentence_index": 0, "correct_answer": "装甲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘船外面装了一只装甲。", "explanation": "这里应该用〈一层〉。装甲是覆盖在车船外面的金属层，量词要用“层”，不能用“只”。"}, {"text": "工人用装甲修补了桥墩。", "explanation": "这里应该用〈钢板〉。装甲是装在车船外面的防弹金属板，修补桥墩要用钢板。"}, {"text": "妈妈用装甲包饺子。", "explanation": "这里应该用〈面皮〉。装甲是裹在车船外面的铁，包饺子要用面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装甲", "is_correct": true, "explanation": "正确：船上的装甲很重，所以船开得很慢。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛很轻，不会让船太重、开得很慢。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“重”说的是分量，不能用来形容价格。"}, {"text": "气球", "is_correct": false, "explanation": "语义：气球很轻，放在船上不会让船开得很慢。"}], "explanations": {"装甲": "正确：船上的装甲很重，所以船开得很慢。", "羽毛": "语义：羽毛很轻，不会让船太重、开得很慢。", "价格": "搭配：“重”说的是分量，不能用来形容价格。", "气球": "语义：气球很轻，放在船上不会让船开得很慢。"}, "sentence_index": 6, "correct_answer": "装甲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵举着装甲挡住了箭。", "explanation": "这里应该用〈盾牌〉。装甲是固定在车船上的防弹金属板，不能拿在手里挡箭。"}, {"text": "农民用装甲围住了菜园。", "explanation": "这里应该用〈铁丝网〉。装甲是车船上的防弹金属板，不能用来围菜园。"}, {"text": "厨师用装甲做了一碗面条。", "explanation": "这里应该用〈面粉〉。装甲是裹在车船外面的铁，做面条要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆坦克有一个装甲。", "corrected_sentence": "这辆坦克有一层装甲。", "error_description": "量词错误：装甲是覆盖在车外的金属层，应该用“层”，不能用“个”。错误形式是“有一个装甲”，正确形式是“有一层装甲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这艘船有很厚装甲。", "corrected_sentence": "这艘船有很厚的装甲。", "error_description": "“很厚”修饰名词“装甲”时中间要加“的”。错误形式是“很厚装甲”，正确形式是“很厚的装甲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
