INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "覆盖在战车、舰艇等外面的防弹金属板。", "primary_collocate": null, "pronunciation": "zhuāng jiǎ", "ipa": "ʈʂwaŋ˥ tɕja˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆战车的装甲能挡住子弹。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舰艇外面都有装甲，不怕小炮。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队买了一批新战车，装甲比以前厚。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在试验新装甲能不能防弹。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战车的装甲上有很多小坑。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘舰艇的装甲是用金属做的。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想让战车更安全，就得加厚装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者看到，战车装甲上还留着子弹的痕迹。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用金属板给舰艇做了一层装甲。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装甲越厚，战车就越重。", "target_word": "装甲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层装甲", "label": "量词"}, {"form": "装甲车", "label": "复合"}, {"form": "装甲兵", "label": "复合"}], "register": "中性", "sense_fingerprint": "战车、舰艇外面防弹的金属板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "装甲", "is_correct": true, "explanation": "正确：装甲是能挡子弹的防护层，战车的装甲能挡住子弹。"}, {"text": "方向盘", "is_correct": false, "explanation": "语义：方向盘用来转向，不能挡住子弹。"}, {"text": "风声", "is_correct": false, "explanation": "搭配：“挡住子弹”的主语必须是实体，风声不能挡子弹。"}, {"text": "车灯", "is_correct": false, "explanation": "语义：车灯用来照明，不能挡住子弹。"}], "explanations": {"装甲": "正确：装甲是能挡子弹的防护层，战车的装甲能挡住子弹。", "方向盘": "语义：方向盘用来转向，不能挡住子弹。", "风声": "搭配：“挡住子弹”的主语必须是实体，风声不能挡子弹。", "车灯": "语义：车灯用来照明，不能挡住子弹。"}, "sentence_index": 0, "correct_answer": "装甲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘舰艇外面有一只装甲。", "explanation": "这里应该用〈一层〉。装甲是覆盖在舰艇外面的金属层，量词要用“层”，不能用“只”。"}, {"text": "工人用装甲修好了漏雨的屋顶。", "explanation": "这里应该用〈铁皮〉。装甲是装在战车、舰艇外面的防弹金属板，修屋顶要用铁皮。"}, {"text": "他用装甲擦干了地板。", "explanation": "这里应该用〈抹布〉。装甲是覆盖在战车、舰艇等外面的防弹金属板，擦地板要用抹布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装甲", "is_correct": true, "explanation": "正确：加厚的是战车外面防弹的金属板，即装甲。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票不是防护物，加厚车票不能让战车更安全。"}, {"text": "被子", "is_correct": false, "explanation": "语义：被子是用来保暖的，不能保护战车。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“加厚”说的是有厚度的实体，不能用来形容合同。"}], "explanations": {"装甲": "正确：加厚的是战车外面防弹的金属板，即装甲。", "车票": "语义：车票不是防护物，加厚车票不能让战车更安全。", "被子": "语义：被子是用来保暖的，不能保护战车。", "合同": "搭配：“加厚”说的是有厚度的实体，不能用来形容合同。"}, "sentence_index": 6, "correct_answer": "装甲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "骑士用装甲挡住了长矛。", "explanation": "这里应该用〈盾牌〉。装甲是装在战车、舰艇外面的防弹金属板，不能拿在手里挡长矛。"}, {"text": "工人用装甲加固了桥梁。", "explanation": "这里应该用〈钢筋〉。装甲是装在战车、舰艇外面的防弹金属板，加固桥梁要用钢筋。"}, {"text": "奶奶用装甲给孙子缝了一件棉袄。", "explanation": "这里应该用〈布料〉。装甲是覆盖在战车、舰艇等外面的防弹金属板，缝棉袄要用布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆战车外面有一只装甲。", "corrected_sentence": "这辆战车外面有一层装甲。", "error_description": "量词错误：装甲是覆盖在战车外面的金属层，应该用“层”，不能用“只”。错误形式是“有一只装甲”，正确形式是“有一层装甲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军舰有很厚装甲。", "corrected_sentence": "军舰有很厚的装甲。", "error_description": "“很厚”修饰名词“装甲”时中间要加“的”。错误形式是“很厚装甲”，正确形式是“很厚的装甲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
