INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "讯息是别人传给你的话和消息。", "primary_collocate": null, "pronunciation": "xùn xī", "ipa": "ɕɥn˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "我收到了他发来的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条讯息是谁传给你的？", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个讯息告诉老师。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里有三条新讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读完讯息，马上笑了。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有回他的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友传来的讯息很短。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过妈妈留下的讯息了吗？", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都会回讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讯息传来时，我正在做饭。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "訊息", "label": "繁体"}], "register": "书面", "sense_fingerprint": "别人传来的一条话或消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作或声音，不能被“收到”或“发来”，句子说不通。"}, {"text": "讯息", "is_correct": true, "explanation": "正确：“讯息”是别人传给你的话或消息，可以“收到”，也可以“发来”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“收到”“发来”不能搭配“天气”，天气不是可以被传送的东西。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天上落下的水，不能被别人“发来”，与句子的语境冲突。"}], "explanations": {"脚步": "语义：脚步是走路的动作或声音，不能被“收到”或“发来”，句子说不通。", "讯息": "正确：“讯息”是别人传给你的话或消息，可以“收到”，也可以“发来”。", "天气": "搭配：“收到”“发来”不能搭配“天气”，天气不是可以被传送的东西。", "雨": "语义：雨是天上落下的水，不能被别人“发来”，与句子的语境冲突。"}, "sentence_index": 0, "correct_answer": "讯息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一位知情的讯息人士透露，这件事下周就会公布。", "explanation": "这里应该用〈消息〉。“消息人士”是固定说法，“讯息”不能这样用。"}, {"text": "我的手机里收到了一棵讯息。", "explanation": "这里应该用〈条〉。讯息用“条”计量，“棵”只用于树木等植物。"}, {"text": "这件衣服的讯息很好看。", "explanation": "这里应该用〈款式〉。“讯息”指别人传来的话或消息，不指衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是可以从朋友那里“传来”的东西。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“很短”说的是长度，不能用来形容面积。"}, {"text": "讯息", "is_correct": true, "explanation": "正确：“讯息”指别人传来的消息，可以说“传来”，也可以说“很短”。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是踩出来的痕迹，不能由朋友“传来”，句子不合常理。"}], "explanations": {"体温": "语义：体温是身体的温度，不是可以从朋友那里“传来”的东西。", "面积": "搭配：“很短”说的是长度，不能用来形容面积。", "讯息": "正确：“讯息”指别人传来的消息，可以说“传来”，也可以说“很短”。", "脚印": "语义：脚印是踩出来的痕迹，不能由朋友“传来”，句子不合常理。"}, "sentence_index": 6, "correct_answer": "讯息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他的讯息很好。", "explanation": "这里应该用〈成绩〉。“讯息”指别人传来的话或消息，不指考试的表现。"}, {"text": "一家讯息社率先报道了这件事。", "explanation": "这里应该用〈通讯社〉。“通讯社”是机构名称，“讯息社”不是这样的说法。"}, {"text": "我昨天收到了一座讯息。", "explanation": "这里应该用〈条〉。讯息用“条”计量，“座”用于山、桥、楼等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这周我收到了三只讯息。", "corrected_sentence": "这周我收到了三条讯息。", "error_description": "错误在量词：“讯息”应该用“条”计量，“只”用于动物等，不能说“三只讯息”。正确说法是“三条讯息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨晚我收到了朋友发来讯息。", "corrected_sentence": "昨晚我收到了朋友发来的讯息。", "error_description": "错误在修饰语：动词短语修饰名词时要加“的”，应说“朋友发来的讯息”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
