INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "消息；信息。", "primary_collocate": null, "pronunciation": "xùn xī", "ipa": "ɕɥn˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "电视上有很多新的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个讯息对我们很重要。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的讯息不一定都是真的。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报纸上找到了公司的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要更多关于这件事的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一则好讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校发布了考试的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你从哪里得到这个讯息的？", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些讯息可以帮助我们做决定。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在等着比赛的讯息。", "target_word": "讯息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "訊息", "label": "繁体"}], "register": "书面", "sense_fingerprint": "关于某件事的消息和信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a31aa07d-e6ef-4776-9420-88ed5b457871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：“味道”是嗅觉感受，电视无法传送，说“新的味道”句意不通。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”是身体的感觉，不能说成“新的饥饿”，句意不通。"}, {"text": "讯息", "is_correct": true, "explanation": "正确：“讯息”指关于某件事的消息，电视上可以播出很多新的讯息。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步是走路的动作或声音，不能算作电视上的“新东西”。"}], "explanations": {"味道": "语义：“味道”是嗅觉感受，电视无法传送，说“新的味道”句意不通。", "饥饿": "语义：“饥饿”是身体的感觉，不能说成“新的饥饿”，句意不通。", "讯息": "正确：“讯息”指关于某件事的消息，电视上可以播出很多新的讯息。", "脚步": "语义：脚步是走路的动作或声音，不能算作电视上的“新东西”。"}, "sentence_index": 0, "correct_answer": "讯息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在报纸上读到了一棵讯息。", "explanation": "这里应该用〈则〉。讯息用“则”计量，“棵”只用于树木等植物。"}, {"text": "这道菜的讯息有点儿咸。", "explanation": "这里应该用〈味道〉。“讯息”指消息和信息，不能形容食物的咸淡。"}, {"text": "他跑步的讯息非常快。", "explanation": "这里应该用〈速度〉。“讯息”指消息和信息，不指动作的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海浪", "is_correct": false, "explanation": "语义：海浪是海水的起伏，学校无法发布海浪，句子不合常理。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是天上落下的水，不能说“学校发布了考试的雨水”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“发布”不能搭配“脾气”，学校也不会发布脾气。"}, {"text": "讯息", "is_correct": true, "explanation": "正确：“讯息”是学校发布的关于考试的消息，可以用“发布”。"}], "explanations": {"海浪": "语义：海浪是海水的起伏，学校无法发布海浪，句子不合常理。", "雨水": "语义：雨水是天上落下的水，不能说“学校发布了考试的雨水”。", "脾气": "搭配：“发布”不能搭配“脾气”，学校也不会发布脾气。", "讯息": "正确：“讯息”是学校发布的关于考试的消息，可以用“发布”。"}, "sentence_index": 6, "correct_answer": "讯息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的讯息很便宜。", "explanation": "这里应该用〈价格〉。“讯息”指消息和信息，不能用来说商品的价钱。"}, {"text": "这家讯息社每天都有新的报道。", "explanation": "这里应该用〈通讯社〉。“通讯社”是机构名称，“讯息社”不是这样的说法。"}, {"text": "她搬走以后，屋里的讯息就只剩一把椅子了。", "explanation": "这里应该用〈东西〉。“讯息”指消息和信息，不能说成一把椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天看到一只重要讯息。", "corrected_sentence": "我今天看到一则重要讯息。", "error_description": "错误在量词：“讯息”的量词应是“则”，“只”不能用于讯息。正确说法是“一则重要讯息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直在等一则很重要讯息。", "corrected_sentence": "我一直在等一则很重要的讯息。", "error_description": "错误在修饰语：“很重要”修饰“讯息”时要加“的”，应说“很重要的讯息”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4b0a034-772f-4490-9d68-5f6ed50783a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
