INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说服，使人改变主意。", "primary_collocate": null, "pronunciation": "shuō dòng", "ipa": "ʂwɔ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我说动了妈妈，她同意我去旅行。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友想放弃，我说动了他再试一试。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说了很久，还是没说动老板。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很固执，但我终于说动了他。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说动了客人，客人买了这套房子。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐说动爸爸，一起去看电影。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想说动老师，让考试晚一天。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么说动她来帮忙的？", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想出一个好办法，说动了大家。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没说动哥哥，他还是不想去。", "target_word": "说动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说动了", "label": "完成体"}, {"form": "没说动", "label": "否定"}, {"form": "说不动", "label": "可能补语（否定）"}], "register": "口语", "sense_fingerprint": "说服别人，使其改变主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c4f7f75-67b9-4dfd-823d-60c9ee5e011a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说动", "is_correct": true, "explanation": "说动 shuō dòng 意思是用话使人改变主意，是正确答案。"}, {"text": "树洞", "is_correct": false, "explanation": "树洞 shù dòng 与说动只在第一个字的韵母和声调上不同（shù 与 shuō），意思是树木上的空洞。"}, {"text": "手动", "is_correct": false, "explanation": "手动 shǒu dòng 与说动第一个字的韵母和声调都不同（shǒu 与 shuō），意思是用手操作。"}, {"text": "鼠洞", "is_correct": false, "explanation": "鼠洞 shǔ dòng 与说动只在第一个字的韵母和声调上不同（shǔ 与 shuō），意思是老鼠挖的洞。"}], "explanations": {"说动": "说动 shuō dòng 意思是用话使人改变主意，是正确答案。", "树洞": "树洞 shù dòng 与说动只在第一个字的韵母和声调上不同（shù 与 shuō），意思是树木上的空洞。", "手动": "手动 shǒu dòng 与说动第一个字的韵母和声调都不同（shǒu 与 shuō），意思是用手操作。", "鼠洞": "鼠洞 shǔ dòng 与说动只在第一个字的韵母和声调上不同（shǔ 与 shuō），意思是老鼠挖的洞。"}, "sentence_index": null, "correct_answer": "说动"}, "level_3": {"options": [{"text": "说动", "is_correct": true, "explanation": "说动指用话使人改变主意，正好填入“我___了妈妈”。"}, {"text": "挡住", "is_correct": false, "explanation": "语义：“挡住”指阻拦，人被挡住后同意去旅行没有合理的因果联系，不能填入。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”指不在意、不理睬，与“她同意我去旅行”的结果相矛盾，不能填入。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”指得罪别人，冒犯妈妈后她不会因此同意我去旅行，前后没有因果关系。"}], "explanations": {"说动": "说动指用话使人改变主意，正好填入“我___了妈妈”。", "挡住": "语义：“挡住”指阻拦，人被挡住后同意去旅行没有合理的因果联系，不能填入。", "忽视": "语义：“忽视”指不在意、不理睬，与“她同意我去旅行”的结果相矛盾，不能填入。", "冒犯": "语义：“冒犯”指得罪别人，冒犯妈妈后她不会因此同意我去旅行，前后没有因果关系。"}, "sentence_index": 0, "correct_answer": "说动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师说动了这道难题，同学们都听懂了。", "explanation": "这里应该用〈讲解〉。“说动”的对象是人，把题目讲清楚要说“讲解”。"}, {"text": "我说动了情况，老师才理解。", "explanation": "这里应该用〈说明〉。“说动”的对象是人，把事情讲清楚要说“说明”。"}, {"text": "她的善良说动了大家，大家都很感激。", "explanation": "这里应该用〈感动〉。“说动”指用话改变他人想法，善良使人受触动要用“感动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说动", "is_correct": true, "explanation": "说动 shuō dòng 意思是用话使人改变主意，是正确答案。"}, {"text": "锁洞", "is_correct": false, "explanation": "锁洞 suǒ dòng 与说动只在声母和声调上不同（suǒ 与 shuō，韵母相同），意思是锁上的钥匙孔。"}, {"text": "甩动", "is_correct": false, "explanation": "甩动 shuǎi dòng 与说动的声母相同，但韵母和声调不同（ai 与 uo），意思是用力摆动。"}, {"text": "闪动", "is_correct": false, "explanation": "闪动 shǎn dòng 与说动的声母相同，但韵母和声调不同（an 与 uo），意思是光线忽明忽暗地晃动。"}], "explanations": {"说动": "说动 shuō dòng 意思是用话使人改变主意，是正确答案。", "锁洞": "锁洞 suǒ dòng 与说动只在声母和声调上不同（suǒ 与 shuō，韵母相同），意思是锁上的钥匙孔。", "甩动": "甩动 shuǎi dòng 与说动的声母相同，但韵母和声调不同（ai 与 uo），意思是用力摆动。", "闪动": "闪动 shǎn dòng 与说动的声母相同，但韵母和声调不同（an 与 uo），意思是光线忽明忽暗地晃动。"}, "sentence_index": null, "correct_answer": "说动"}, "level_3": {"options": [{"text": "说动", "is_correct": true, "explanation": "说动指用话使人改变主意，正好填入“我想___老师”，表示想说服老师改期。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指修饰外表，与“让考试晚一天”的请求无关。"}, {"text": "教训", "is_correct": false, "explanation": "语义：“教训”指训斥或惩罚，与请老师改期的意图相反。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”后不能接“让考试晚一天”这样的结构，句子不通。"}], "explanations": {"说动": "说动指用话使人改变主意，正好填入“我想___老师”，表示想说服老师改期。", "打扮": "语义：“打扮”指修饰外表，与“让考试晚一天”的请求无关。", "教训": "语义：“教训”指训斥或惩罚，与请老师改期的意图相反。", "送": "搭配：“送”后不能接“让考试晚一天”这样的结构，句子不通。"}, "sentence_index": 6, "correct_answer": "说动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "改革说动了经济发展。", "explanation": "这里应该用〈推动〉。“说动”的对象是人，经济发展要用“推动”。"}, {"text": "他说动了那张桌子，把它搬到了门口。", "explanation": "这里应该用〈搬动〉。“说动”只用于人，搬动桌子要用“搬动”。"}, {"text": "这次谈判说动了僵局，双方才有了进展。", "explanation": "这里应该用〈打破〉。“说动”只用于人，打破僵局要用“打破”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我花了很久，终于把爸爸说动着。", "corrected_sentence": "我花了很久，终于把爸爸说动了。", "error_description": "体标错误：“说动”是表示结果的动词，已经完成时应用“了”。“着”表示持续状态，不能与“说动”搭配，应说“说动了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我劝了他一个下午，还是不说动他。", "corrected_sentence": "我劝了他一个下午，还是没说动他。", "error_description": "否定词错误：表示劝说已经发生但没有成功，应用“没”。“不”不能用于这种已完成的否定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e24661-9dbc-40c9-affb-86ac66012635') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
