INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "调查人员是去问人、找东西，把事情弄清楚的人。", "primary_collocate": null, "pronunciation": "diào chá rén yuán", "ipa": "tjɑʊ˥˩ ʈʂʰa˧˥ ʐən˧˥ yɛn˧˥", "syllable_count": 4, "sentences": [{"text": "调查人员到现场问了很多人。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员在房间里找到了一把钥匙。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几位调查人员正在查那件事。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员把看到的情况都写下来。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当一名调查人员。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员一家一家地问。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口来了两位调查人员。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员终于弄清楚了事情的经过。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查人员坐在桌子旁，认真听他说。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的调查人员很有耐心。", "target_word": "调查人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "去问人、找东西，把事情弄清楚的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查人员", "is_correct": true, "explanation": "正确：“调查人员”指去问人、找东西、弄清事情的人，正好符合“到现场问了很多人”。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责调查，句中“问了很多人”指的是调查工作。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的职责是演唱，不会到现场向很多人询问情况。"}, {"text": "差役", "is_correct": false, "explanation": "语域：“差役”是古代衙门的差人，不用于描述现代的调查工作。"}], "explanations": {"调查人员": "正确：“调查人员”指去问人、找东西、弄清事情的人，正好符合“到现场问了很多人”。", "厨师": "语义：厨师不负责调查，句中“问了很多人”指的是调查工作。", "歌手": "语义：歌手的职责是演唱，不会到现场向很多人询问情况。", "差役": "语域：“差役”是古代衙门的差人，不用于描述现代的调查工作。"}, "sentence_index": 0, "correct_answer": "调查人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们请了一名调查人员来翻译这份英文合同。", "explanation": "这里应该用〈译员〉。调查人员负责问话、查证事实，不负责翻译语言。"}, {"text": "饭馆里的调查人员把菜端给客人。", "explanation": "这里应该用〈服务员〉。调查人员负责查问、弄清事情，不负责端菜、招待客人。"}, {"text": "他请了一名调查人员在法庭上为自己辩护。", "explanation": "这里应该用〈律师〉。调查人员负责查证事实，不负责在法庭上为当事人辩护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查人员", "is_correct": true, "explanation": "正确：“调查人员”是来查问事情的人，与“门口来了两位”相符。"}, {"text": "鸡", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“两位鸡”，句子也不通。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：“来了”指人前来，公交车不是来访的人，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”是器物，量词“位”不用于它，“门口来了两位桌子”不成立。"}], "explanations": {"调查人员": "正确：“调查人员”是来查问事情的人，与“门口来了两位”相符。", "鸡": "搭配：量词“位”只用于人，不能说“两位鸡”，句子也不通。", "公交车": "语义：“来了”指人前来，公交车不是来访的人，句意不通。", "桌子": "搭配：“桌子”是器物，量词“位”不用于它，“门口来了两位桌子”不成立。"}, "sentence_index": 6, "correct_answer": "调查人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路口的调查人员在指挥交通。", "explanation": "这里应该用〈交警〉。调查人员负责查问、调查，不负责指挥交通。"}, {"text": "病房里的调查人员在给病人打针。", "explanation": "这里应该用〈护士〉。调查人员不负责护理和打针。"}, {"text": "厨房里的调查人员正在做菜。", "explanation": "这里应该用〈厨师〉。调查人员不做饭，做菜的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校里来了两只调查人员。", "corrected_sentence": "学校里来了两名调查人员。", "error_description": "量词错误：指人的“调查人员”应该用“名”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里来了三位调查人员们。", "corrected_sentence": "院子里来了三位调查人员。", "error_description": "数量词错误：“三位”已表示数量，“们”不能与数词加量词同用，应去掉“们”，改为“三位调查人员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走私是偷偷地把东西运进来或运出去，不让管事的人知道。", "primary_collocate": null, "pronunciation": "zǒu sī", "ipa": "tsou˨˩˦ sz̩˥", "syllable_count": 2, "sentences": [{"text": "有人走私象牙，海关查到了。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们夜里用小船走私货物。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走私会伤害国家的经济。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查他是不是走私。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠走私赚了很多钱，后来坐了牢。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把东西藏在车里想走私。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家严打走私，抓了很多人。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没走私过，只做正当生意。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边境上常有人走私手机。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让工人走私酒，工人不肯。", "target_word": "走私", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "走私了", "label": "体标"}, {"form": "走私过", "label": "体标"}, {"form": "走私货", "label": "复合"}, {"form": "走私犯", "label": "复合"}], "register": "中性", "sense_fingerprint": "偷偷运进或运出东西，瞒着管理的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3efd60c-e060-4786-8479-6c763e1a6952') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走私", "is_correct": true, "explanation": "正确。「走私」指违法偷运象牙，与「海关查到了」相合。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：「清洗」是清理污物，与「海关查到了」的违法查获语境不合。"}, {"text": "救治", "is_correct": false, "explanation": "搭配：「救治」的对象是病人或伤员，不说「救治象牙」。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」是观赏，与句中的违法查获语境矛盾。"}], "explanations": {"走私": "正确。「走私」指违法偷运象牙，与「海关查到了」相合。", "清洗": "语义：「清洗」是清理污物，与「海关查到了」的违法查获语境不合。", "救治": "搭配：「救治」的对象是病人或伤员，不说「救治象牙」。", "欣赏": "语义：「欣赏」是观赏，与句中的违法查获语境矛盾。"}, "sentence_index": 0, "correct_answer": "走私"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他公开走私了这批货物，海关全都知道。", "explanation": "这里应该用〈运输〉。「走私」的定义是偷偷运送、不让管事的人知道，不能与「公开」连用；公开运送应说「运输」。"}, {"text": "这所学校正式走私了一批教材。", "explanation": "这里应该用〈采购〉。「走私」是偷偷运送、不让管事的人知道，不能与「正式」连用；学校正式买教材应说「采购」。"}, {"text": "学生走私了作业。", "explanation": "这里应该用〈完成〉。「走私」的对象是货物，作业不能偷运出入国境，也不是违法行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走私", "is_correct": true, "explanation": "正确。「走私」指违法偷运货物的行为，与「严打」相合。"}, {"text": "走廊", "is_correct": false, "explanation": "搭配：「严打」的对象是违法行为，不说「严打走廊」。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：「严打」的对象是违法行为，不说「严打散步」。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：「公路」不是违法行为，不能作「严打」的对象。"}], "explanations": {"走私": "正确。「走私」指违法偷运货物的行为，与「严打」相合。", "走廊": "搭配：「严打」的对象是违法行为，不说「严打走廊」。", "散步": "搭配：「严打」的对象是违法行为，不说「严打散步」。", "公路": "搭配：「公路」不是违法行为，不能作「严打」的对象。"}, "sentence_index": 6, "correct_answer": "走私"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校允许学生走私文具。", "explanation": "这里应该用〈带〉。「走私」指违法偷运、不让管事的人知道，学校允许时就不算走私，应说「允许学生带文具」。"}, {"text": "他用走私的速度跑完了全程。", "explanation": "这里应该用〈快〉。「走私」只指偷偷运送货物，不能用来形容速度，应说「他用很快的速度跑完了全程」。"}, {"text": "他每天在操场上走私，锻炼身体。", "explanation": "这里应该用〈跑步〉。「走私」是偷偷运送货物的行为，不能用在操场上做运动的场景，应说「在操场上跑步」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从国外走私出了一批名贵木材。", "corrected_sentence": "他从国外走私进了一批名贵木材。", "error_description": "补语「出」表示由内向外运出，与「从国外」的方向矛盾，应说「走私进了一批名贵木材」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把酒走私了进城。", "corrected_sentence": "工人把酒走私进了城。", "error_description": "「了」应放在补语「进」之后，应说「走私进了城」，不能说「走私了进城」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0926863d-898b-4ac0-83d8-41003db869ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
