INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "超出是比原来想的、定的范围更多。", "primary_collocate": null, "pronunciation": "chāo chū", "ipa": "ʈʂʰɑʊ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这次旅行的花费超出了我们的计划。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的结果超出了大家的想象。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜好吃，超出我的预期。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天来的人数超出了我们的预计。", "target_word": "超出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出的精彩程度超出了我的想象。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机的价格超出了我原来想的。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的表现超出了老师的期望。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的难度超出了我的预料。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作的收入超出了我原来的想法。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动的效果超出了我们的预期。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "超出了", "label": "体标（了）"}, {"form": "超出过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "结果比原来的计划、预算或想象更多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超出", "is_correct": true, "explanation": "正确：“超出”表示超过原来的计划，与“花费超出计划”的意思相符。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指养育动物，不能用来描述“花费”和“计划”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多搭配器物、设施，不搭配“花费”和“计划”。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行作品，与“花费”“计划”无关。"}], "explanations": {"超出": "正确：“超出”表示超过原来的计划，与“花费超出计划”的意思相符。", "饲养": "语义：“饲养”指养育动物，不能用来描述“花费”和“计划”。", "修理": "搭配：“修理”多搭配器物、设施，不搭配“花费”和“计划”。", "出版": "语义：“出版”指印刷发行作品，与“花费”“计划”无关。"}, "sentence_index": 0, "correct_answer": "超出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子超出了我。", "explanation": "这里应该用〈超过〉。超出多指越过范围、限度或预期，不用来比较两个人的高矮。"}, {"text": "这辆公交车超出了我家门口。", "explanation": "这里应该用〈经过〉。超出指越过界限或数量，公交车从门口经过不能说“超出”。"}, {"text": "我们明天超出北京去上海。", "explanation": "这里应该用〈离开〉。超出指比预期或计划更多，离开某地要用“离开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超出", "is_correct": true, "explanation": "正确：“超出”表示超过老师的期望，与句意相符。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”多搭配书刊、文件，不搭配“表现”和“期望”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭菜，与“表现”和“期望”无关。"}, {"text": "孵化", "is_correct": false, "explanation": "语义：“孵化”指卵变成幼体，句中说的是人的表现和期望。"}], "explanations": {"超出": "正确：“超出”表示超过老师的期望，与句意相符。", "印刷": "搭配：“印刷”多搭配书刊、文件，不搭配“表现”和“期望”。", "烹饪": "语义：“烹饪”指做饭菜，与“表现”和“期望”无关。", "孵化": "语义：“孵化”指卵变成幼体，句中说的是人的表现和期望。"}, "sentence_index": 6, "correct_answer": "超出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我终于超出了这道数学题。", "explanation": "这里应该用〈解答〉。超出指越过界限，解出问题要用“解答”。"}, {"text": "我们超出了这场考试。", "explanation": "这里应该用〈通过〉。超出指越过界限，考试合格要用“通过”。"}, {"text": "他超出了那本小说。", "explanation": "这里应该用〈读完〉。超出指越过界限，读完一本书要用“读完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的花费超出着预算。", "corrected_sentence": "这次的花费超出了预算。", "error_description": "体标错误：“超出”表示已经发生的超过，应用“了”；“着”表示持续的状态，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩很超出了老师的期望。", "corrected_sentence": "他的成绩超出了老师的期望。", "error_description": "副词误用：“很”一般修饰形容词，不能修饰动词“超出”，应删去“很”，说“超出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
