INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "越过一定的范围或限度。", "primary_collocate": null, "pronunciation": "chāo chū", "ipa": "ʈʂʰɑʊ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这个问题超出了我的能力范围。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车速不能超出规定的限度。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的话超出了开玩笑的限度。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题超出了课本里学过的内容。", "target_word": "超出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李的重量不能超出二十公斤。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的行为超出了学校的规定。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水涨得很高，超出了安全线。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些要求超出了公司的责任范围。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要问超出工作范围的问题。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事已经超出了我能管的范围。", "target_word": "超出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "超出了", "label": "体标（了）"}, {"form": "超出过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "越过规定、能力或范围的界限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cf938f4-42ad-492e-99ec-250d2cb0e12e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "超出", "is_correct": true, "explanation": "正确：“超出”表示超过能力范围，与句意相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭菜，不能用来说问题超出能力。"}, {"text": "检修", "is_correct": false, "explanation": "搭配：“检修”多搭配设备，不搭配“问题”和“能力范围”。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多搭配资金、账户，不能冻结“能力范围”。"}], "explanations": {"超出": "正确：“超出”表示超过能力范围，与句意相符。", "烹饪": "语义：“烹饪”指做饭菜，不能用来说问题超出能力。", "检修": "搭配：“检修”多搭配设备，不搭配“问题”和“能力范围”。", "冻结": "搭配：“冻结”多搭配资金、账户，不能冻结“能力范围”。"}, "sentence_index": 0, "correct_answer": "超出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高超出了我。", "explanation": "这里应该用〈超过〉。超出多指越过规定或界限，不用来比较两个人的高矮。"}, {"text": "他超出了这次体检。", "explanation": "这里应该用〈通过〉。超出指越过界限，体检合格要用“通过”。"}, {"text": "我们超出了这个难关。", "explanation": "这里应该用〈突破〉。突破指克服障碍、打破限制，超出指越过界限，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超出", "is_correct": true, "explanation": "正确：“超出”表示越过安全线，与“河水涨得很高”的句意相符。"}, {"text": "缝制", "is_correct": false, "explanation": "语义：“缝制”指用针线做衣物，与河水和安全线无关。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指奏乐，句中没有音乐的语境。"}, {"text": "包扎", "is_correct": false, "explanation": "搭配：“包扎”搭配伤口，不搭配“安全线”。"}], "explanations": {"超出": "正确：“超出”表示越过安全线，与“河水涨得很高”的句意相符。", "缝制": "语义：“缝制”指用针线做衣物，与河水和安全线无关。", "演奏": "语义：“演奏”指奏乐，句中没有音乐的语境。", "包扎": "搭配：“包扎”搭配伤口，不搭配“安全线”。"}, "sentence_index": 6, "correct_answer": "超出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的车超出了前面的卡车。", "explanation": "这里应该用〈超过〉。超出指越过规定的范围或限度，车从后面赶到前面要用“超过”。"}, {"text": "老师超出了课堂的秩序。", "explanation": "这里应该用〈控制〉。超出指越过界限，不用来表示掌控或管理。"}, {"text": "工人超出了那座桥。", "explanation": "这里应该用〈修好〉。超出指越过界限，不用来表示修理完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题很超出了我的能力范围。", "corrected_sentence": "这道题超出了我的能力范围。", "error_description": "副词误用：“很”一般修饰形容词，不能修饰动词“超出”，应删去“很”，说“超出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事超出着我的管辖范围。", "corrected_sentence": "这件事超出了我的管辖范围。", "error_description": "体标错误：“超出”表示已经发生的超越，应用“了”，不能用“着”（“着”表示持续的状态）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08c6323b-6638-4afc-b6d6-f5d63da6177e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
