INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99047, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑出是从里面一直跑到外面。", "primary_collocate": null, "pronunciation": "pǎo chū", "ipa": "pʰɑʊ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "一听到火警，他一口气跑出大楼。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从厨房一直跑出了大门。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞走了，孩子跑出家门去追。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影还没结束，她就跑出了电影院。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，我们跑出帐篷玩。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗从后门跑出去，跑到了街上。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑出地铁站，发现下雨了。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟大叫一声，跑出了家门。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门一开，兔子就跑出笼子了。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球赛结束后，球迷们跑出体育馆。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑出了", "label": "完成体"}, {"form": "跑出来", "label": "复合趋向"}, {"form": "跑出去", "label": "复合趋向"}, {"form": "跑不出", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "跑出：从里面一直跑到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99047, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出（pǎo chū）是正确答案，指从里面一直跑到外面。"}, {"text": "泡出", "is_correct": false, "explanation": "跑 pǎo（第三声）与泡 pào（第四声）声调不同，泡出指浸泡后释放出来。"}, {"text": "刨出", "is_correct": false, "explanation": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。"}, {"text": "跑输", "is_correct": false, "explanation": "出 chū 与输 shū 声母不同（ch 与 sh），跑输指比赛中落后于对手。"}], "explanations": {"跑出": "跑出（pǎo chū）是正确答案，指从里面一直跑到外面。", "泡出": "跑 pǎo（第三声）与泡 pào（第四声）声调不同，泡出指浸泡后释放出来。", "刨出": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。", "跑输": "出 chū 与输 shū 声母不同（ch 与 sh），跑输指比赛中落后于对手。"}, "sentence_index": null, "correct_answer": "跑出"}, "level_3": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出是正确答案，指他一口气从大楼里跑到外面。"}, {"text": "驶出", "is_correct": false, "explanation": "语义：“驶出”指车船开出，不用于人跑出大楼。"}, {"text": "写出", "is_correct": false, "explanation": "搭配：“写出”的宾语是文字、文章，不能以大楼作宾语。"}, {"text": "说出", "is_correct": false, "explanation": "配价：“说出”的宾语是话语，不能以大楼作宾语。"}], "explanations": {"跑出": "跑出是正确答案，指他一口气从大楼里跑到外面。", "驶出": "语义：“驶出”指车船开出，不用于人跑出大楼。", "写出": "搭配：“写出”的宾语是文字、文章，不能以大楼作宾语。", "说出": "配价：“说出”的宾语是话语，不能以大楼作宾语。"}, "sentence_index": 0, "correct_answer": "跑出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的花费跑出了预算。", "explanation": "这里应该用〈超出〉。超出可指超过预算、能力等范围，跑出只指身体从里面跑到外面。"}, {"text": "我们终于跑出了困境。", "explanation": "这里应该用〈走出〉。走出困境表示摆脱困难，跑出只指身体动作，不能用于困境。"}, {"text": "他从抽屉里跑出了信封。", "explanation": "这里应该用〈取出〉。取出表示从里面拿东西出来；跑出是不及物动词，不能带“信封”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99047, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出（pǎo chū）是正确答案，指从里面一直跑到外面。"}, {"text": "抛出", "is_correct": false, "explanation": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。"}, {"text": "刨出", "is_correct": false, "explanation": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。"}, {"text": "保出", "is_correct": false, "explanation": "跑 pǎo 与保 bǎo 声母不同（p 与 b），保出指通过担保把人弄出来。"}], "explanations": {"跑出": "跑出（pǎo chū）是正确答案，指从里面一直跑到外面。", "抛出": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。", "刨出": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。", "保出": "跑 pǎo 与保 bǎo 声母不同（p 与 b），保出指通过担保把人弄出来。"}, "sentence_index": null, "correct_answer": "跑出"}, "level_3": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出是正确答案，指他从地铁站里跑到外面。"}, {"text": "流出", "is_correct": false, "explanation": "语义：“流出”多指液体、气体，或成群的人流出；单独的“他”不说“流出”地铁站。"}, {"text": "画出", "is_correct": false, "explanation": "语义：“画出”指用笔画成图形，不能说画出地铁站来表示离开。"}, {"text": "投入", "is_correct": false, "explanation": "搭配：“投入”的宾语是精力、工作等，不说投入地铁站。"}], "explanations": {"跑出": "跑出是正确答案，指他从地铁站里跑到外面。", "流出": "语义：“流出”多指液体、气体，或成群的人流出；单独的“他”不说“流出”地铁站。", "画出": "语义：“画出”指用笔画成图形，不能说画出地铁站来表示离开。", "投入": "搭配：“投入”的宾语是精力、工作等，不说投入地铁站。"}, "sentence_index": 6, "correct_answer": "跑出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑出了心里的秘密。", "explanation": "这里应该用〈说出〉。秘密要用说出来表达，跑出只表示身体从里面跑到外面，不能带秘密作宾语。"}, {"text": "我们要跑出改革的第一步。", "explanation": "这里应该用〈迈出〉。迈出第一步比喻开始行动，跑出只指身体动作。"}, {"text": "警察跑出了人质。", "explanation": "这里应该用〈释放〉。释放可带人作宾语，表示使人获得自由；跑出是不及物动词，不能带“人质”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = E