INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从里面跑到外面。", "primary_collocate": null, "pronunciation": "pǎo chū", "ipa": "pʰɑʊ˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "下课了，学生们跑出教室。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗从院子里跑出去了。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到喊声，马上跑出门外。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跑出来看雪。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站里，一个小男孩跑出了人群。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，大家都跑出了房子。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫从箱子里跑出来了。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着跑出了房间。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑出商店，却没追上他。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到铃声，老师跑出办公室。", "target_word": "跑出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑出了", "label": "完成体"}, {"form": "跑出来", "label": "复合趋向"}, {"form": "跑出去", "label": "复合趋向"}, {"form": "跑不出", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "跑出：从里面跑到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8b66da-3fe9-4aa1-a85b-15257d96b0de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99048, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出（pǎo chū）是正确答案，指从里面跑到外面。"}, {"text": "泡出", "is_correct": false, "explanation": "跑 pǎo（第三声）与泡 pào（第四声）声调不同，泡出指浸泡后释放出来。"}, {"text": "抛出", "is_correct": false, "explanation": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。"}, {"text": "跑输", "is_correct": false, "explanation": "出 chū 与输 shū 声母不同（ch 与 sh），跑输指比赛中落后于对手。"}], "explanations": {"跑出": "跑出（pǎo chū）是正确答案，指从里面跑到外面。", "泡出": "跑 pǎo（第三声）与泡 pào（第四声）声调不同，泡出指浸泡后释放出来。", "抛出": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。", "跑输": "出 chū 与输 shū 声母不同（ch 与 sh），跑输指比赛中落后于对手。"}, "sentence_index": null, "correct_answer": "跑出"}, "level_3": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出是正确答案，指学生从教室里跑到外面。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”的宾语是课程、活动，不能以教室为宾语。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人或动物降生，与下课后离开教室无关。"}, {"text": "复习", "is_correct": false, "explanation": "搭配：“复习”的宾语是课文、功课，不能说复习教室。"}], "explanations": {"跑出": "跑出是正确答案，指学生从教室里跑到外面。", "结束": "搭配：“结束”的宾语是课程、活动，不能以教室为宾语。", "出生": "语义：“出生”指人或动物降生，与下课后离开教室无关。", "复习": "搭配：“复习”的宾语是课文、功课，不能说复习教室。"}, "sentence_index": 0, "correct_answer": "跑出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她终于跑出了失恋的阴影。", "explanation": "这里应该用〈走出〉。走出可指摆脱痛苦或阴影，跑出只指身体从里面跑到外面，不能用于心理状态。"}, {"text": "他大声跑出了自己的想法。", "explanation": "这里应该用〈说出〉。想法要用说出来表达，跑出不能带想法作宾语。"}, {"text": "她跑出了人生的第一步。", "explanation": "这里应该用〈迈出〉。迈出第一步比喻开始行动，跑出只表示身体从里面跑到外面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99048, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出（pǎo chū）是正确答案，指从里面跑到外面。"}, {"text": "抛出", "is_correct": false, "explanation": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。"}, {"text": "刨出", "is_correct": false, "explanation": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。"}, {"text": "保出", "is_correct": false, "explanation": "跑 pǎo 与保 bǎo 声母不同（p 与 b），保出指通过担保把人弄出来。"}], "explanations": {"跑出": "跑出（pǎo chū）是正确答案，指从里面跑到外面。", "抛出": "跑 pǎo 与抛 pāo 声调不同，抛出指向外扔。", "刨出": "跑 pǎo 与刨 páo 声调不同，刨出指挖掘后取出来。", "保出": "跑 pǎo 与保 bǎo 声母不同（p 与 b），保出指通过担保把人弄出来。"}, "sentence_index": null, "correct_answer": "跑出"}, "level_3": {"options": [{"text": "跑出", "is_correct": true, "explanation": "跑出是正确答案，指猫从箱子里跑到外面。"}, {"text": "说出", "is_correct": false, "explanation": "语义：猫不会说话，“说出”与猫的动作不符。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：猫不会唱歌，“唱出”与从箱子里出来无关。"}, {"text": "织出", "is_correct": false, "explanation": "搭配：“织出”的宾语是布、毛衣等织物，不能用于猫。"}], "explanations": {"跑出": "跑出是正确答案，指猫从箱子里跑到外面。", "说出": "语义：猫不会说话，“说出”与猫的动作不符。", "唱出": "语义：猫不会唱歌，“唱出”与从箱子里出来无关。", "织出": "搭配：“织出”的宾语是布、毛衣等织物，不能用于猫。"}, "sentence_index": 6, "correct_answer": "跑出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事跑出了我的能力范围。", "explanation": "这里应该用〈超出〉。超出可指超过能力或范围，可用于抽象事物；跑出只指身体从里面跑到外面。"}, {"text": "他跑出了一声尖叫。", "explanation": "这里应该用〈发出〉。发出可带声音作宾语，表示从内部传出；跑出只表示人或物从里面跑到外面，不能带声音作宾语。"}, {"text": "他从包里跑出了钥匙。", "explanation": "这里应该用〈取出〉。取出表示从里面拿东西出来；跑出是不及物动词，不能带“钥匙”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗从后门跑出了去。", "corrected_sentence": "小狗从后门跑出去了。", "error_description": "错误在复合趋向补语的语序：“去”应紧跟“出”，说“跑出去了”，“了”放在句末；“跑出了去”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子跑出了把房间。", "corrected_sentence": "他一下子跑出了房间。", "error_description": "错误在“把”的位置：“跑出”是不及物动词，“房间”前不能加“把”；应说“跑出了房间”，不能说“跑出了把房间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f518e4-6545-4934-a6ee-a447ae14a339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
