INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99049, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "跟手是接着就做，马上做。", "primary_collocate": null, "pronunciation": "gēn shǒu", "ipa": "kən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他一进门，跟手就把灯打开了。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说完话，跟手去做饭了。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师写完题目，跟手叫学生回答。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她接过电话，跟手跑了出去。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吃完饭，跟手去洗碗吧。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝完水，跟手又倒了一杯。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课铃一响，同学们跟手走出教室。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理开完会，跟手给客人打电话。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到门铃，她跟手去开门。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了票，跟手进了电影院。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做完一件事后马上接着做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟手", "is_correct": true, "explanation": "正确：表示进门后紧接着把灯打开，与“就”呼应。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢，与“一进门就”的迅速动作相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“一……就”的必然接续相矛盾。"}, {"text": "最终", "is_correct": false, "explanation": "语域：“最终”偏书面，与这句口语叙述不协调，也与“就”的接续不合。"}], "explanations": {"跟手": "正确：表示进门后紧接着把灯打开，与“就”呼应。", "慢慢": "语义：“慢慢”表示缓慢，与“一进门就”的迅速动作相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“一……就”的必然接续相矛盾。", "最终": "语域：“最终”偏书面，与这句口语叙述不协调，也与“就”的接续不合。"}, "sentence_index": 0, "correct_answer": "跟手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一进门，跟手就生病了。", "explanation": "跟手表示接着做某个动作，“生病”不是人能接着去做的动作，不能与跟手搭配。"}, {"text": "他曾经跟手去了北京。", "explanation": "跟手强调紧接着前一个动作去做某个具体动作，需要有明确的前后衔接；“曾经”指泛泛的过去经历，与之不搭。"}, {"text": "他跟手睡了一整天。", "explanation": "跟手表示前一个动作做完后紧接着做另一个动作；这句前面没有先发生的动作，“睡了一整天”也是持续很久的状态，不能用跟手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟手", "is_correct": true, "explanation": "正确：表示铃声一响，同学们紧接着走出教室。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示永远不做，与“铃一响就走”的动作矛盾。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示碰巧，与铃响后每次都走出的常规动作不符。"}, {"text": "并未", "is_correct": false, "explanation": "语义：“并未”表示并没有发生，与“铃一响就走出教室”的动作相反。"}], "explanations": {"跟手": "正确：表示铃声一响，同学们紧接着走出教室。", "从不": "语义：“从不”表示永远不做，与“铃一响就走”的动作矛盾。", "偶然": "语义：“偶然”表示碰巧，与铃响后每次都走出的常规动作不符。", "并未": "语义：“并未”表示并没有发生，与“铃一响就走出教室”的动作相反。"}, "sentence_index": 6, "correct_answer": "跟手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我跟手会说英语。", "explanation": "这里把“跟手”用来说明能力，但它只表示紧接着做某个具体动作，不能用来说明会不会做某事。"}, {"text": "他一边唱歌，跟手跳舞。", "explanation": "这里应该用〈同时〉。跟手表示接着做，不表示两件事同时进行。"}, {"text": "老师一讲完，我跟手很喜欢这节课。", "explanation": "跟手要接具体的动作，不能接“很喜欢”这类心理状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下班回家，跟手了做饭。", "corrected_sentence": "他下班回家，跟手做饭。", "error_description": "体标错误：“了”不能夹在副词“跟手”与动词之间，应删去，说“跟手做饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议结束后，经理跟手的给客人打电话。", "corrected_sentence": "会议结束后，经理跟手给客人打电话。", "error_description": "词性错误：“跟手”是副词，后面不能加“的”，应说“跟手给客人打电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
