INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99050, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "随手，顺手（顺便把某事做了）。", "primary_collocate": null, "pronunciation": "gēn shǒu", "ipa": "kən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "出门时，请跟手关灯。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完的书，你跟手放回书架吧。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回家，跟手把鞋放好。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完的水果皮，请跟手扔进垃圾桶。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出去时，跟手把信寄了。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在桌子旁，跟手拿了一本书看。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完手，跟手把水龙头关好。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完的笔，要跟手放回盒子里。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走过邮局，我跟手把包裹寄了。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进了厨房，他跟手把菜洗了。", "target_word": "跟手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "顺手、顺便把某事做了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟手", "is_correct": true, "explanation": "正确：表示出门时顺手把灯关掉，与“出门时”的语境相符。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”表示多次重复，与出门时关一次灯的语境不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，不能用来描述出门时的关灯动作。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是书面副词，与这句口语祈使句不协调。"}], "explanations": {"跟手": "正确：表示出门时顺手把灯关掉，与“出门时”的语境相符。", "反复": "语义：“反复”表示多次重复，与出门时关一次灯的语境不合。", "忽然": "语义：“忽然”表示突然，不能用来描述出门时的关灯动作。", "遂": "语域：“遂”是书面副词，与这句口语祈使句不协调。"}, "sentence_index": 0, "correct_answer": "跟手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他曾经跟手学过三年钢琴。", "explanation": "学钢琴需要长期坚持，不是随手或紧接着就能完成的动作，与“跟手”不搭。"}, {"text": "为了给妈妈庆生，我跟手买了一个蛋糕。", "explanation": "这里应该用〈特意〉。跟手强调顺带、紧接着做，专门为某个目的去做要用“特意”。"}, {"text": "我跟手在这家公司工作了十年。", "explanation": "跟手表示顺手做一件小事，不能修饰“工作十年”这样长期的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟手", "is_correct": true, "explanation": "正确：表示洗完手后顺手把水龙头关好。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示永远没有这种行为，与洗完手后关水龙头的动作矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与洗完手后每次都关水龙头的语境不符。"}, {"text": "未曾", "is_correct": false, "explanation": "语义：“未曾”表示从来没有过，与“洗完手”后顺手关好水龙头的动作相反。"}], "explanations": {"跟手": "正确：表示洗完手后顺手把水龙头关好。", "从不": "语义：“从不”表示永远没有这种行为，与洗完手后关水龙头的动作矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与洗完手后每次都关水龙头的语境不符。", "未曾": "语义：“未曾”表示从来没有过，与“洗完手”后顺手关好水龙头的动作相反。"}, "sentence_index": 6, "correct_answer": "跟手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我跟手会做饭。", "explanation": "这里把“跟手”用来说明能力，但它只表示随手或紧接着做某个动作，不能用来描述会不会做某事。"}, {"text": "他跟手生了三天的病。", "explanation": "跟手表示随手或紧接着做某个动作，“生病”持续三天，不是随手或紧接着就能做的动作，不能搭配。"}, {"text": "她跟手很喜欢这个城市。", "explanation": "跟手要接具体的动作，不能接“很喜欢”这类心理状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出门时，请跟手的带上门。", "corrected_sentence": "出门时，请跟手带上门。", "error_description": "词性错误：“跟手”是副词，后面不能加“的”，应说“跟手带上门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用完的剪刀，你跟手了收起来吧。", "corrected_sentence": "用完的剪刀，你跟手收起来吧。", "error_description": "体标错误：“跟手”是副词，后面不能加“了”，应说“跟手收起来吧”。错误形式是“跟手了收起来”，正确形式是“跟手收起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
