INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99053, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "送死是自己去做很危险的事，会丢掉性命。", "primary_collocate": null, "pronunciation": "sòng sǐ", "ipa": "sʊŋ˥˩ sɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "别去那里，那是去送死。", "target_word": "送死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有武器就上战场，不是送死吗？", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明知有危险，还去送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨天爬山，简直是送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不会游泳还下海，这是送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不想白白去送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有准备就进山，等于送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不愿意去送死。", "target_word": "送死", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么黑的路，一个人走是送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车那么快，真是在送死。", "target_word": "送死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "动词，明知危险还去做，会丢掉性命", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '538b8765-1c9e-4db9-8583-9f5d1dd35ff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送死", "is_correct": true, "explanation": "送死指明知危险还去做，会丢掉性命，符合“别去那里”的劝阻语境。"}, {"text": "逃命", "is_correct": false, "explanation": "语义：“逃命”指躲避危险求生，与“别去那里”的劝阻语境不相容，句意说不通。"}, {"text": "打球", "is_correct": false, "explanation": "语义：“打球”是普通的运动，没有危险，与“别去那里”的劝阻语境不相合，句意说不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”与危险无关，与“别去那里”的劝阻语境不相合，句意不通。"}], "explanations": {"送死": "送死指明知危险还去做，会丢掉性命，符合“别去那里”的劝阻语境。", "逃命": "语义：“逃命”指躲避危险求生，与“别去那里”的劝阻语境不相容，句意说不通。", "打球": "语义：“打球”是普通的运动，没有危险，与“别去那里”的劝阻语境不相合，句意说不通。", "上学": "语义：“上学”与危险无关，与“别去那里”的劝阻语境不相合，句意不通。"}, "sentence_index": 0, "correct_answer": "送死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在那次意外中送死。", "explanation": "这里应该用〈送命〉。送死指自己主动去冒必死的危险，是有意的；因意外丧命要用〈送命〉。"}, {"text": "他年纪大了，在家里安静地送死。", "explanation": "这里应该用〈去世〉。送死只用于自己去冒必死的危险而丧命，寿终正寝要用〈去世〉。"}, {"text": "他被车撞伤后，只能躺在路边送死。", "explanation": "这里应该用〈等死〉。送死指主动去冒险，伤后只能等待死亡要用〈等死〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送死", "is_correct": true, "explanation": "送死指明知危险还去冒险，此处“进山”没有准备，正好与之相合。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”是悠闲的出游，与没有准备就进山的危险含义相反，“等于旅游”说不通。"}, {"text": "歇息", "is_correct": false, "explanation": "语义：“歇息”是休息，与“没有准备就进山”的危险语义不符，“等于歇息”说不通。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：“殉职”是书面语，专指因公牺牲，口语中不用来形容进山。"}], "explanations": {"送死": "送死指明知危险还去冒险，此处“进山”没有准备，正好与之相合。", "旅游": "语义：“旅游”是悠闲的出游，与没有准备就进山的危险含义相反，“等于旅游”说不通。", "歇息": "语义：“歇息”是休息，与“没有准备就进山”的危险语义不符，“等于歇息”说不通。", "殉职": "语域：“殉职”是书面语，专指因公牺牲，口语中不用来形容进山。"}, "sentence_index": 6, "correct_answer": "送死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很好，我们去公园散步，这真是送死。", "explanation": "这里应该用〈享受〉。送死指去冒必死的危险，散步并无危险，不能用送死。"}, {"text": "他每天在家看电视，简直是送死。", "explanation": "这里应该用〈放松〉。送死指去冒必死的危险，在家看电视与生死无关，不能用送死。"}, {"text": "吃完饭后我们去打篮球，真是送死。", "explanation": "这里应该用〈锻炼〉。送死指去冒必死的危险，打篮球只是运动，不能用送死。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明明知道危险，却偏要把自己送死。", "corrected_sentence": "他明明知道危险，却偏要去送死。", "error_description": "“送死”是不及物动词，不能带宾语，也不能用“把”字句；应说“偏要去送死”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这样走下去，就是被送死。", "corrected_sentence": "我们这样走下去，就是在送死。", "error_description": "“送死”是不及物的动词，不能用“被”字句；此处应用“在”，说“就是在送死”，不能说“被送死”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d1df8c-23e6-4bf6-8b40-263efbffaf4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
