INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这天指前面说到的或正在说的那一天。", "primary_collocate": null, "pronunciation": "zhè tiān", "ipa": "ʈʂɤ˥˩ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "这天早上，我六点就起床了。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天是我的生日，朋友们都来了。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天天气很好，我们去公园玩。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天是星期六，我不用上班。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天下午，我在家看书。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天我哪儿也不去，只想休息。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天晚上，我们一起吃了饭。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天是周末，路上的人很多。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天下着大雨，我们哪儿也去不了。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天过得很快，我还没做完作业，天就黑了。", "target_word": "这天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指话语中所说的某一天（单独的一天）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3997216-d3ae-4dcb-ab5c-3abc7b75bba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这天", "is_correct": true, "explanation": "正确：“这天”指说话时的这一天，可以修饰“早上”，与“我六点就起床了”相符。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“早上”是一天中的时段，“一辈子”指一生，二者不能组合。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“去年”指过去的一整年，不能与“早上”这样的具体时段搭配。"}, {"text": "今年", "is_correct": false, "explanation": "搭配：“今年”是年份，不能直接修饰“早上”这一具体时段。"}], "explanations": {"这天": "正确：“这天”指说话时的这一天，可以修饰“早上”，与“我六点就起床了”相符。", "一辈子": "语义：“早上”是一天中的时段，“一辈子”指一生，二者不能组合。", "去年": "搭配：“去年”指过去的一整年，不能与“早上”这样的具体时段搭配。", "今年": "搭配：“今年”是年份，不能直接修饰“早上”这一具体时段。"}, "sentence_index": 0, "correct_answer": "这天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这天我一直很忙，已经忙了一个星期了。", "explanation": "这里应该用〈这几天〉。“这天”只指一天，不能包括一个星期。"}, {"text": "这天我们每天都去游泳。", "explanation": "这里应该用〈这段时间〉。“这天”只指一天，和“每天”矛盾。"}, {"text": "这天春天花开得特别早。", "explanation": "这里应该用〈今年〉。“这天”只指一天，不能用来说一个季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这天", "is_correct": true, "explanation": "正确：“这天晚上”指说话时的这个晚上，与“我们一起吃了饭”相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”是将来，而“吃了饭”表示已经发生，前后时间矛盾。"}, {"text": "一生", "is_correct": false, "explanation": "语义：“一生”指整个人生，不是一天中的某个晚上，句子说不通。"}, {"text": "三天", "is_correct": false, "explanation": "搭配：“晚上”是一天中的时段，“三天”是时长，不能说“三天晚上”。"}], "explanations": {"这天": "正确：“这天晚上”指说话时的这个晚上，与“我们一起吃了饭”相符。", "明年": "语义：“明年”是将来，而“吃了饭”表示已经发生，前后时间矛盾。", "一生": "语义：“一生”指整个人生，不是一天中的某个晚上，句子说不通。", "三天": "搭配：“晚上”是一天中的时段，“三天”是时长，不能说“三天晚上”。"}, "sentence_index": 6, "correct_answer": "这天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这天我每天都很忙。", "explanation": "这里应该用〈这些天〉。“这天”只指一天，不能和“每天”一起用。"}, {"text": "这天整整一年我都在国外。", "explanation": "这里应该用〈这一年〉。“这天”只指一天，不能指一整年。"}, {"text": "这天冬天特别冷，河都结冰了。", "explanation": "这里应该用〈今年〉。“这天”只指一天，不能用来说整个冬天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这天了下午一起去看电影。", "corrected_sentence": "我们这天下午一起去看电影。", "error_description": "助词错误：“了”不能插在时间状语“这天下午”中间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这天了晚上，我们一起看了电影。", "corrected_sentence": "这天晚上，我们一起看了电影。", "error_description": "助词错误：“了”不能插在时间状语“这天晚上”中间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '376c07fe-6748-4691-8f68-06c09b64cc76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
