INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新开始是从头再来一次。", "primary_collocate": null, "pronunciation": "chóng xīn kāi shǐ", "ipa": "ʈʂʰʊŋ˧˥ ɕin˥ kʰaɪ˥ ʂɻ̩˨˩", "syllable_count": 4, "sentences": [{"text": "他想离开这里，重新开始新的生活。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了没关系，我们可以重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市以后，她重新开始学中文。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我决定明年重新开始跑步。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们吵架以后，又想重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作丢了，爸爸决定重新开始找工作。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说，每天早上都是重新开始的机会。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，奶奶重新开始画画。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是能重新开始，你想做什么？", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年的休息，他重新开始工作了。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重新开始了", "label": "体标"}, {"form": "重新開始", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生活、感情、工作等从头再来一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重新开始", "is_correct": true, "explanation": "正确。“重新开始”指从头再来，与“想离开这里”“新的生活”相符。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“想要新的生活”的意图相反。"}, {"text": "继续", "is_correct": false, "explanation": "搭配：“继续”接已经存在的事情，不能接“新的生活”这样的新开端。"}, {"text": "重复", "is_correct": false, "explanation": "搭配：“重复”接已经做过的事，不能用来修饰“新的生活”。"}], "explanations": {"重新开始": "正确。“重新开始”指从头再来，与“想离开这里”“新的生活”相符。", "结束": "语义：“结束”表示终止，与“想要新的生活”的意图相反。", "继续": "搭配：“继续”接已经存在的事情，不能接“新的生活”这样的新开端。", "重复": "搭配：“重复”接已经做过的事，不能用来修饰“新的生活”。"}, "sentence_index": 0, "correct_answer": "重新开始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手术后，他终于重新开始了健康。", "explanation": "这里应该用〈恢复〉。“重新开始”用于行为或活动，身体状态的回到原样要说恢复。"}, {"text": "他每天都跑步，从没停过，今年还是重新开始跑步。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，这里并没有中断，应说继续。"}, {"text": "他第一次学游泳，决定重新开始学游泳。", "explanation": "这里应该用〈开始〉。“重新”表示再次，第一次做应说开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重新开始", "is_correct": true, "explanation": "正确。“重新开始”指从头再来，与“每天早上都是……的机会”相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“机会”的积极含义相反，每天早上不会是放弃的机会。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是消极的事，不是从头再来的机会。"}, {"text": "失眠", "is_correct": false, "explanation": "搭配：“失眠”是状态，不能与“机会”搭配。"}], "explanations": {"重新开始": "正确。“重新开始”指从头再来，与“每天早上都是……的机会”相符。", "放弃": "语义：“放弃”与“机会”的积极含义相反，每天早上不会是放弃的机会。", "迟到": "语义：“迟到”是消极的事，不是从头再来的机会。", "失眠": "搭配：“失眠”是状态，不能与“机会”搭配。"}, "sentence_index": 6, "correct_answer": "重新开始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过一年的休息，他重新开始了一个苹果。", "explanation": "这里应该用〈吃〉。“重新开始”接的是工作、生活等活动，不能接“苹果”这样的具体事物；吃苹果应说吃。"}, {"text": "这家店一直营业，从没关过门，今年还要重新开始营业。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，这家店从没关过门，应说继续。"}, {"text": "他从来没有停止过工作，现在决定重新开始工作。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，他没有停过，应说继续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他决定明年重新开始了学习画画。", "corrected_sentence": "他决定明年重新开始学习画画。", "error_description": "“明年”是未来的事，不能用“了”表示已经完成，应去掉“了”，说“重新开始学习画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离婚以后，她决定重新开始着生活。", "corrected_sentence": "离婚以后，她决定重新开始生活。", "error_description": "“重新开始”表示动作从头再来，不能接“着”表示持续状态，应去掉“着”，说“重新开始生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
