INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次从头开始。", "primary_collocate": null, "pronunciation": "chóng xīn kāi shǐ", "ipa": "ʈʂʰʊŋ˧˥ ɕin˥ kʰaɪ˥ ʂɻ̩˨˩", "syllable_count": 4, "sentences": [{"text": "电脑坏了，游戏只能重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写到一半被电话打断了，只好重新开始写。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏进行到一半停电了，只好重新开始玩。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛因为下雨停了，一个小时后重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器关了以后，要按这个键重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出中途停电了，乐队只好重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网速太慢，下载又重新开始了。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画到一半被打断了，他决定重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音时有人敲门，只好重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议中间停电，十分钟后重新开始。", "target_word": "重新开始", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重新开始了", "label": "体标"}, {"form": "重新開始", "label": "繁体"}], "register": "中性", "sense_fingerprint": "游戏、比赛、程序、活动等中断后再次从头开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88131405-7030-4d15-aa9d-0a48d00bcf95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重新开始", "is_correct": true, "explanation": "正确。“重新开始”指中断后再从头开始，与“电脑坏了，游戏只能……”相符。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”针对物体表面，不能与“游戏”搭配。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物品或房间，不能用于“游戏”。"}, {"text": "继续", "is_correct": false, "explanation": "语义：电脑坏了之后游戏已经中断，“只能继续”与语境矛盾。"}], "explanations": {"重新开始": "正确。“重新开始”指中断后再从头开始，与“电脑坏了，游戏只能……”相符。", "擦拭": "搭配：“擦拭”针对物体表面，不能与“游戏”搭配。", "装饰": "搭配：“装饰”用于物品或房间，不能用于“游戏”。", "继续": "语义：电脑坏了之后游戏已经中断，“只能继续”与语境矛盾。"}, "sentence_index": 0, "correct_answer": "重新开始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我们第一次合作，我们决定重新开始合作。", "explanation": "这里应该用〈开始〉。“重新”表示再次，第一次合作不能说重新开始。"}, {"text": "我们刚打到第三关，中间没有停过，现在还要重新开始玩下去。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，游戏中间没有停过，应说继续。"}, {"text": "比赛从头到尾没有停过，但一个小时后又重新开始了。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，这场比赛没有中断，应说继续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重新开始", "is_correct": true, "explanation": "正确。“重新开始”指中断后再从头开始，与“网速太慢，下载又……了”的语境相符。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”针对衣物，不能与“下载”搭配。"}, {"text": "晾晒", "is_correct": false, "explanation": "搭配：“晾晒”针对衣物或被子，不能与“下载”搭配。"}, {"text": "拍照", "is_correct": false, "explanation": "搭配：“拍照”不能与“下载”搭配，句子不通。"}], "explanations": {"重新开始": "正确。“重新开始”指中断后再从头开始，与“网速太慢，下载又……了”的语境相符。", "熨烫": "搭配：“熨烫”针对衣物，不能与“下载”搭配。", "晾晒": "搭配：“晾晒”针对衣物或被子，不能与“下载”搭配。", "拍照": "搭配：“拍照”不能与“下载”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "重新开始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议很顺利，从头到尾没有停过，十分钟后又重新开始。", "explanation": "这里应该用〈继续〉。“重新开始”表示中断后再来，这里会议没有中断，应说继续。"}, {"text": "他把这张照片重新开始了一遍。", "explanation": "这里应该用〈修〉。“重新开始”表示从头再做一个过程，不能接“照片”这样的物品，修照片应说修。"}, {"text": "这台新电脑还没开过机，主人按下按钮，它又重新开始了。", "explanation": "这里应该用〈开始〉。“重新”表示再次，这台电脑还没开过机，应说开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "停电以后，他只好重新开始得写作业。", "corrected_sentence": "停电以后，他只好重新开始写作业。", "error_description": "“得”用于动词后接补语，“重新开始”后直接接宾语“写作业”，不需要“得”。正确形式是“重新开始写作业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "网速恢复正常以后，下载又重新开始着。", "corrected_sentence": "网速恢复正常以后，下载又重新开始了。", "error_description": "体标错误：“重新开始”表示一下子发生的变化，不能跟表示持续的“着”。这里说的是已经发生的变化，应该用“了”，即“又重新开始了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af95e219-044f-4d55-9840-f6ea9329cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
