INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "锅是用来煮饭炒菜的圆圆的铁器。", "primary_collocate": null, "pronunciation": "guō", "ipa": "kwɔ˥", "syllable_count": 1, "sentences": [{"text": "妈妈用大锅煮饭，因为家里人很多。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口锅太小了，炒不了很多菜。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把锅放在火上，开始炒菜。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新买的那口锅很重，我拿不动。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的水开了，快放面条。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的锅用了二十年了，还很好用。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用锅蒸了几个包子。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完米，他拿出一口锅来煮饭。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个锅是圆的，盖子也是圆的。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭以前，先把锅洗干净。", "target_word": "锅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口", "label": "量词"}, {"form": "锅盖", "label": "复合"}, {"form": "炒锅", "label": "复合"}, {"form": "铁锅", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来煮饭炒菜的圆形铁制厨具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5e84c5-2a16-4f68-a12b-1f0403cb5795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99073, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：煮饭炒菜的炊具，即本词。"}, {"text": "国", "is_correct": false, "explanation": "guó（第二声）与 guō（第一声）声调不同，意思是国家。"}, {"text": "果", "is_correct": false, "explanation": "guǒ（第三声）与 guō（第一声）声调不同，意思是水果。"}, {"text": "过", "is_correct": false, "explanation": "guò（第四声）与 guō（第一声）声调不同，意思是经过。"}], "explanations": {"锅": "锅：煮饭炒菜的炊具，即本词。", "国": "guó（第二声）与 guō（第一声）声调不同，意思是国家。", "果": "guǒ（第三声）与 guō（第一声）声调不同，意思是水果。", "过": "guò（第四声）与 guō（第一声）声调不同，意思是经过。"}, "sentence_index": null, "correct_answer": "锅"}, "level_3": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：煮饭的炊具，与“煮饭”搭配。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗是盛饭的器皿，不能用来煮饭。"}, {"text": "桶", "is_correct": false, "explanation": "语义：桶用来装水，不能拿来煮饭。"}, {"text": "铲子", "is_correct": false, "explanation": "搭配：铲子用来翻炒，不能说用铲子煮饭。"}], "explanations": {"锅": "锅：煮饭的炊具，与“煮饭”搭配。", "碗": "语义：碗是盛饭的器皿，不能用来煮饭。", "桶": "语义：桶用来装水，不能拿来煮饭。", "铲子": "搭配：铲子用来翻炒，不能说用铲子煮饭。"}, "sentence_index": 0, "correct_answer": "锅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用锅切了一块肉。", "explanation": "这里应该用〈菜刀〉。切肉要用菜刀，锅是烹饪用的炊具，不能用来切肉。"}, {"text": "他用锅盛了一碗饭。", "explanation": "这里应该用〈碗〉。盛饭要用碗，锅是煮饭炒菜的炊具，不能用来盛饭。"}, {"text": "妈妈用锅洗了脸。", "explanation": "这里应该用〈脸盆〉。洗脸要用脸盆，锅是烹饪用的炊具，不能用来洗脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99073, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：煮饭炒菜的炊具，即本词。"}, {"text": "哥", "is_correct": false, "explanation": "gē 与 guō 韵母 e 与 uo 不同，声调相同（第一声），意思是哥哥。"}, {"text": "个", "is_correct": false, "explanation": "gè 与 guō 韵母 e 与 uo 不同，声调也不同，意思是量词“个”。"}, {"text": "裹", "is_correct": false, "explanation": "guǒ（第三声）与 guō（第一声）声调不同，意思是包住、缠绕。"}], "explanations": {"锅": "锅：煮饭炒菜的炊具，即本词。", "哥": "gē 与 guō 韵母 e 与 uo 不同，声调相同（第一声），意思是哥哥。", "个": "gè 与 guō 韵母 e 与 uo 不同，声调也不同，意思是量词“个”。", "裹": "guǒ（第三声）与 guō（第一声）声调不同，意思是包住、缠绕。"}, "sentence_index": null, "correct_answer": "锅"}, "level_3": {"options": [{"text": "锅", "is_correct": true, "explanation": "锅：蒸包子的炊具，与“蒸”搭配。"}, {"text": "刀", "is_correct": false, "explanation": "语义：刀用来切割，不能用来蒸包子。"}, {"text": "扇子", "is_correct": false, "explanation": "语义：扇子用来扇风，与蒸包子的语境不符。"}, {"text": "饭勺", "is_correct": false, "explanation": "搭配：饭勺只用来盛饭，不能说用饭勺蒸包子。"}], "explanations": {"锅": "锅：蒸包子的炊具，与“蒸”搭配。", "刀": "语义：刀用来切割，不能用来蒸包子。", "扇子": "语义：扇子用来扇风，与蒸包子的语境不符。", "饭勺": "搭配：饭勺只用来盛饭，不能说用饭勺蒸包子。"}, "sentence_index": 6, "correct_answer": "锅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用锅喝了一口水。", "explanation": "这里应该用〈杯子〉。喝水要用杯子，锅是炊具，不能拿来喝水。"}, {"text": "妈妈用锅洗了衣服。", "explanation": "这里应该用〈盆〉。洗衣服要用盆，锅不是洗衣器具。"}, {"text": "妈妈用锅量了一杯米。", "explanation": "这里应该用〈量杯〉。量米要用量杯，锅是烹饪用的炊具，不能用来量米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一张新锅，用来炖汤。", "corrected_sentence": "妈妈买了一口新锅，用来炖汤。", "error_description": "量词错误。“锅”的量词应为“口”，“张”用于平面的东西，不能用来数锅。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (99073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姥姥用一张大锅熬了粥。", "corrected_sentence": "姥姥用一口大锅熬了粥。", "error_description": "量词错误。“锅”的量词应为“口”，“张”用于平面的东西，不能用来数锅。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6adbf331-022a-4337-b8ae-9c0dc357a6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
